window.ATELIER_THEORY = [{"topic":"Articolo","area":"parole","lead":"L’articolo accompagna il nome e aiuta a capire genere, numero e modo in cui presentiamo una persona o una cosa.","objectives":["Individuare il nome","Scegliere la forma","Distinguere gli usi"],"sections":[{"title":"Riconoscere la funzione","text":"L’articolo si trova davanti a un nome, anche quando fra i due compare un aggettivo: una grande finestra. Concorda con il nome nel genere e nel numero. Il determinativo presenta qualcosa di identificabile: il banco della nostra aula. L’indeterminativo introduce spesso un elemento nuovo o uno qualsiasi: un banco. La scelta dipende dal contesto: dopo aver presentato una sedia, possiamo chiamarla la sedia perché chi ascolta sa ormai di quale parliamo. Il determinativo può anche indicare un’intera categoria: il violino è uno strumento ad arco.","examples":[{"sentence":"Una sedia è vicino alla porta. La sedia è rossa.","explanation":"Una introduce l’oggetto; la lo riprende quando è conosciuto."},{"sentence":"Lo scaffale contiene gli strumenti.","explanation":"Lo e gli precedono qui s seguita da consonante."}]},{"title":"Le forme e i suoni iniziali","text":"I determinativi sono il, lo, la, l’, i, gli, le. Il e i precedono molti nomi maschili; lo e gli precedono, fra gli altri, s seguita da consonante, z, gn, ps: lo studente, gli zaini. Davanti a una vocale piena il maschile lo si elide: l’arco. Al femminile la forma elisa è comune, ma la forma intera può restare: l’amica o la amica. Gli indeterminativi singolari sono un, uno, una e un’. Un davanti a vocale maschile non vuole apostrofo; al femminile si può usare la forma elisa un’amica oppure la forma intera una amica. Alcune parole che iniziano per i seguita da vocale, come iato e iena, cominciano nella pronuncia con una i semiconsonantica: nella norma tradizionale si dicono lo iato e la iena, senza elidere l’articolo. Negli usi reali possono esserci oscillazioni: se hai un dubbio consulta un dizionario.","examples":[{"sentence":"Un arco e un’asola sono sul tavolo.","explanation":"Arco è maschile: un senza apostrofo; asola è femminile: un’."},{"sentence":"Prendo del legno.","explanation":"Del è partitivo: significa una quantità non precisata di legno."},{"sentence":"Lo iato e la iena sono due gruppi corretti.","explanation":"La i iniziale di iato e iena ha valore semiconsonantico; nella norma tradizionale l’articolo non è eliso."}]},{"title":"Quantità e preposizioni articolate","text":"Il partitivo indica una quantità non precisata: del pane significa un po’ di pane; dei fogli significa alcuni fogli. Le forme sono del, dello, della, dell’, dei, degli, delle. Le stesse forme possono essere preposizioni articolate: nell’espressione il colore della stoffa, «della» unisce «di» e «la» e introduce una specificazione. Per decidere, prova il significato, non soltanto la forma. Le preposizioni di, a, da, in, su si uniscono agli articoli determinativi: al banco, dalla porta, negli armadi. Con e per restano normalmente separate nell’uso corrente.","examples":[{"sentence":"Il colore del legno è chiaro.","explanation":"Del è di più il e collega colore a legno."}]},{"title":"Controllare il contesto","text":"L’articolo non accompagna ogni nome in ogni frase. Molti nomi propri di persona si usano senza articolo: Sara arriva. Nelle elencazioni e nelle espressioni fisse può mancare: carta e penna, andare a scuola. Alcuni nomi geografici lo richiedono, altri no: l’Italia, Roma. Per l’analisi grammaticale indica categoria, genere e numero; per una preposizione articolata riconosci anche la preposizione di partenza. Non confondere l’articolo con un pronome: in lo vedo, lo sostituisce qualcuno e non introduce un nome. Quando correggi, leggi sempre il gruppo completo.","examples":[{"sentence":"Lo studente lo osserva.","explanation":"Il primo lo introduce studente ed è articolo; il secondo sostituisce un oggetto ed è pronome."}]},{"title":"Quando l’articolo cambia il valore della parola","text":"L’articolo può presentare come nome una parola che normalmente appartiene a un’altra categoria: il rosso indica un colore; il progettare può indicare l’attività del progettare. In questi casi non basta osservare la forma isolata: controlla come la parola funziona nella frase. L’indeterminativo non possiede un plurale proprio: per parlare di più elementi indefiniti si possono usare alcuni o alcune, oppure un partitivo plurale, quando il contesto lo consente.","examples":[{"sentence":"Il verde del campione è intenso; una foglia verde è sul tavolo.","explanation":"Nel primo gruppo verde funziona come nome di colore; nel secondo qualifica foglia."},{"sentence":"Una matita è sul tavolo; alcune matite sono nel cassetto.","explanation":"Alcune esprime una quantità indefinita al plurale: non è il plurale di una."}]},{"title":"Articolo e nomi di parentela","text":"Con un nome di parentela singolare preceduto da mio, tuo, suo, nostro o vostro, nell’uso comune l’articolo manca: mia sorella. Ricompare, per esempio, con il plurale, con loro o con un nome alterato: le mie sorelle, il loro zio, la mia sorellina. Ci sono altre costruzioni e usi familiari possibili: valuta sempre l’espressione completa. Se una preposizione precede un’espressione con quantità indefinita, spesso alcuni o un po’ di aiutano a formulare la frase in modo chiaro.","examples":[{"sentence":"Mia zia prepara il modello; le mie zie lo osservano.","explanation":"Con zia singolare preceduto da mia manca l’articolo; con zie plurale compare le."},{"sentence":"Parlo con alcuni allievi del corso.","explanation":"Alcuni allievi indica una quantità indefinita dopo la preposizione con."}]}],"diagram":{"title":"Articolo: i collegamenti da ricordare","steps":[{"label":"Determinativo","detail":"Il, lo, la, l’, i, gli, le: referente identificabile."},{"label":"Indeterminativo","detail":"Un, uno, una, un’: un elemento non ancora identificato."},{"label":"Partitivo","detail":"Del, della, dei, delle: quantità non precisata."},{"label":"Accordo e suono","detail":"Genere e numero del nome; lo scaffale, un arco, un’asola."}]},"pitfalls":[{"mistake":"Un’ago","correction":"Un ago","why":"Ago è maschile: un non perde una vocale e non ha apostrofo."},{"mistake":"Il strumenti","correction":"Gli strumenti","why":"Il nome è plurale e comincia con s più consonante."}],"recap":["Il determinativo presenta elementi identificabili.","L’indeterminativo introduce spesso elementi nuovi.","Il partitivo indica quantità non precisate.","Forma e funzione vanno controllate nella frase."],"review":[{"question":"Perché scrivo un’arancia?","answer":"Arancia è femminile e comincia per vocale: una diventa un’."},{"question":"Che cosa significa delle in «compro delle viti»?","answer":"È partitivo e significa alcune viti."},{"question":"In «la vedo», la è articolo?","answer":"No: sostituisce una persona o cosa, quindi è pronome."}],"levels":{"base":{"focus":"Individuare il nome","example":{"sentence":"Una sedia è vicino alla porta. La sedia è rossa.","explanation":"Una introduce l’oggetto; la lo riprende quando è conosciuto."}},"consolidamento":{"focus":"Scegliere la forma","example":{"sentence":"Un arco e un’asola sono sul tavolo.","explanation":"Arco è maschile: un senza apostrofo; asola è femminile: un’."}},"avanzato":{"focus":"Distinguere gli usi","example":{"sentence":"Lo studente lo osserva.","explanation":"Il primo lo introduce studente ed è articolo; il secondo sostituisce un oggetto ed è pronome."}}},"simplified":{"lead":"L’articolo si mette davanti al nome.","steps":["Trova il nome: sedia.","Sedia è femminile singolare: scegli la oppure una.","Controlla se la sedia è già conosciuta."],"example":{"sentence":"La sedia è rossa.","explanation":"La accompagna il nome sedia."}},"pei":{"rule":"Davanti a sedia puoi scrivere la o una.","example":{"sentence":"La sedia è rossa.","explanation":"La accompagna il nome sedia."}},"trackExamples":{"moda":{"sentence":"La sarta prepara un’asola.","explanation":"Un’ accompagna il nome femminile asola."},"arredo":{"sentence":"Controlliamo lo schienale.","explanation":"Schienale richiede lo perché inizia con s più consonante."},"liuteria":{"sentence":"Accordiamo gli strumenti.","explanation":"Gli concorda con strumenti, maschile plurale."}},"anchor":{"sentence":"Uno zaino occupa due sedie. Lo zaino viaggia comodo.","explanation":"Uno presenta lo zaino per la prima volta. Lo lo riprende quando sappiamo di quale zaino parliamo.","memory":"Prima uno zaino; poi lo zaino."}},{"topic":"Nome","area":"parole","lead":"Il nome dà un nome a persone, animali, oggetti, luoghi, idee, sentimenti e attività.","objectives":["Riconoscere i nomi","Controllare genere e numero","Distinguere le categorie"],"sections":[{"title":"Che cosa può indicare","text":"I nomi non indicano soltanto oggetti che si possono toccare. Coraggio, amicizia e precisione sono nomi perché permettono di parlare di qualità e idee. Un nome comune indica una categoria, come città; un nome proprio identifica un referente particolare, come Cremona, e si scrive con la maiuscola. La distinzione fra concreto e astratto riguarda il significato nel contesto: costruzione può indicare un’attività oppure un edificio. Per riconoscere un nome osserva anche il gruppo in cui compare: può ricevere articolo e aggettivi e svolgere diverse funzioni nella frase.","examples":[{"sentence":"La precisione migliora il lavoro.","explanation":"Precisione è un nome astratto: indica una qualità."},{"sentence":"Visitiamo Cremona, una città lombarda.","explanation":"Cremona è proprio; città è comune."}]},{"title":"Genere e persone","text":"I nomi italiani hanno genere maschile o femminile, ma la terminazione non basta sempre per stabilirlo: il problema è maschile, la mano è femminile. Per le persone il femminile può formarsi cambiando desinenza, come allievo e allieva, con un suffisso, come attore e attrice, oppure con una parola diversa, come fratello e sorella. Alcuni nomi hanno una sola forma per entrambi i generi: un artista, un’artista; articolo e accordi rendono visibile la differenza. Per molti animali una forma grammaticale indica entrambi i sessi: una giraffa maschio.","examples":[{"sentence":"Un artista parla con un’artista.","explanation":"La forma artista resta uguale; l’articolo distingue qui maschile e femminile."},{"sentence":"Le città organizzano due festival.","explanation":"Città e festival sono invariabili; articoli e numerali mostrano il plurale."}]},{"title":"Numero e plurali difficili","text":"Il numero distingue singolare e plurale. Molti nomi in -o fanno il plurale in -i; quelli femminili in -a spesso in -e; quelli in -e in -i. Sono tendenze da verificare: ala diventa ali, poeta diventa poeti. I nomi invariabili non cambiano forma: città, film; il numero appare negli articoli e negli accordi. Alcuni nomi si usano soprattutto al plurale, come forbici. Altri hanno due plurali con significati diversi: i bracci di una gru e le braccia di una persona. Il dizionario aiuta nei casi non prevedibili.","examples":[{"sentence":"La classe entra in laboratorio.","explanation":"Classe è collettivo singolare e concorda con entra."}]},{"title":"Struttura e significato collettivo","text":"Un nome primitivo non si analizza, nella famiglia considerata, come derivato da un’altra parola: carta. Un derivato aggiunge elementi riconoscibili: cartiera; un alterato modifica una sfumatura: cartaccia. Un composto unisce elementi: portafoglio. Non ogni finale simile indica alterazione: un bottone non è un piccolo botto. Un collettivo singolare indica un insieme, come classe o orchestra. Normalmente richiede un verbo singolare quando è soggetto: la classe lavora. Nell’analisi separa questi criteri: un nome può essere nello stesso tempo comune, concreto, collettivo, femminile e singolare. Ogni etichetta risponde a una domanda diversa.","examples":[{"sentence":"Le braccia sono stanche; i bracci della gru sono lunghi.","explanation":"I due plurali di braccio hanno significati diversi."}]},{"title":"Nomi mobili, comuni, indipendenti e promiscui","text":"Per alcune persone il nome cambia forma secondo il genere: allievo e allieva sono forme mobili. Altri nomi riferiti a persone conservano la stessa forma: il cantante e la cantante sono di genere comune; articoli e accordi aiutano a riconoscere il genere. Nelle coppie indipendenti cambiano le parole, come padre e madre. Per alcuni animali il nome ha un solo genere grammaticale per entrambi i sessi: la giraffa può indicare un maschio o una femmina; se serve, si aggiunge maschio o femmina. Genere grammaticale e sesso del referente non coincidono automaticamente.","examples":[{"sentence":"Il cantante è arrivato; la cantante è arrivata.","explanation":"Cantante mantiene la forma; articolo e participio indicano il genere del referente."},{"sentence":"Una giraffa maschio attraversa il recinto.","explanation":"Giraffa rimane grammaticalmente femminile anche quando l’animale è maschio."}]},{"title":"Nomi difettivi e plurali diversi","text":"Un nome invariabile mantiene la stessa forma nei due numeri: il film, i film. Un nome difettivo è invece normalmente usato soltanto in uno dei due numeri: le stoviglie si usa di solito al plurale; il latte come materia si usa per lo più al singolare. Alcuni nomi ammettono due plurali con significati o contesti differenti: i muri di una casa, le mura di una città. Queste sono tendenze d’uso, non un divieto assoluto per ogni significato: in caso di dubbio consulta un dizionario.","examples":[{"sentence":"I film iniziano alle quattro; le stoviglie sono nell’armadio.","explanation":"Film è invariabile; stoviglie è usato normalmente al plurale."},{"sentence":"I muri della stanza sono bianchi; le mura della città sono antiche.","explanation":"Muri e mura sono due plurali di muro, usati qui con significati diversi."}]},{"title":"Sfumature dei nomi alterati","text":"Un suffisso alterativo può suggerire dimensione, affetto o giudizio: un diminutivo può indicare piccolezza, un accrescitivo grandezza, un vezzeggiativo affetto e un peggiorativo una valutazione negativa. Il significato dipende però dal contesto: un suffisso non basta da solo a stabilire l’intenzione di chi parla. Non confondere un vero alterato con un falso alterato, cioè una parola che assomiglia a un alterato ma ha un significato proprio: un mattone non è un grande matto.","examples":[{"sentence":"Un tavolino sostiene il vaso; un tavolone occupa la sala.","explanation":"Tavolino suggerisce piccolezza; tavolone suggerisce grandi dimensioni."},{"sentence":"La casetta è al termine del sentiero.","explanation":"Casetta può indicare una casa piccola; il contesto aiuta a interpretare la sfumatura."}]},{"title":"Nomi sovrabbondanti","text":"Alcuni nomi presentano più di una forma di plurale, talvolta con significati o usi differenti: sono detti sovrabbondanti nella terminologia scolastica. Braccio può dare i bracci di una gru oppure le braccia di una persona; muro dà i muri di una stanza oppure le mura di una città. Non sono nomi invariabili, che mantengono la stessa forma, né difettivi, usati normalmente soltanto in un numero. Per scegliere la forma controlla il significato nel contesto e consulta il dizionario.","examples":[{"sentence":"Le braccia di Nora sono stanche; i bracci della gru si alzano.","explanation":"I due plurali di braccio sono usati qui per referenti diversi."},{"sentence":"I muri della stanza sono chiari; le mura della città sono antiche.","explanation":"Muri e mura sono due plurali di muro con usi distinti nel contesto."}]}],"diagram":{"title":"Nome: i collegamenti da ricordare","steps":[{"label":"Significato","detail":"Comune o proprio; concreto o astratto; individuale o collettivo."},{"label":"Genere","detail":"Maschile o femminile: controlla articolo e accordi."},{"label":"Numero","detail":"Singolare o plurale; alcuni nomi sono invariabili."},{"label":"Struttura","detail":"Primitivo, derivato, alterato o composto."}]},"pitfalls":[{"mistake":"La problema","correction":"Il problema","why":"Problema è maschile, anche se finisce in -a."},{"mistake":"La classe lavorano","correction":"La classe lavora","why":"Il nome collettivo classe è grammaticalmente singolare."}],"recap":["I nomi possono indicare anche idee e attività.","Il genere non si ricava sempre dalla terminazione.","Il numero può essere segnalato dagli accordi.","Un collettivo singolare richiede normalmente accordo singolare."],"review":[{"question":"Precisione è un nome anche se non si tocca?","answer":"Sì: indica una qualità astratta."},{"question":"Qual è il plurale di città?","answer":"Città: è invariabile."},{"question":"Bottone è un accrescitivo di botto?","answer":"No: la somiglianza delle lettere non crea una derivazione."}],"levels":{"base":{"focus":"Riconoscere i nomi","example":{"sentence":"La precisione migliora il lavoro.","explanation":"Precisione è un nome astratto: indica una qualità."}},"consolidamento":{"focus":"Controllare genere e numero","example":{"sentence":"Un artista parla con un’artista.","explanation":"La forma artista resta uguale; l’articolo distingue qui maschile e femminile."}},"avanzato":{"focus":"Distinguere le categorie","example":{"sentence":"Le braccia sono stanche; i bracci della gru sono lunghi.","explanation":"I due plurali di braccio hanno significati diversi."}}},"simplified":{"lead":"Il nome indica una persona, una cosa oppure un’idea.","steps":["Leggi la parola e chiediti che cosa indica.","Cerca l’articolo: il banco, la sedia.","Guarda se indica uno o più elementi."],"example":{"sentence":"Il banco è pulito.","explanation":"Banco nomina un oggetto dell’aula."}},"pei":{"rule":"Banco è un nome: indica un oggetto.","example":{"sentence":"Il banco è pulito.","explanation":"Banco nomina un oggetto dell’aula."}},"trackExamples":{"moda":{"sentence":"La modellista controlla la lunghezza.","explanation":"Modellista nomina una persona; lunghezza una proprietà."},"arredo":{"sentence":"La squadra monta le mensole.","explanation":"Squadra è collettivo singolare; mensole è plurale."},"liuteria":{"sentence":"La liutaia osserva le venature.","explanation":"Liutaia è femminile singolare; venature femminile plurale."}},"anchor":{"sentence":"La pazienza non entra nello zaino, ma serve ogni mattina.","explanation":"Pazienza è un nome astratto: nomina una qualità anche se non possiamo afferrarla. Zaino è un nome concreto.","memory":"Anche ciò che non tocchi può avere un nome."}},{"topic":"Aggettivo","area":"parole","lead":"L’aggettivo accompagna un nome e ne precisa qualità, appartenenza, quantità o posizione.","objectives":["Trovare il nome descritto","Fare l’accordo","Interpretare tipo e grado"],"sections":[{"title":"Qualificativi e accordo","text":"Gli aggettivi qualificativi esprimono caratteristiche: un tessuto morbido, una risposta precisa. Di solito concordano con il nome nel genere e nel numero. Alcuni hanno quattro forme, come rosso, rossa, rossi, rosse; altri ne hanno due, come verde e verdi. Alcuni restano invariabili, come blu. Se un aggettivo si riferisce a più nomi, l’accordo dipende dai nomi: sedia e mensola nuove; tavolo e sedia nuovi, secondo l’accordo grammaticale tradizionale. Non scegliere la forma guardando soltanto il nome più vicino: controlla a quali elementi si riferisce davvero.","examples":[{"sentence":"Le stoffe morbide sono sul tavolo.","explanation":"Morbide concorda con stoffe: femminile plurale."},{"sentence":"Una sedia blu e due sedie blu.","explanation":"Blu è un aggettivo invariabile."}]},{"title":"Posizione e funzione","text":"L’aggettivo può essere attributo, quando accompagna direttamente un nome, oppure parte del predicato nominale, quando è collegato al soggetto da essere: una parete chiara, la parete è chiara. La posizione può cambiare il significato. Un vecchio amico è un amico di lunga data; un amico vecchio è avanti negli anni. Dopo il nome la qualità spesso distingue un elemento dagli altri; prima del nome può esprimere una valutazione o una caratteristica data per nota. Queste sono tendenze: è sempre il contesto a guidare l’interpretazione.","examples":[{"sentence":"Questo è un vecchio amico.","explanation":"Vecchio prima di amico indica qui una relazione di lunga durata."},{"sentence":"La seconda mensola è più alta della prima.","explanation":"Più alta esprime un comparativo di maggioranza."}]},{"title":"Confronti e intensità","text":"Il comparativo confronta qualità o elementi: più alto di, meno alto di, alto come o quanto. Il superlativo relativo indica il grado massimo o minimo entro un gruppo: il più alto della classe. Il superlativo assoluto esprime intensità senza un gruppo di confronto: altissimo, molto alto. Alcuni aggettivi hanno forme particolari: buono, migliore, ottimo; cattivo, peggiore, pessimo. Migliore contiene già il confronto, quindi nel significato comune non richiede più. Non tutti gli aggettivi ammettono normalmente i gradi: triangolare descrive una forma, non una qualità graduabile.","examples":[{"sentence":"Questo tessuto è ottimo.","explanation":"Ottimo è superlativo assoluto di buono."}]},{"title":"Aggettivi determinativi","text":"I possessivi indicano una relazione di appartenenza: mio, tuo, suo, nostro, vostro, loro. I dimostrativi situano un referente: questo, quello. Gli indefiniti danno quantità o identità non precise: alcuni, molti, ogni. I numerali indicano numero o ordine: tre, terzo. Interrogativi ed esclamativi introducono domande o esclamazioni: quale misura?, che sorpresa! Una stessa parola può essere aggettivo o pronome: in questi fogli accompagna un nome, in scelgo questi lo sostituisce. Per l’analisi indica tipo, genere, numero e, se presente, grado. Confronta sempre la parola con il nome a cui si riferisce.","examples":[{"sentence":"Scelgo questi fogli; tu prendi quelli.","explanation":"Questi è aggettivo perché accompagna fogli; quelli è pronome."}]},{"title":"La struttura dei qualificativi","text":"Un aggettivo primitivo costituisce una base lessicale, come dolce. Un derivato nasce da un’altra parola mediante un elemento aggiunto: nebbioso da nebbia. Un alterato modifica una sfumatura, spesso attraverso un suffisso: bellino può suggerire apprezzamento o una qualità attenuata secondo il contesto. Un composto unisce più elementi lessicali: agrodolce. Le categorie descrivono la formazione della parola e sono distinte dal suo genere, numero e grado.","examples":[{"sentence":"Il tè è agrodolce.","explanation":"Agrodolce unisce due elementi che esprimono qualità."},{"sentence":"Il paesaggio è nebbioso.","explanation":"Nebbioso deriva dal nome nebbia con un suffisso."}]},{"title":"Identificativi e possessivi particolari","text":"Stesso e medesimo possono accompagnare un nome per indicare identità: scegliamo la stessa stoffa. Se sostituiscono un nome assumono funzione pronominale: scelgo la medesima. Proprio può rafforzare un possessivo oppure riferirsi al soggetto: Sara cura il proprio lavoro. Altrui è invariabile e indica ciò che appartiene ad altre persone: rispettiamo le idee altrui. Per distinguere aggettivo e pronome verifica se la parola accompagna o sostituisce il nome.","examples":[{"sentence":"Usiamo lo stesso metro.","explanation":"Stesso accompagna metro e indica identità."},{"sentence":"Le allieve rispettano le idee altrui.","explanation":"Altrui accompagna idee e resta invariabile."}]},{"title":"Cardinali, ordinali e moltiplicativi","text":"I numerali cardinali indicano quante persone o cose: tre pannelli. Gli ordinali indicano il posto in una serie: il terzo pannello. I moltiplicativi indicano un multiplo, come doppio, triplo e quadruplo: una dose doppia. Come altri aggettivi, concordano quando la loro forma è variabile. I numeri possono essere scritti con cifre arabe, come 4 e 12, oppure con numeri romani, come IV e XII, secondo l’uso: IV può indicare quarto e XII dodicesimo in una successione.","examples":[{"sentence":"Servono tre ripiani; montiamo il terzo.","explanation":"Tre è cardinale e indica la quantità; terzo è ordinale e indica una posizione."},{"sentence":"Prepara una dose doppia.","explanation":"Doppia è numerale moltiplicativo e concorda con dose."},{"sentence":"Il capitolo IV segue il capitolo III.","explanation":"IV e III sono numeri romani che indicano qui quarto e terzo."}]}],"diagram":{"title":"Aggettivo: i collegamenti da ricordare","steps":[{"label":"Qualificativo","detail":"Descrive una qualità: una stoffa morbida."},{"label":"Determinativo","detail":"Precisa appartenenza, posizione, quantità o ordine."},{"label":"Accordo","detail":"Le stoffe morbide: nome e aggettivo concordano."},{"label":"Grado","detail":"Alto; più alto di; altissimo; il più alto del gruppo."}]},"pitfalls":[{"mistake":"Più migliore","correction":"Migliore","why":"Migliore esprime già un comparativo nel significato comune."},{"mistake":"Due mensole nuovo","correction":"Due mensole nuove","why":"L’aggettivo concorda con il nome femminile plurale."}],"recap":["L’aggettivo precisa un nome.","Le forme variabili concordano in genere e numero.","Posizione e contesto possono cambiare il significato.","Aggettivo e pronome si distinguono osservando la presenza del nome."],"review":[{"question":"Qual è il grado di altissimo?","answer":"Superlativo assoluto."},{"question":"In «molti studenti», molti è pronome?","answer":"No: accompagna studenti ed è aggettivo indefinito."},{"question":"Come diventa blu al plurale?","answer":"Resta blu: è invariabile."}],"levels":{"base":{"focus":"Trovare il nome descritto","example":{"sentence":"Le stoffe morbide sono sul tavolo.","explanation":"Morbide concorda con stoffe: femminile plurale."}},"consolidamento":{"focus":"Fare l’accordo","example":{"sentence":"Questo è un vecchio amico.","explanation":"Vecchio prima di amico indica qui una relazione di lunga durata."}},"avanzato":{"focus":"Interpretare tipo e grado","example":{"sentence":"Scelgo questi fogli; tu prendi quelli.","explanation":"Questi è aggettivo perché accompagna fogli; quelli è pronome."}}},"simplified":{"lead":"L’aggettivo aggiunge un’informazione al nome.","steps":["Trova il nome: stoffa.","Cerca la parola che la descrive: morbida.","Se dici stoffe, scrivi morbide."],"example":{"sentence":"La stoffa è morbida.","explanation":"Morbida descrive la stoffa."}},"pei":{"rule":"L’aggettivo concorda con il nome: stoffa morbida, stoffe morbide.","example":{"sentence":"La stoffa è morbida.","explanation":"Morbida descrive la stoffa."}},"trackExamples":{"moda":{"sentence":"Queste maniche corte sono pronte.","explanation":"Queste è dimostrativo; corte è qualificativo."},"arredo":{"sentence":"Il tavolo è più largo della scrivania.","explanation":"Più largo esprime un confronto di maggioranza."},"liuteria":{"sentence":"Due tavole sottili sono asciutte.","explanation":"Due è numerale; sottili concorda con tavole."}},"anchor":{"sentence":"Due calzini spaiati hanno molto carattere.","explanation":"Due indica il numero; spaiati una caratteristica. Entrambi accompagnano calzini e sono aggettivi.","memory":"Numero e qualità si appoggiano al nome."}},{"topic":"Pronomi","area":"parole","lead":"Il pronome permette di richiamare persone, cose o idee senza ripetere sempre un nome.","objectives":["Trovare il referente","Riconoscere la funzione","Collegare le proposizioni"],"sections":[{"title":"Sostituire e richiamare","text":"Il pronome può sostituire un nome già espresso oppure indicare direttamente i partecipanti alla comunicazione. In Sara arriva: lei porta il progetto, lei riprende Sara; io e tu identificano chi parla e chi ascolta senza un nome precedente. Per capire un testo occorre trovare il referente, cioè la persona o cosa richiamata. Un pronome ambiguo può creare confusione se due nomi sono ugualmente possibili. Molte forme possono essere anche aggettivi: questo quaderno, scelgo questo. La presenza del nome e il ruolo svolto nella frase aiutano a distinguerle.","examples":[{"sentence":"Sara presenta il progetto. Lei è pronta.","explanation":"Lei riprende Sara ed è soggetto."},{"sentence":"Questo disegno è mio; prendo quello.","explanation":"Quello sostituisce disegno ed è pronome dimostrativo."}]},{"title":"Personali: soggetto e complementi","text":"I personali soggetto sono io, tu, egli, ella, esso, essa, noi, voi, essi, esse; lui, lei e loro sono normali soggetti nell’italiano corrente. I complementi possono avere forme toniche, come me, te, lui, noi, oppure atone, come mi, ti, lo, la, gli, le, ci, vi, li, si, ne. Le forme toniche ricevono rilievo e seguono le preposizioni: per me. Le atone si appoggiano al verbo: mi ascolta, ascoltami. Lo, la, li, le possono essere oggetti; gli e le significano rispettivamente a lui e a lei.","examples":[{"sentence":"La ascolto e le rispondo.","explanation":"La è oggetto; le significa a lei ed è complemento di termine."},{"sentence":"Quel libro è per me.","explanation":"Dopo per si usa la forma tonica me."}]},{"title":"Combinazioni e funzioni","text":"Non riconoscere un pronome soltanto dalle lettere. In le sedie, le è articolo; in le sposto è pronome oggetto; in le telefono significa a lei. Mi, ti, ci, vi cambiano funzione secondo il verbo: mi guarda, mi parla. Ci può indicare anche un luogo: ci andiamo; ne può significare di questo oppure una quantità: ne parliamo, ne prendo due. Combinando due atoni si hanno forme come me lo, te la, glielo. Glielo può significare lo a lui o a lei: il contesto rende chiaro il destinatario.","examples":[{"sentence":"Abbiamo tre campioni: ne scelgo due.","explanation":"Ne riprende i campioni e si accompagna alla quantità due."}]},{"title":"Altre famiglie di pronomi","text":"Possessivi, dimostrativi, indefiniti, numerali, interrogativi ed esclamativi possono sostituire un nome: il mio, quello, qualcuno, due, chi?, quanto! I relativi collegano una subordinata a un antecedente: il libro che leggo. Che è invariabile e svolge funzione di soggetto o oggetto; cui segue normalmente una preposizione: la persona a cui scrivo. Il quale varia e può chiarire il riferimento. Chi può unire il significato di colui che: chi studia impara. Quando analizzi un relativo, cerca sia l’antecedente sia la funzione nella proposizione che esso introduce.","examples":[{"sentence":"Il progetto a cui lavoro è complesso.","explanation":"Cui riprende progetto; a appartiene alla costruzione lavorare a qualcosa."}]},{"title":"Relativi misti o doppi","text":"Alcune parole riuniscono il riferimento a una persona o cosa e il collegamento con una relativa. Chi può significare «colui o colei che»: in Chi ascolta capisce, chi vale come la persona che ascolta. Chiunque può indicare qualunque persona che compia l’azione. Sono detti pronomi relativi misti o doppi perché concentrano due funzioni. Non ogni chi ha questo valore: in Chi arriva? introduce una domanda ed è un pronome interrogativo.","examples":[{"sentence":"Chi costruisce il modello controlla le misure.","explanation":"Chi equivale qui a la persona che e introduce la relativa."},{"sentence":"Chi arriva alla porta?","explanation":"Chi introduce una domanda: qui è interrogativo, non relativo misto."}]},{"title":"Identificativi e riflessivo tonico","text":"Stesso e medesimo possono essere pronomi identificativi quando sostituiscono un nome già noto: scelgo la stessa sottintende, per esempio, la stessa stoffa. Se accompagnano il nome sono aggettivi: scelgo la stessa stoffa. Il pronome tonico sé si riferisce al soggetto di terza persona: Marta porta con sé il quaderno. Davanti a stesso o medesimo si incontrano sia sé stesso sia se stesso: entrambe le grafie sono accettate. Senza questi rafforzativi, non confondere sé pronome con se congiunzione.","examples":[{"sentence":"Ho scelto la stessa.","explanation":"Stessa sostituisce un nome femminile già noto ed è pronome identificativo."},{"sentence":"Luca porta il quaderno con sé.","explanation":"Sé è pronome tonico riferito al soggetto Luca."},{"sentence":"Nora pensa a sé stessa; si trova anche «se stessa».","explanation":"Con stessa sono ammesse entrambe le grafie del pronome rafforzato."}]}],"diagram":{"title":"Pronomi: i collegamenti da ricordare","steps":[{"label":"Personali","detail":"Io, tu, lui; mi, lo, le: partecipanti e referenti."},{"label":"Altre famiglie","detail":"Questo, mio, qualcuno, chi: sostituiscono o indicano referenti."},{"label":"Relativi","detail":"Che e cui collegano una subordinata a un antecedente."},{"label":"Funzione","detail":"Il pronome può essere soggetto, oggetto o altro complemento."}]},"pitfalls":[{"mistake":"Ho telefonato a Marta: gli ho parlato.","correction":"Ho telefonato a Marta: le ho parlato.","why":"Nello standard le significa a lei; gli significa a lui."},{"mistake":"La persona che ho scritto","correction":"La persona a cui ho scritto","why":"Scrivere a qualcuno richiede il complemento introdotto da a."}],"recap":["Il referente deve essere chiaro.","Un pronome può svolgere funzioni diverse.","La stessa forma può essere articolo o pronome.","Il relativo ha un ruolo nella propria proposizione."],"review":[{"question":"In «le telefono», che cosa significa le?","answer":"A lei: è un pronome personale con funzione di termine."},{"question":"Qual è l’antecedente in «il libro che leggo»?","answer":"Il libro; che lo riprende come oggetto di leggo."},{"question":"In «scelgo questo», questo è aggettivo?","answer":"No: sostituisce un nome ed è pronome."}],"levels":{"base":{"focus":"Trovare il referente","example":{"sentence":"Sara presenta il progetto. Lei è pronta.","explanation":"Lei riprende Sara ed è soggetto."}},"consolidamento":{"focus":"Riconoscere la funzione","example":{"sentence":"La ascolto e le rispondo.","explanation":"La è oggetto; le significa a lei ed è complemento di termine."}},"avanzato":{"focus":"Collegare le proposizioni","example":{"sentence":"Il progetto a cui lavoro è complesso.","explanation":"Cui riprende progetto; a appartiene alla costruzione lavorare a qualcosa."}}},"simplified":{"lead":"Il pronome richiama qualcuno o qualcosa senza ripetere il nome.","steps":["Trova il nome già scritto.","Cerca la parola che lo richiama.","Verifica che si capisca di chi o di che cosa si parla."],"example":{"sentence":"Vedo il banco. Lo pulisco.","explanation":"Lo richiama il banco."}},"pei":{"rule":"Lo può sostituire un nome maschile singolare.","example":{"sentence":"Vedo il banco. Lo pulisco.","explanation":"Lo richiama il banco."}},"trackExamples":{"moda":{"sentence":"La sarta misura la manica e la accorcia.","explanation":"Il pronome la riprende la manica."},"arredo":{"sentence":"Consegno il disegno a Luca: glielo consegno oggi.","explanation":"Glielo combina lo, il disegno, e gli, a Luca."},"liuteria":{"sentence":"Le corde che monto sono nuove.","explanation":"Che riprende corde ed è oggetto di monto."}},"anchor":{"sentence":"Il biscotto era qui. Qualcuno lo ha visto?","explanation":"Lo richiama il biscotto senza ripeterne il nome; qualcuno indica una persona non precisata.","memory":"Lo rimanda al biscotto scomparso."}},{"topic":"Avverbi","area":"parole","lead":"L’avverbio precisa un verbo, un aggettivo, un altro avverbio o il significato di un’intera frase.","objectives":["Trovare che cosa viene precisato","Riconoscere il significato","Controllare funzione e posizione"],"sections":[{"title":"Una parola che precisa","text":"L’avverbio è una parte invariabile del discorso: non cambia per accordarsi con un nome. Può spiegare come avviene un’azione, dove o quando si svolge, quanto è intensa, oppure esprimere un punto di vista. In lavora bene precisa il verbo; in molto preciso modifica un aggettivo; in davvero lentamente modifica un altro avverbio. In forse pioverà introduce una valutazione di possibilità sull’intera frase. Per riconoscerlo osserva quindi non soltanto il suo significato, ma anche l’elemento a cui si collega. Una parola isolata non basta sempre per classificarla.","examples":[{"sentence":"Gli studenti lavorano lentamente.","explanation":"Lentamente precisa il modo dell’azione lavorano."},{"sentence":"Il disegno è molto preciso.","explanation":"Molto modifica l’aggettivo preciso."}]},{"title":"Tipi e locuzioni","text":"Gli avverbi di modo indicano una maniera: bene, male, lentamente. Quelli di tempo situano gli eventi: oggi, ieri, presto, spesso. Quelli di luogo orientano nello spazio: qui, là, sopra, vicino. Quelli di quantità o grado indicano intensità: molto, poco, troppo, abbastanza. Ci sono inoltre avverbi di affermazione, negazione e dubbio: certamente, non, forse. Le locuzioni avverbiali sono gruppi di parole con una funzione analoga: a poco a poco, di tanto in tanto, all’improvviso. Alcune classificazioni possono variare nei dettagli: il significato nella frase resta il primo controllo.","examples":[{"sentence":"Di tanto in tanto controlliamo la misura.","explanation":"La locuzione indica frequenza e ha valore avverbiale."},{"sentence":"La stoffa cade bene, questa cade meglio.","explanation":"Meglio è il comparativo di bene."}]},{"title":"Forma e confronto","text":"Molti avverbi di modo si formano con -mente a partire da un aggettivo: lenta diventa lentamente; gentile diventa gentilmente. Non tutti, però, finiscono così: bene è un avverbio. Alcuni aggettivi si usano con valore avverbiale e restano invariabili: parlare chiaro, andare piano. Molti avverbi ammettono gradi: più lentamente, molto bene, prestissimo. Bene ha il comparativo meglio e il superlativo benissimo; male ha peggio e malissimo. Non tutti i significati sono graduabili: qui non forma normalmente un comparativo. Prima di aggiungere più verifica se una forma esprime già il confronto.","examples":[{"sentence":"Le allieve parlano chiaro.","explanation":"Chiaro è usato con valore avverbiale e non concorda con allieve."}]},{"title":"Posizione e parole simili","text":"La posizione dell’avverbio può modificare l’informazione messa in risalto: solo Luca legge e Luca legge solo romanzi non dicono la stessa cosa. Nelle negazioni standard, «non» precede il verbo; nessuno dopo il verbo richiede normalmente non: non arriva nessuno. Molto può essere aggettivo in molta pazienza, pronome in molti partecipano, avverbio in lavora molto: solo l’ultimo uso è invariabile. Sopra può funzionare da avverbio in guarda sopra oppure da preposizione in sopra il tavolo. Per decidere leggi la costruzione completa, cerca il legame con le altre parole e prova una parafrasi.","examples":[{"sentence":"Solo Marta legge; Marta legge solo racconti.","explanation":"Nella prima frase è esclusa ogni altra persona; nella seconda ogni altro tipo di testo."}]},{"title":"Avverbi interrogativi, esclamativi e alterati","text":"Dove, quando, come, perché e quanto possono introdurre una domanda diretta o indiretta quando precisano luogo, tempo, modo, causa o quantità: dove lavori? e non so dove lavori. Come e quanto possono anche introdurre esclamazioni: quanto corre! Alcuni avverbi hanno forme alterate che aggiungono una sfumatura: benino, maluccio, pochino o prestino. Il loro valore dipende dal contesto e non coincide necessariamente con un superlativo: benissimo esprime intensità, benino spesso un giudizio moderato.","examples":[{"sentence":"Quando arriva il tessuto? Non so quando arriverà.","explanation":"Quando introduce una domanda diretta e poi una domanda indiretta."},{"sentence":"Quanto corre il treno!","explanation":"Quanto introduce un’esclamazione riferita all’intensità del correre."}]}],"diagram":{"title":"Avverbi: i collegamenti da ricordare","steps":[{"label":"Che cosa modificano","detail":"Verbo, aggettivo, altro avverbio o intera frase."},{"label":"Significati","detail":"Modo, tempo, luogo, quantità, affermazione, negazione, dubbio."},{"label":"Forma","detail":"Sono invariabili: lavora molto, lavorano molto."},{"label":"Locuzioni e gradi","detail":"A poco a poco; bene, meglio, benissimo."}]},"pitfalls":[{"mistake":"Le ragazze lavorano molte.","correction":"Le ragazze lavorano molto.","why":"Molto è avverbio riferito a lavorano e resta invariabile."},{"mistake":"Più meglio","correction":"Meglio","why":"Meglio contiene già il valore comparativo."}],"recap":["L’avverbio è invariabile.","Può modificare elementi diversi della frase.","Una locuzione avverbiale contiene più parole.","Posizione e costruzione aiutano a riconoscerne il valore."],"review":[{"question":"Molto è sempre avverbio?","answer":"No: in molti fogli è aggettivo; in lavora molto è avverbio."},{"question":"Qual è il comparativo di bene?","answer":"Meglio."},{"question":"Che cosa precisa ieri in «ieri siamo usciti»?","answer":"Il tempo in cui si svolge l’evento."}],"levels":{"base":{"focus":"Trovare che cosa viene precisato","example":{"sentence":"Gli studenti lavorano lentamente.","explanation":"Lentamente precisa il modo dell’azione lavorano."}},"consolidamento":{"focus":"Riconoscere il significato","example":{"sentence":"Di tanto in tanto controlliamo la misura.","explanation":"La locuzione indica frequenza e ha valore avverbiale."}},"avanzato":{"focus":"Controllare funzione e posizione","example":{"sentence":"Solo Marta legge; Marta legge solo racconti.","explanation":"Nella prima frase è esclusa ogni altra persona; nella seconda ogni altro tipo di testo."}}},"simplified":{"lead":"L’avverbio può dire come, dove o quando avviene un fatto.","steps":["Trova il verbo: cammina.","Cerca una parola che lo precisa: lentamente.","L’avverbio non cambia se il soggetto è plurale."],"example":{"sentence":"Luca cammina lentamente.","explanation":"Lentamente dice come cammina."}},"pei":{"rule":"Lentamente dice come avviene l’azione.","example":{"sentence":"Luca cammina lentamente.","explanation":"Lentamente dice come cammina."}},"trackExamples":{"moda":{"sentence":"La macchina cuce lentamente.","explanation":"Lentamente precisa il modo dell’azione."},"arredo":{"sentence":"Il mobile è abbastanza stabile.","explanation":"Abbastanza indica il grado dell’aggettivo stabile."},"liuteria":{"sentence":"Oggi accordiamo lo strumento.","explanation":"Oggi situa l’azione nel tempo."}},"anchor":{"sentence":"La lumaca arriva lentamente, ma arriva.","explanation":"Lentamente precisa come arriva la lumaca. È avverbio e resterebbe uguale parlando di due lumache.","memory":"Due lumache arrivano ancora lentamente."}},{"topic":"Preposizioni","area":"parole","lead":"Le preposizioni collegano parole e gruppi di parole, mostrando relazioni che si capiscono dal contesto.","objectives":["Trovare il collegamento","Ricostruire la forma","Capire la relazione"],"sections":[{"title":"Collegare elementi","text":"Una preposizione introduce un gruppo che dipende da un nome, un aggettivo, un verbo o un’altra espressione. Può specificare un rapporto di luogo, tempo, possesso, mezzo e molti altri significati. In il quaderno di Sara collega il nome quaderno alla persona cui appartiene; in penso a Sara completa il significato di penso. Le preposizioni non hanno genere e numero. Non vanno però interpretate come etichette automatiche: a può introdurre un destinatario, un luogo o un orario. Per capire la relazione leggi l’intera frase e considera il verbo o il nome reggente.","examples":[{"sentence":"Consegno il foglio a Luca.","explanation":"A introduce il destinatario della consegna."},{"sentence":"Andiamo a Cremona alle nove.","explanation":"A Cremona indica destinazione; alle nove indica tempo."}]},{"title":"Semplici e articolate","text":"Le preposizioni semplici sono di, a, da, in, con, su, per, tra e fra. Tra e fra hanno lo stesso significato; spesso si sceglie la forma che evita ripetizioni di suono. Di, a, da, in e su si uniscono agli articoli determinativi formando preposizioni articolate: del, allo, dalla, negli, sulle. Genere e numero dell’articolo dipendono dal nome; la sua forma fonetica dipende dalla parola immediatamente successiva: allo studente, al bravo studente. Con il e con i possono diventare col e coi, ma le forme separate sono normali; per lo e per il restano normalmente separati nell’uso contemporaneo.","examples":[{"sentence":"Gli attrezzi sono negli armadi.","explanation":"Negli unisce in e gli."},{"sentence":"Il banco è davanti alla finestra.","explanation":"Davanti a è una locuzione; a si unisce a la formando alla."}]},{"title":"Improprie e locuzioni","text":"Alcune parole funzionano da preposizioni pur appartenendo, in altri usi, ad altre categorie: durante la lezione, dopo cena, sopra il banco, secondo me. Si chiamano tradizionalmente preposizioni improprie. Se manca il gruppo introdotto, alcune possono essere avverbi: salgo sopra. Le locuzioni prepositive sono gruppi con funzione di preposizione: vicino a, davanti a, a causa di, per mezzo di. La preposizione finale fa parte della costruzione: davanti alla porta. Non cancellarla solo perché la locuzione contiene già più parole. Per capire il valore puoi sostituire il gruppo con una parafrasi equivalente.","examples":[{"sentence":"Durante la prova ascolto con attenzione.","explanation":"Durante introduce il tempo; con attenzione precisa il modo."}]},{"title":"Usare la costruzione giusta","text":"La scelta della preposizione dipende anche dalle parole che la richiedono: partecipare a una gara, dipendere da una decisione, essere capace di ascoltare. Non esiste una sola traduzione valida in ogni lingua: chi impara italiano deve memorizzare piccoli gruppi di parole. Con i luoghi sono frequenti a Roma, in Italia, a scuola, in laboratorio; l’articolo può cambiare la costruzione: nella scuola del quartiere. Del può essere anche articolo partitivo: compro del pane, cioè un po’ di pane. In il prezzo del pane, invece, collega due nomi ed è preposizione articolata. Il significato risolve la distinzione.","examples":[{"sentence":"Compro del pane e controllo il prezzo del pane.","explanation":"Il primo del è partitivo; il secondo è preposizione articolata."}]}],"diagram":{"title":"Preposizioni: i collegamenti da ricordare","steps":[{"label":"Semplici","detail":"Di, a, da, in, con, su, per, tra, fra."},{"label":"Articolate","detail":"Preposizione più articolo: a + gli = agli."},{"label":"Improprie e locuzioni","detail":"Durante la lezione; davanti alla porta."},{"label":"Relazione","detail":"La stessa preposizione può esprimere significati diversi."}]},"pitfalls":[{"mistake":"A gli studenti","correction":"Agli studenti","why":"A e gli formano la preposizione articolata agli."},{"mistake":"Partecipare di una gara","correction":"Partecipare a una gara","why":"In questo significato partecipare richiede a."}],"recap":["La preposizione collega elementi.","Le articolate uniscono preposizione e articolo.","Una stessa preposizione introduce rapporti diversi.","Alcune costruzioni vanno apprese insieme alla parola reggente."],"review":[{"question":"Come si forma sulle?","answer":"Su più le."},{"question":"A indica sempre il termine?","answer":"No: in a Roma può indicare un luogo."},{"question":"In «davanti alla porta», qual è la locuzione di partenza?","answer":"Davanti a; a più la forma alla."}],"levels":{"base":{"focus":"Trovare il collegamento","example":{"sentence":"Consegno il foglio a Luca.","explanation":"A introduce il destinatario della consegna."}},"consolidamento":{"focus":"Ricostruire la forma","example":{"sentence":"Gli attrezzi sono negli armadi.","explanation":"Negli unisce in e gli."}},"avanzato":{"focus":"Capire la relazione","example":{"sentence":"Compro del pane e controllo il prezzo del pane.","explanation":"Il primo del è partitivo; il secondo è preposizione articolata."}}},"simplified":{"lead":"La preposizione collega parole e gruppi di parole.","steps":["Trova una parola breve come di, a, con.","Leggi anche ciò che viene prima e dopo.","Chiediti quale rapporto viene espresso."],"example":{"sentence":"Taglio con le forbici.","explanation":"Con collega il verbo allo strumento."}},"pei":{"rule":"Con può indicare lo strumento usato.","example":{"sentence":"Taglio con le forbici.","explanation":"Con collega il verbo allo strumento."}},"trackExamples":{"moda":{"sentence":"Il cartamodello è sul tavolo.","explanation":"Sul unisce su e il."},"arredo":{"sentence":"La mensola è vicino alla finestra.","explanation":"Vicino a collega la mensola al suo riferimento spaziale."},"liuteria":{"sentence":"La custodia dello strumento è chiusa.","explanation":"Dello unisce di e lo e collega custodia a strumento."}},"anchor":{"sentence":"Il gatto dorme sul progetto di Luca.","explanation":"Sul collega dorme al luogo; di collega progetto alla persona cui appartiene. Le relazioni sono diverse.","memory":"Le preposizioni mostrano i collegamenti."}},{"topic":"Congiunzioni","area":"parole","lead":"Le congiunzioni collegano parole o proposizioni e rendono esplicito il rapporto fra le informazioni.","objectives":["Trovare gli elementi collegati","Riconoscere il rapporto","Controllare la costruzione"],"sections":[{"title":"Collegare parole e frasi","text":"Una congiunzione è invariabile. Può collegare parole che svolgono un ruolo simile, come legno e metallo, oppure proposizioni, come disegno e controllo le misure. Il collegamento non è soltanto una giustapposizione: può aggiungere, opporre, spiegare una causa o porre una condizione. Per analizzare correttamente conta i nuclei verbali e individua gli elementi effettivamente uniti. In compro carta e colla, e unisce due nomi; in compro la carta e preparo il disegno unisce due proposizioni. Il significato del rapporto aiuta poi a scegliere la congiunzione più adatta.","examples":[{"sentence":"Porto carta e colla.","explanation":"E collega due nomi con la stessa funzione."},{"sentence":"Il progetto è semplice ma efficace.","explanation":"Ma contrappone due caratteristiche senza creare una dipendenza."}]},{"title":"Coordinare","text":"Le congiunzioni coordinanti collegano elementi sullo stesso piano sintattico. Le copulative aggiungono: e, anche, né. Le disgiuntive presentano alternative: o, oppure. Le avversative esprimono un contrasto: ma, però, tuttavia. Le esplicative chiariscono: cioè, infatti. Le conclusive introducono una conseguenza o conclusione: quindi, dunque. Le correlative lavorano in coppia: sia… sia, né… né, o… o. Alcune grammatiche trattano parole come quindi e tuttavia anche come avverbi con funzione di collegamento: è utile riconoscere anzitutto il rapporto logico che costruiscono fra gli enunciati.","examples":[{"sentence":"Scegliamo legno oppure metallo.","explanation":"Oppure presenta un’alternativa."},{"sentence":"Resto perché piove.","explanation":"Perché introduce la causa della permanenza."}]},{"title":"Subordinare","text":"Le subordinanti introducono proposizioni che dipendono da un’altra. Possono completare ciò che un verbo esprime, come penso che arriverà, oppure indicare tempo, causa, scopo, condizione, concessione o conseguenza. Fra le forme frequenti troviamo quando, mentre, perché, se, benché, affinché, così… che. Esistono locuzioni congiuntive formate da più parole: prima che, a meno che, dal momento che. Per scegliere il modo verbale bisogna considerare la costruzione: benché e affinché richiedono normalmente il congiuntivo. Non si decide il modo soltanto dal grado di certezza personale: contano anche le regole della frase.","examples":[{"sentence":"Ti aiuto affinché tu riesca.","explanation":"Affinché introduce uno scopo e richiede qui il congiuntivo riesca."}]},{"title":"Distinguere gli usi nel contesto","text":"Una stessa forma può esprimere rapporti diversi. Perché introduce una causa in resto perché piove, uno scopo in te lo spiego perché tu capisca e una domanda in perché ridi? Nell’ultimo caso ha valore interrogativo. Che può essere congiunzione in so che arrivi, ma pronome relativo in il foglio che leggo: il relativo riprende un nome e svolge una funzione nella subordinata. Evita connettivi in contrasto con il ragionamento: quindi annuncia una conclusione, ma introduce un’opposizione. Prima di scegliere, esprimi con parole semplici il legame fra le informazioni e verifica che il testo lo renda chiaro.","examples":[{"sentence":"So che arrivi; leggo il messaggio che mandi.","explanation":"Il primo che è congiunzione; il secondo è relativo e riprende messaggio."}]}],"diagram":{"title":"Congiunzioni: i collegamenti da ricordare","steps":[{"label":"Coordinanti","detail":"Uniscono elementi sullo stesso piano: e, ma, oppure."},{"label":"Subordinanti","detail":"Introducono una dipendenza: perché, se, benché."},{"label":"Relazioni","detail":"Aggiunta, alternativa, contrasto, causa, scopo, condizione."},{"label":"Costruzione","detail":"Con benché e affinché si usa normalmente il congiuntivo."}]},"pitfalls":[{"mistake":"Benché piove, usciamo.","correction":"Benché piova, usciamo.","why":"Benché richiede normalmente il congiuntivo."},{"mistake":"È fragile, quindi è resistente.","correction":"È fragile, quindi va protetto.","why":"La conclusione deve essere coerente con la premessa."}],"recap":["Le coordinanti collegano elementi sullo stesso piano.","Le subordinanti introducono una dipendenza.","I connettivi rendono espliciti i rapporti logici.","La stessa parola può avere usi diversi."],"review":[{"question":"In «carta e colla», e collega proposizioni?","answer":"No: collega due nomi."},{"question":"Che rapporto esprime ma?","answer":"Un’opposizione o un contrasto."},{"question":"Perché è sempre causale?","answer":"No: può introdurre anche uno scopo o una domanda."}],"levels":{"base":{"focus":"Trovare gli elementi collegati","example":{"sentence":"Porto carta e colla.","explanation":"E collega due nomi con la stessa funzione."}},"consolidamento":{"focus":"Riconoscere il rapporto","example":{"sentence":"Scegliamo legno oppure metallo.","explanation":"Oppure presenta un’alternativa."}},"avanzato":{"focus":"Controllare la costruzione","example":{"sentence":"So che arrivi; leggo il messaggio che mandi.","explanation":"Il primo che è congiunzione; il secondo è relativo e riprende messaggio."}}},"simplified":{"lead":"La congiunzione collega parole o frasi.","steps":["Cerca e, ma, oppure, perché.","Leggi le due parti collegate.","Chiediti se aggiungono, contrastano o spiegano qualcosa."],"example":{"sentence":"Prendo carta e colla.","explanation":"E unisce carta e colla."}},"pei":{"rule":"E può unire due nomi.","example":{"sentence":"Prendo carta e colla.","explanation":"E unisce carta e colla."}},"trackExamples":{"moda":{"sentence":"Scelgo il lino perché è fresco.","explanation":"Perché introduce una causa."},"arredo":{"sentence":"Il pannello è leggero ma robusto.","explanation":"Ma mette in contrasto due caratteristiche."},"liuteria":{"sentence":"Controllo le corde affinché la prova riesca.","explanation":"Affinché introduce lo scopo del controllo."}},"anchor":{"sentence":"Volevo dormire, ma il bus è arrivato.","explanation":"Ma collega due proposizioni e segnala il contrasto fra il desiderio e ciò che accade.","memory":"Ma introduce una svolta nel ragionamento."}},{"topic":"Ortografia","area":"parole","lead":"L’ortografia raccoglie le convenzioni che permettono di scrivere le parole in modo riconoscibile e condiviso.","objectives":["Riconoscere i punti difficili","Distinguere accento e apostrofo","Rivedere la frase"],"sections":[{"title":"Suoni e lettere","text":"Nell’italiano scritto un suono non corrisponde sempre a una sola lettera. Ch e gh mantengono il suono duro davanti a e e i: chiave, ghiro. Ci e gi possono indicare il suono dolce davanti ad altre vocali: ciotola, giacca. Nei gruppi sce e sci la scrittura dipende dalla parola: scena non contiene i, mentre scienza e coscienza la conservano. Il suono di gn si scrive normalmente senza i prima di a, e, o, u: campagna; fanno eccezione forme come compagnia. Per parole dubbie consulta il dizionario, perché la pronuncia da sola può non bastare.","examples":[{"sentence":"La pala è accanto alla palla.","explanation":"La consonante doppia distingue due parole diverse."},{"sentence":"La camicia ha due tasche; le camicie sono pronte.","explanation":"Nel plurale di camicia la i si conserva perché c è preceduta da vocale."}]},{"title":"Doppie e gruppi difficili","text":"Le consonanti doppie possono cambiare il significato: pala e palla, casa e cassa. Pronunciare lentamente aiuta, ma gli usi regionali possono rendere il controllo meno sicuro: occorre conoscere la forma scritta. Davanti a p e b si scrive normalmente m: campo, gamba. Per il suono di cuore e quadro si usano grafie diverse: cu, qu e cqu non si possono scegliere a caso. Acqua e acquisto hanno cqu; scuola e cuoco hanno cu. Nei plurali in -cia e -gia, la i si conserva se prima c’è una vocale: camicie; di solito cade dopo consonante: arance. Se la i è tonica, si mantiene: farmacie.","examples":[{"sentence":"Il progetto è semplice e chiaro.","explanation":"È è verbo essere; e collega due aggettivi."},{"sentence":"Un amico aspetta un’amica.","explanation":"Un maschile non ha apostrofo; un’ femminile deriva dall’elisione di una."}]},{"title":"Accento e apostrofo","text":"L’accento scritto segnala la vocale tonica in alcune parole e distingue forme diverse: è verbo, e congiunzione; dà verbo, da preposizione; sì affermazione, si pronome. Nei polisillabi italiani tronchi terminanti in vocale è obbligatorio: città, perché. Qui e qua non lo richiedono. L’apostrofo segnala spesso un’elisione: l’amica, un’amica. Un maschile davanti a vocale resta senza apostrofo: un amico. Il troncamento può non avere apostrofo: qual è, buon giorno; po’ è invece la forma troncata di poco e si scrive con apostrofo, non con accento. Dopo un apostrofo interno alla parola non si mette uno spazio.","examples":[{"sentence":"Qual è il tuo banco?","explanation":"Qual è si scrive senza apostrofo."}]},{"title":"H, separazioni e revisione","text":"La h distingue alcune forme di avere da parole omofone: ho e o, hai e ai, ha e a, hanno e anno. Prova a cambiare il tempo: se ha diventa aveva, stai usando il verbo. Distingui anche ce n’è, cioè ce ne è, da ce ne: ce ne sono due. Alcune espressioni hanno grafia fissa: a posto, d’accordo, soprattutto, un po’. Durante la revisione controlla separatamente lettere, accenti e divisione delle parole: leggere soltanto per il significato fa sfuggire errori frequenti. Un correttore automatico può aiutare, ma non riconosce sempre una parola corretta usata nella frase sbagliata.","examples":[{"sentence":"Marta ha il metro e va a scuola.","explanation":"Ha è verbo avere; a è preposizione. Possiamo dire Marta aveva il metro."}]},{"title":"Accento: quando serve","text":"L’accento tonico è la maggiore intensità con cui si pronuncia una sillaba; l’accento grafico è il segno scritto. Nei polisillabi italiani terminanti in vocale e accentati sull’ultima sillaba il segno è obbligatorio: libertà, lunedì, perché. Molti monosillabi non lo richiedono: qui, qua, fu, fa. Alcuni monosillabi lo portano per distinguersi da parole uguali nella forma ma diverse nella funzione: dà verbo e da preposizione; lì avverbio e li pronome; sì affermazione e si pronome. Non confondere l’accento con l’apostrofo: è e un po’ hanno segni e funzioni diversi.","examples":[{"sentence":"Lì c’è il cassetto; li ripongo più tardi.","explanation":"Lì indica un luogo; li è un pronome e non porta l’accento."},{"sentence":"Il corso finì lunedì.","explanation":"Finì e lunedì hanno l’accento sull’ultima sillaba, indicato nella scrittura."}]},{"title":"Maiuscole e parole da distinguere","text":"Usa la maiuscola all’inizio di un testo e dopo un punto che chiude una frase; usala nei nomi propri di persone e luoghi: Nora, Cremona. Dopo due punti la maiuscola dipende dalla costruzione, per esempio può introdurre una citazione diretta. Alcune parole simili si distinguono dal loro significato: l’anno è un periodo di dodici mesi, hanno è una voce di avere; la può essere un articolo, là indica un luogo. Controlla anche i confini delle parole: a volte si scrive separato, invece avvolte è una forma del verbo avvolgere. Se una parola ha più grafie possibili, consulta il dizionario e il contesto.","examples":[{"sentence":"A volte le stoffe sono avvolte nella carta.","explanation":"A volte significa talvolta; avvolte descrive le stoffe ed è una forma di avvolgere."},{"sentence":"Nora vive a Cremona. Studia liuteria.","explanation":"Nora e Cremona sono nomi propri; Studia inizia una nuova frase."}]},{"title":"Accento grave e acuto sulla e","text":"La e finale accentata può essere scritta con accento grave, è, oppure acuto, é. Nella grafia standard perché, poiché e affinché vogliono é; caffè, cioè ed è verbo vogliono è. Anche ventitré e sé pronome prendono l’acuto. Il segno corrisponde di norma alla differenza fra e aperta ed e chiusa, ma la pronuncia varia tra le regioni: quando hai un dubbio controlla il dizionario. Il monosillabo tre, senza prefisso, non ha accento.","examples":[{"sentence":"Perché il caffè è pronto?","explanation":"Perché porta l’acuto; caffè ed è portano il grave."},{"sentence":"I campioni sono ventitré, non tre.","explanation":"Ventitré porta l’accento grafico; tre da solo non lo richiede."}]},{"title":"Grafie vicine: ce, cie, li, gli e consonanti doppie","text":"Il suono non basta sempre per scegliere tutte le lettere. Cielo e cieco si scrivono con cie, mentre cena e cento si scrivono con ce. Foglia contiene il gruppo gli; parole come Italia e vigilia si scrivono con li. Il contesto e la famiglia di parole aiutano, ma le grafie vanno conosciute e, nel dubbio, controllate nel dizionario. Acqua e acquisto hanno cqu; soqquadro si scrive invece con qq. Non ricavare automaticamente la grafia di ogni parola da una sola somiglianza di suono.","examples":[{"sentence":"Il cielo è chiaro sopra la città.","explanation":"Cielo si scrive con cie."},{"sentence":"La foglia è accanto al libro sulla storia d’Italia.","explanation":"Foglia contiene gli; Italia contiene li."},{"sentence":"La stanza è a soqquadro.","explanation":"Soqquadro si scrive con qq."}]},{"title":"Elisione, forma intera e parole vicine","text":"Nell’elisione una vocale finale cade davanti a una vocale e l’apostrofo segnala la caduta: un’amica deriva da una amica. Con gli articoli femminili la e una davanti a vocale piena, la forma elisa è comune, ma si può anche mantenere la forma intera: l’insegnante o la insegnante, un’amica o una amica. Un maschile invece non prende apostrofo: un amico. Non sostituire l’apostrofo con un accento e non inserire uno spazio dopo l’apostrofo nella forma elisa.","examples":[{"sentence":"L’insegnante entra; anche «la insegnante entra» è possibile.","explanation":"La può elidersi davanti a vocale oppure rimanere intero."},{"sentence":"Ho incontrato un’amica; «una amica» è possibile.","explanation":"L’apostrofo compare soltanto nella forma elisa un’."}]}],"diagram":{"title":"Ortografia: i collegamenti da ricordare","steps":[{"label":"Lettere","detail":"Controlla doppie e gruppi: palla, chiave, acqua."},{"label":"Accento","detail":"È verbo; e congiunzione. Città ha accento finale."},{"label":"Apostrofo","detail":"Un’amica; un amico. Po’ sì, qual è senza apostrofo."},{"label":"Parole omofone","detail":"Ho, hai, ha, hanno sono forme del verbo avere."}]},"pitfalls":[{"mistake":"Un pò","correction":"Un po’","why":"Po’ è troncamento di poco con apostrofo."},{"mistake":"Qual’è","correction":"Qual è","why":"Qual è un troncamento che non richiede apostrofo."}],"recap":["La grafia non si ricava sempre dalla pronuncia.","Le doppie possono distinguere parole diverse.","Accento e apostrofo hanno funzioni diverse.","Il contesto distingue parole che si pronunciano allo stesso modo."],"review":[{"question":"Come distinguo ha da a?","answer":"Ha è verbo avere e può diventare aveva; a è preposizione."},{"question":"Perché scrivo un ago senza apostrofo?","answer":"Ago è maschile e un è già la forma corretta."},{"question":"Qual è la grafia corretta di un poco abbreviato?","answer":"Un po’, con apostrofo."}],"levels":{"base":{"focus":"Riconoscere i punti difficili","example":{"sentence":"La pala è accanto alla palla.","explanation":"La consonante doppia distingue due parole diverse."}},"consolidamento":{"focus":"Distinguere accento e apostrofo","example":{"sentence":"Il progetto è semplice e chiaro.","explanation":"È è verbo essere; e collega due aggettivi."}},"avanzato":{"focus":"Rivedere la frase","example":{"sentence":"Marta ha il metro e va a scuola.","explanation":"Ha è verbo avere; a è preposizione. Possiamo dire Marta aveva il metro."}}},"simplified":{"lead":"Le parole si scrivono secondo regole condivise.","steps":["Controlla se serve h: ho un libro.","Distingui e da è: è un verbo.","Scrivi un ago senza apostrofo."],"example":{"sentence":"Ho un quaderno.","explanation":"Ho indica che possiedo il quaderno."}},"pei":{"rule":"Ho, con h, è una forma del verbo avere.","example":{"sentence":"Ho un quaderno.","explanation":"Ho indica che possiedo il quaderno."}},"trackExamples":{"moda":{"sentence":"La sarta ha un ago.","explanation":"Ha è verbo e un ago non vuole apostrofo."},"arredo":{"sentence":"Il mobile è già a posto.","explanation":"È ha l’accento; a posto si scrive in due parole."},"liuteria":{"sentence":"C’è un po’ di colla sul banco.","explanation":"C’è contiene ci ed è; po’ si scrive con apostrofo."}},"anchor":{"sentence":"Ho un ago, non un drago.","explanation":"Ho è verbo avere e richiede h. Un ago è maschile: un non vuole apostrofo, neppure davanti alla vocale.","memory":"Ho con h; un ago senza apostrofo."}},{"topic":"Modi verbali","area":"parole","lead":"Il modo verbale mostra come presentiamo un fatto: come affermazione, possibilità, richiesta o azione dipendente da un’altra.","objectives":["Riconoscere i modi finiti","Usare le costruzioni","Interpretare i modi indefiniti"],"sections":[{"title":"Modi finiti e persone","text":"I modi finiti sono indicativo, congiuntivo, condizionale e imperativo. Le loro forme permettono normalmente di riconoscere la persona grammaticale, anche se alcune coincidono: che io parli, che tu parli, che lui parli. L’indicativo presenta fatti come affermati o descritti: studio, studiavo, studierò. Può parlare anche di fatti immaginati o incerti nel futuro: non è una garanzia che accadranno. Il modo si sceglie considerando insieme il significato e la costruzione della frase. Prima di analizzarlo riconosci l’intera forma verbale: avrei studiato appartiene al condizionale, pur contenendo un participio.","examples":[{"sentence":"Oggi studio; domani studierò.","explanation":"Entrambe le forme sono all’indicativo, ma hanno tempi diversi."},{"sentence":"Sono contenta che tu sia qui.","explanation":"Il congiuntivo sia si riferisce a una presenza reale."}]},{"title":"Congiuntivo e condizionale","text":"Il congiuntivo compare spesso in subordinate dipendenti da desiderio, dubbio, valutazione o necessità: spero che arrivi, è necessario che ascolti. Alcune congiunzioni lo richiedono: benché piova, affinché riesca. Non significa sempre irrealtà: sono contento che tu sia qui può riferirsi a una presenza reale. Il condizionale esprime possibilità legata a una condizione, desiderio, richiesta cortese oppure un’informazione non confermata: verrei, vorrei, potresti aiutarmi? Nel periodo ipotetico dell’eventualità si usa se più congiuntivo e condizionale nella conseguenza: se avessi tempo, verrei. Evita il condizionale dopo questo se.","examples":[{"sentence":"Se avessi il metro, misurerei il ripiano.","explanation":"Avessi è congiuntivo; misurerei è condizionale."},{"sentence":"Potresti passarmi il foglio?","explanation":"Il condizionale rende cortese la richiesta."}]},{"title":"Imperativo e richieste","text":"L’imperativo serve a dare istruzioni, fare inviti, esprimere consigli e ordini: ascolta, entrate. Il tono dipende dalla situazione, dalle parole aggiunte e dalla relazione fra le persone. Per le forme di cortesia si usa il congiuntivo con valore esortativo: entri, ascolti. Nell’imperativo negativo di seconda persona singolare si usa non più infinito: non correre. I pronomi atoni possono unirsi al verbo: ascoltami, prendilo; con non si può dire non prenderlo oppure non lo prendere. Distinguere un ordine da una richiesta cortese aiuta a scrivere istruzioni adeguate a chi le riceve.","examples":[{"sentence":"Non correre in laboratorio.","explanation":"L’imperativo negativo rivolto a tu usa l’infinito."}]},{"title":"Modi indefiniti e forme composte","text":"Infinito, participio e gerundio sono modi indefiniti: normalmente non esprimono la persona come i modi finiti. L’infinito nomina il processo: leggere, avere letto; può avere valore di nome in il leggere. Il participio ha forme presente e passato: cantante, cantato; può diventare aggettivo o nome. Il gerundio collega azioni: camminando, avendo camminato. Il suo soggetto va reso chiaro: entrando in aula, ho salutato significa che sono entrato io. Le forme composte indicano spesso anteriorità: dopo avere letto rispetto a un’azione successiva. Nell’analisi distingue modo e tempo: indicativo presente è una combinazione, non un’unica categoria.","examples":[{"sentence":"Entrando in aula, ho salutato.","explanation":"Il soggetto del gerundio è lo stesso di ho salutato: io."}]}],"diagram":{"title":"Modi verbali: i collegamenti da ricordare","steps":[{"label":"Indicativo","detail":"Afferma o descrive fatti: studio, studiavo, studierò."},{"label":"Congiuntivo","detail":"Dipende da verbi e congiunzioni: spero che arrivi."},{"label":"Condizionale","detail":"Ipotesi, desiderio, cortesia: verrei, vorrei."},{"label":"Imperativo","detail":"Istruzioni e inviti: ascolta; non correre."},{"label":"Indefiniti","detail":"Infinito, participio, gerundio: leggere, letto, leggendo."}]},"pitfalls":[{"mistake":"Se avrei tempo, verrei.","correction":"Se avessi tempo, verrei.","why":"Nell’ipotesi eventuale se introduce il congiuntivo."},{"mistake":"Non corri!","correction":"Non correre!","why":"Il comando negativo rivolto a tu usa non più infinito."}],"recap":["Modo e tempo sono categorie diverse.","Il congiuntivo dipende anche dalla costruzione.","Il condizionale può esprimere cortesia.","Il soggetto del gerundio deve essere chiaro."],"review":[{"question":"Quali sono i modi indefiniti?","answer":"Infinito, participio e gerundio."},{"question":"Il congiuntivo indica sempre un fatto irreale?","answer":"No: può dipendere dalla costruzione anche per fatti reali."},{"question":"Come trasformo corri in un divieto rivolto a tu?","answer":"Non correre."}],"levels":{"base":{"focus":"Riconoscere i modi finiti","example":{"sentence":"Oggi studio; domani studierò.","explanation":"Entrambe le forme sono all’indicativo, ma hanno tempi diversi."}},"consolidamento":{"focus":"Usare le costruzioni","example":{"sentence":"Se avessi il metro, misurerei il ripiano.","explanation":"Avessi è congiuntivo; misurerei è condizionale."}},"avanzato":{"focus":"Interpretare i modi indefiniti","example":{"sentence":"Entrando in aula, ho salutato.","explanation":"Il soggetto del gerundio è lo stesso di ho salutato: io."}}},"simplified":{"lead":"Il modo può esprimere un fatto, una richiesta o un’ipotesi.","steps":["Trova il verbo nella frase.","Chiediti se la frase racconta oppure dà un’istruzione.","Ascolta indica qui un’istruzione."],"example":{"sentence":"Ascolta la spiegazione.","explanation":"Ascolta è un invito o un’istruzione rivolto a tu."}},"pei":{"rule":"L’imperativo serve anche a dare istruzioni.","example":{"sentence":"Ascolta la spiegazione.","explanation":"Ascolta è un invito o un’istruzione rivolto a tu."}},"trackExamples":{"moda":{"sentence":"Vorrei accorciare la manica.","explanation":"Vorrei è condizionale; accorciare è infinito."},"arredo":{"sentence":"Misurate il pannello.","explanation":"Misurate ha qui valore di imperativo rivolto a voi."},"liuteria":{"sentence":"Spero che lo strumento sia pronto.","explanation":"Sia è congiuntivo presente dipendente da spero."}},"anchor":{"sentence":"Se fossi un gatto, dormirei sul quaderno.","explanation":"Fossi è congiuntivo e introduce l’ipotesi; dormirei è condizionale e ne esprime la conseguenza.","memory":"Se fossi: ipotesi. Dormirei: conseguenza."}},{"topic":"Tempi verbali","area":"parole","lead":"I tempi verbali collocano gli eventi e mostrano come un’azione si collega al momento in cui parliamo e alle altre azioni.","objectives":["Collocare gli eventi","Riconoscere la forma","Collegare le azioni"],"sections":[{"title":"Tempo e punto di riferimento","text":"Per interpretare un tempo chiediti rispetto a quale momento si colloca il fatto. Il presente può indicare ciò che accade ora, un’abitudine o una verità generale: disegno, ogni lunedì disegno, l’acqua gela a zero gradi in condizioni ordinarie. Può indicare anche un futuro programmato: domani parto. Il passato colloca un evento prima del riferimento; il futuro dopo. Le parole ieri, domani e allora aiutano, ma non sostituiscono il verbo. Lo stesso tempo può assumere valori diversi nel racconto: il presente storico rende vicini eventi passati, come nel 1861 nasce il Regno d’Italia.","examples":[{"sentence":"Ogni mattina prendo il bus.","explanation":"Il presente indica un’abitudine."},{"sentence":"Domani consegno il progetto.","explanation":"Il presente esprime qui un futuro programmato."}]},{"title":"Semplici e composti","text":"Nella forma attiva, un tempo semplice è espresso da una sola parola: scrivo, scrivevo, scrissi. Un tempo composto contiene l’ausiliare essere o avere e il participio passato: ho scritto, ero arrivato. Nella forma passiva anche un tempo semplice può avere più parole: viene controllato è presente. Non contare le parole separatamente: avevo studiato è un’unica forma verbale. Ogni modo ha il proprio sistema di tempi. L’indicativo possiede presente, imperfetto, passato remoto, futuro semplice e i corrispondenti tempi composti: passato prossimo, trapassato prossimo, trapassato remoto, futuro anteriore. Gli altri modi hanno meno tempi. Il participio o l’infinito dentro una forma composta non cambiano il modo dell’intera forma: avrei scritto resta condizionale passato.","examples":[{"sentence":"Stavo in aula quando è suonata la campana.","explanation":"L’imperfetto presenta lo sfondo; il passato prossimo l’evento."},{"sentence":"Quando siamo arrivati, Marta aveva già aperto.","explanation":"Il trapassato indica un fatto anteriore all’arrivo."}]},{"title":"Raccontare il passato","text":"L’imperfetto presenta spesso uno sfondo, un’abitudine o un’azione osservata nel suo svolgimento: pioveva, andavo ogni giorno. Il passato prossimo e il passato remoto presentano normalmente eventi considerati nel loro insieme: è arrivato, arrivò. La scelta fra questi due varia secondo il tipo di testo, l’area geografica e il legame con il presente; non dipende soltanto da quanti giorni siano passati. Il trapassato prossimo indica un fatto precedente a un altro momento passato: quando arrivai, aveva finito. In una narrazione alternare sfondo ed eventi conclusi permette di ricostruire chiaramente l’ordine e la durata delle azioni.","examples":[{"sentence":"Quando avrò finito, uscirò.","explanation":"Il futuro anteriore precede il futuro semplice."}]},{"title":"Anteriorità e futuro","text":"Il futuro anteriore esprime un evento precedente a un altro futuro: quando avrò finito, uscirò. Può anche esprimere una supposizione sul passato: avrà dimenticato l’orario. Il futuro semplice può esprimere una previsione oppure una supposizione sul presente: saranno le tre. Nelle subordinate i tempi si coordinano con il verbo reggente: penso che sia pronto, pensavo che fosse pronto, pensavo che fosse arrivato. Il condizionale passato può indicare un futuro visto dal passato: disse che sarebbe tornato. Per controllare la coerenza disegna una linea degli eventi e separa il momento del fatto da quello in cui viene raccontato.","examples":[{"sentence":"Leo disse che sarebbe tornato.","explanation":"Il condizionale passato indica un evento futuro rispetto a disse."}]}],"diagram":{"title":"Tempi verbali: i collegamenti da ricordare","steps":[{"label":"Riferimento","detail":"Prima, nello stesso momento o dopo il momento di riferimento."},{"label":"Semplici e composti","detail":"Scrivo; ho scritto: ausiliare e participio insieme."},{"label":"Sfondo ed eventi","detail":"Studiavo quando è arrivato: svolgimento ed evento."},{"label":"Anteriorità","detail":"Avevo finito prima di arrivare; avrò finito prima di uscire."}]},"pitfalls":[{"mistake":"Quando arrivai, finiva già il lavoro.","correction":"Quando arrivai, aveva già finito il lavoro.","why":"Se il lavoro era concluso prima dell’arrivo serve esprimere anteriorità."},{"mistake":"Ho studiato: due predicati.","correction":"Ho studiato: una forma verbale composta.","why":"L’ausiliare e il participio costituiscono insieme il passato prossimo."}],"recap":["Il tempo si interpreta rispetto a un riferimento.","Le forme composte comprendono ausiliare e participio.","L’imperfetto presenta spesso sfondo e abitudini.","I tempi composti possono esprimere anteriorità."],"review":[{"question":"Che cosa indica aveva finito rispetto ad arrivò?","answer":"Un evento già concluso prima dell’arrivo."},{"question":"In «domani parto», quale valore ha il presente?","answer":"Indica un futuro programmato."},{"question":"Qual è il tempo di avrò letto?","answer":"Futuro anteriore dell’indicativo."}],"levels":{"base":{"focus":"Collocare gli eventi","example":{"sentence":"Ogni mattina prendo il bus.","explanation":"Il presente indica un’abitudine."}},"consolidamento":{"focus":"Riconoscere la forma","example":{"sentence":"Stavo in aula quando è suonata la campana.","explanation":"L’imperfetto presenta lo sfondo; il passato prossimo l’evento."}},"avanzato":{"focus":"Collegare le azioni","example":{"sentence":"Leo disse che sarebbe tornato.","explanation":"Il condizionale passato indica un evento futuro rispetto a disse."}}},"simplified":{"lead":"Il verbo aiuta a capire quando avviene un fatto.","steps":["Cerca il verbo.","Chiediti se il fatto è prima, adesso o dopo.","Usa anche parole come ieri, oggi, domani."],"example":{"sentence":"Adesso leggo.","explanation":"Leggo è indicativo presente."}},"pei":{"rule":"Il presente può indicare un’azione che avviene adesso.","example":{"sentence":"Adesso leggo.","explanation":"Leggo è indicativo presente."}},"trackExamples":{"moda":{"sentence":"Mentre cucivo, è finito il filo.","explanation":"L’imperfetto dà lo sfondo; il passato prossimo introduce l’evento."},"arredo":{"sentence":"Avevamo misurato il vano prima del montaggio.","explanation":"Il trapassato indica un’azione anteriore a un momento passato."},"liuteria":{"sentence":"Quando avrò accordato il violino, inizierà la prova.","explanation":"L’accordatura sarà conclusa prima dell’inizio futuro."}},"anchor":{"sentence":"Quando è suonata la sveglia, avevo già aperto un occhio.","explanation":"Avevo aperto indica un fatto precedente a è suonata. Il trapassato ci fa tornare a un momento ancora anteriore.","memory":"Prima avevo aperto; poi è suonata."}},{"topic":"Ausiliari","area":"parole","lead":"Essere e avere aiutano a formare tempi composti e altre costruzioni, ma possono anche avere un significato proprio.","objectives":["Riconoscere l’ausiliare","Scegliere secondo il verbo","Controllare l’accordo"],"sections":[{"title":"Verbi con funzioni diverse","text":"Un ausiliare sostiene un altro verbo nella formazione di una forma composta. In ho letto, ho non esprime possesso: costruisce con letto il passato prossimo di leggere. In sono arrivata, sono costruisce il passato prossimo di arrivare. Essere e avere possono però essere verbi autonomi: ho un quaderno, sono a casa. Essere può anche unire soggetto e parte nominale: il quaderno è nuovo. Per l’analisi guarda quindi tutto il gruppo verbale. La sola presenza di essere non rende una frase passiva e la sola presenza di avere non garantisce un tempo composto.","examples":[{"sentence":"Ho un metro; ho misurato il banco.","explanation":"Nel primo caso avere indica possesso; nel secondo è ausiliare."},{"sentence":"Sono in aula; sono arrivato.","explanation":"Nel primo caso essere ha valore autonomo; nel secondo è ausiliare."}]},{"title":"Scegliere essere o avere","text":"I verbi transitivi attivi formano normalmente i tempi composti con avere: ho costruito un modello. Gli intransitivi possono avere l’uno o l’altro ausiliare: sono arrivato, ho camminato. La regola vaga secondo cui tutti i verbi di movimento richiedono essere non funziona: camminare usa avere. Conta la costruzione del verbo, da controllare nel dizionario. Alcuni cambiano ausiliare secondo l’uso: ho passato un foglio e sono passato da casa. I verbi riflessivi e gli intransitivi pronominali si costruiscono normalmente con essere: mi sono lavato, si è accorto. Anche i transitivi nella forma passiva richiedono essere come ausiliare fondamentale.","examples":[{"sentence":"Marta ha camminato ed è arrivata.","explanation":"Due verbi di movimento richiedono qui ausiliari diversi."},{"sentence":"Le allieve sono entrate.","explanation":"Con essere il participio entrate concorda con il soggetto."}]},{"title":"Accordare il participio","text":"Con essere il participio concorda normalmente con il soggetto in genere e numero: Luca è arrivato, Marta è arrivata, le allieve sono arrivate. Con avere il participio rimane normalmente alla forma maschile singolare: Marta ha letto due pagine. Se precedono i pronomi oggetto lo, la, li, le, nello standard si fa l’accordo: le pagine le ho lette. Con mi, ti, ci, vi oggetto esistono oscillazioni ammesse; per gli esercizi è utile esplicitare la costruzione scelta. Nelle forme riflessive e pronominali bisogna riconoscere il soggetto, senza accordare automaticamente con l’ultimo nome apparso.","examples":[{"sentence":"Le viti? Le ho contate.","explanation":"Il pronome oggetto le precede avere e il participio concorda."}]},{"title":"Servili e forme complesse","text":"Dovere, potere e volere possono accompagnare un infinito e contribuire al suo significato: devo partire. Nei tempi composti l’ausiliare segue spesso quello dell’infinito: sono dovuto partire, ho dovuto lavorare. Nell’uso esistono varianti, soprattutto con potere e volere; non correggere come impossibile ogni costruzione con avere. La posizione dei pronomi influisce: mi sono dovuto alzare, ho dovuto alzarmi. Essere compare anche nel passivo: è stato costruito comprende il passato prossimo di essere più il participio del verbo. Viene costruito è passivo con venire, possibile nei tempi semplici. Per decifrare forme lunghe parti sempre dal verbo che porta il significato principale.","examples":[{"sentence":"Mi sono dovuto alzare; ho dovuto alzarmi.","explanation":"La posizione del pronome riflessivo si accompagna a due costruzioni corrette."}]}],"diagram":{"title":"Ausiliari: i collegamenti da ricordare","steps":[{"label":"Avere","detail":"Ho letto: forma normalmente il composto dei transitivi attivi."},{"label":"Essere","detail":"Sono arrivata; mi sono lavata; è stato costruito."},{"label":"Scelta","detail":"Gli intransitivi richiedono un controllo: ho camminato."},{"label":"Accordo","detail":"Con essere guarda il soggetto; con avere controlla i pronomi oggetto."}]},"pitfalls":[{"mistake":"Ho arrivato.","correction":"Sono arrivato.","why":"Arrivare forma i tempi composti con essere."},{"mistake":"Le ragazze sono arrivato.","correction":"Le ragazze sono arrivate.","why":"Il participio con essere concorda con il soggetto femminile plurale."}],"recap":["Essere e avere possono avere più funzioni.","L’ausiliare degli intransitivi va verificato.","Con essere il participio concorda con il soggetto.","Le forme lunghe vanno lette come un insieme."],"review":[{"question":"Ho una penna è un tempo composto?","answer":"No: avere ha significato proprio e manca il participio."},{"question":"Perché non basta dire che un verbo indica movimento?","answer":"Perché arrivare usa essere e camminare usa avere."},{"question":"Come completo «le stoffe le ho…» con tagliare?","answer":"Tagliate: il pronome oggetto le precede il participio."}],"levels":{"base":{"focus":"Riconoscere l’ausiliare","example":{"sentence":"Ho un metro; ho misurato il banco.","explanation":"Nel primo caso avere indica possesso; nel secondo è ausiliare."}},"consolidamento":{"focus":"Scegliere secondo il verbo","example":{"sentence":"Marta ha camminato ed è arrivata.","explanation":"Due verbi di movimento richiedono qui ausiliari diversi."}},"avanzato":{"focus":"Controllare l’accordo","example":{"sentence":"Mi sono dovuto alzare; ho dovuto alzarmi.","explanation":"La posizione del pronome riflessivo si accompagna a due costruzioni corrette."}}},"simplified":{"lead":"Essere e avere aiutano a formare i tempi composti.","steps":["Leggi insieme le parole: ho letto.","Trova ho: è una forma di avere.","Ho e letto formano un solo tempo verbale."],"example":{"sentence":"Ho letto una pagina.","explanation":"Ho aiuta letto a formare il passato prossimo."}},"pei":{"rule":"Ho letto è una forma composta con avere.","example":{"sentence":"Ho letto una pagina.","explanation":"Ho aiuta letto a formare il passato prossimo."}},"trackExamples":{"moda":{"sentence":"La modellista ha tagliato le tasche.","explanation":"Avere è ausiliare del transitivo tagliare."},"arredo":{"sentence":"Le mensole sono arrivate.","explanation":"Il participio concorda con mensole."},"liuteria":{"sentence":"Il liutaio ha lavorato in silenzio.","explanation":"Lavorare è intransitivo e usa avere."}},"anchor":{"sentence":"Ho camminato fino al bus, ma sono arrivato tardi.","explanation":"Camminare usa avere; arrivare usa essere. Anche due verbi di movimento possono scegliere ausiliari diversi.","memory":"Ho camminato, sono arrivato."}},{"topic":"Transitività","area":"parole","lead":"La transitività riguarda la costruzione del verbo: alcuni verbi possono avere un oggetto diretto, altri richiedono rapporti diversi.","objectives":["Cercare l’oggetto diretto","Osservare la costruzione","Provare il passivo"],"sections":[{"title":"Verbo e partecipanti","text":"Il verbo organizza le informazioni necessarie a descrivere un fatto. Tagliare può collegare chi taglia a ciò che viene tagliato: Sara taglia il cartone. Un verbo transitivo ammette un complemento oggetto diretto, normalmente senza preposizione. Un intransitivo non lo ammette nella costruzione considerata: Sara dorme, parte per Roma, telefona a Luca. Un verbo può richiedere un complemento introdotto da preposizione ed essere comunque intransitivo: dipendere da qualcosa. La domanda chi? o che cosa? è utile soltanto dopo aver riconosciuto il soggetto e il legame con il verbo.","examples":[{"sentence":"Sara taglia il cartone.","explanation":"Taglia ammette un oggetto diretto: il cartone."},{"sentence":"Sara telefona a Luca.","explanation":"Telefonare è qui intransitivo; a Luca indica il destinatario."}]},{"title":"Oggetto espresso o non espresso","text":"Un verbo transitivo può comparire senza un oggetto espresso quando il contesto lo rende chiaro oppure l’attività viene presentata in generale: oggi leggo, Marta cucina. La mancanza di un nome dopo il verbo non lo trasforma automaticamente in intransitivo. Per verificare se la costruzione ammette un oggetto prova ad aggiungerne uno coerente: leggo un romanzo. Un oggetto può essere anche un pronome: lo leggo. L’ordine delle parole non è decisivo: il progetto, lo presenta Sara mette l’oggetto prima del soggetto. Cerca i rapporti sintattici, non la posizione fissa.","examples":[{"sentence":"Oggi leggo.","explanation":"Leggere è usato senza oggetto espresso, ma può ammetterlo."},{"sentence":"Finisco il compito; la lezione finisce.","explanation":"Finire ha un uso transitivo e un uso intransitivo."}]},{"title":"Usi diversi dello stesso verbo","text":"Alcuni verbi hanno costruzioni transitive e intransitive con significati vicini o diversi. Finisco il compito è transitivo; la lezione finisce è intransitivo. Passo il foglio è transitivo; passo da casa è intransitivo. In alcuni casi cambia anche l’ausiliare: ho passato il foglio, sono passato da casa. Non assegnare quindi una sola etichetta senza leggere la frase. Esistono oggetti interni con verbi normalmente intransitivi: vivere una vita serena. Questi usi particolari mostrano che significato e costruzione devono essere analizzati insieme. Il dizionario riporta spesso le diverse possibilità con esempi separati.","examples":[{"sentence":"Ho passato il foglio; sono passato da casa.","explanation":"Il cambio di costruzione si accompagna a un diverso ausiliare."}]},{"title":"Passivo e altri controlli","text":"Una costruzione transitiva attiva può spesso essere trasformata in passiva: Sara prepara il modello, il modello è preparato da Sara. L’oggetto dell’attiva diventa soggetto della passiva. La prova va usata con giudizio: non ogni verbo transitivo produce un passivo naturale in tutti i significati. Avere in ho due fratelli, per esempio, non dà una normale trasformazione passiva. Un intransitivo come arrivare non forma quel passivo: sono arrivato è un tempo composto attivo, non una forma passiva. Non confondere infine oggetto diretto e termine: ascolto Luca contiene oggetto; telefono a Luca contiene termine.","examples":[{"sentence":"Il modello è preparato da Sara; Sara è arrivata.","explanation":"La prima frase è passiva; la seconda contiene un passato prossimo attivo intransitivo."}]}],"diagram":{"title":"Transitività: i collegamenti da ricordare","steps":[{"label":"Transitivo","detail":"Ammette un oggetto diretto: taglio il foglio."},{"label":"Intransitivo","detail":"Non ammette oggetto diretto in quell’uso: parto per Roma."},{"label":"Oggetto non espresso","detail":"Oggi leggo: il transitivo può non mostrare l’oggetto."},{"label":"Cambio di costruzione","detail":"Finisco il compito; la lezione finisce."}]},"pitfalls":[{"mistake":"Telefono Luca.","correction":"Telefono a Luca.","why":"Nello standard telefonare richiede a per indicare il destinatario."},{"mistake":"Sono arrivato è passivo.","correction":"Sono arrivato è passato prossimo attivo.","why":"Arrivare è intransitivo e usa essere come ausiliare."}],"recap":["Un transitivo ammette un oggetto diretto.","Un oggetto può essere sottinteso o pronominale.","Uno stesso verbo può avere costruzioni diverse.","Essere più participio non indica sempre un passivo."],"review":[{"question":"Leggo senza oggetto diventa automaticamente intransitivo?","answer":"No: può essere un uso assoluto di un verbo transitivo."},{"question":"In «telefono a Marta», Marta è oggetto diretto?","answer":"No: a Marta è complemento di termine."},{"question":"Che cosa diventa l’oggetto nel passivo?","answer":"Diventa il soggetto della frase passiva."}],"levels":{"base":{"focus":"Cercare l’oggetto diretto","example":{"sentence":"Sara taglia il cartone.","explanation":"Taglia ammette un oggetto diretto: il cartone."}},"consolidamento":{"focus":"Osservare la costruzione","example":{"sentence":"Oggi leggo.","explanation":"Leggere è usato senza oggetto espresso, ma può ammetterlo."}},"avanzato":{"focus":"Provare il passivo","example":{"sentence":"Il modello è preparato da Sara; Sara è arrivata.","explanation":"La prima frase è passiva; la seconda contiene un passato prossimo attivo intransitivo."}}},"simplified":{"lead":"Alcuni verbi ammettono un oggetto diretto.","steps":["Trova il verbo: taglia.","Cerca che cosa viene tagliato.","Il cartone è collegato direttamente a taglia."],"example":{"sentence":"Sara taglia il cartone.","explanation":"Il cartone è oggetto; taglia è transitivo."}},"pei":{"rule":"Tagliare può avere un oggetto: il cartone.","example":{"sentence":"Sara taglia il cartone.","explanation":"Il cartone è oggetto; taglia è transitivo."}},"trackExamples":{"moda":{"sentence":"La sarta cuce una tasca.","explanation":"Una tasca è oggetto diretto di cuce."},"arredo":{"sentence":"Il mobile pesa molto.","explanation":"Pesare qui indica una proprietà ed è usato senza oggetto diretto."},"liuteria":{"sentence":"L’allieva ascolta il violino.","explanation":"Il violino è oggetto diretto del transitivo ascoltare."}},"anchor":{"sentence":"Passo il biscotto a Leo, poi passo da casa sua.","explanation":"Passo il biscotto è transitivo: il biscotto è oggetto. Passo da casa è un uso intransitivo con un luogo.","memory":"Stesso verbo, costruzioni diverse."}},{"topic":"Passivo","area":"parole","lead":"La forma passiva presenta il fatto dal punto di vista di chi o di ciò che riceve l’azione.","objectives":["Riconoscere il soggetto passivo","Costruire la forma","Distinguere azione e stato"],"sections":[{"title":"Cambiare il punto di vista","text":"Nella frase attiva la classe costruisce il modello, il soggetto è la classe e il modello è oggetto. Nella passiva il modello è costruito dalla classe, il modello diventa soggetto e dalla classe indica chi compie l’azione. Il fatto di base rimane lo stesso, ma cambia il punto da cui viene presentato. Questa trasformazione riguarda normalmente verbi transitivi con un oggetto diretto. Non basta spostare le parole: bisogna cambiare anche la forma verbale. Il soggetto della passiva concorda con il verbo, pur non essendo chi agisce.","examples":[{"sentence":"La classe costruisce il modello. Il modello è costruito dalla classe.","explanation":"L’oggetto dell’attiva diventa soggetto della passiva; il soggetto dell’attiva, la classe, diventa complemento d’agente."},{"sentence":"Le tavole sono state controllate.","explanation":"La forma passiva è al passato prossimo e il participio concorda con tavole."}]},{"title":"Formare il passivo","text":"Il passivo si forma con essere al modo e al tempo richiesti più il participio passato del verbo, accordato con il soggetto: è controllato, erano controllate, sarà controllato. Nei tempi composti la forma si allunga: è stato controllato, erano state controllate. Il tempo si riconosce sull’intera costruzione: è stato aperto corrisponde al passato prossimo, fu aperto al passato remoto. Venire può sostituire essere nei tempi semplici e mette in rilievo l’azione: viene controllato. Non si usa normalmente nei tempi composti per costruire il passivo: si dice è stato controllato, non è venuto controllato.","examples":[{"sentence":"Il cancello viene aperto alle otto.","explanation":"Venire forma un passivo in un tempo semplice."},{"sentence":"Il modulo va firmato.","explanation":"Andare più participio esprime qui obbligo: deve essere firmato."}]},{"title":"Chi agisce e obbligo","text":"Chi compie l’azione può comparire in un complemento introdotto da da: da Luca, dal vento. Nella terminologia scolastica si parla di agente per persona o animale e di causa efficiente per una forza o cosa inanimata. Il complemento può mancare quando l’autore è ignoto, evidente o poco importante: la porta è stata chiusa. Andare più participio, nei tempi semplici, esprime spesso necessità: il modulo va firmato significa deve essere firmato. Questa costruzione non coincide con un normale evento passato. In altri usi andare può accompagnare verbi come perdere: il documento è andato perduto.","examples":[{"sentence":"Il ramo è spezzato dal vento.","explanation":"Dal vento è complemento di causa efficiente."}]},{"title":"Riconoscere i casi simili","text":"Essere più participio può indicare un’azione passiva, un risultato o una qualità: la porta è aperta può descrivere uno stato. Un contesto come viene aperta alle otto rende chiara l’azione. Sono arrivati è invece passato prossimo attivo di un intransitivo. Il si passivante costruisce un passivo con terza persona e accordo: si vendono libri, cioè libri sono venduti. Si lavora bene non contiene un oggetto trasformabile in soggetto ed è impersonale. Nella trasformazione conserva tempo, negazione e significato: Luca non aprirà il pacco diventa il pacco non sarà aperto da Luca.","examples":[{"sentence":"Si vendono strumenti usati.","explanation":"Strumenti usati è soggetto plurale del si passivante; il verbo concorda."}]}],"diagram":{"title":"Passivo: i collegamenti da ricordare","steps":[{"label":"Attiva","detail":"La classe costruisce il modello: soggetto, verbo, oggetto."},{"label":"Passiva","detail":"Il modello è costruito dalla classe: il modello è soggetto."},{"label":"Forme","detail":"Essere + participio; venire nei tempi semplici; si passivante."},{"label":"Accordo","detail":"Le sedie sono state montate: il participio concorda."},{"label":"Chi agisce","detail":"Da Sara: agente. Dal vento: causa efficiente."}]},"pitfalls":[{"mistake":"Le sedie è stato montato.","correction":"Le sedie sono state montate.","why":"Ausiliare e participi concordano con il soggetto plurale femminile."},{"mistake":"Sono arrivati è passivo.","correction":"Sono arrivati è attivo.","why":"Essere è l’ausiliare del tempo composto di arrivare."}],"recap":["La passiva cambia il punto di vista sul fatto.","Il soggetto riceve l’azione.","Il participio concorda con il soggetto.","L’agente può essere espresso oppure mancare."],"review":[{"question":"Come trasformo «Sara apre la porta»?","answer":"La porta è aperta da Sara."},{"question":"Che cosa significa «il modulo va firmato»?","answer":"Il modulo deve essere firmato."},{"question":"Qual è il soggetto di «si vendono libri»?","answer":"Libri, con cui concorda vendono."}],"levels":{"base":{"focus":"Riconoscere il soggetto passivo","example":{"sentence":"La classe costruisce il modello. Il modello è costruito dalla classe.","explanation":"Oggetto e soggetto scambiano i ruoli sintattici nella trasformazione."}},"consolidamento":{"focus":"Costruire la forma","example":{"sentence":"Il cancello viene aperto alle otto.","explanation":"Venire forma un passivo in un tempo semplice."}},"avanzato":{"focus":"Distinguere azione e stato","example":{"sentence":"Si vendono strumenti usati.","explanation":"Strumenti usati è soggetto plurale del si passivante; il verbo concorda."}}},"simplified":{"lead":"Nel passivo il soggetto riceve l’azione.","steps":["Trova il verbo: è aperta.","Chiediti che cosa viene aperto: la porta.","La porta è il soggetto della passiva."],"example":{"sentence":"La porta è aperta da Sara.","explanation":"La porta riceve l’azione; Sara la compie."}},"pei":{"rule":"La porta è aperta da Sara è una frase passiva.","example":{"sentence":"La porta è aperta da Sara.","explanation":"La porta riceve l’azione; Sara la compie."}},"trackExamples":{"moda":{"sentence":"L’abito è cucito dalla sarta.","explanation":"Abito è soggetto; dalla sarta indica l’agente."},"arredo":{"sentence":"Le ante verranno montate domani.","explanation":"Venire forma qui un passivo al futuro semplice."},"liuteria":{"sentence":"La cassa è stata verniciata dalla liutaia.","explanation":"È stata verniciata è passato prossimo passivo."}},"anchor":{"sentence":"Il panino è stato divorato da Leo. Del panino resta il ricordo.","explanation":"Il panino è soggetto passivo: riceve l’azione. L’attiva è Leo ha divorato il panino.","memory":"L’oggetto dell’attiva diventa soggetto passivo."}},{"topic":"Riflessivo","area":"parole","lead":"Nelle costruzioni riflessive un pronome richiama il soggetto; il rapporto preciso cambia secondo il verbo e la frase.","objectives":["Verificare chi riceve l’azione","Distinguere i rapporti","Formare il tempo composto"],"sections":[{"title":"Il riflessivo proprio","text":"Un verbo è riflessivo proprio quando il soggetto agisce su sé stesso: Marta si lava. Il pronome si equivale qui a sé stessa ed è complemento oggetto. Le forme riflessive sono mi, ti, si, ci, vi, si e concordano con la persona del soggetto: io mi lavo, noi ci laviamo. Per riconoscere questa costruzione prova a sostituire il pronome con me stesso, te stesso, sé stesso. La sostituzione deve mantenere il significato. Un verbo transitivo può avere usi attivi e riflessivi: lavo il pennello, mi lavo. La forma del pronome, da sola, non basta.","examples":[{"sentence":"Marta si lava.","explanation":"Si significa sé stessa ed è oggetto: riflessivo proprio."},{"sentence":"Marta si lava le mani.","explanation":"Le mani è oggetto; si significa a sé stessa: riflessivo indiretto."}]},{"title":"Riflessivo indiretto e reciproco","text":"In mi lavo le mani, le mani è l’oggetto diretto; mi significa a me stesso. Questa costruzione si chiama riflessiva indiretta o apparente. Si usa spesso con parti del corpo e indumenti: si mette il cappotto. Il riflessivo reciproco indica un’azione scambiata fra più partecipanti: Luca e Sara si salutano significa che ciascuno saluta l’altro. Il plurale non rende automaticamente reciproco il verbo: i ragazzi si lavano può significare che ognuno lava sé stesso. Per distinguere prova le parafrasi sé stessi e l’un l’altro e scegli quella coerente con il contesto.","examples":[{"sentence":"Luca e Sara si salutano.","explanation":"L’azione è scambiata: Luca saluta Sara e Sara saluta Luca."},{"sentence":"I ragazzi si pettinano, ognuno davanti al proprio specchio.","explanation":"Il contesto indica riflessivo proprio, non reciproco."}]},{"title":"Verbi pronominali e altre forme di si","text":"In accorgersi, pentirsi, vergognarsi il pronome fa parte della costruzione del verbo, senza equivalere a un oggetto diretto: mi accorgo non significa accorgo me stesso. Si parla di verbi intransitivi pronominali. In il vetro si rompe, il pronome presenta un cambiamento che riguarda il soggetto, senza dire che il vetro agisce volontariamente su sé stesso. Si può inoltre avere valore impersonale, come si lavora, oppure passivante, come si riparano sedie. Questi usi non sono riflessivi propri. Cerca il significato e il rapporto fra i partecipanti prima di assegnare l’etichetta.","examples":[{"sentence":"Mi sono accorta dell’errore.","explanation":"Accorgersi è pronominale; mi non significa me stessa come oggetto."}]},{"title":"Forme composte e posizione","text":"Le costruzioni riflessive e pronominali formano normalmente i tempi composti con essere: mi sono lavato, si è accorta. Il participio concorda normalmente con il soggetto: le allieve si sono preparate. Il pronome precede un verbo finito, ma si unisce a infinito, gerundio e imperativo affermativo: lavarsi, lavandosi, lavati. Con un verbo servile sono possibili mi devo preparare e devo prepararmi. Nel negativo rivolto a tu si può dire non lavarti oppure non ti lavare. Per analizzare una frase individua prima l’intero gruppo verbale e poi verifica che cosa sostituisce il pronome: l’eventuale oggetto può già essere espresso da un altro nome.","examples":[{"sentence":"Si riparano sedie; si lavora bene.","explanation":"Il primo si è passivante; il secondo è impersonale."}]}],"diagram":{"title":"Riflessivo: i collegamenti da ricordare","steps":[{"label":"Proprio","detail":"Si lava = lava sé stesso: il pronome è oggetto."},{"label":"Indiretto","detail":"Si lava le mani = lava le mani a sé stesso."},{"label":"Reciproco","detail":"Si salutano = ciascuno saluta l’altro."},{"label":"Pronominale","detail":"Accorgersi: il pronome fa parte del verbo."},{"label":"Altri si","detail":"Si lavora è impersonale; si vendono libri è passivante."}]},"pitfalls":[{"mistake":"Mi ho lavato.","correction":"Mi sono lavato.","why":"La costruzione riflessiva richiede essere."},{"mistake":"Ogni si è riflessivo.","correction":"Si può avere anche valore pronominale, impersonale o passivante.","why":"Occorre controllare significato e costruzione."}],"recap":["Nel riflessivo proprio il soggetto agisce su sé stesso.","Nel riflessivo indiretto l’oggetto è un altro elemento.","Il reciproco esprime uno scambio.","Si non indica sempre un riflessivo."],"review":[{"question":"Che funzione ha le mani in «mi lavo le mani»?","answer":"È complemento oggetto; mi significa a me stesso."},{"question":"Che cosa significa «si salutano» in senso reciproco?","answer":"Ciascuno saluta l’altro."},{"question":"Accorgersi è riflessivo proprio?","answer":"No: è un verbo intransitivo pronominale."}],"levels":{"base":{"focus":"Verificare chi riceve l’azione","example":{"sentence":"Marta si lava.","explanation":"Si significa sé stessa ed è oggetto: riflessivo proprio."}},"consolidamento":{"focus":"Distinguere i rapporti","example":{"sentence":"Luca e Sara si salutano.","explanation":"L’azione è scambiata: Luca saluta Sara e Sara saluta Luca."}},"avanzato":{"focus":"Formare il tempo composto","example":{"sentence":"Le allieve si sono preparate.","explanation":"Il composto riflessivo usa essere; preparate concorda con il soggetto femminile plurale."}}},"simplified":{"lead":"Nel riflessivo proprio una persona agisce su sé stessa.","steps":["Trova la persona: Sara.","Leggi si lava.","Prova a dire lava sé stessa."],"example":{"sentence":"Sara si lava.","explanation":"Sara lava sé stessa."}},"pei":{"rule":"Si lava può significare lava sé stesso o sé stessa.","example":{"sentence":"Sara si lava.","explanation":"Sara lava sé stessa."}},"trackExamples":{"moda":{"sentence":"La modellista si mette il grembiule.","explanation":"Il grembiule è oggetto; si significa a sé stessa."},"arredo":{"sentence":"I compagni si aiutano a montare la mensola.","explanation":"Nel contesto si indica aiuto reciproco."},"liuteria":{"sentence":"La liutaia si prepara alla prova.","explanation":"La costruzione pronominale forma il composto si è preparata."}},"anchor":{"sentence":"Leo si guarda allo specchio: la pettinatura resiste.","explanation":"Si significa sé stesso ed è oggetto di guarda: Leo guarda Leo. È un riflessivo proprio.","memory":"Prova a dire sé stesso."}},{"topic":"Suoni e sillabe","area":"parole","lead":"Per parlare e leggere usiamo suoni; per scrivere usiamo lettere. La sillaba organizza questi suoni attorno a una vocale.","objectives":["Distinguere lettere e suoni","Dividere le sillabe","Individuare l’accento"],"sections":[{"title":"Suoni e scrittura","text":"Le lettere dell’alfabeto italiano di uso tradizionale sono ventuno; j, k, w, x, y compaiono in prestiti, nomi propri e alcune altre parole. Le lettere sono segni grafici, mentre i fonemi sono suoni capaci di distinguere parole: pane e cane cambiano per un suono iniziale. Non esiste sempre una corrispondenza di uno a uno. Un solo suono può essere rappresentato da più lettere: gn in gnomo, ch in chiave. Una stessa lettera può avere suoni diversi: c in casa e cena. Osservare la pronuncia evita di confondere il numero delle lettere con quello dei suoni.","examples":[{"sentence":"Pane e cane.","explanation":"La sostituzione del suono iniziale distingue due parole."},{"sentence":"Gnomo.","explanation":"Gn rappresenta un unico suono, pur essendo scritto con due lettere."}]},{"title":"Vocali vicine","text":"Una sillaba contiene un nucleo vocalico. Due vocali vicine possono appartenere alla stessa sillaba oppure a sillabe diverse. Nel dittongo una i o una u non accentata si unisce a un’altra vocale, come in pie-de o uo-mo; nel trittongo si combinano tre elementi vocalici, come in guai. Nello iato le vocali appartengono a sillabe separate: pa-e-se, po-e-ta, pa-u-ra. Una i o una u tonica tende a formare iato: zì-o, pa-ù-ra. La sola presenza di due lettere vocaliche non basta: in chi la h modifica la c e non è un suono vocalico.","examples":[{"sentence":"Pie-de; pa-e-se.","explanation":"In piede ie sta nella stessa sillaba; in paese a ed e formano iato."},{"sentence":"Pal-la; ac-qua.","explanation":"Si separano sia la doppia sia il gruppo cq."}]},{"title":"Dividere in sillabe","text":"Per dividere una parola, una consonante fra due vocali passa normalmente alla sillaba successiva: ca-sa. Le doppie si separano: pal-la, gat-to. Anche cq si separa: ac-qua. I gruppi che possono iniziare una parola restano spesso uniti: a-pri-le, li-bro. La s seguita da consonante si unisce alla sillaba successiva: fe-sta, mo-stro. Digrammi e trigrammi che rappresentano un unico suono non si spezzano: ba-gno, fi-glio, pe-sce. Lo iato si divide e il dittongo resta unito. Nei casi incerti la sillabazione indicata dal dizionario è un controllo più affidabile di una pausa inventata nella lettura.","examples":[{"sentence":"Fe-sta; ba-gno.","explanation":"La s si unisce alla sillaba successiva; gn non si divide."}]},{"title":"Accento e lettura","text":"Ogni parola piena ha una sillaba pronunciata con maggiore rilievo, detta tonica. Le parole tronche hanno l’accento sull’ultima: città; le piane sulla penultima: matita; le sdrucciole sulla terzultima: tavolo; esistono anche accenti più arretrati. L’accento tonico riguarda la pronuncia e di solito non si scrive; l’accento grafico compare nei casi previsti dall’ortografia. Cambiare accento può cambiare parola: àncora e ancóra. La divisione in sillabe aiuta ad andare a capo, ma la lettura espressiva segue anche gruppi di significato e punteggiatura. Prima individua come suona la parola, poi controlla come rappresentarla sulla pagina.","examples":[{"sentence":"Àncora; ancóra.","explanation":"Lo spostamento dell’accento distingue il nome dell’oggetto dall’avverbio."}]}],"diagram":{"title":"Suoni e sillabe: i collegamenti da ricordare","steps":[{"label":"Suoni e lettere","detail":"Gn: due lettere rappresentano un suono."},{"label":"Vocali vicine","detail":"Dittongo nella stessa sillaba; iato in sillabe diverse."},{"label":"Divisione","detail":"Pal-la, ac-qua; ba-gno, fe-sta."},{"label":"Accento","detail":"Tronca: città. Piana: matita. Sdrucciola: tavolo."}]},"pitfalls":[{"mistake":"Gat-to diventa ga-tto.","correction":"Gat-to","why":"Le consonanti doppie si dividono fra le due sillabe."},{"mistake":"Ba-g-no","correction":"Ba-gno","why":"Il gruppo gn che rappresenta un suono resta unito."}],"recap":["Lettere e suoni sono piani diversi.","La sillaba ha un nucleo vocalico.","Dittongo e iato si distinguono nella pronuncia.","L’accento tonico non è sempre scritto."],"review":[{"question":"Come divido acqua?","answer":"Ac-qua: cq si separa."},{"question":"Che cosa distingue una parola piana da una tronca?","answer":"La piana ha accento sulla penultima sillaba; la tronca sull’ultima."},{"question":"In bagno divido g da n?","answer":"No: ba-gno."}],"levels":{"base":{"focus":"Distinguere lettere e suoni","example":{"sentence":"Pane e cane.","explanation":"La sostituzione del suono iniziale distingue due parole."}},"consolidamento":{"focus":"Dividere le sillabe","example":{"sentence":"Pie-de; pa-e-se.","explanation":"In piede ie sta nella stessa sillaba; in paese a ed e formano iato."}},"avanzato":{"focus":"Individuare l’accento","example":{"sentence":"Àncora; ancóra.","explanation":"Lo spostamento dell’accento distingue il nome dell’oggetto dall’avverbio."}}},"simplified":{"lead":"Una parola si può dividere in sillabe.","steps":["Pronuncia lentamente gatto.","Trova la doppia t.","Separa le due t: gat-to."],"example":{"sentence":"Gat-to.","explanation":"La prima t chiude la prima sillaba; la seconda apre la successiva."}},"pei":{"rule":"Le consonanti doppie si separano nella divisione in sillabe.","example":{"sentence":"Gat-to.","explanation":"La prima t chiude la prima sillaba; la seconda apre la successiva."}},"trackExamples":{"moda":{"sentence":"Stof-fa è divisa in due sillabe.","explanation":"La doppia f si separa."},"arredo":{"sentence":"Ta-vo-lo ha tre sillabe.","explanation":"L’accento è sulla terzultima: tàvolo è sdrucciola."},"liuteria":{"sentence":"Cor-da si divide in due sillabe.","explanation":"Il gruppo rd si separa: r chiude la prima sillaba, d apre la seconda."}},"anchor":{"sentence":"Il gat-to fa le fusa sulla car-tel-la.","explanation":"Le consonanti doppie si separano nella divisione in sillabe: gat-to, car-tel-la.","memory":"Le doppie si dividono fra due sillabe."}},{"topic":"Punteggiatura","area":"parole","lead":"La punteggiatura organizza il testo e aiuta a capire quali informazioni sono collegate, separate o messe in rilievo.","objectives":["Trovare i confini","Gestire elenco e inciso","Controllare il significato"],"sections":[{"title":"Frasi e confini","text":"Il punto chiude un’unità di senso e permette di passare alla successiva. Dopo il punto si usa la maiuscola. La virgola separa elementi di un elenco, parti coordinate e informazioni inserite nella frase. Non corrisponde a ogni pausa del respiro: prima bisogna riconoscere la struttura. In una frase neutra non si separano con una virgola soggetto e predicato, né verbo e oggetto. In il gruppo, dopo la prova, corregge il modello le virgole racchiudono invece un inciso: eliminandolo resta il gruppo corregge il modello. L’inciso va chiuso con la stessa cura con cui viene aperto.","examples":[{"sentence":"Portiamo carta, matite e colla.","explanation":"Le virgole separano elementi di un elenco semplice."},{"sentence":"Il gruppo, dopo la prova, corregge il modello.","explanation":"Le due virgole racchiudono l’inciso senza separare il nucleo soggetto-predicato."}]},{"title":"Virgole che cambiano il significato","text":"Le virgole isolano un vocativo: Luca, ascolta. Possono segnalare apposizioni e relative esplicative: mia sorella, che vive a Roma, arriva oggi. Senza virgole una relativa può restringere il gruppo: gli studenti che hanno finito escono significa che esce soltanto chi ha finito; con le virgole l’informazione è presentata come aggiunta riferita al gruppo già identificato. Negli elenchi semplici di solito non serve una virgola prima dell’ultima e. Il segno dipende dalla costruzione, non da un divieto assoluto: con frasi lunghe o incisi può esserci una virgola anche prima di e.","examples":[{"sentence":"Luca, ascolta!","explanation":"La virgola isola il vocativo, cioè la persona chiamata."},{"sentence":"Gli studenti che hanno finito escono.","explanation":"La relativa senza virgole seleziona il gruppo degli studenti che escono."}]},{"title":"Due punti e punto e virgola","text":"I due punti annunciano una spiegazione, una conseguenza, un elenco o un discorso diretto: serve una cosa: attenzione. L’elemento che segue deve sviluppare davvero ciò che precede. Il punto e virgola separa unità strettamente collegate ma già articolate al loro interno, oppure elementi complessi di un elenco. È più forte della virgola e meno conclusivo del punto. Non occorre inserirlo per rendere un testo più formale: sceglilo quando rende chiari i confini. Parentesi e lineette possono racchiudere incisi; in un testo scolastico basta spesso una coppia di virgole o parentesi ben costruita.","examples":[{"sentence":"Ho un problema: manca il metro.","explanation":"I due punti introducono una spiegazione."}]},{"title":"Domande, citazioni e revisione","text":"Il punto interrogativo chiude una domanda diretta; nell’interrogativa indiretta si usa il punto normale: chiedo dove sia il banco. Il punto esclamativo segnala un’esclamazione o un ordine forte e va usato con misura. I puntini di sospensione sono tre e indicano un’interruzione o una parte lasciata implicita. Le virgolette racchiudono citazioni, parole riportate e usi particolari; nel discorso diretto distinguono la voce di chi parla. Quando rileggi, verifica il rapporto fra le frasi prima di aggiungere segni. Lo spazio va normalmente dopo virgola, punto e altri segni, non prima; parentesi e virgolette restano vicine al testo che racchiudono.","examples":[{"sentence":"Chiedo dove sia il banco. Dov’è il banco?","explanation":"La prima è interrogativa indiretta; la seconda è domanda diretta."}]}],"diagram":{"title":"Punteggiatura: i collegamenti da ricordare","steps":[{"label":"Punto","detail":"Chiude un’unità di senso."},{"label":"Virgola","detail":"Elenco, vocativo, inciso; non separa normalmente soggetto e verbo."},{"label":"Due punti","detail":"Annunciano una spiegazione, un elenco o una voce diretta."},{"label":"Punto e virgola","detail":"Separa unità vicine e già articolate."},{"label":"Domanda diretta","detail":"Dove sei? La domanda indiretta chiude normalmente con il punto."}]},"pitfalls":[{"mistake":"La classe, prepara il progetto.","correction":"La classe prepara il progetto.","why":"Non si separano normalmente soggetto e predicato."},{"mistake":"Mi chiedo dove sia il metro?","correction":"Mi chiedo dove sia il metro.","why":"È una domanda indiretta, non una domanda rivolta direttamente al lettore."}],"recap":["La punteggiatura segue anche la sintassi.","Una pausa del respiro non richiede sempre una virgola.","Le virgole possono cambiare il significato di una relativa.","La domanda indiretta non richiede da sola il punto interrogativo."],"review":[{"question":"Che cosa fanno le due virgole di un inciso?","answer":"Segnalano l’inizio e la fine dell’informazione inserita."},{"question":"Posso separare normalmente soggetto e verbo con una virgola?","answer":"No, se non interviene una costruzione particolare come un inciso."},{"question":"Quando uso i due punti?","answer":"Per introdurre una spiegazione, un elenco o un discorso diretto coerente con ciò che precede."}],"levels":{"base":{"focus":"Trovare i confini","example":{"sentence":"Portiamo carta, matite e colla.","explanation":"Le virgole separano elementi di un elenco semplice."}},"consolidamento":{"focus":"Gestire elenco e inciso","example":{"sentence":"Luca, ascolta!","explanation":"La virgola isola il vocativo, cioè la persona chiamata."}},"avanzato":{"focus":"Controllare il significato","example":{"sentence":"Chiedo dove sia il banco. Dov’è il banco?","explanation":"La prima è interrogativa indiretta; la seconda è domanda diretta."}}},"simplified":{"lead":"I segni aiutano a separare e collegare le informazioni.","steps":["Leggi una frase completa.","Quando è conclusa, puoi mettere il punto.","La parola successiva inizia con la maiuscola."],"example":{"sentence":"Il banco è pulito. Sara entra.","explanation":"Il punto separa due frasi."}},"pei":{"rule":"Il punto chiude una frase.","example":{"sentence":"Il banco è pulito. Sara entra.","explanation":"Il punto separa due frasi."}},"trackExamples":{"moda":{"sentence":"Servono tre materiali: lino, filo e bottoni.","explanation":"I due punti annunciano l’elenco."},"arredo":{"sentence":"Misuriamo il vano; poi controlliamo il disegno.","explanation":"Il punto e virgola collega due unità autonome ma vicine."},"liuteria":{"sentence":"La docente chiede: «Il violino è pronto?»","explanation":"I due punti introducono il discorso diretto; la domanda è nelle virgolette."}},"anchor":{"sentence":"Mangiamo, ragazzi!","explanation":"La virgola separa ragazzi, che qui è un vocativo. Chi parla chiama i compagni e li invita a mangiare.","memory":"La persona chiamata si separa con la virgola."}},{"topic":"Formazione delle parole","area":"parole","lead":"Le parole possono nascere da altre parole, unendo elementi o aggiungendo parti che ne cambiano significato e categoria.","objectives":["Riconoscere la base","Distinguere i meccanismi","Verificare il significato"],"sections":[{"title":"Radice, desinenza e famiglia","text":"In molte parole si distingue una parte che porta il significato di base e una parte che esprime informazioni grammaticali. In tavoli la base tavol- si riconosce anche in tavolo, mentre -i segnala il plurale. Non tutte le parole si dividono con la stessa facilità: città è invariabile. Una famiglia lessicale comprende parole legate da una base e da un significato riconoscibile: fiore, fiorire, fiorista. La somiglianza di lettere non basta: bisogna poter spiegare il rapporto. Flettere una parola, come tavolo in tavoli, non significa crearne una nuova nel lessico.","examples":[{"sentence":"Fiore, fiorista, fiorire.","explanation":"Le parole appartengono alla stessa famiglia e condividono una base di significato."},{"sentence":"Tavolo, tavoli.","explanation":"È un cambio di numero, non la creazione di una nuova parola del lessico."}]},{"title":"Derivazione","text":"La derivazione forma parole nuove mediante prefissi e suffissi. Il prefisso precede la base: rileggere significa leggere di nuovo, disordine esprime una mancanza o opposizione rispetto all’ordine. Il suffisso segue la base: da fiore nasce fiorista, da utile utilità. Può cambiare anche la categoria grammaticale: bello è aggettivo, bellezza è nome. Alcune parole si formano con prefisso e suffisso insieme secondo un meccanismo detto parasintesi: imbiancare si collega a bianco. Non attribuire un valore fisso a ogni sequenza: in- può indicare negazione in inutile, ma non ha quel significato in ogni parola che comincia con quelle lettere.","examples":[{"sentence":"Rileggere il testo.","explanation":"Il prefisso ri- esprime qui ripetizione."},{"sentence":"Bello diventa bellezza.","explanation":"Il suffisso forma un nome a partire da un aggettivo."}]},{"title":"Alterazione e falsi alterati","text":"L’alterazione modifica soprattutto una sfumatura di quantità, dimensione o giudizio, senza cambiare il riferimento di base. Librino può indicare un libro piccolo oppure un tono affettuoso; librone suggerisce grandi dimensioni; libraccio esprime un giudizio negativo. I valori principali sono diminutivo, accrescitivo, vezzeggiativo e dispregiativo, ma dipendono dal contesto. Non tutti i suffissi sono alterativi: libreria è un derivato. Un falso alterato assomiglia a una forma alterata senza esserlo nel significato corrente: un bottone non è un piccolo botto, un lampone non è una grande lampada. Prima di classificare, ricostruisci il rapporto di significato.","examples":[{"sentence":"Un libraccio e un bottone.","explanation":"Libraccio è alterato; bottone è un falso alterato."}]},{"title":"Composizione e altre formazioni","text":"La composizione unisce parole o elementi lessicali: portapenne, cassaforte, caposquadra. Le categorie di partenza possono essere diverse, come verbo più nome o nome più aggettivo. Il plurale dei composti non segue un’unica regola: casseforti, capisquadra, portapenne invariabile; nei dubbi va consultato il dizionario. Il lessico cresce anche con sigle, abbreviazioni, prestiti da altre lingue e cambi di funzione: un nome può diventare aggettivo o viceversa in certi usi. Per analizzare una parola chiediti quali elementi riconosci, quale significato aggiunge ciascuno e se la forma ottenuta è davvero usata. Non ogni combinazione grammaticalmente possibile produce una parola comune.","examples":[{"sentence":"Una cassaforte, due casseforti.","explanation":"Il composto unisce nome e aggettivo; al plurale cambiano entrambi gli elementi."}]},{"title":"Elementi di origine greca o latina e parole macedonia","text":"Alcune parole si costruiscono con elementi dotati di significato che derivano spesso dal greco o dal latino: bio- in biologia richiama la vita e -logia lo studio. Questi elementi possono chiamarsi prefissoidi se compaiono all’inizio e suffissoidi se compaiono alla fine. Una parola macedonia nasce invece dalla fusione di parti di parole: cantautore unisce parti di cantante e autore; apericena combina aperitivo e cena. Non tutte le parole che si somigliano si formano così: il dizionario aiuta a ricostruirne la struttura.","examples":[{"sentence":"La biologia studia gli esseri viventi.","explanation":"Bio- richiama la vita e -logia lo studio."},{"sentence":"Un cantautore presenta la propria canzone.","explanation":"Cantautore unisce parti di cantante e autore."}]},{"title":"Conglomerati, parole-frase e unità lessicali","text":"Un conglomerato può nascere dalla saldatura di più parole in un’unica forma, come saliscendi. Alcune espressioni nate da una frase, come fai da te, possono funzionare come un’unica unità di significato; alcune grammatiche le chiamano parole-frase. Un’unità lessicale, detta anche polirematica, è un gruppo di parole separate che insieme esprime un significato unitario: ferro da stiro indica un oggetto preciso. Queste etichette possono variare secondo la grammatica; cerca soprattutto di capire come il gruppo sia formato e quale significato abbia nell’uso.","examples":[{"sentence":"Il saliscendi chiude il cancello.","explanation":"Saliscendi è una forma unica nata dall’unione di più elementi."},{"sentence":"Il ferro da stiro è sul ripiano.","explanation":"Ferro da stiro è un gruppo di parole che indica un oggetto preciso."}]}],"diagram":{"title":"Formazione delle parole: i collegamenti da ricordare","steps":[{"label":"Flessione","detail":"Tavolo, tavoli: cambia l’informazione grammaticale."},{"label":"Derivazione","detail":"Prefisso o suffisso: rileggere, bellezza."},{"label":"Alterazione","detail":"Dimensione o giudizio: librino, librone, libraccio."},{"label":"Composizione","detail":"Elementi uniti: portapenne, cassaforte."}]},"pitfalls":[{"mistake":"Bottone è diminutivo di botto.","correction":"Bottone è un falso alterato.","why":"Il significato corrente non mantiene quel rapporto."},{"mistake":"Tavoli è un derivato di tavolo.","correction":"Tavoli è il plurale di tavolo.","why":"La flessione cambia informazioni grammaticali, non crea un nuovo lessema."}],"recap":["La famiglia lessicale unisce forma e significato.","Prefissi e suffissi formano derivati.","Gli alterati aggiungono sfumature.","I composti uniscono elementi lessicali."],"review":[{"question":"Che cosa cambia ri- in rileggere?","answer":"Indica che si legge di nuovo."},{"question":"Perché bellezza è derivato?","answer":"Un suffisso forma un nome a partire dall’aggettivo bello."},{"question":"Il plurale dei composti è sempre prevedibile?","answer":"No: nei casi dubbi serve il dizionario."}],"levels":{"base":{"focus":"Riconoscere la base","example":{"sentence":"Fiore, fiorista, fiorire.","explanation":"Le parole appartengono alla stessa famiglia e condividono una base di significato."}},"consolidamento":{"focus":"Distinguere i meccanismi","example":{"sentence":"Rileggere il testo.","explanation":"Il prefisso ri- esprime qui ripetizione."}},"avanzato":{"focus":"Verificare il significato","example":{"sentence":"Una cassaforte, due casseforti.","explanation":"Il composto unisce nome e aggettivo; al plurale cambiano entrambi gli elementi."}}},"simplified":{"lead":"Da una parola possono nascere parole nuove.","steps":["Parti da libro.","Aggiungi -ino: librino.","Chiediti quale sfumatura cambia."],"example":{"sentence":"Porto un librino.","explanation":"Il suffisso -ino aggiunge qui un valore diminutivo."}},"pei":{"rule":"Librino può indicare un libro piccolo.","example":{"sentence":"Porto un librino.","explanation":"Il suffisso -ino aggiunge qui un valore diminutivo."}},"trackExamples":{"moda":{"sentence":"Scucire significa disfare una cucitura.","explanation":"Il prefisso s- modifica il significato di cucire."},"arredo":{"sentence":"Una cassapanca occupa poco spazio.","explanation":"Cassapanca unisce due nomi."},"liuteria":{"sentence":"Il liutaio ripone gli attrezzi nel portautensili.","explanation":"Portautensili è un composto di forma verbale e nome."}},"anchor":{"sentence":"Un librone occupa il banco; un libraccio rovina la lettura.","explanation":"Librone è un accrescitivo; libraccio esprime un giudizio negativo. I suffissi aggiungono sfumature diverse a libro.","memory":"Guarda il suffisso e chiediti che cosa aggiunge."}},{"topic":"Significato e registro","area":"parole","lead":"Il significato dipende dalle relazioni fra le parole e dal contesto; il registro dipende anche dalla situazione e da chi ci ascolta.","objectives":["Usare il contesto","Collegare i significati","Adattare il registro"],"sections":[{"title":"Capire nel contesto","text":"Una parola può avere più significati collegati: il collo di una persona e il collo di una bottiglia. Si parla di polisemia. Altre parole condividono la forma ma hanno origini e significati distinti: riso può indicare il cereale o l’atto del ridere; sono omonimi. Nella lettura il contesto permette di scegliere il significato pertinente. Il significato letterale indica l’uso di base; quello figurato trasferisce una proprietà: una montagna di compiti non è un rilievo geografico. Per interpretare un’espressione figurata cerca che cosa il confronto vuole far capire, senza tradurla parola per parola.","examples":[{"sentence":"Il collo della bottiglia è stretto.","explanation":"Collo ha un significato collegato per somiglianza alla parte del corpo."},{"sentence":"Ho una montagna di compiti.","explanation":"Montagna è figurato e indica una grande quantità."}]},{"title":"Relazioni fra significati","text":"I sinonimi hanno significati vicini, ma raramente sono intercambiabili in ogni contesto: abitazione e casa non hanno sempre lo stesso tono o gli stessi usi. I contrari esprimono opposizioni, come largo e stretto; alcuni prevedono gradi intermedi, altri un’esclusione più netta. Un iperonimo ha significato più generale: strumento; un iponimo più specifico: violino. Un campo semantico raccoglie parole legate a un ambito: ago, filo, cucitura, imbastire. Non è la stessa cosa di una famiglia lessicale, che richiede una parentela di forma e significato. Queste relazioni aiutano a scegliere termini precisi e a evitare ripetizioni.","examples":[{"sentence":"Il violino è uno strumento.","explanation":"Strumento è iperonimo; violino è iponimo."},{"sentence":"Casa e abitazione hanno significati vicini.","explanation":"Sono sinonimi parziali: tono e contesto possono renderli diversi."}]},{"title":"Situazione e registro","text":"Il registro è il modo di esprimersi adatto alla situazione. In una conversazione fra amici possiamo usare ciao e mi passi quella cosa?; in una richiesta a un ufficio servono formule più precise e rispettose. Formale non significa difficile: un testo può essere cortese e chiaro con parole comuni. Il registro dipende da destinatario, scopo, mezzo e rapporto fra le persone. Un messaggio rapido, una relazione di laboratorio e un colloquio richiedono scelte diverse. Le varietà regionali e colloquiali hanno usi legittimi, ma negli elaborati scolastici conviene saper usare l’italiano standard richiesto dalla consegna.","examples":[{"sentence":"Puoi inviarmi il disegno? Potrebbe inviarmi il disegno?","explanation":"La seconda richiesta adotta un registro più formale e cortese."}]},{"title":"Lessico comune e tecnico","text":"I linguaggi settoriali usano parole precise per attività particolari: ordito nella tessitura, incastro nell’arredo, ponticello nella liuteria. Alcune parole comuni assumono un significato tecnico: fondo può indicare una parte dello strumento. Chi scrive deve valutare ciò che il destinatario sa già e spiegare un termine quando serve. Evita parole generiche se una scelta più precisa chiarisce il lavoro: materiale può diventare lino, compensato o acero secondo il caso. Per controllare il lessico usa il dizionario per significati e costruzioni, poi rileggi la frase completa: un sinonimo corretto in astratto può risultare inadatto al tono o alla combinazione con le altre parole.","examples":[{"sentence":"Il fondo del violino è di acero.","explanation":"Fondo ha qui un significato tecnico legato alle parti dello strumento."}]},{"title":"Denotazione e connotazione","text":"La denotazione è il significato descrittivo che una parola usa per individuare qualcosa: volpe può indicare un animale. La connotazione comprende le associazioni o le sfumature che la parola assume in un contesto: dire che una persona è una volpe può suggerire astuzia, con apprezzamento o critica secondo la situazione. Non tutte le persone associano le stesse emozioni a una parola. Distingui ciò che il termine designa dalla valutazione o dall’effetto che suggerisce nel testo.","examples":[{"sentence":"Una volpe attraversa il prato.","explanation":"Volpe indica qui l’animale nel suo significato descrittivo."},{"sentence":"Marta è una volpe negli scacchi.","explanation":"Volpe è usato in senso figurato e suggerisce astuzia; il contesto orienta la valutazione."}]}],"diagram":{"title":"Significato e registro: i collegamenti da ricordare","steps":[{"label":"Contesto","detail":"Seleziona il significato letterale, figurato o tecnico."},{"label":"Relazioni","detail":"Sinonimi, contrari, iperonimi e iponimi."},{"label":"Registro","detail":"Si adatta a interlocutore, scopo, mezzo e situazione."},{"label":"Precisione","detail":"Usa termini specifici e spiega quelli tecnici se serve."}]},"pitfalls":[{"mistake":"Un sinonimo va bene in ogni frase.","correction":"I sinonimi vanno controllati nel contesto.","why":"Possono cambiare tono, significato preciso o combinazioni ammesse."},{"mistake":"Formale significa usare parole complicate.","correction":"Formale significa adeguato a una situazione ufficiale.","why":"La chiarezza resta utile anche nei testi formali."}],"recap":["Il contesto seleziona il significato.","I sinonimi non sono sempre equivalenti.","Iperonimo e iponimo collegano generale e specifico.","Il registro si adatta alla situazione."],"review":[{"question":"Qual è l’iperonimo di violino fra strumento e corda?","answer":"Strumento: è la categoria più generale."},{"question":"Montagna di compiti ha significato letterale?","answer":"No: è un’espressione figurata."},{"question":"Perché spiego un termine tecnico?","answer":"Per rendere comprensibile il testo a chi potrebbe non conoscerlo."}],"levels":{"base":{"focus":"Usare il contesto","example":{"sentence":"Il collo della bottiglia è stretto.","explanation":"Collo ha un significato collegato per somiglianza alla parte del corpo."}},"consolidamento":{"focus":"Collegare i significati","example":{"sentence":"Il violino è uno strumento.","explanation":"Strumento è iperonimo; violino è iponimo."}},"avanzato":{"focus":"Adattare il registro","example":{"sentence":"Il fondo del violino è di acero.","explanation":"Fondo ha qui un significato tecnico legato alle parti dello strumento."}}},"simplified":{"lead":"Il contesto aiuta a capire il significato delle parole.","steps":["Leggi la frase intera.","Cerca il significato adatto alla situazione.","Scegli parole comprensibili per chi ascolta."],"example":{"sentence":"Ho una montagna di compiti.","explanation":"Montagna significa qui una grande quantità."}},"pei":{"rule":"Una parola può avere un significato figurato.","example":{"sentence":"Ho una montagna di compiti.","explanation":"Montagna significa qui una grande quantità."}},"trackExamples":{"moda":{"sentence":"La cucitura è storta.","explanation":"Cucitura è più preciso di cosa nel resoconto del lavoro."},"arredo":{"sentence":"Il mobile richiede un incastro preciso.","explanation":"Incastro appartiene al lessico tecnico dell’arredo."},"liuteria":{"sentence":"Controlliamo il ponticello del violino.","explanation":"Ponticello ha un significato tecnico diverso da piccolo ponte urbano."}},"anchor":{"sentence":"Ho una montagna di compiti, ma nessuno mi presta gli scarponi.","explanation":"Montagna è usato in senso figurato per indicare una grande quantità. Il contesto esclude il significato geografico.","memory":"Per capire una parola, leggile attorno."}},{"topic":"Interiezioni","area":"parole","lead":"Le interiezioni esprimono reazioni, richiami e atteggiamenti con parole o espressioni spesso autonome.","objectives":["Riconoscere la reazione","Distinguere gli usi","Scegliere scrittura e tono"],"sections":[{"title":"Reazioni e richiami","text":"Un’interiezione può esprimere sorpresa, dolore, dubbio, gioia, disappunto oppure richiamare l’attenzione: ah, ahi, mah, ehi. Il significato preciso dipende dal contesto e dall’intonazione. Ah può segnalare che abbiamo capito oppure una sorpresa; mah può manifestare incertezza o scetticismo. Queste parole non entrano normalmente nei rapporti sintattici come un nome oggetto o un verbo: possono costituire da sole un enunciato. Non descrivono per forza un’emozione nominata in modo esplicito: la comunicano attraverso l’uso. Per interpretarle occorre chiedersi chi parla, a chi si rivolge e che cosa è appena successo.","examples":[{"sentence":"Ahi! Mi sono punto.","explanation":"Ahi esprime una reazione di dolore."},{"sentence":"Mah, non sono convinto.","explanation":"Mah segnala dubbio o perplessità."}]},{"title":"Proprie, improprie e locuzioni","text":"Le interiezioni proprie si usano soprattutto con questa funzione: oh, eh, uffa, boh, ahi. Le improprie sono parole di altre categorie adoperate come esclamazioni o richiami: bravo!, basta!, coraggio! La stessa parola va quindi analizzata nella frase: coraggio è nome in serve coraggio, ma ha valore interiettivo quando viene detto da solo per incoraggiare. Le locuzioni interiettive comprendono più parole: per fortuna!, mamma mia!, che peccato! Possono riferirsi alla frase che segue o costituire una reazione autonoma. Non esiste una corrispondenza fissa fra una sola forma e una sola emozione: il tono può capovolgere anche un apparente complimento.","examples":[{"sentence":"Coraggio! Prova ancora.","explanation":"Coraggio è un nome usato qui come interiezione impropria."},{"sentence":"Serve coraggio per riprovare.","explanation":"Qui coraggio torna a essere un nome dentro la frase."}]},{"title":"Scrittura e punteggiatura","text":"Molte interiezioni contengono h in posizioni fissate dall’uso: ah, eh, oh, mah. La scrittura distingue parole che si pronunciano in modo simile: ah è un’esclamazione, ha è verbo avere, a è preposizione; oh si distingue da ho e da o. L’interiezione può essere seguita da punto esclamativo, interrogativo o virgola secondo il tono e la costruzione: ah, ora capisco; eh? non ho sentito. Non è obbligatorio il punto esclamativo per ogni interiezione. Nei dialoghi scegli il segno che rende la reazione leggibile, senza accumulare punti che rendano incerto il significato.","examples":[{"sentence":"Ah, ho capito!","explanation":"Ah è interiezione; ho è verbo avere."}]},{"title":"Suoni imitati e registro","text":"Le onomatopee imitano rumori o versi: tic tac, boom, miao. Possono comparire come enunciati autonomi, ma la loro funzione imitativa è diversa da una reazione come uffa. Una parola può anche diventare nome: sento un ticchettio. Interiezioni e onomatopee sono frequenti nei dialoghi, nei fumetti e nei messaggi informali. In una relazione di laboratorio conviene descrivere il fatto con precisione: invece di uffa, il pezzo non va, scrivi il pezzo non entra nell’incastro. Il registro non rende sbagliata l’interiezione: indica soltanto in quale situazione è utile. Se la riporti in un dialogo, controlla che il tono sia coerente con chi parla.","examples":[{"sentence":"Tic tac: l’orologio si sente in tutta l’aula.","explanation":"Tic tac imita un suono ed è onomatopea."}]}],"diagram":{"title":"Interiezioni: i collegamenti da ricordare","steps":[{"label":"Proprie","detail":"Ah, ahi, mah, uffa: reazioni e richiami."},{"label":"Improprie","detail":"Bravo!, coraggio!: parole di altre categorie usate come esclamazioni."},{"label":"Locuzioni","detail":"Che peccato!, per fortuna!: più parole per una reazione."},{"label":"Onomatopee","detail":"Tic tac, boom, miao: imitano suoni e versi."}]},"pitfalls":[{"mistake":"Ha! Che sorpresa!","correction":"Ah! Che sorpresa!","why":"L’interiezione è ah; ha appartiene al verbo avere."},{"mistake":"Ogni punto esclamativo segnala un’interiezione.","correction":"Un punto esclamativo può chiudere anche una frase completa.","why":"La categoria dipende dalle parole e dal loro uso, non dal solo segno."}],"recap":["Il contesto chiarisce il valore dell’interiezione.","Le interiezioni possono essere proprie o improprie.","H e posizione delle lettere distinguono parole diverse.","L’onomatopea imita un suono."],"review":[{"question":"In «basta!», basta può avere valore interiettivo?","answer":"Sì: è una parola usata come richiamo o esclamazione autonoma."},{"question":"Che differenza c’è fra ah e ha?","answer":"Ah è interiezione; ha è verbo avere."},{"question":"Il punto esclamativo è obbligatorio dopo mah?","answer":"No: la punteggiatura dipende da tono e costruzione."}],"levels":{"base":{"focus":"Riconoscere la reazione","example":{"sentence":"Ahi! Mi sono punto.","explanation":"Ahi esprime una reazione di dolore."}},"consolidamento":{"focus":"Distinguere gli usi","example":{"sentence":"Coraggio! Prova ancora.","explanation":"Coraggio è un nome usato qui come interiezione impropria."}},"avanzato":{"focus":"Scegliere scrittura e tono","example":{"sentence":"Tic tac: l’orologio si sente in tutta l’aula.","explanation":"Tic tac imita un suono ed è onomatopea."}}},"simplified":{"lead":"Alcune parole comunicano subito una reazione.","steps":["Leggi Ahi!","Immagina il tono di chi parla.","Ahi esprime qui dolore."],"example":{"sentence":"Ahi! Mi sono punto.","explanation":"Ahi comunica dolore."}},"pei":{"rule":"Ahi può esprimere una reazione di dolore.","example":{"sentence":"Ahi! Mi sono punto.","explanation":"Ahi comunica dolore."}},"trackExamples":{"moda":{"sentence":"Ahi! L’ago punge.","explanation":"Ahi esprime dolore."},"arredo":{"sentence":"Oh, la mensola è finalmente dritta.","explanation":"Oh comunica una reazione di sorpresa o soddisfazione nel contesto."},"liuteria":{"sentence":"Uffa, la corda si è rotta.","explanation":"Uffa esprime disappunto in un registro informale."}},"anchor":{"sentence":"Uffa! Il biscotto è caduto dalla parte della marmellata.","explanation":"Uffa esprime disappunto come reazione autonoma; il resto della frase spiega che cosa è successo.","memory":"Uffa comunica il disappunto senza descriverlo."}},{"topic":"Soggetto, predicato e oggetto","area":"frase","lead":"Una frase si capisce meglio riconoscendo di chi si parla, che cosa viene detto e quale elemento è collegato direttamente al verbo come oggetto.","objectives":["Individuare il predicato","Riconoscere il soggetto","Cercare l’oggetto"],"sections":[{"title":"Partire dal predicato","text":"Il predicato è ciò che si dice del soggetto e ha come centro un verbo. Può esprimere un’azione, uno stato, un cambiamento o una caratteristica. Il predicato verbale comprende il verbo con eventuali ausiliari e costruzioni unitarie: ha lavorato, è stato controllato, deve partire. Il predicato nominale unisce essere, detto copula, a un nome o un aggettivo: è una studentessa, è precisa. Essere non è sempre copula: in è in aula ha valore autonomo e forma un predicato verbale. Individuare l’intera forma verbale evita di contare un tempo composto come due predicati.","examples":[{"sentence":"La classe prepara il modello.","explanation":"La classe è soggetto, prepara predicato verbale, il modello oggetto."},{"sentence":"Il modello è preciso.","explanation":"È preciso è predicato nominale; preciso non è oggetto."}]},{"title":"Trovare il soggetto","text":"Il soggetto è l’elemento con cui il verbo concorda nella persona e nel numero e di cui il predicato dice qualcosa. Può compiere un’azione, riceverla, trovarsi in uno stato o possedere una caratteristica: Luca apre, il pacco è aperto, Luca dorme. Non coincide quindi sempre con chi fa qualcosa. Può stare dopo il verbo: sul banco riposano due tavole. Può essere sottinteso: lavoriamo indica noi. Nelle frasi impersonali, come piove, non c’è un soggetto da inventare. Un gruppo soggetto può comprendere articolo, attributi e specificazioni: le due tavole di abete.","examples":[{"sentence":"Sul banco riposano due tavole di abete.","explanation":"Il soggetto completo è due tavole di abete, anche se segue il verbo."},{"sentence":"Abbiamo finito il disegno.","explanation":"Il soggetto sottinteso è noi; abbiamo finito è un’unica forma verbale."}]},{"title":"Riconoscere l’oggetto","text":"Il complemento oggetto dipende direttamente da un verbo transitivo: la classe prepara il modello. Nei riflessivi propri, come Luca si lava, il pronome oggetto può riferirsi allo stesso soggetto. Non è normalmente introdotto da preposizione. Può essere un nome, un gruppo nominale, un pronome o una proposizione: lo preparo, so che arriverai. La domanda chi? o che cosa? va fatta rispetto al verbo dopo aver identificato il soggetto, altrimenti può confondere. In arriva il bus, il bus risponde a che cosa arriva? ma è soggetto. Anche un partitivo può introdurre un oggetto: compro dei fogli significa compro alcuni fogli, non un complemento indiretto.","examples":[{"sentence":"Compro dei fogli.","explanation":"Dei fogli è oggetto con articolo partitivo."}]},{"title":"Analizzare gruppi e trasformazioni","text":"Nell’analisi distingui il nucleo dal gruppo completo: in la classe misura una lunga tavola di acero, tavola è il nome centrale dell’oggetto, mentre una lunga tavola di acero è l’intero gruppo. L’ordine può cambiare senza cambiare i ruoli: il modello lo presenta Sara mantiene Sara come soggetto. La passiva offre un confronto utile: Sara controlla il modello diventa il modello è controllato da Sara. L’oggetto dell’attiva è soggetto nella passiva e non resta oggetto. Se due verbi sono coordinati, analizza ciascuno: il gruppo misura il banco e controlla le sedie contiene un soggetto condiviso e due oggetti diversi.","examples":[{"sentence":"Il modello è controllato dalla classe.","explanation":"Il modello è soggetto passivo, non oggetto."}]},{"title":"La frase minima e le espansioni","text":"La frase minima contiene il verbo e gli elementi richiesti dal suo significato nella costruzione considerata. Un verbo impersonale può bastare da solo: nevica. Con dorme serve normalmente il soggetto: il gatto dorme. Con ripara possiamo indicare anche ciò che viene riparato: Lea ripara il violino. In Lea consegna il modello a Sam il verbo collega chi consegna, ciò che è consegnato e il destinatario. Altri dettagli possono ampliare la frase: ieri, nel laboratorio o con cura. Le costruzioni cambiano a seconda del contesto: non decidere che un elemento manca senza verificare se può essere sottinteso. Il nucleo della frase è diverso dal nucleo di un gruppo nominale: in una tavola lunga, tavola è il nome centrale del gruppo.","examples":[{"sentence":"Ieri Lea ha riparato il violino in laboratorio.","explanation":"Lea ha riparato il violino è il nucleo della costruzione; ieri e in laboratorio aggiungono informazioni."}]},{"title":"Una frase, analizzata passo per passo","text":"Osserva: «Ieri Nora, giovane liutaia, ha mostrato il progetto a Sam in laboratorio». 1. Trova il predicato: ha mostrato. 2. Cerca il soggetto: Nora; giovane liutaia precisa Nora, con liutaia apposizione e giovane suo attributo. 3. Individua l’oggetto: il progetto. 4. Cerca il destinatario: a Sam è complemento di termine. 5. Individua gli altri elementi: ieri indica tempo e in laboratorio luogo. Rileggi collegando ogni gruppo alla parola cui si riferisce. La stessa frase può essere suddivisa in gruppi e poi analizzata distinguendo le funzioni al loro interno.","examples":[{"sentence":"Ieri Nora, giovane liutaia, ha mostrato il progetto a Sam in laboratorio.","explanation":"Nora: soggetto; giovane: attributo; liutaia: apposizione; ha mostrato: predicato verbale; il progetto: oggetto; a Sam: termine; ieri: tempo; in laboratorio: stato in luogo."}]}],"diagram":{"title":"Soggetto, predicato e oggetto: i collegamenti da ricordare","steps":[{"label":"Predicato","detail":"Dice qualcosa: prepara, ha preparato, è preciso."},{"label":"Soggetto","detail":"Concorda con il verbo e può agire, ricevere o essere in uno stato."},{"label":"Oggetto","detail":"Dipende direttamente da un transitivo: preparo il modello."},{"label":"Gruppi completi","detail":"Il nome centrale può avere articoli, attributi e complementi."}]},"pitfalls":[{"mistake":"Il soggetto è sempre chi compie l’azione.","correction":"Il soggetto può anche ricevere l’azione o essere in uno stato.","why":"Nella passiva riceve l’azione e concorda con il verbo."},{"mistake":"È preciso contiene l’oggetto preciso.","correction":"È preciso è un predicato nominale.","why":"Preciso esprime una caratteristica del soggetto tramite essere."}],"recap":["Il predicato ha come centro un verbo.","Il soggetto si riconosce anche dall’accordo.","L’oggetto dipende direttamente da un transitivo.","I gruppi completi comprendono le espansioni del nome."],"review":[{"question":"Qual è il soggetto di «arrivano gli studenti»?","answer":"Gli studenti: il verbo plurale concorda con quel gruppo."},{"question":"Che cosa è «è stabile» in «il tavolo è stabile»?","answer":"Il predicato nominale completo."},{"question":"Il soggetto di una passiva è un oggetto?","answer":"No: riceve l’azione ma ha funzione di soggetto."}],"levels":{"base":{"focus":"Individuare il predicato","example":{"sentence":"La classe prepara il modello.","explanation":"La classe è soggetto, prepara predicato verbale, il modello oggetto."}},"consolidamento":{"focus":"Riconoscere il soggetto","example":{"sentence":"Sul banco riposano due tavole di abete.","explanation":"Il soggetto completo è due tavole di abete, anche se segue il verbo."}},"avanzato":{"focus":"Cercare l’oggetto","example":{"sentence":"Il modello è controllato dalla classe.","explanation":"Il modello è soggetto passivo, non oggetto."}}},"simplified":{"lead":"Nella frase cerca il verbo, il soggetto e l’eventuale oggetto.","steps":["Trova il verbo: taglia.","Chi taglia? Sara è il soggetto.","Che cosa taglia? Il cartone è l’oggetto."],"example":{"sentence":"Sara taglia il cartone.","explanation":"Sara è soggetto; taglia predicato; il cartone oggetto."}},"pei":{"rule":"In Sara taglia il cartone, Sara è soggetto e il cartone è oggetto.","example":{"sentence":"Sara taglia il cartone.","explanation":"Sara è soggetto; taglia predicato; il cartone oggetto."}},"trackExamples":{"moda":{"sentence":"La sarta taglia una manica.","explanation":"Sarta è soggetto; una manica è oggetto."},"arredo":{"sentence":"Il tavolo nuovo è stabile.","explanation":"Il tavolo nuovo è il gruppo soggetto; è stabile è predicato nominale."},"liuteria":{"sentence":"La liutaia controlla la superficie della tavola.","explanation":"L’intero gruppo oggetto è la superficie della tavola."}},"anchor":{"sentence":"Il gatto occupa il banco. Il progetto aspetta.","explanation":"Nella prima frase il gatto è soggetto, occupa è predicato e il banco è oggetto. Nella seconda il progetto è soggetto.","memory":"Cerca il verbo, poi separa soggetto e oggetto."}},{"topic":"Attributo e apposizione","area":"frase","lead":"Attributo e apposizione aggiungono informazioni a un nome: l’attributo è un aggettivo, l’apposizione ha come centro un nome.","objectives":["Riconoscere l’attributo","Riconoscere l’apposizione","Controllare il legame"],"sections":[{"title":"L’attributo","text":"L’attributo è un aggettivo riferito direttamente a un nome. Può esprimere una qualità, ma anche appartenenza, quantità, posizione o ordine: una stoffa morbida, il mio quaderno, tre fogli, questo banco, il secondo piano. Concorda con il nome secondo le regole dell’aggettivo e può comparire prima o dopo. Un nome può avere più attributi: queste due piccole scatole. Per individuarli cerca a quale nome si riferisce ogni parola e verifica se appartiene alla categoria degli aggettivi. L’articolo accompagna il nome ma non è un attributo, perché è una categoria diversa.","examples":[{"sentence":"Il vecchio ponte resiste.","explanation":"Vecchio è aggettivo riferito direttamente a ponte: attributo."},{"sentence":"Abbiamo osservato tre rondini.","explanation":"Tre è aggettivo numerale e attributo di rondini."}]},{"title":"L’apposizione","text":"L’apposizione è un nome o un gruppo nominale che chiarisce, identifica o presenta un altro nome: Sara, la progettista, espone il lavoro. Progettista è il centro dell’apposizione; la progettista del gruppo è il suo gruppo completo. Può precedere il nome: il poeta Dante. Non richiede sempre virgole: il ruolo identificativo e la struttura della frase guidano la punteggiatura. Le virgole si usano spesso quando l’informazione è aggiunta come inciso. L’apposizione può avere propri attributi e complementi: Sara, giovane progettista di interni. Giovane descrive progettista, non è esso stesso un’apposizione.","examples":[{"sentence":"Elena, mia sorella, telefona.","explanation":"Mia sorella è il gruppo appositivo; sorella ne è il nome centrale."},{"sentence":"Il poeta Dante scrisse la Commedia.","explanation":"Poeta è apposizione di Dante senza virgole."}]},{"title":"Funzioni diverse nella frase","text":"Attributi e apposizioni possono riferirsi al soggetto o a un complemento. In la docente osserva il disegno preciso, preciso è attributo dell’oggetto; in scrivo a Marco, il capogruppo, l’apposizione chiarisce un complemento di termine. Non sono funzioni riservate al soggetto. Per analizzare un gruppo conserva il rapporto interno: in la superficie liscia del tavolo, liscia si riferisce a superficie. In il tavolo dalla superficie liscia, invece, liscia appartiene al nome superficie dentro un complemento. L’accordo aiuta, ma per scegliere serve anche capire il significato e leggere il gruppo completo.","examples":[{"sentence":"La docente osserva il disegno preciso.","explanation":"Preciso è attributo del nome che svolge funzione di oggetto."}]},{"title":"Confronto con il predicato","text":"Un aggettivo collegato al soggetto da essere non è attributo in quella costruzione: il ponte è vecchio contiene un predicato nominale, mentre il vecchio ponte contiene un attributo. Anche un nome dopo essere può essere parte nominale: Sara è una progettista. In Sara, la progettista, parla, il nome è invece apposizione. Con altri verbi può esserci un complemento predicativo: considero Sara esperta. La distinzione dipende dal legame sintattico, non soltanto dalla categoria della parola. Negli esercizi controlla se è richiesto il nucleo, come progettista, oppure tutto il gruppo, come la progettista del laboratorio.","examples":[{"sentence":"Il ponte è vecchio.","explanation":"È vecchio è predicato nominale: vecchio non è attributo in questa frase."}]},{"title":"Attributo del nome del predicato e tipi di apposizione","text":"Un attributo può precisare anche il nome che costituisce la parte nominale del predicato: in Lina è una liutaia esperta, esperta accompagna liutaia ed è attributo di quel nome. Non va separato come se il verbo attribuisse direttamente esperta a Lina. In alcune grammatiche scolastiche si distingue tra apposizione semplice, formata dal nome che precisa un altro nome, e apposizione composta, quando quel nome è accompagnato da attributi o complementi. Confronta la liutaia Lina e Lina, esperta liutaia del quartiere: la seconda apposizione comprende un gruppo più ampio. Le virgole dipendono dalla funzione e dal contesto, non soltanto dall’etichetta semplice o composta.","examples":[{"sentence":"Nora è una restauratrice attenta.","explanation":"Attenta è attributo di restauratrice, nome che fa parte del predicato nominale."},{"sentence":"La docente Lina parla; Lina, docente esperta del laboratorio, spiega.","explanation":"Docente è apposizione semplice nel primo esempio; docente esperta del laboratorio è un gruppo appositivo più ampio nel secondo."}]}],"diagram":{"title":"Attributo e apposizione: i collegamenti da ricordare","steps":[{"label":"Attributo","detail":"È aggettivo: il vecchio ponte, tre fogli."},{"label":"Apposizione","detail":"È nome: Sara, la progettista."},{"label":"Espansioni","detail":"L’apposizione può avere propri attributi e complementi."},{"label":"Confronto","detail":"Il ponte è vecchio: vecchio è parte nominale, non attributo."}]},"pitfalls":[{"mistake":"Il ponte è vecchio: vecchio è attributo.","correction":"Il ponte è vecchio: vecchio è parte nominale.","why":"Essere collega la qualità al soggetto nel predicato."},{"mistake":"In «mia sorella», mia è apposizione.","correction":"Sorella è il nome centrale dell’apposizione; mia è suo attributo.","why":"L’apposizione ha centro nominale, l’attributo è un aggettivo."}],"recap":["L’attributo è un aggettivo legato a un nome.","L’apposizione ha un nome come centro.","Entrambi possono riferirsi a soggetti e complementi.","La stessa parola cambia funzione secondo la costruzione."],"review":[{"question":"Tre in «tre fogli» può essere attributo?","answer":"Sì: è un aggettivo numerale riferito a fogli."},{"question":"In «Sara è progettista», progettista è apposizione?","answer":"No: è parte nominale del predicato."},{"question":"In «Luca, il mio compagno», qual è il centro dell’apposizione?","answer":"Compagno; mio è attributo di compagno."}],"levels":{"base":{"focus":"Riconoscere l’attributo","example":{"sentence":"Il vecchio ponte resiste.","explanation":"Vecchio è aggettivo riferito direttamente a ponte: attributo."}},"consolidamento":{"focus":"Riconoscere l’apposizione","example":{"sentence":"Elena, mia sorella, telefona.","explanation":"Mia sorella è il gruppo appositivo; sorella ne è il nome centrale."}},"avanzato":{"focus":"Controllare il legame","example":{"sentence":"Il ponte è vecchio.","explanation":"È vecchio è predicato nominale: vecchio non è attributo in questa frase."}}},"simplified":{"lead":"Un aggettivo può descrivere direttamente un nome.","steps":["Trova il nome: sedia.","Cerca l’aggettivo: rossa.","Rossa è attributo di sedia."],"example":{"sentence":"La sedia rossa è qui.","explanation":"Rossa accompagna direttamente sedia."}},"pei":{"rule":"In sedia rossa, rossa è un attributo.","example":{"sentence":"La sedia rossa è qui.","explanation":"Rossa accompagna direttamente sedia."}},"trackExamples":{"moda":{"sentence":"La manica destra è corta.","explanation":"Destra è attributo; corta è parte nominale."},"arredo":{"sentence":"Sofia, la progettista del gruppo, presenta il mobile.","explanation":"Progettista è il centro dell’apposizione."},"liuteria":{"sentence":"Il ponticello nuovo è pronto.","explanation":"Nuovo è attributo di ponticello; pronto appartiene al predicato."}},"anchor":{"sentence":"Leo, il cuoco, prepara un toast gigante.","explanation":"Cuoco è nome e apposizione di Leo; gigante è aggettivo e attributo di toast.","memory":"Apposizione: nome. Attributo: aggettivo."}},{"topic":"Termine e specificazione","area":"frase","lead":"Il termine indica a chi o a che cosa si rivolge un rapporto; la specificazione precisa il significato di un nome.","objectives":["Individuare il termine","Individuare la specificazione","Confrontare i significati"],"sections":[{"title":"Il complemento di termine","text":"Il complemento di termine indica il destinatario o l’elemento verso cui si orienta ciò che il verbo o un’altra espressione comunica: consegno il foglio a Sara, questa scelta è utile alla classe. Risponde alle domande a chi? a che cosa? quando quelle domande sono coerenti con la costruzione. È introdotto normalmente da a, semplice o articolata. Può essere espresso da una persona, un gruppo o una cosa: al gruppo, al progetto. Non ogni a introduce termine: vado a Roma indica una destinazione nello spazio. Il significato e la parola da cui il complemento dipende sono decisivi.","examples":[{"sentence":"Consegno il pacco a Luca.","explanation":"A Luca è termine: indica il destinatario della consegna."},{"sentence":"Il progetto è utile alla classe.","explanation":"Alla classe è termine dipendente dall’aggettivo utile."}]},{"title":"Termine espresso da pronomi","text":"Il termine può essere un pronome atono senza preposizione visibile. In le scrivo, le significa a lei; in gli rispondo, gli significa a lui. Mi, ti, ci, vi possono significare a me, a te, a noi, a voi. Le stesse forme possono avere altre funzioni: mi chiama contiene un oggetto, mi telefona contiene un termine. Le può anche significare loro come oggetto femminile plurale: le osservo, riferito alle sedie. Per riconoscere la funzione espandi il pronome e controlla la costruzione del verbo. Nell’italiano formale è utile distinguere con cura gli, a lui, e le, a lei.","examples":[{"sentence":"Le scrivo una lettera.","explanation":"Le significa a lei ed è complemento di termine."},{"sentence":"Il colore della stoffa è intenso.","explanation":"Della stoffa specifica il nome colore."}]},{"title":"Il complemento di specificazione","text":"La specificazione precisa un nome stabilendo una relazione di appartenenza, riferimento o altra dipendenza: il banco della classe, il colore della vernice, il ricordo della vacanza. È introdotta normalmente da di, semplice o articolata, e risponde a di chi? di che cosa? nel rapporto con il nome reggente. Non equivale soltanto a possesso: la lunghezza della tavola indica una proprietà riferita alla tavola. Una specificazione può contenere attributi e altre espansioni: il progetto dei nuovi studenti. Individua prima il nome precisato e poi il gruppo dipendente, senza fermarti all’articolo o al primo nome.","examples":[{"sentence":"La sedia di legno è leggera.","explanation":"Di legno indica materia, non specificazione."}]},{"title":"Confrontare i casi","text":"La preposizione di introduce anche materia, argomento e altre relazioni: una sedia di legno indica materia, parlare di musica indica argomento. Del può inoltre essere un articolo partitivo: compro del pane significa un po’ di pane e non specifica un nome precedente. Per distinguere termine e specificazione chiediti quale parola viene completata e quale relazione si costruisce. In consegno il progetto di Sara alla docente, di Sara specifica progetto e alla docente indica il destinatario di consegno. Riconoscere entrambi nella stessa frase evita di assegnare l’etichetta in base alla sola posizione o alla prima preposizione incontrata.","examples":[{"sentence":"Consegno il progetto di Sara alla docente.","explanation":"Di Sara specifica progetto; alla docente è il termine di consegno."}]},{"title":"La particella ne: guarda il contesto","text":"La particella ne può sostituire gruppi con funzioni diverse: per riconoscerla ricostruisci il gruppo a cui rimanda e osserva il rapporto nella frase. In «Conosco il progetto e ne parlo» significa del progetto e indica l’argomento; in «Conosco il progetto e ne apprezzo i dettagli» significa del progetto e specifica dettagli. In «Entro in aula e ne esco» significa dall’aula e indica provenienza; in «Ho cinque matite e ne scelgo due» significa delle cinque matite e indica l’insieme da cui si sceglie, cioè un partitivo. Non attribuire sempre a ne la stessa funzione.","examples":[{"sentence":"Conosco il progetto: ne parlo e ne controllo i dettagli.","explanation":"Nel primo caso ne indica l’argomento; nel secondo specifica i dettagli."},{"sentence":"Ho cinque matite e ne scelgo due.","explanation":"Ne rimanda all’insieme delle matite: è complemento partitivo."}]}],"diagram":{"title":"Termine e specificazione: i collegamenti da ricordare","steps":[{"label":"Termine","detail":"A chi? A che cosa? Consegno il foglio alla docente."},{"label":"Pronomi di termine","detail":"Gli = a lui; le = a lei; mi = a me secondo la costruzione."},{"label":"Specificazione","detail":"Di chi? Di che cosa? Il colore della stoffa."},{"label":"Controllo del significato","detail":"A Roma è luogo; di legno è materia; del pane può essere partitivo."}]},"pitfalls":[{"mistake":"A Roma è sempre termine.","correction":"In «vado a Roma», a Roma indica luogo.","why":"La preposizione a non basta per classificare il complemento."},{"mistake":"Di legno è sempre specificazione.","correction":"In «sedia di legno», di legno indica materia.","why":"Occorre interpretare la relazione con sedia."}],"recap":["Il termine indica il destinatario di un rapporto.","Il termine può essere espresso da un pronome.","La specificazione precisa un nome.","Le preposizioni da sole non decidono l’analisi."],"review":[{"question":"Che cosa significa le in «le rispondo»?","answer":"A lei: è complemento di termine."},{"question":"Che cosa specifica del violino in «il manico del violino»?","answer":"Il nome manico."},{"question":"Del in «compro del pane» introduce specificazione?","answer":"No: è articolo partitivo davanti all’oggetto."}],"levels":{"base":{"focus":"Individuare il termine","example":{"sentence":"Consegno il pacco a Luca.","explanation":"A Luca è termine: indica il destinatario della consegna."}},"consolidamento":{"focus":"Individuare la specificazione","example":{"sentence":"Il colore della stoffa è intenso.","explanation":"Della stoffa specifica il nome colore."}},"avanzato":{"focus":"Confrontare i significati","example":{"sentence":"Consegno il progetto di Sara alla docente.","explanation":"Di Sara specifica progetto; alla docente è il termine di consegno."}}},"simplified":{"lead":"Il termine può indicare la persona che riceve qualcosa.","steps":["Trova il verbo: consegno.","Leggi a chi viene consegnato il foglio.","A Sara indica il destinatario."],"example":{"sentence":"Consegno il foglio a Sara.","explanation":"A Sara indica il destinatario della consegna."}},"pei":{"rule":"A Sara è termine quando indica a chi consegno.","example":{"sentence":"Consegno il foglio a Sara.","explanation":"A Sara indica il destinatario della consegna."}},"trackExamples":{"moda":{"sentence":"Consegno il bozzetto alla modellista.","explanation":"Alla modellista indica il destinatario."},"arredo":{"sentence":"Il bordo della mensola è liscio.","explanation":"Della mensola specifica bordo."},"liuteria":{"sentence":"Mostro alla classe il manico del violino.","explanation":"Alla classe è termine; del violino è specificazione."}},"anchor":{"sentence":"Passo a Leo il panino di Marta. Marta osserva.","explanation":"A Leo indica il destinatario ed è termine. Di Marta precisa a chi appartiene il panino ed è specificazione.","memory":"A chi lo passo? Di chi è il panino?"}},{"topic":"Luogo e tempo","area":"frase","lead":"I complementi di luogo e tempo collocano gli eventi nello spazio e nel tempo, distinguendo posizioni, direzioni, momenti e durate.","objectives":["Collocare nello spazio","Collocare nel tempo","Leggere il gruppo completo"],"sections":[{"title":"Posizione e destinazione","text":"Il complemento di stato in luogo indica dove si trova qualcuno o avviene un fatto senza uno spostamento verso una meta: studio in aula, il metro resta sul banco. Può accompagnare anche un’attività: cammino nel cortile descrive un movimento svolto entro un luogo, senza indicarlo come destinazione. Il moto a luogo indica invece verso dove si dirige lo spostamento: vado in laboratorio, porto il disegno a scuola. Le preposizioni possono coincidere: in aula è stato in luogo in resto in aula e moto a luogo in entro in aula. Verbo e significato del fatto permettono di distinguere.","examples":[{"sentence":"Le forbici restano nel cassetto.","explanation":"Nel cassetto indica stato in luogo."},{"sentence":"Portiamo le ante in laboratorio.","explanation":"In laboratorio indica moto a luogo, cioè destinazione."}]},{"title":"Provenienza e passaggio","text":"Il moto da luogo indica da dove parte uno spostamento: esco dall’aula, torno da Roma. Il moto per luogo indica il percorso o passaggio: passo attraverso il corridoio, cammino per il parco per raggiungere l’uscita. Da può introdurre anche altri rapporti: il mobile è costruito da Luca contiene un agente, non un’origine spaziale. I luoghi possono essere reali oppure figurati, come uscire da un dubbio. Nell’analisi scolastica anche avverbi e particelle possono esprimere luogo: qui, fuori, ci vado, ne esco. Una domanda spaziale aiuta soltanto se restituisce il significato della frase, non se è applicata meccanicamente.","examples":[{"sentence":"Esco dall’aula e passo per il corridoio.","explanation":"Dall’aula indica provenienza; per il corridoio indica percorso."},{"sentence":"Domani iniziamo alle nove.","explanation":"Domani e alle nove collocano l’evento nel tempo."}]},{"title":"Momento e durata","text":"Il tempo determinato indica quando avviene un fatto: domani, alle nove, lunedì, durante la lezione. Può riferirsi a un intervallo individuato, non per forza a un istante brevissimo: nel mese di marzo. Il tempo continuato indica per quanto tempo dura un fatto: per due ore, tutta la mattina. Può comparire senza preposizione: ho studiato due ore. Per non confonderli, chiediti se il gruppo colloca l’evento oppure ne misura la durata. In lunedì lavoriamo per tre ore, lunedì colloca e per tre ore misura. Anche gli avverbi possono avere funzione temporale, non soltanto i gruppi nominali.","examples":[{"sentence":"Abbiamo osservato il campione per due ore.","explanation":"Per due ore misura la durata: tempo continuato."}]},{"title":"Relazioni temporali e gruppi completi","text":"Espressioni come da due giorni possono indicare una durata che continua fino al riferimento; tra due giorni colloca un evento futuro. In due ore può indicare il tempo impiegato per completare qualcosa: ho costruito il modello in due ore. Leggi il contesto per distinguere tempo e mezzo: con il treno non indica durata. Quando un esercizio chiede tutto il complemento, includi preposizione, articolo, eventuali numerali e attributi: per due lunghe ore. Una frase può contenere più luoghi e più tempi. Un piccolo schema con partenza, percorso e meta, insieme a una linea temporale, aiuta a separarli senza assegnare ogni preposizione a una sola categoria.","examples":[{"sentence":"Lunedì lavoriamo per tre ore in laboratorio.","explanation":"Lunedì indica quando; per tre ore durata; in laboratorio luogo dell’attività."}]}],"diagram":{"title":"Luogo e tempo: i collegamenti da ricordare","steps":[{"label":"Stato e meta","detail":"Resto in aula; entro in aula."},{"label":"Origine e percorso","detail":"Esco dall’aula; passo per il corridoio."},{"label":"Tempo determinato","detail":"Quando? Domani, alle nove, nel mese di marzo."},{"label":"Tempo continuato","detail":"Per quanto tempo? Per due ore, tutta la mattina."}]},"pitfalls":[{"mistake":"In laboratorio indica sempre stato in luogo.","correction":"In «entro in laboratorio» indica moto a luogo.","why":"La stessa preposizione può indicare una destinazione."},{"mistake":"Due ore è sempre tempo determinato.","correction":"In «studio due ore» indica durata.","why":"La funzione dipende dal rapporto con il fatto descritto."}],"recap":["Il luogo distingue posizione e direzioni.","Le preposizioni possono avere più valori.","Il tempo determinato colloca un evento.","Il tempo continuato ne esprime la durata."],"review":[{"question":"Che luogo esprime dall’aula in «esco dall’aula»?","answer":"Moto da luogo: indica la provenienza."},{"question":"Che differenza c’è fra lunedì e per tre ore?","answer":"Lunedì colloca il fatto; per tre ore ne misura la durata."},{"question":"Un’attività con movimento esclude lo stato in luogo?","answer":"No: camminare nel cortile può descrivere un’attività svolta entro quel luogo."}],"levels":{"base":{"focus":"Collocare nello spazio","example":{"sentence":"Le forbici restano nel cassetto.","explanation":"Nel cassetto indica stato in luogo."}},"consolidamento":{"focus":"Collocare nel tempo","example":{"sentence":"Domani iniziamo alle nove e lavoriamo per due ore.","explanation":"Domani e alle nove collocano gli eventi nel tempo: tempo determinato. Per due ore misura la durata del lavoro: tempo continuato."}},"avanzato":{"focus":"Leggere il gruppo completo","example":{"sentence":"Lunedì lavoriamo per tre ore in laboratorio.","explanation":"Lunedì indica quando; per tre ore durata; in laboratorio luogo dell’attività."}}},"simplified":{"lead":"Il luogo dice dove; il tempo dice quando o per quanto.","steps":["Trova l’espressione di luogo.","Cerca poi l’espressione di tempo.","Non confondere le due informazioni."],"example":{"sentence":"Oggi lavoro in aula.","explanation":"Oggi indica tempo; in aula indica luogo."}},"pei":{"rule":"In aula dice dove; oggi dice quando.","example":{"sentence":"Oggi lavoro in aula.","explanation":"Oggi indica tempo; in aula indica luogo."}},"trackExamples":{"moda":{"sentence":"La sarta lavora in atelier per due ore.","explanation":"In atelier indica il luogo dell’attività; per due ore la durata."},"arredo":{"sentence":"Domani portiamo le ante in laboratorio.","explanation":"Domani indica tempo; in laboratorio la meta."},"liuteria":{"sentence":"Il calibro resta nel cassetto fino a domani.","explanation":"Nel cassetto indica posizione; fino a domani un limite temporale."}},"anchor":{"sentence":"Il bus passa davanti a casa alle sette. Io arrivo alle sette e uno.","explanation":"Davanti a casa colloca il passaggio nello spazio; alle sette e alle sette e uno collocano gli eventi nel tempo.","memory":"Dove? Quando? Tieni separate le due coordinate."}},{"topic":"Causa, fine, mezzo e modo","area":"frase","lead":"Questi complementi spiegano perché accade qualcosa, per quale scopo, con quale strumento e in quale maniera.","objectives":["Distinguere causa e fine","Riconoscere il mezzo","Riconoscere il modo"],"sections":[{"title":"Causa: da che cosa nasce il fatto","text":"Il complemento di causa indica il motivo che provoca un fatto, uno stato o una reazione: tremo per il freddo, sono felice per il risultato. La causa viene presentata come origine della situazione, anche quando non è un’azione volontaria. Può essere introdotta da per, di, da, a causa di e altre espressioni: piange di gioia, è stanco per il lavoro. La domanda perché? va precisata: per quale motivo? Non ogni gruppo con per è causa. In studio per l’esame il gruppo indica normalmente ciò a cui il lavoro mira, mentre resto a casa per la febbre indica il motivo della permanenza.","examples":[{"sentence":"Tremava per il freddo.","explanation":"Per il freddo indica la causa del tremore."},{"sentence":"Mi alleno per la gara.","explanation":"Per la gara indica lo scopo dell’allenamento."}]},{"title":"Fine: verso quale risultato","text":"Il complemento di fine o scopo indica il risultato a cui si mira: mi alleno per la gara, preparo un cartello per l’esposizione. Non dice che quel risultato si realizzerà certamente, ma lo presenta come obiettivo. Si trova con per, a, da e locuzioni come allo scopo di: occhiali da sole indica una destinazione d’uso. Causa e fine possono avere la stessa preposizione: litigo per un errore e studio per una promozione. Prova due parafrasi: a causa di aiuta a riconoscere il motivo; allo scopo di aiuta a riconoscere l’obiettivo. La frase completa deve rendere sensata la sostituzione.","examples":[{"sentence":"Preparo il cartello per l’esposizione.","explanation":"Per l’esposizione indica la destinazione e lo scopo del cartello."},{"sentence":"Taglio il cartone con le forbici.","explanation":"Con le forbici indica lo strumento impiegato."}]},{"title":"Mezzo: con che cosa","text":"Il complemento di mezzo o strumento indica ciò attraverso cui si realizza il fatto: taglio con le forbici, invio il messaggio per posta, viaggio in treno. Può essere un oggetto, un materiale, un mezzo di trasporto o un canale di comunicazione. La domanda utile è con quale strumento? oppure attraverso quale mezzo? Con non introduce sempre mezzo: con calma descrive una maniera, con Sara indica compagnia. La persona che agisce non è uno strumento soltanto perché è preceduta da con. Nelle frasi tecniche scegliere uno strumento concreto spesso rende evidente il rapporto e limita le interpretazioni concorrenti.","examples":[{"sentence":"Invio il messaggio per posta.","explanation":"Per posta indica il mezzo o canale della comunicazione."}]},{"title":"Modo: in quale maniera","text":"Il complemento di modo descrive come si svolge il fatto: risponde con gentilezza, lavora in silenzio, controlla con attenzione. Può essere espresso anche da un avverbio, come lentamente, o da una locuzione. Alcune espressioni possono avere letture vicine: con la forza può richiamare una risorsa impiegata oppure il modo di agire. Nei casi dubbi serve più contesto e non conviene inventare un’unica soluzione obbligatoria. Per analizzare separa le domande: quale causa ha prodotto il fatto? quale scopo si cerca? quale strumento si usa? come si agisce? Una frase può contenere più rapporti: per il rumore ascolto con le cuffie e procedo con attenzione.","examples":[{"sentence":"Rispondo con gentilezza.","explanation":"Con gentilezza indica il modo della risposta."}]}],"diagram":{"title":"Causa, fine, mezzo e modo: i collegamenti da ricordare","steps":[{"label":"Causa","detail":"Per quale motivo? Tremo per il freddo."},{"label":"Fine","detail":"Per quale scopo? Mi alleno per la gara."},{"label":"Mezzo","detail":"Con quale strumento? Taglio con le forbici."},{"label":"Modo","detail":"In quale maniera? Rispondo con gentilezza."}]},"pitfalls":[{"mistake":"Per introduce sempre causa.","correction":"Per può introdurre anche fine, mezzo e altri rapporti.","why":"Il significato del gruppo decide l’analisi."},{"mistake":"Con attenzione è mezzo.","correction":"Con attenzione è modo.","why":"Non indica uno strumento, ma come viene svolta l’azione."}],"recap":["La causa è il motivo del fatto.","Il fine è l’obiettivo cercato.","Il mezzo è lo strumento o il canale.","Il modo è la maniera in cui il fatto avviene."],"review":[{"question":"Perché con le forbici è mezzo?","answer":"Le forbici sono lo strumento con cui si taglia."},{"question":"Che cosa distingue causa e scopo?","answer":"La causa provoca o motiva il fatto; lo scopo è il risultato a cui si mira."},{"question":"Con indica sempre mezzo?","answer":"No: può indicare anche modo, compagnia e altri rapporti."}],"levels":{"base":{"focus":"Distinguere causa e fine","example":{"sentence":"Tremava per il freddo.","explanation":"Per il freddo indica la causa del tremore."}},"consolidamento":{"focus":"Riconoscere il mezzo","example":{"sentence":"Taglio il cartone con le forbici.","explanation":"Con le forbici indica lo strumento impiegato."}},"avanzato":{"focus":"Riconoscere il modo","example":{"sentence":"Rispondo con gentilezza.","explanation":"Con gentilezza indica il modo della risposta."}}},"simplified":{"lead":"Il mezzo è lo strumento con cui fai qualcosa.","steps":["Trova l’azione: taglio.","Cerca lo strumento usato.","Con le forbici indica il mezzo."],"example":{"sentence":"Taglio con le forbici.","explanation":"Le forbici sono il mezzo usato."}},"pei":{"rule":"Con le forbici indica lo strumento per tagliare.","example":{"sentence":"Taglio con le forbici.","explanation":"Le forbici sono il mezzo usato."}},"trackExamples":{"moda":{"sentence":"La sarta taglia con le forbici e lavora con cura.","explanation":"Con le forbici è mezzo; con cura è modo."},"arredo":{"sentence":"Il pannello si è gonfiato per l’umidità.","explanation":"Per l’umidità indica la causa."},"liuteria":{"sentence":"Prepariamo lo strumento per il concerto.","explanation":"Per il concerto indica lo scopo della preparazione."}},"anchor":{"sentence":"Per la fame apro il panino con le mani, con molta calma.","explanation":"Per la fame indica causa; con le mani mezzo; con molta calma modo. In studio per la prova, per la prova indica invece uno scopo.","memory":"Motivo, obiettivo, strumento e maniera sono domande diverse."}},{"topic":"Oggetto","area":"frase","lead":"Il complemento oggetto è collegato direttamente a un verbo transitivo e va distinto dal soggetto e dai complementi introdotti da preposizione.","objectives":["Trovare la costruzione transitiva","Separare nucleo e gruppo","Confrontare i ruoli"],"sections":[{"title":"Un rapporto diretto con il verbo","text":"Il complemento oggetto è un elemento previsto dalla costruzione di un verbo transitivo: Sara prepara una torta, il gruppo misura la nicchia. Non è normalmente introdotto da una preposizione. Spesso indica ciò su cui si esercita un’azione, ma non deve essere per forza un oggetto materiale né ricevere un effetto visibile: amo la musica, conosco Luca. Per riconoscerlo cerca prima il predicato e il soggetto, poi controlla che cosa completa direttamente quel verbo. Le domande chi? e che cosa? aiutano soltanto se il rapporto sintattico è già chiaro: in arriva Luca, Luca è soggetto.","examples":[{"sentence":"La sarta stira la gonna.","explanation":"La gonna è oggetto diretto di stira."},{"sentence":"Conosco Luca.","explanation":"Luca è oggetto anche se è una persona e non subisce una modifica materiale."}]},{"title":"Il nucleo e il gruppo completo","text":"L’oggetto può essere costituito da un nome con articolo e altri elementi: una cerniera invisibile, due ripiani regolabili, la superficie della tavola. Il nucleo è il nome centrale; il gruppo completo comprende anche determinanti, attributi e complementi che dipendono dal nome. In controllo la superficie della tavola, superficie è il nucleo e la superficie della tavola è il gruppo completo; della tavola mantiene al suo interno funzione di specificazione. Quando la consegna chiede una sola parola, non trascrivere tutto il gruppo; quando chiede l’intero oggetto, non eliminare articolo e informazioni dipendenti. Questa distinzione evita risposte incomplete.","examples":[{"sentence":"Il gruppo sceglie una cerniera invisibile.","explanation":"Il nucleo è cerniera; l’intero gruppo è una cerniera invisibile."},{"sentence":"La liutaia controlla la superficie della tavola.","explanation":"L’oggetto completo include la specificazione della tavola."}]},{"title":"Pronomi, partitivi e proposizioni","text":"L’oggetto può essere un pronome: lo misuro, la ascolto, li porto, le scelgo. Mi, ti, ci, vi possono essere oggetti con alcuni verbi: mi guarda; con altri sono termini: mi parla. Dei in compro dei fogli non è una preposizione che introduce un complemento indiretto: è articolo partitivo e dei fogli è oggetto. L’oggetto può anche essere una proposizione che completa un verbo: so che arriverai, desidero partire. Nella frase complessa si parla di subordinata oggettiva. Non assegnare automaticamente la funzione di oggetto a tutto ciò che segue un verbo: molti verbi richiedono costruzioni diverse.","examples":[{"sentence":"Compro dei fogli e li porto in aula.","explanation":"Dei fogli è oggetto con partitivo; li è pronome oggetto che lo riprende."}]},{"title":"Posizione e confronto con il passivo","text":"L’oggetto si trova spesso dopo il verbo, ma può precederlo per mettere un’informazione in evidenza: quel disegno, lo presenta Marta. In questa costruzione il pronome lo riprende l’oggetto, mentre Marta resta soggetto. La concordanza verbale aiuta a distinguere i ruoli. Nella trasformazione passiva l’oggetto attivo diventa soggetto: Marta controlla le corde, le corde sono controllate da Marta. Non conserva quindi funzione di oggetto. L’assenza di preposizione è un indizio utile, non una prova sufficiente: anche soggetti, tempi e durate possono comparire senza preposizione. Ho lavorato due ore contiene una durata, non un oggetto diretto.","examples":[{"sentence":"Le corde sono controllate da Marta.","explanation":"Le corde è soggetto della passiva, corrispondente all’oggetto dell’attiva."}]}],"diagram":{"title":"Oggetto: i collegamenti da ricordare","steps":[{"label":"Legame diretto","detail":"Il transitivo ammette un oggetto: osservo il disegno."},{"label":"Nucleo","detail":"Il nome centrale: cerniera."},{"label":"Gruppo completo","detail":"Articolo ed espansioni: una cerniera invisibile."},{"label":"Altre forme","detail":"Lo osservo; compro dei fogli; so che arrivi."},{"label":"Passiva","detail":"L’oggetto dell’attiva diventa soggetto della passiva."}]},"pitfalls":[{"mistake":"Arriva il bus: il bus è oggetto.","correction":"Il bus è soggetto.","why":"Concorda con arriva; non completa un transitivo come oggetto."},{"mistake":"La superficie della tavola: l’oggetto completo è superficie.","correction":"L’oggetto completo è la superficie della tavola.","why":"Superficie è solo il nucleo del gruppo richiesto."}],"recap":["L’oggetto dipende direttamente da un transitivo.","Può indicare persone, cose, idee o intere proposizioni.","Nucleo e gruppo completo sono risposte diverse.","Nella passiva l’oggetto attivo diventa soggetto."],"review":[{"question":"Qual è il nucleo dell’oggetto in «misuro due ripiani regolabili»?","answer":"Ripiani."},{"question":"Che funzione ha li in «li controllo»?","answer":"Pronome personale con funzione di complemento oggetto."},{"question":"Due ore è oggetto in «lavoro due ore»?","answer":"No: esprime la durata del lavoro."}],"levels":{"base":{"focus":"Trovare la costruzione transitiva","example":{"sentence":"La sarta stira la gonna.","explanation":"La gonna è oggetto diretto di stira."}},"consolidamento":{"focus":"Separare nucleo e gruppo","example":{"sentence":"Il gruppo sceglie una cerniera invisibile.","explanation":"Il nucleo è cerniera; l’intero gruppo è una cerniera invisibile."}},"avanzato":{"focus":"Confrontare i ruoli","example":{"sentence":"Le corde sono controllate da Marta.","explanation":"Le corde è soggetto della passiva, corrispondente all’oggetto dell’attiva."}}},"simplified":{"lead":"L’oggetto completa direttamente un verbo transitivo.","steps":["Trova il verbo: stira.","Trova il soggetto: Sara.","Che cosa stira Sara? La gonna."],"example":{"sentence":"Sara stira la gonna.","explanation":"La gonna è il gruppo oggetto completo."}},"pei":{"rule":"In Sara stira la gonna, la gonna è oggetto.","example":{"sentence":"Sara stira la gonna.","explanation":"La gonna è il gruppo oggetto completo."}},"trackExamples":{"moda":{"sentence":"La sarta sceglie una cerniera invisibile.","explanation":"L’oggetto completo comprende articolo, nome e attributo."},"arredo":{"sentence":"Il gruppo misura la nicchia.","explanation":"Nicchia è il nucleo dell’oggetto la nicchia."},"liuteria":{"sentence":"Milo osserva il ponticello.","explanation":"Il ponticello è oggetto diretto di osserva."}},"anchor":{"sentence":"Il gatto osserva il mio panino gigante.","explanation":"Il gatto è soggetto. Il mio panino gigante è l’intero oggetto; panino è il suo nome centrale.","memory":"Se serve tutto l’oggetto, porta anche le espansioni."}},{"topic":"Soggetto e predicato","area":"frase","lead":"Il soggetto e il predicato costruiscono il rapporto centrale della frase: il predicato dice qualcosa e il soggetto è l’elemento cui quel contenuto viene attribuito.","objectives":["Riconoscere l’accordo","Individuare tutto il soggetto","Distinguere i predicati"],"sections":[{"title":"La relazione centrale","text":"Il soggetto non è definito soltanto come chi compie un’azione. In il legno è leggero possiede una caratteristica; in il pacco è stato aperto riceve un’azione; in Luca dorme si trova in una condizione. Il verbo concorda normalmente con il soggetto nella persona e nel numero: io lavoro, noi lavoriamo. Per cercarlo individua prima il verbo e chiediti a quale elemento si riferisce. Se cambi il numero del possibile soggetto, verifica se devi cambiare anche il verbo. Questo controllo è più affidabile della posizione, perché il soggetto può comparire prima o dopo il predicato.","examples":[{"sentence":"Le allieve preparano il manichino.","explanation":"Le allieve è soggetto e concorda con preparano."},{"sentence":"Sul banco riposano due tavole di abete.","explanation":"Il soggetto completo segue il verbo: due tavole di abete."}]},{"title":"Espresso, sottinteso e assente","text":"Un soggetto può essere un nome, un pronome, un infinito o un’intera proposizione: Sara ascolta, lei ascolta, leggere aiuta, che tu sia qui mi piace. Il gruppo soggetto può comprendere attributi e complementi: le due tavole di abete. Quando la persona si ricava dal verbo o dal contesto, il soggetto è sottinteso: abbiamo finito significa noi abbiamo finito. Non va però inventato nelle frasi impersonali: piove non ha un soggetto come il cielo. I collettivi singolari concordano normalmente al singolare: la classe lavora. La vicinanza di un plurale non cambia automaticamente questo accordo.","examples":[{"sentence":"Abbiamo vinto la partita.","explanation":"Il soggetto noi è sottinteso e si ricava dal verbo."},{"sentence":"Piove.","explanation":"È una frase impersonale: non occorre inventare un soggetto."}]},{"title":"Predicato verbale","text":"Il predicato verbale ha come centro un verbo che esprime un processo, uno stato o un evento. Può essere formato da una parola o da una costruzione complessa: dorme, ha dormito, è stato aperto, deve partire. Ausiliari e participi costituiscono insieme una forma verbale composta e non vanno contati come predicati separati. Essere ha valore verbale autonomo quando significa trovarsi, esistere o appartenere: il libro è sul banco, questa penna è di Sara. Nei predicati con verbi servili si considera normalmente il gruppo unitario: può arrivare. L’analisi deve seguire il significato della costruzione, non il numero delle parole.","examples":[{"sentence":"Il tavolo è stabile.","explanation":"È stabile è predicato nominale completo."}]},{"title":"Predicato nominale e confronto","text":"Il predicato nominale comprende essere come copula e una parte nominale, nome o aggettivo, che indica identità o qualità: il tavolo è stabile, Sara è una studentessa. Il predicato completo è è stabile o è una studentessa, non soltanto la parola finale. In un tavolo stabile, invece, stabile è attributo perché accompagna direttamente il nome. Con verbi come sembrare o diventare si parla generalmente di verbo copulativo e complemento predicativo del soggetto; alcune grammatiche scolastiche ampliano l’etichetta predicato nominale. Negli esercizi segui la convenzione dichiarata. In ogni caso resta chiaro il legame: una qualità viene attribuita al soggetto attraverso il verbo.","examples":[{"sentence":"Il tavolo è in laboratorio.","explanation":"Essere significa trovarsi e forma qui predicato verbale."}]},{"title":"Soggetto partitivo e parole usate come nomi","text":"Un soggetto può essere introdotto da un articolo partitivo quando indica una quantità o un numero non precisato: degli allievi aspettano significa che alcuni allievi aspettano. Il soggetto è l’intero gruppo degli allievi; degli è articolo partitivo. Non confonderlo con il complemento partitivo: in due degli allievi aspettano, due è il nucleo del soggetto e degli allievi indica l’insieme da cui due sono individuati. Anche parole di altre categorie possono funzionare come nomi e fare da soggetto: in il necessario è pronto, necessario è un aggettivo usato come nome.","examples":[{"sentence":"Delle allieve arrivano; due delle allieve restano.","explanation":"Nel primo caso delle allieve è soggetto partitivo; nel secondo delle allieve è complemento partitivo dipendente da due."},{"sentence":"Il necessario è sul banco.","explanation":"Necessario è un aggettivo usato come nome e costituisce il nucleo del soggetto."}]}],"diagram":{"title":"Soggetto e predicato: i collegamenti da ricordare","steps":[{"label":"Soggetto","detail":"Concorda col verbo: arrivano due pacchi."},{"label":"Presenza","detail":"Può essere espresso o sottinteso; nelle impersonali manca."},{"label":"Predicato verbale","detail":"Un verbo o gruppo verbale: lavora, ha lavorato."},{"label":"Predicato nominale","detail":"Essere copula + nome o aggettivo: è stabile, è una studentessa."}]},"pitfalls":[{"mistake":"In «piove» il soggetto è il cielo.","correction":"Piove è impersonale.","why":"La frase non richiede un soggetto sottinteso."},{"mistake":"È stabile: il predicato è soltanto stabile.","correction":"Il predicato nominale completo è è stabile.","why":"Comprende copula e parte nominale."}],"recap":["Il soggetto concorda con il verbo.","Può seguire il predicato o essere sottinteso.","Le frasi impersonali non richiedono un soggetto.","Il predicato nominale comprende copula e parte nominale."],"review":[{"question":"Qual è il soggetto di «arrivano due pacchi»?","answer":"Due pacchi."},{"question":"È sul banco è predicato nominale?","answer":"No: essere ha valore autonomo di trovarsi."},{"question":"Qual è il predicato nominale in «il cielo è limpido»?","answer":"È limpido."}],"levels":{"base":{"focus":"Riconoscere l’accordo","example":{"sentence":"Le allieve preparano il manichino.","explanation":"Le allieve è soggetto e concorda con preparano."}},"consolidamento":{"focus":"Individuare tutto il soggetto","example":{"sentence":"Abbiamo vinto la partita.","explanation":"Il soggetto noi è sottinteso e si ricava dal verbo."}},"avanzato":{"focus":"Distinguere i predicati","example":{"sentence":"Il tavolo è in laboratorio.","explanation":"Essere significa trovarsi e forma qui predicato verbale."}}},"simplified":{"lead":"Il verbo dice qualcosa del soggetto e concorda con esso.","steps":["Trova il verbo: arrivano.","Cerca chi arriva: i ragazzi.","I ragazzi è plurale, come arrivano."],"example":{"sentence":"Arrivano i ragazzi.","explanation":"Il soggetto viene dopo il verbo."}},"pei":{"rule":"I ragazzi è soggetto di arrivano.","example":{"sentence":"Arrivano i ragazzi.","explanation":"Il soggetto viene dopo il verbo."}},"trackExamples":{"moda":{"sentence":"Le allieve sono attente.","explanation":"Le allieve è soggetto; sono attente è predicato nominale."},"arredo":{"sentence":"Il tavolo è stabile.","explanation":"Stabile descrive il soggetto attraverso la copula è."},"liuteria":{"sentence":"Sul banco riposano due tavole di abete.","explanation":"Il gruppo soggetto completo è due tavole di abete."}},"anchor":{"sentence":"Sul banco dorme il gatto. Il progetto è salvo.","explanation":"Il gatto è soggetto anche se segue dorme. È salvo è il predicato nominale della seconda frase.","memory":"Il soggetto può arrivare dopo il verbo."}},{"topic":"Agente e passivo","area":"frase","lead":"Nella frase passiva il soggetto riceve l’azione; un complemento con da può indicare chi o che cosa la compie.","objectives":["Trovare il soggetto passivo","Riconoscere chi agisce","Trasformare con precisione"],"sections":[{"title":"Riconoscere una passiva","text":"Una passiva presenta l’evento a partire da ciò che riceve l’azione: la notizia fu diffusa da Luca. La notizia è soggetto, perché il verbo concorda con quel nome; fu diffusa è predicato verbale passivo; da Luca indica chi ha diffuso. Il fatto può essere espresso attivamente: Luca diffuse la notizia. Non tutti i verbi ammettono questa trasformazione, che riguarda normalmente costruzioni transitive. In sono arrivati gli studenti non c’è una passiva: essere serve a formare il passato prossimo attivo di arrivare. Per riconoscerla cerca il rapporto fra i partecipanti e prova la corrispondente frase attiva.","examples":[{"sentence":"La notizia fu diffusa da Luca.","explanation":"La notizia è soggetto; da Luca è agente."},{"sentence":"Luca diffuse la notizia.","explanation":"Nell’attiva Luca è soggetto e la notizia è oggetto."}]},{"title":"Agente e causa efficiente","text":"Il complemento d’agente indica una persona o un animale che compie l’azione della passiva: il modello è stato costruito dagli studenti. Il complemento di causa efficiente indica invece una forza o un elemento inanimato: il ramo è stato spezzato dal vento. Entrambi sono introdotti di solito da da, semplice o articolata; possono comparire anche locuzioni come da parte di. Le domande da chi? e da che cosa? funzionano quando il verbo è passivo e il gruppo identifica chi produce il fatto. Non ogni da chi? corrisponde a un agente: vado da Luca indica una meta presso una persona.","examples":[{"sentence":"Il ramo è stato spezzato dal vento.","explanation":"Dal vento è causa efficiente perché indica una forza inanimata."},{"sentence":"Il pacco è stato aperto.","explanation":"La passiva resta corretta anche senza agente espresso."}]},{"title":"Agente espresso o omesso","text":"La passiva può non dire chi agisce: il pacco è stato aperto. Il soggetto resta il pacco e l’assenza dell’agente non rende la frase incompleta. Questa scelta è utile quando l’autore dell’azione è ignoto, evidente dal contesto o poco importante per l’informazione. Se trasformi in attiva una frase senza agente, non inventare una persona precisa: qualcuno ha aperto il pacco conserva l’indeterminatezza. Nei testi informativi la passiva può mettere in primo piano un oggetto o una procedura. Quando però è importante sapere chi ha svolto il lavoro, esplicitare l’agente evita un’informazione mancante.","examples":[{"sentence":"Le sedie sono state verniciate dagli allievi.","explanation":"Il participio concorda con sedie; dagli allievi indica l’agente."}]},{"title":"Trasformare conservando il fatto","text":"Per passare dall’attiva alla passiva, l’oggetto diventa soggetto, il verbo conserva modo e tempo nella forma passiva e il soggetto attivo può diventare agente. Luca ha verniciato la sedia diventa la sedia è stata verniciata da Luca. Il participio concorda con il nuovo soggetto: le sedie sono state verniciate. Conserva negazioni, tempi e complementi: non ha aperto non può diventare ha aperto. Essere più participio può anche descrivere uno stato: la porta è aperta. Un contesto con viene aperta chiarisce l’azione; con era già aperta quando arrivai si descrive soprattutto un risultato. L’agente va riconosciuto per il suo rapporto con l’evento, non soltanto dalla preposizione.","examples":[{"sentence":"Vado da Luca; il pacco è stato aperto da Luca.","explanation":"Il primo da Luca indica meta; il secondo agente della passiva."}]}],"diagram":{"title":"Agente e passivo: i collegamenti da ricordare","steps":[{"label":"Soggetto passivo","detail":"Riceve l’azione: il panino è stato preso."},{"label":"Agente","detail":"Persona o animale che agisce: dal gatto."},{"label":"Causa efficiente","detail":"Forza o elemento inanimato: dal vento."},{"label":"Omissione","detail":"L’agente può mancare: il pacco è stato aperto."},{"label":"Trasformazione","detail":"Oggetto attivo diventa soggetto; tempo e significato restano."}]},"pitfalls":[{"mistake":"Da Luca è sempre agente.","correction":"In «vado da Luca» indica moto a luogo.","why":"Il gruppo diventa agente quando esprime chi compie un’azione passiva."},{"mistake":"La sedia è stata verniciato.","correction":"La sedia è stata verniciata.","why":"Il participio concorda con il soggetto femminile singolare."}],"recap":["Il soggetto passivo riceve l’azione.","L’agente è persona o animale.","La causa efficiente è forza o elemento inanimato.","L’autore dell’azione può non essere espresso."],"review":[{"question":"Qual è l’agente in «il mobile è montato da Sara»?","answer":"Da Sara."},{"question":"Che funzione ha dal vento in «il ramo è spezzato dal vento»?","answer":"Complemento di causa efficiente."},{"question":"Posso trasformare una passiva senza agente inventando un nome?","answer":"No: devo mantenere l’indeterminatezza, per esempio usando qualcuno."}],"levels":{"base":{"focus":"Trovare il soggetto passivo","example":{"sentence":"La notizia fu diffusa da Luca.","explanation":"La notizia è soggetto; da Luca è agente."}},"consolidamento":{"focus":"Riconoscere chi agisce","example":{"sentence":"Il ramo è stato spezzato dal vento.","explanation":"Dal vento è causa efficiente perché indica una forza inanimata."}},"avanzato":{"focus":"Trasformare con precisione","example":{"sentence":"Vado da Luca; il pacco è stato aperto da Luca.","explanation":"Il primo da Luca indica meta; il secondo agente della passiva."}}},"simplified":{"lead":"In una passiva l’agente indica chi compie l’azione.","steps":["Leggi è aperta.","La porta riceve l’azione.","Da Sara dice chi la compie."],"example":{"sentence":"La porta è aperta da Sara.","explanation":"Da Sara indica chi apre la porta."}},"pei":{"rule":"Da Sara è agente in la porta è aperta da Sara.","example":{"sentence":"La porta è aperta da Sara.","explanation":"Da Sara indica chi apre la porta."}},"trackExamples":{"moda":{"sentence":"L’abito è rifinito dalla sarta.","explanation":"Dalla sarta è agente."},"arredo":{"sentence":"Il pannello è deformato dall’umidità.","explanation":"Dall’umidità indica causa efficiente."},"liuteria":{"sentence":"Lo strumento è stato controllato dalla liutaia.","explanation":"Dalla liutaia indica chi ha compiuto il controllo."}},"anchor":{"sentence":"Il panino è stato preso dal gatto. Nessuno aveva dubbi.","explanation":"Il panino è soggetto passivo; dal gatto è complemento d’agente perché indica l’animale che ha compiuto l’azione.","memory":"Nel passivo chiedi: da chi è stata compiuta l’azione?"}},{"topic":"Altri complementi","area":"frase","lead":"Alcuni complementi precisano separazione, origine, benefici, mancanze o responsabilità.","objectives":["Riconoscere la relazione","Distinguere complementi vicini","Motivare la scelta nel contesto"],"sections":[{"title":"Allontanamento e separazione","text":"Il complemento di allontanamento o separazione indica la persona, la cosa o l’ambito da cui qualcuno o qualcosa viene separato. Dipende spesso da verbi come separare, liberare o allontanare e può essere introdotto da da. Un distacco può essere anche figurato: separare una notizia da un’opinione. Il moto da luogo descrive invece il luogo da cui parte uno spostamento: esco dalla stanza. La preposizione da compare in entrambi i casi: serve interpretare il verbo e il rapporto.","examples":[{"sentence":"La docente separa i campioni difettosi da quelli integri.","explanation":"Da quelli integri indica ciò da cui i campioni sono separati."},{"sentence":"Il gruppo si è allontanato dalle cattive abitudini.","explanation":"Dalle cattive abitudini indica un distacco figurato."}]},{"title":"Origine e provenienza","text":"Il complemento di origine o provenienza indica da quale famiglia, condizione, ambiente o luogo qualcuno o qualcosa trae origine. Può dipendere da parole come nato, discendere o provenire. In «Nadia discende da una famiglia di musicisti», il gruppo «da una famiglia di musicisti» presenta un’origine familiare; non descrive necessariamente un viaggio. Il moto da luogo indica invece la partenza concreta di uno spostamento. Alcune grammatiche distinguono questi casi in modi diversi: esplicita il significato nella frase.","examples":[{"sentence":"La restauratrice discende da una famiglia di falegnami.","explanation":"Da una famiglia di falegnami indica origine familiare."},{"sentence":"L’allieva esce dal laboratorio.","explanation":"Dal laboratorio è il punto di partenza di uno spostamento."}]},{"title":"Vantaggio e svantaggio","text":"Il complemento di vantaggio indica la persona, il gruppo o la cosa che riceve un beneficio; quello di svantaggio indica chi subisce un danno. Possono essere introdotti da per, a favore di o a danno di. Non ogni gruppo con per ha questa funzione: risparmio per il viaggio indica lo scopo del risparmio; raccolgo fondi per la biblioteca indica il soggetto beneficiario. Considera il senso dell’intera frase.","examples":[{"sentence":"La classe raccoglie fondi per la biblioteca.","explanation":"Per la biblioteca indica chi beneficia della raccolta."},{"sentence":"La scelta va a danno dei partecipanti.","explanation":"A danno dei partecipanti indica chi subisce uno svantaggio."}]},{"title":"Abbondanza e privazione","text":"Il complemento di abbondanza indica ciò di cui qualcuno o qualcosa è ricco o fornito; quello di privazione indica ciò che manca. Si collega spesso a parole come pieno, ricco, privo o sprovvisto ed è introdotto da di. Il medesimo gruppo può avere funzioni diverse in altre frasi: la scatola dei bottoni precisa quale scatola; piena di bottoni indica ciò che abbonda nella scatola.","examples":[{"sentence":"Il cassetto è pieno di matite.","explanation":"Di matite indica ciò che abbonda nel cassetto."},{"sentence":"Il telaio è privo di cornice.","explanation":"Di cornice indica ciò che manca al telaio."}]},{"title":"Colpa e pena","text":"Il complemento di colpa indica il fatto contestato o la responsabilità attribuita a qualcuno; compare con parole come accusare o imputare. Il complemento di pena indica invece la sanzione stabilita o inflitta, con verbi come condannare o punire. Non identificare le funzioni solo attraverso la preposizione: verifica se la frase parla della contestazione oppure della conseguenza disciplinare o giuridica.","examples":[{"sentence":"Il giocatore è accusato di violazione del regolamento.","explanation":"Di violazione del regolamento indica la colpa contestata."},{"sentence":"La squadra è stata punita con una giornata di sospensione.","explanation":"Con una giornata di sospensione indica la pena."}]}],"diagram":{"title":"Altri complementi: osserva il rapporto","steps":[{"label":"Separazione","detail":"Da chi o da che cosa si separa?"},{"label":"Origine","detail":"Da quale famiglia o ambiente proviene?"},{"label":"Beneficio o danno","detail":"Chi riceve il vantaggio o subisce lo svantaggio?"},{"label":"Presenza o mancanza","detail":"Di che cosa è pieno o privo?"},{"label":"Responsabilità e sanzione","detail":"Quale fatto è contestato? Quale pena è inflitta?"}]},"pitfalls":[{"mistake":"Ogni gruppo con da indica moto da luogo.","correction":"Può indicare anche separazione o origine.","why":"La preposizione da sola non identifica la funzione."},{"mistake":"Colpa e pena sono la stessa cosa.","correction":"La colpa è il fatto contestato; la pena è la sanzione.","why":"I due gruppi rispondono a relazioni diverse."}],"recap":["La separazione indica da che cosa ci si distacca.","L’origine può riferirsi anche a una famiglia o a un ambiente.","Vantaggio e svantaggio riguardano beneficio e danno.","Abbondanza e privazione riguardano presenza o mancanza.","Colpa e pena distinguono il fatto contestato dalla sanzione."],"review":[{"question":"In «La classe raccoglie fondi per la biblioteca», chi beneficia della raccolta?","answer":"La biblioteca: per la biblioteca è complemento di vantaggio."},{"question":"Che cosa manca in «Il cassetto è privo di matite»?","answer":"Le matite: di matite è complemento di privazione."},{"question":"In che cosa differiscono colpa e pena?","answer":"La colpa è il fatto contestato; la pena è la sanzione."}],"levels":{"base":{"focus":"Riconoscere il beneficio","example":{"sentence":"Raccogliamo fondi per la biblioteca.","explanation":"Per la biblioteca indica il beneficiario."}},"consolidamento":{"focus":"Distinguere abbondanza e privazione","example":{"sentence":"La scatola è piena di fili e priva di etichette.","explanation":"Di fili indica abbondanza; di etichette privazione."}},"avanzato":{"focus":"Distinguere rapporti vicini","example":{"sentence":"L’allieva discende da una famiglia di artigiani ed esce dal laboratorio.","explanation":"Il primo gruppo indica origine familiare, il secondo il luogo di partenza."}}},"simplified":{"lead":"Il complemento aggiunge un’informazione alla frase.","steps":["Cerca il verbo o la parola che il gruppo completa.","Chiediti quale rapporto esprime.","Controlla il significato della frase intera."],"example":{"sentence":"Il cassetto è pieno di matite.","explanation":"Di matite dice che cosa c’è in abbondanza."}},"pei":{"rule":"Pieno di indica che cosa c’è in abbondanza.","example":{"sentence":"Il cassetto è pieno di matite.","explanation":"Di matite indica che cosa contiene il cassetto."}},"trackExamples":{"moda":{"sentence":"La scatola è piena di bottoni.","explanation":"Di bottoni indica abbondanza."},"arredo":{"sentence":"La cornice è priva di sostegno.","explanation":"Di sostegno indica privazione."},"liuteria":{"sentence":"La liutaia discende da una famiglia di musicisti.","explanation":"Da una famiglia di musicisti indica origine familiare."}},"anchor":{"sentence":"La scatola è piena di bottoni, ma priva di ago.","explanation":"Di bottoni indica abbondanza; di ago indica privazione.","memory":"Pieno: che cosa c’è? Privo: che cosa manca?"}},{"topic":"Verbi · indicativo presente","area":"parole","lead":"Il presente indicativo presenta fatti attuali, abitudini e verità generali; il contesto precisa quando avviene l’azione.","objectives":["Riconoscere fatti attuali, abitudini e verità generali.","Coniugare verbi regolari e irregolari al presente.","Distinguere il presente attuale, storico e con valore futuro."],"sections":[{"title":"Come si forma","text":"Il presente è un tempo semplice: ha una sola parola e non richiede un ausiliare. Nei verbi regolari si toglie la desinenza dell’infinito e si aggiungono le terminazioni della persona. Cantare appartiene alla prima coniugazione; temere alla seconda; dormire alla terza. Le forme di uno stesso verbo costituiscono un paradigma, cioè un modello ordinato. Il soggetto può restare sottinteso perché la terminazione comunica spesso chi agisce; quando non basta, il contesto scioglie il dubbio. Nel parlato capita spesso di omettere il pronome personale.","examples":[{"sentence":"Io canto nel coro.","explanation":"Canto è prima persona singolare: il soggetto è io."},{"sentence":"Noi dormiamo otto ore.","explanation":"Dormiamo è il presente della terza coniugazione."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","canto"],["tu","canti"],["lui / lei","canta"],["noi","cantiamo"],["voi","cantate"],["loro","cantano"]]}},{"title":"Usi del presente","text":"Il presente può descrivere ciò che accade nel momento in cui parliamo, ma non si limita a questo uso. Esprime anche un’abitudine ripetuta e una proprietà considerata generalmente valida. Per riconoscerne il valore osserva gli indicatori temporali, come adesso, ogni giorno e sempre. La forma verbale è identica, mentre cambia il rapporto con il tempo. L’indicativo presenta questi contenuti come fatti o come informazioni assunte da chi parla, senza garantire da solo che siano veri.","examples":[{"sentence":"Adesso controllo le misure.","explanation":"L’azione coincide con il momento in cui si parla."},{"sentence":"Ogni mattina prendo l’autobus.","explanation":"Ogni mattina segnala un’abitudine ripetuta."}]},{"title":"Presente, futuro e racconto","text":"Con un riferimento futuro chiaro il presente può indicare un programma: domani partiamo. Il futuro semplice, invece, rende esplicita la collocazione successiva e può esprimere anche una previsione. Nei racconti e nei riassunti il presente storico rende vicini fatti passati: nel 1861 nasce il Regno d’Italia. La data impedisce di interpretarli come eventi di oggi. Nello stesso testo mantieni coerente la prospettiva scelta; cambiare tempo senza motivo rende difficile ricostruire la successione dei fatti.","examples":[{"sentence":"Domani consegniamo il progetto.","explanation":"Il presente ha valore futuro grazie a domani."}]},{"title":"Irregolarità da controllare","text":"Essere e avere hanno forme proprie: sono, sei, è, siamo, siete, sono; ho, hai, ha, abbiamo, avete, hanno. Anche andare, fare e dire cambiano parte della radice: vado, faccio, dico. Alcuni verbi in -ire inseriscono -isc- in certe persone: finisco, finisci, finisce, finiamo, finite, finiscono. Nei verbi in -care e -gare si conserva il suono duro con h davanti a i: cerchi, paghi. Impara queste famiglie insieme al significato, evitando di inventare forme per analogia.","examples":[{"sentence":"Tu cerchi il disegno e lui finisce il lavoro.","explanation":"Cerchi conserva il suono duro; finisce inserisce -isc-."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il presente indicativo descrive fatti attuali, abitudini e verità generali."},{"label":"Costruisci","detail":"Unisci la radice alle desinenze della persona."},{"label":"Confronta","detail":"Il contesto distingue azione attuale, abitudine e programma futuro."},{"label":"Controlla","detail":"Controlla irregolari, -isc- e grafie come cerchi e paghi."}]},"pitfalls":[{"mistake":"Io ando a scuola.","correction":"Io vado a scuola.","why":"Andare ha un presente irregolare."},{"mistake":"Tu cerci il foglio.","correction":"Tu cerchi il foglio.","why":"La h conserva il suono duro di c davanti a i."}],"recap":["Il presente indicativo descrive fatti attuali, abitudini e verità generali.","Unisci la radice alle desinenze della persona.","Il contesto distingue azione attuale, abitudine e programma futuro.","Controlla irregolari, -isc- e grafie come cerchi e paghi."],"review":[{"question":"Il presente indica sempre questo istante?","answer":"No: indica anche abitudini, verità generali e, con un contesto chiaro, eventi futuri."},{"question":"Qual è il presente di finire con noi?","answer":"Noi finiamo, senza -isc-."},{"question":"Perché si scrive paghi?","answer":"La h mantiene il suono duro della g davanti a i."}],"levels":{"base":{"focus":"Il presente indicativo descrive fatti attuali, abitudini e verità generali.","example":{"sentence":"Io canto nel coro.","explanation":"Canto è prima persona singolare: il soggetto è io."}},"consolidamento":{"focus":"Unisci la radice alle desinenze della persona. Il contesto distingue azione attuale, abitudine e programma futuro.","example":{"sentence":"Adesso controllo le misure.","explanation":"L’azione coincide con il momento in cui si parla."}},"avanzato":{"focus":"Controlla irregolari, -isc- e grafie come cerchi e paghi.","example":{"sentence":"Tu cerchi il disegno e lui finisce il lavoro.","explanation":"Cerchi conserva il suono duro; finisce inserisce -isc-."}}},"simplified":{"lead":"Il presente indicativo presenta fatti attuali, abitudini e verità generali; il contesto precisa quando avviene l’azione.","steps":["Il presente indicativo descrive fatti attuali, abitudini e verità generali.","Unisci la radice alle desinenze della persona.","Il contesto distingue azione attuale, abitudine e programma futuro."],"example":{"sentence":"Il gatto dorme sul mio quaderno.","explanation":"Dorme è indicativo presente: il gatto sta dormendo adesso. Se aggiungo ogni pomeriggio, la stessa forma descrive un’abitudine."}},"pei":{"rule":"Il presente racconta che cosa succede adesso o ogni giorno.","example":{"sentence":"Io canto nel coro.","explanation":"Canto è prima persona singolare: il soggetto è io."}},"trackExamples":{"moda":{"sentence":"La sarta taglia il tessuto.","explanation":"Taglia descrive un’azione al presente."},"arredo":{"sentence":"Ogni giorno misuriamo i pannelli.","explanation":"Misuriamo indica un’abitudine."},"liuteria":{"sentence":"Il liutaio controlla il ponticello.","explanation":"Controlla è presente, terza persona singolare."}},"anchor":{"sentence":"Il gatto dorme sul mio quaderno.","explanation":"Dorme è indicativo presente: il gatto sta dormendo adesso. Se aggiungo ogni pomeriggio, la stessa forma descrive un’abitudine.","memory":"Adesso e ogni giorno possono usare lo stesso presente."}},{"topic":"Verbi · indicativo imperfetto","area":"parole","lead":"L’imperfetto mostra un fatto passato nel suo svolgimento, come abitudine o come sfondo di un racconto.","objectives":["Usare l’imperfetto per sfondi, descrizioni e abitudini.","Coniugare cantavo, ero, facevo nelle diverse persone.","Distinguere un’azione in corso da un evento delimitato."],"sections":[{"title":"Formazione e modello","text":"L’imperfetto è un tempo semplice dell’indicativo. Le terminazioni regolari sono -avo, -avi, -ava, -avamo, -avate, -avano per cantare; -evo e le corrispondenti persone per temere; -ivo per dormire. La terminazione contiene il segnale -v- e distingue la persona. Essere segue un modello irregolare: ero, eri, era, eravamo, eravate, erano. Fare, dire e bere conservano una radice più lunga rispetto all’infinito moderno: facevo, dicevo, bevevo. Avere è regolare in questo tempo: avevo. Anche leggevo, leggevamo e leggevano conservano chiaramente la radice del verbo leggere.","examples":[{"sentence":"Da piccolo cantavo spesso.","explanation":"Cantavo è prima persona singolare dell’imperfetto."},{"sentence":"Il laboratorio era luminoso.","explanation":"Era appartiene al paradigma irregolare di essere."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","cantavo"],["tu","cantavi"],["lui / lei","cantava"],["noi","cantavamo"],["voi","cantavate"],["loro","cantavano"]]}},{"title":"Durata, abitudine e descrizione","text":"L’imperfetto presenta l’azione dall’interno, senza metterne in primo piano l’inizio o la conclusione. È adatto alle abitudini del passato, alle descrizioni di persone e ambienti, agli stati d’animo e alle situazioni che facevano da sfondo. Non significa necessariamente che un’azione sia durata molto: anche un gesto breve può essere ripetuto abitualmente. Gli indicatori ogni estate, di solito e mentre aiutano a riconoscere questi valori, ma bisogna sempre leggere il significato dell’intera frase.","examples":[{"sentence":"Ogni estate lavoravamo con nostro nonno.","explanation":"L’imperfetto segnala un’abitudine passata."},{"sentence":"La stanza aveva due finestre.","explanation":"Aveva descrive una caratteristica dello sfondo."}]},{"title":"Confronto con i passati conclusi","text":"Passato prossimo e passato remoto presentano di solito l’evento come un fatto delimitato; l’imperfetto ne mostra invece lo svolgimento o la ripetizione. In leggevo quando è suonato il telefono, la lettura costituisce lo sfondo e lo squillo introduce l’evento che avanza nel racconto. La distinzione non dipende soltanto dalla distanza cronologica. Si può dire ieri studiavo quando sei arrivato e, parlando di molti anni fa, quel giorno studiai due ore: cambia il modo di osservare il fatto.","examples":[{"sentence":"Mentre levigavo il legno, è mancata la corrente.","explanation":"Levigavo è lo sfondo in corso; è mancata indica l’evento sopraggiunto."}]},{"title":"Usi particolari e precisione","text":"Nella lingua parlata l’imperfetto può rendere una richiesta più cortese: volevo un’informazione. Può comparire anche nel gioco, nelle ipotesi e nei racconti immaginati. Riconosci questi usi senza sostituirli automaticamente ai modi richiesti nello scritto sorvegliato. Per un’ipotesi irreale è più chiaro usare se avessi tempo, verrei, anziché se avevo tempo, venivo. Quando produci un testo scolastico, scegli l’imperfetto per il suo preciso valore e controlla la coerenza con gli altri tempi della narrazione.","examples":[{"sentence":"Volevo chiedere un chiarimento.","explanation":"Qui l’imperfetto attenua una richiesta attuale."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"L’imperfetto presenta abitudini, descrizioni e azioni in corso nel passato."},{"label":"Costruisci","detail":"Forma i verbi regolari con -avo, -evo o -ivo e le altre persone."},{"label":"Confronta","detail":"Confronta lo sfondo all’imperfetto con l’evento concluso al passato."},{"label":"Controlla","detail":"Riconosci gli usi di cortesia e distinguili dalle ipotesi nello scritto."}]},"pitfalls":[{"mistake":"Io faceo i compiti.","correction":"Io facevo i compiti.","why":"Fare usa la radice face- nell’imperfetto."},{"mistake":"L’imperfetto indica soltanto azioni molto lunghe.","correction":"L’imperfetto mostra lo svolgimento o l’abitudine.","why":"La durata materiale non decide da sola il tempo verbale."}],"recap":["L’imperfetto presenta abitudini, descrizioni e azioni in corso nel passato.","Forma i verbi regolari con -avo, -evo o -ivo e le altre persone.","Confronta lo sfondo all’imperfetto con l’evento concluso al passato.","Riconosci gli usi di cortesia e distinguili dalle ipotesi nello scritto."],"review":[{"question":"Che differenza c’è tra studiavo e ho studiato?","answer":"Studiavo mostra lo svolgimento o l’abitudine; ho studiato presenta un fatto delimitato."},{"question":"Qual è l’imperfetto di essere con noi?","answer":"Noi eravamo."},{"question":"In volevo un’informazione, il fatto è sempre passato?","answer":"No: può essere un modo cortese di fare una richiesta nel presente."}],"levels":{"base":{"focus":"L’imperfetto presenta abitudini, descrizioni e azioni in corso nel passato.","example":{"sentence":"Da piccolo cantavo spesso.","explanation":"Cantavo è prima persona singolare dell’imperfetto."}},"consolidamento":{"focus":"Forma i verbi regolari con -avo, -evo o -ivo e le altre persone. Confronta lo sfondo all’imperfetto con l’evento concluso al passato.","example":{"sentence":"Ogni estate lavoravamo con nostro nonno.","explanation":"L’imperfetto segnala un’abitudine passata."}},"avanzato":{"focus":"Riconosci gli usi di cortesia e distinguili dalle ipotesi nello scritto.","example":{"sentence":"Volevo chiedere un chiarimento.","explanation":"Qui l’imperfetto attenua una richiesta attuale."}}},"simplified":{"lead":"L’imperfetto mostra un fatto passato nel suo svolgimento, come abitudine o come sfondo di un racconto.","steps":["L’imperfetto presenta abitudini, descrizioni e azioni in corso nel passato.","Forma i verbi regolari con -avo, -evo o -ivo e le altre persone.","Confronta lo sfondo all’imperfetto con l’evento concluso al passato."],"example":{"sentence":"Mentre studiavo, il gatto russava.","explanation":"Studiavo e russava mostrano due azioni in corso nello stesso momento passato. Non ci viene detto quando finiscono."}},"pei":{"rule":"L’imperfetto racconta che cosa succedeva o si faceva spesso nel passato.","example":{"sentence":"Da piccolo cantavo spesso.","explanation":"Cantavo è prima persona singolare dell’imperfetto."}},"trackExamples":{"moda":{"sentence":"Da bambina disegnava abiti.","explanation":"Disegnava esprime un’abitudine passata."},"arredo":{"sentence":"La sedia aveva uno schienale alto.","explanation":"Aveva descrive il mobile nel passato."},"liuteria":{"sentence":"Mentre accordavo il violino, ascoltavo ogni corda.","explanation":"I due imperfetti mostrano azioni contemporanee in corso."}},"anchor":{"sentence":"Mentre studiavo, il gatto russava.","explanation":"Studiavo e russava mostrano due azioni in corso nello stesso momento passato. Non ci viene detto quando finiscono.","memory":"L’imperfetto tiene aperta la scena del passato."}},{"topic":"Verbi · indicativo futuro semplice","area":"parole","lead":"Il futuro semplice colloca un fatto dopo il momento in cui parliamo e può esprimere anche previsioni o supposizioni.","objectives":["Coniugare il futuro con accenti e radici corrette.","Esprimere programmi, promesse e previsioni.","Riconoscere il futuro con valore di supposizione."],"sections":[{"title":"Come costruire le forme","text":"Il futuro semplice è formato da una sola parola. Le desinenze sono -ò, -ai, -à, -emo, -ete, -anno. Nel modello regolare della prima coniugazione la vocale a diventa e: cantare dà canterò; temere dà temerò e dormire dà dormirò. La prima e la terza persona singolare richiedono l’accento scritto. Non aggiungere un ausiliare: avrò cantato appartiene al futuro anteriore. Il pronome personale può essere omesso se la terminazione e il contesto rendono chiaro il soggetto.","examples":[{"sentence":"Domani canterò nel coro.","explanation":"Canterò è futuro semplice, prima persona singolare."},{"sentence":"Voi dormirete qui.","explanation":"Dormirete segue il modello regolare dei verbi in -ire."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","canterò"],["tu","canterai"],["lui / lei","canterà"],["noi","canteremo"],["voi","canterete"],["loro","canteranno"]]}},{"title":"Programmi, previsioni e promesse","text":"Il futuro serve a comunicare eventi successivi al momento presente: un progetto, una promessa, una decisione o una previsione. La forma verbale non garantisce che il fatto avverrà: il risultato dipende dalla situazione reale. Gli indicatori domani, tra un mese e l’anno prossimo chiariscono la collocazione. Per programmi già stabiliti si usa spesso anche il presente, come domani partiamo. La scelta dipende dal punto di vista: il presente avvicina il programma, il futuro segnala esplicitamente la posteriorità.","examples":[{"sentence":"Finiremo il lavoro venerdì.","explanation":"Il futuro comunica un risultato previsto."},{"sentence":"Ti restituirò gli appunti.","explanation":"Il futuro esprime una promessa."}]},{"title":"Supposizione e confronto fra tempi","text":"Il futuro può riferirsi al presente quando chi parla formula una supposizione: saranno le otto significa probabilmente sono le otto. Per interpretarlo considera il contesto, non soltanto il nome del tempo. Il futuro anteriore presenta invece un fatto già concluso prima di un altro momento futuro: quando avrò finito, uscirò. Se devi descrivere due azioni future in successione, verifica quale deve essere completata prima e quale avviene dopo; questo rapporto guida la scelta tra semplice e composto.","examples":[{"sentence":"Il negozio è chiuso: saranno in pausa.","explanation":"Saranno esprime una supposizione sulla situazione attuale."}]},{"title":"Radici irregolari e ortografia","text":"Molti verbi frequenti cambiano radice: essere dà sarò; avere avrò; andare andrò; fare farò; dare darò; stare starò; venire verrò; potere potrò; volere vorrò. Le desinenze restano quelle del futuro. Nei verbi in -care e -gare compare h: cercherò, pagherò. Nei verbi in -ciare e -giare si perde di norma la i non accentata: comincerò, mangerò. Studia la prima persona insieme alla radice: riconosciuta questa, puoi completare il paradigma senza imparare sei forme isolate.","examples":[{"sentence":"Cercherai il materiale e poi verrai qui.","explanation":"Cercherai conserva il suono duro; verrai usa la radice irregolare verr-."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il futuro semplice indica un evento successivo o una supposizione."},{"label":"Costruisci","detail":"Usa -ò, -ai, -à, -emo, -ete, -anno."},{"label":"Confronta","detail":"Distingui il fatto futuro dal fatto già compiuto del futuro anteriore."},{"label":"Controlla","detail":"Controlla accenti e radici irregolari come sar-, avr- e verr-."}]},"pitfalls":[{"mistake":"Io cantarò.","correction":"Io canterò.","why":"Nella prima coniugazione regolare a diventa e."},{"mistake":"Lui finira domani.","correction":"Lui finirà domani.","why":"La terza persona singolare del futuro richiede l’accento."}],"recap":["Il futuro semplice indica un evento successivo o una supposizione.","Usa -ò, -ai, -à, -emo, -ete, -anno.","Distingui il fatto futuro dal fatto già compiuto del futuro anteriore.","Controlla accenti e radici irregolari come sar-, avr- e verr-."],"review":[{"question":"Quali sono le sei desinenze del futuro?","answer":"-ò, -ai, -à, -emo, -ete, -anno."},{"question":"In saranno stanchi il futuro può parlare del presente?","answer":"Sì: può significare probabilmente sono stanchi."},{"question":"Qual è il futuro di venire con noi?","answer":"Noi verremo."}],"levels":{"base":{"focus":"Il futuro semplice indica un evento successivo o una supposizione.","example":{"sentence":"Domani canterò nel coro.","explanation":"Canterò è futuro semplice, prima persona singolare."}},"consolidamento":{"focus":"Usa -ò, -ai, -à, -emo, -ete, -anno. Distingui il fatto futuro dal fatto già compiuto del futuro anteriore.","example":{"sentence":"Finiremo il lavoro venerdì.","explanation":"Il futuro comunica un risultato previsto."}},"avanzato":{"focus":"Controlla accenti e radici irregolari come sar-, avr- e verr-.","example":{"sentence":"Cercherai il materiale e poi verrai qui.","explanation":"Cercherai conserva il suono duro; verrai usa la radice irregolare verr-."}}},"simplified":{"lead":"Il futuro semplice colloca un fatto dopo il momento in cui parliamo e può esprimere anche previsioni o supposizioni.","steps":["Il futuro semplice indica un evento successivo o una supposizione.","Usa -ò, -ai, -à, -emo, -ete, -anno.","Distingui il fatto futuro dal fatto già compiuto del futuro anteriore."],"example":{"sentence":"Domani il mio zaino peserà una tonnellata.","explanation":"Peserà è futuro semplice, terza persona singolare. La tonnellata è un’esagerazione scherzosa; domani colloca il peso previsto nel futuro."}},"pei":{"rule":"Il futuro racconta che cosa succederà: domani canterò.","example":{"sentence":"Domani canterò nel coro.","explanation":"Canterò è futuro semplice, prima persona singolare."}},"trackExamples":{"moda":{"sentence":"Domani cuciremo la fodera.","explanation":"Cuciremo colloca l’azione nel futuro."},"arredo":{"sentence":"Il falegname monterà le ante.","explanation":"Monterà è una previsione futura."},"liuteria":{"sentence":"Il liutaio proverà lo strumento.","explanation":"Proverà presenta un controllo successivo."}},"anchor":{"sentence":"Domani il mio zaino peserà una tonnellata.","explanation":"Peserà è futuro semplice, terza persona singolare. La tonnellata è un’esagerazione scherzosa; domani colloca il peso previsto nel futuro.","memory":"Futuro in arrivo: peserà ha l’accento sulla à."}},{"topic":"Verbi · indicativo passato remoto","area":"parole","lead":"Il passato remoto presenta un evento passato come concluso, spesso separato dal presente nel racconto.","objectives":["Riconoscere gli eventi conclusi in un racconto.","Coniugare i principali passati remoti regolari e irregolari.","Spiegare il rapporto con imperfetto e passato prossimo."],"sections":[{"title":"Formazione del tempo semplice","text":"Il passato remoto è un tempo semplice dell’indicativo. Il modello cantare presenta cantai, cantasti, cantò, cantammo, cantaste, cantarono; dormire presenta dormii, dormisti, dormì, dormimmo, dormiste, dormirono. Per molti verbi regolari in -ere esistono le serie -ei, -esti, -é, -emmo, -este, -erono e, in vari verbi, -etti, -esti, -ette, -emmo, -este, -ettero. Le alternative non sono disponibili liberamente per ogni verbo: quando hai dubbi controlla il paradigma specifico invece di combinare terminazioni a caso.","examples":[{"sentence":"Il coro cantò due brani.","explanation":"Cantò è terza persona singolare del passato remoto."},{"sentence":"Noi dormimmo in ostello.","explanation":"Dormimmo segue il modello regolare di dormire."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","cantai"],["tu","cantasti"],["lui / lei","cantò"],["noi","cantammo"],["voi","cantaste"],["loro","cantarono"]]}},{"title":"Il fatto concluso nel racconto","text":"Il passato remoto fa avanzare il racconto presentando un fatto come interamente compiuto. È frequente nella narrazione storica, nelle fiabe e nella prosa letteraria, ma compare anche nella lingua parlata di alcune aree italiane. Non indica obbligatoriamente un passato lontanissimo: conta il modo in cui chi parla collega l’evento al presente. Una data antica può accompagnare un passato prossimo, mentre un fatto recente può essere narrato al passato remoto secondo le abitudini linguistiche e la prospettiva del parlante.","examples":[{"sentence":"Il viaggiatore entrò e posò la valigia.","explanation":"I due passati remoti presentano una sequenza di eventi conclusi."},{"sentence":"Nel 1861 fu proclamato il Regno d’Italia.","explanation":"Il passato remoto è adatto alla narrazione storica."}]},{"title":"Confronto con imperfetto e passato prossimo","text":"L’imperfetto descrive lo sfondo o lo svolgimento; il passato remoto mette a fuoco l’evento delimitato. In pioveva quando uscì, la pioggia costituisce lo sfondo e l’uscita è il fatto che interviene. Il passato prossimo può svolgere una funzione narrativa simile al remoto, con un diverso rapporto percepito con il presente e con differenti usi regionali. In un racconto scolastico scegli una prospettiva coerente: alterna i tempi quando cambia la funzione, evitando sostituzioni prive di motivo.","examples":[{"sentence":"La sala era vuota quando arrivarono gli ospiti.","explanation":"Era descrive la situazione; arrivarono introduce il cambiamento."}]},{"title":"I principali verbi irregolari","text":"Molti verbi comuni richiedono una radice irregolare, soprattutto nella prima e terza persona singolare e nella terza plurale: fare dà feci, facesti, fece, facemmo, faceste, fecero; dire dà dissi e disse; leggere dà lessi e lesse; prendere dà presi e prese. Essere ha fui, fosti, fu, fummo, foste, furono; avere ha ebbi, avesti, ebbe, avemmo, aveste, ebbero. Fu non ha accento; cantò e dormì lo richiedono. Per scegliere la grafia, controlla la parola precisa.","examples":[{"sentence":"Lei fece il disegno e loro presero le misure.","explanation":"Fece e presero hanno radici irregolari."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il passato remoto presenta un evento passato come concluso."},{"label":"Costruisci","detail":"Impara un paradigma completo e controlla la persona."},{"label":"Confronta","detail":"Distingui l’evento narrato dallo sfondo all’imperfetto."},{"label":"Controlla","detail":"La scelta rispetto al passato prossimo dipende anche da prospettiva e uso regionale."}]},"pitfalls":[{"mistake":"Lui fù felice.","correction":"Lui fu felice.","why":"Fu si scrive senza accento."},{"mistake":"Io prendetti il treno.","correction":"Io presi il treno.","why":"Prendere ha un passato remoto irregolare."}],"recap":["Il passato remoto presenta un evento passato come concluso.","Impara un paradigma completo e controlla la persona.","Distingui l’evento narrato dallo sfondo all’imperfetto.","La scelta rispetto al passato prossimo dipende anche da prospettiva e uso regionale."],"review":[{"question":"Il remoto si usa soltanto per fatti molto antichi?","answer":"No: la scelta dipende anche dal rapporto percepito con il presente e dagli usi regionali."},{"question":"Qual è il passato remoto di essere con loro?","answer":"Loro furono."},{"question":"Che differenza c’è tra entrava ed entrò?","answer":"Entrava mostra svolgimento o abitudine; entrò presenta un ingresso come evento delimitato."}],"levels":{"base":{"focus":"Il passato remoto presenta un evento passato come concluso.","example":{"sentence":"Il coro cantò due brani.","explanation":"Cantò è terza persona singolare del passato remoto."}},"consolidamento":{"focus":"Impara un paradigma completo e controlla la persona. Distingui l’evento narrato dallo sfondo all’imperfetto.","example":{"sentence":"Il viaggiatore entrò e posò la valigia.","explanation":"I due passati remoti presentano una sequenza di eventi conclusi."}},"avanzato":{"focus":"La scelta rispetto al passato prossimo dipende anche da prospettiva e uso regionale.","example":{"sentence":"Lei fece il disegno e loro presero le misure.","explanation":"Fece e presero hanno radici irregolari."}}},"simplified":{"lead":"Il passato remoto presenta un evento passato come concluso, spesso separato dal presente nel racconto.","steps":["Il passato remoto presenta un evento passato come concluso.","Impara un paradigma completo e controlla la persona.","Distingui l’evento narrato dallo sfondo all’imperfetto."],"example":{"sentence":"Il gatto saltò sul banco e tutti risero.","explanation":"Saltò e risero presentano due eventi conclusi che fanno avanzare il racconto. Risero è una forma irregolare di ridere."}},"pei":{"rule":"Il passato remoto racconta un fatto concluso: ieri il gatto saltò.","example":{"sentence":"Il coro cantò due brani.","explanation":"Cantò è terza persona singolare del passato remoto."}},"trackExamples":{"moda":{"sentence":"La costumista cucì l’abito per la prima.","explanation":"Cucì presenta un lavoro concluso nel racconto."},"arredo":{"sentence":"L’artigiano costruì una cassapanca.","explanation":"Costruì è un evento narrativo compiuto."},"liuteria":{"sentence":"Il maestro provò il violino e sorrise.","explanation":"Provò e sorrise fanno avanzare il racconto."}},"anchor":{"sentence":"Il gatto saltò sul banco e tutti risero.","explanation":"Saltò e risero presentano due eventi conclusi che fanno avanzare il racconto. Risero è una forma irregolare di ridere.","memory":"Al remoto il racconto fa un passo: saltò, poi risero."}},{"topic":"Verbi · congiuntivo presente","area":"parole","lead":"Il congiuntivo presente compare soprattutto in frasi dipendenti che esprimono desideri, opinioni, possibilità o necessità riferiti al presente o al futuro.","objectives":["Coniugare il congiuntivo presente nelle sei persone.","Usarlo dopo speranze, opinioni e congiunzioni che lo richiedono.","Esprimere contemporaneità o posteriorità rispetto al presente."],"sections":[{"title":"Forme e persone","text":"Il congiuntivo presente è un tempo semplice. Cantare presenta canti, canti, canti, cantiamo, cantiate, cantino; temere presenta tema, tema, tema, temiamo, temiate, temano; dormire presenta dorma, dorma, dorma, dormiamo, dormiate, dormano. Le tre persone singolari coincidono spesso: il soggetto espresso o il contesto permettono di distinguerle. La congiunzione che introduce molte subordinate, ma non fa parte della forma del verbo e non compare davanti a ogni congiuntivo. Essere ha sia e avere abbia. Per le persone plurali controlla bene le terminazioni: cantiate è diverso da cantate.","examples":[{"sentence":"Spero che tu canti con noi.","explanation":"Canti è congiuntivo presente, seconda persona singolare."},{"sentence":"È necessario che loro dormano.","explanation":"Dormano è terza persona plurale."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","canti"],["tu","canti"],["lui / lei","canti"],["noi","cantiamo"],["voi","cantiate"],["loro","cantino"]]}},{"title":"Dove si usa","text":"Il congiuntivo si trova dopo espressioni come spero che, penso che, temo che, è possibile che, è necessario che. Compare anche dopo congiunzioni come benché, affinché e purché. La scelta dipende dalla costruzione e dal significato della frase: sapere che richiede normalmente l’indicativo, mentre sperare che introduce normalmente il congiuntivo. Evita la scorciatoia secondo cui il congiuntivo esprimerebbe sempre incertezza: in benché sia stanco, continuo a lavorare la stanchezza può essere un fatto noto.","examples":[{"sentence":"Penso che il progetto sia valido.","explanation":"L’opinione è introdotta da penso che."},{"sentence":"Ti presto gli appunti purché tu li restituisca.","explanation":"Purché introduce una condizione e richiede il congiuntivo."}]},{"title":"Il rapporto con gli altri tempi","text":"Dopo una reggente al presente, il congiuntivo presente esprime contemporaneità o posteriorità: credo che studi ora, spero che arrivi domani. Non esiste un futuro del congiuntivo. Per un fatto precedente si usa il congiuntivo passato: credo che abbia studiato ieri. Se la reggente è passata, il congiuntivo imperfetto è spesso la scelta per un fatto contemporaneo: pensavo che studiasse. Questi rapporti si ricostruiscono dal significato e dai riferimenti temporali, non sostituendo i tempi in modo meccanico.","examples":[{"sentence":"Spero che domani arrivi il materiale.","explanation":"Il presente del congiuntivo può riferirsi al futuro."}]},{"title":"Irregolari e controllo della forma","text":"Molti irregolari conservano una radice riconoscibile dal presente indicativo: faccio dà faccia, dico dà dica, vengo dà venga, posso dà possa. Essere presenta sia, sia, sia, siamo, siate, siano; avere abbia, abbia, abbia, abbiamo, abbiate, abbiano. Nei verbi in -ire con ampliamento compare -isc-: finisca, finiamo, finiate, finiscano. Per un ordine cortese rivolto a Lei si usano forme del congiuntivo: entri pure. Nell’analisi considera anche questa funzione, senza scambiarla per un normale ordine rivolto a tu.","examples":[{"sentence":"Signora, entri pure e si sieda.","explanation":"Entri e si sieda sono forme di cortesia rivolte a Lei."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il congiuntivo presente si usa in molte subordinate di opinione, desiderio o necessità."},{"label":"Costruisci","detail":"Controlla la costruzione: spero che arrivi, so che arriva."},{"label":"Confronta","detail":"Dopo una reggente presente può indicare contemporaneità o futuro."},{"label":"Controlla","detail":"Studia sia, abbia e le altre radici irregolari; distingui l’uso di cortesia."}]},"pitfalls":[{"mistake":"Spero che lui viene.","correction":"Spero che lui venga.","why":"Sperare che richiede normalmente il congiuntivo."},{"mistake":"Bisogna che voi cantate.","correction":"Bisogna che voi cantiate.","why":"La seconda plurale del congiuntivo di cantare è cantiate."}],"recap":["Il congiuntivo presente si usa in molte subordinate di opinione, desiderio o necessità.","Controlla la costruzione: spero che arrivi, so che arriva.","Dopo una reggente presente può indicare contemporaneità o futuro.","Studia sia, abbia e le altre radici irregolari; distingui l’uso di cortesia."],"review":[{"question":"Come distingui io canti da tu canti?","answer":"Attraverso il soggetto espresso o il contesto."},{"question":"Esiste un futuro del congiuntivo?","answer":"No: il congiuntivo presente può riferirsi al futuro."},{"question":"Il congiuntivo esprime sempre un fatto incerto?","answer":"No: la scelta dipende anche dalla costruzione, come dopo benché."}],"levels":{"base":{"focus":"Il congiuntivo presente si usa in molte subordinate di opinione, desiderio o necessità.","example":{"sentence":"Spero che tu canti con noi.","explanation":"Canti è congiuntivo presente, seconda persona singolare."}},"consolidamento":{"focus":"Controlla la costruzione: spero che arrivi, so che arriva. Dopo una reggente presente può indicare contemporaneità o futuro.","example":{"sentence":"Penso che il progetto sia valido.","explanation":"L’opinione è introdotta da penso che."}},"avanzato":{"focus":"Studia sia, abbia e le altre radici irregolari; distingui l’uso di cortesia.","example":{"sentence":"Signora, entri pure e si sieda.","explanation":"Entri e si sieda sono forme di cortesia rivolte a Lei."}}},"simplified":{"lead":"Il congiuntivo presente compare soprattutto in frasi dipendenti che esprimono desideri, opinioni, possibilità o necessità riferiti al presente o al futuro.","steps":["Il congiuntivo presente si usa in molte subordinate di opinione, desiderio o necessità.","Controlla la costruzione: spero che arrivi, so che arriva.","Dopo una reggente presente può indicare contemporaneità o futuro."],"example":{"sentence":"Spero che il bus arrivi prima dell’interrogazione.","explanation":"Arrivi è congiuntivo presente: dipende dalla speranza e riguarda un momento futuro."}},"pei":{"rule":"Dopo spero che usa il congiuntivo: spero che arrivi.","example":{"sentence":"Spero che tu canti con noi.","explanation":"Canti è congiuntivo presente, seconda persona singolare."}},"trackExamples":{"moda":{"sentence":"Spero che la fodera sia resistente.","explanation":"Sia segue un’espressione di speranza."},"arredo":{"sentence":"È necessario che il ripiano regga il peso.","explanation":"Regga esprime una caratteristica necessaria."},"liuteria":{"sentence":"Il maestro vuole che noi proviamo il violino.","explanation":"Proviamo è congiuntivo retto da vuole che."}},"anchor":{"sentence":"Spero che il bus arrivi prima dell’interrogazione.","explanation":"Arrivi è congiuntivo presente: dipende dalla speranza e riguarda un momento futuro.","memory":"Spero che arrivi: il congiuntivo presente vale anche per domani."}},{"topic":"Verbi · congiuntivo imperfetto","area":"parole","lead":"Il congiuntivo imperfetto collega molti fatti a una reggente passata e compare nelle ipotesi possibili o irreali del presente.","objectives":["Formare cantassi, temessi e dormissi.","Collegare un fatto a una reggente passata.","Costruire ipotesi con se fossi e conseguenze al condizionale."],"sections":[{"title":"Costruire il paradigma","text":"Il congiuntivo imperfetto è un tempo semplice. Le serie regolari sono -assi, -assi, -asse, -assimo, -aste, -assero per cantare; -essi e le altre persone per temere; -issi per dormire. La prima e la seconda persona singolare coincidono, quindi il contesto o il pronome chiariscono il soggetto. La doppia s è necessaria in forme come cantassi e cantassimo. Essere presenta fossi, fossi, fosse, fossimo, foste, fossero; avere presenta avessi, avessi, avesse, avessimo, aveste, avessero.","examples":[{"sentence":"Credevo che tu cantassi nel coro.","explanation":"Cantassi è seconda persona singolare del congiuntivo imperfetto."},{"sentence":"Desideravano che noi dormissimo di più.","explanation":"Dormissimo è prima persona plurale."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","cantassi"],["tu","cantassi"],["lui / lei","cantasse"],["noi","cantassimo"],["voi","cantaste"],["loro","cantassero"]]}},{"title":"Dipendenza da un tempo passato","text":"Dopo una reggente al passato, il congiuntivo imperfetto presenta spesso un fatto contemporaneo: pensavo che fosse a scuola. Può riferirsi anche a un fatto successivo rispetto a un desiderio o a una richiesta passati: volevo che arrivassi presto. Per un fatto anteriore alla reggente passata si usa invece il congiuntivo trapassato: pensavo che fosse già arrivato. Chiediti prima quale evento viene prima; poi scegli il tempo capace di esprimere quel rapporto senza perdere il punto di vista del racconto.","examples":[{"sentence":"Ieri pensavo che Marta fosse in laboratorio.","explanation":"Fosse indica una situazione contemporanea al pensiero passato."},{"sentence":"Il docente voleva che consegnassimo il giorno dopo.","explanation":"La consegna è successiva al desiderio espresso nel passato."}]},{"title":"Ipotesi e desideri nel presente","text":"Nel periodo ipotetico il congiuntivo imperfetto compare nella frase introdotta da se: se avessi tempo, leggerei. Il risultato è espresso normalmente dal condizionale presente. L’ipotesi può riguardare il presente o il futuro e presentarsi come possibile oppure contraria alla situazione reale. In vorrei che tu venissi il congiuntivo imperfetto dipende da un desiderio al condizionale. In magari fossi al mare esprime direttamente un desiderio. Il nome imperfetto, quindi, non basta a collocare l’azione nel passato.","examples":[{"sentence":"Se avessi tempo, leggerei il manuale.","explanation":"Avessi formula l’ipotesi; leggerei ne presenta la conseguenza."}]},{"title":"Forme frequenti e scelta del modo","text":"Fare dà facessi, dire dicessi e bere bevessi, con radici che ricordano quelle dell’imperfetto indicativo. Evita di sostituire il congiuntivo con il condizionale nella condizione ipotetica: si dice se potessi, verrei. Un se interrogativo ha invece una funzione diversa: mi chiedo se sarebbe utile chiedere aiuto contiene una domanda indiretta, non la condizione di un periodo ipotetico. Per l’analisi scolastica riconosci prima il tipo di frase; una parola introduttiva isolata non determina automaticamente il modo verbale.","examples":[{"sentence":"Vorrei che voi faceste una prova.","explanation":"Faceste è congiuntivo imperfetto, seconda persona plurale."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il congiuntivo imperfetto può dipendere da una reggente passata."},{"label":"Costruisci","detail":"Forma cantassi, temessi, dormissi e controlla le persone."},{"label":"Confronta","detail":"Nell’ipotesi usa se avessi tempo, leggerei."},{"label":"Controlla","detail":"Il tempo può riferirsi al presente: se fossi libero, verrei ora."}]},"pitfalls":[{"mistake":"Se avrei tempo, verrei.","correction":"Se avessi tempo, verrei.","why":"La condizione di questo periodo ipotetico richiede il congiuntivo imperfetto."},{"mistake":"Pensavo che lui fusse a casa.","correction":"Pensavo che lui fosse a casa.","why":"La forma corretta di essere è fosse."}],"recap":["Il congiuntivo imperfetto può dipendere da una reggente passata.","Forma cantassi, temessi, dormissi e controlla le persone.","Nell’ipotesi usa se avessi tempo, leggerei.","Il tempo può riferirsi al presente: se fossi libero, verrei ora."],"review":[{"question":"Qual è il congiuntivo imperfetto di essere con noi?","answer":"Noi fossimo."},{"question":"Il congiuntivo imperfetto parla sempre del passato?","answer":"No: nell’ipotesi se fossi libero può riferirsi al presente."},{"question":"Quale tempo esprime anteriorità dopo pensavo?","answer":"Il congiuntivo trapassato: pensavo che fosse arrivato."}],"levels":{"base":{"focus":"Il congiuntivo imperfetto può dipendere da una reggente passata.","example":{"sentence":"Credevo che tu cantassi nel coro.","explanation":"Cantassi è seconda persona singolare del congiuntivo imperfetto."}},"consolidamento":{"focus":"Forma cantassi, temessi, dormissi e controlla le persone. Nell’ipotesi usa se avessi tempo, leggerei.","example":{"sentence":"Ieri pensavo che Marta fosse in laboratorio.","explanation":"Fosse indica una situazione contemporanea al pensiero passato."}},"avanzato":{"focus":"Il tempo può riferirsi al presente: se fossi libero, verrei ora.","example":{"sentence":"Vorrei che voi faceste una prova.","explanation":"Faceste è congiuntivo imperfetto, seconda persona plurale."}}},"simplified":{"lead":"Il congiuntivo imperfetto collega molti fatti a una reggente passata e compare nelle ipotesi possibili o irreali del presente.","steps":["Il congiuntivo imperfetto può dipendere da una reggente passata.","Forma cantassi, temessi, dormissi e controlla le persone.","Nell’ipotesi usa se avessi tempo, leggerei."],"example":{"sentence":"Se lo zaino fosse leggero, correrei al bus.","explanation":"Fosse è congiuntivo imperfetto di essere e introduce l’ipotesi; correrei ne esprime la conseguenza. L’ipotesi riguarda adesso."}},"pei":{"rule":"Per questa ipotesi scrivi se fosse, non se sarebbe.","example":{"sentence":"Credevo che tu cantassi nel coro.","explanation":"Cantassi è seconda persona singolare del congiuntivo imperfetto."}},"trackExamples":{"moda":{"sentence":"Vorrei che tu scegliessi un tessuto più leggero.","explanation":"Scegliessi dipende da un desiderio al condizionale."},"arredo":{"sentence":"Se il mobile fosse più stretto, entrerebbe.","explanation":"Fosse introduce un’ipotesi sul presente."},"liuteria":{"sentence":"Il maestro chiedeva che ascoltassimo la risonanza.","explanation":"Ascoltassimo dipende da una richiesta passata."}},"anchor":{"sentence":"Se lo zaino fosse leggero, correrei al bus.","explanation":"Fosse è congiuntivo imperfetto di essere e introduce l’ipotesi; correrei ne esprime la conseguenza. L’ipotesi riguarda adesso.","memory":"Se fosse, correrei: condizione al congiuntivo, risultato al condizionale."}},{"topic":"Verbi · condizionale presente","area":"parole","lead":"Il condizionale presente esprime una conseguenza subordinata a una condizione, un desiderio o una richiesta cortese.","objectives":["Formare il condizionale presente dalla radice corretta.","Esprimere desideri, richieste cortesi e conseguenze ipotetiche.","Distinguere canteremmo da canteremo."],"sections":[{"title":"Radice e terminazioni","text":"Il condizionale presente è un tempo semplice. Le desinenze sono -ei, -esti, -ebbe, -emmo, -este, -ebbero. La radice coincide di solito con quella del futuro: canter- dà canterei, temer- dà temerei e dormir- dà dormirei. Anche molte irregolarità sono condivise: sarò e sarei, avrò e avrei, verrò e verrei, potrò e potrei. La prima persona plurale termina in -emmo, con doppia m: canteremmo. Il futuro canteremo ha invece una sola m. Pronunciare distintamente le due parole può aiutarti a ricordare la differenza nella scrittura.","examples":[{"sentence":"Io canterei volentieri.","explanation":"Canterei è prima persona singolare del condizionale presente."},{"sentence":"Noi verremmo domani.","explanation":"Verremmo ha la radice irregolare verr- e la terminazione -emmo."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","canterei"],["tu","canteresti"],["lui / lei","canterebbe"],["noi","canteremmo"],["voi","cantereste"],["loro","canterebbero"]]}},{"title":"Condizione e conseguenza","text":"In se studiassi, capiresti, il congiuntivo imperfetto presenta la condizione e il condizionale presente esprime la conseguenza. L’ipotesi può essere realizzabile oppure contraria alla situazione attuale: se avessi una bicicletta, arriverei prima può essere detto da chi non la possiede. Il condizionale può comparire anche senza una frase con se quando la condizione si ricava dal contesto: con più tempo migliorerei il disegno. Ricostruire la condizione implicita aiuta a comprendere il valore della forma.","examples":[{"sentence":"Se provassi ancora, riusciresti.","explanation":"Riusciresti presenta il risultato legato alla condizione."},{"sentence":"Con una guida lavorerei meglio.","explanation":"La condizione sottintesa è se avessi una guida."}]},{"title":"Cortesia, desiderio e notizia non confermata","text":"Il condizionale attenua una richiesta: potresti aiutarmi? Esprime anche un desiderio, come vorrei imparare, oppure un consiglio, come dovresti riposare. Nel linguaggio giornalistico può segnalare una notizia attribuita ad altre fonti e non confermata direttamente: il ministro sarebbe in viaggio. In quest’ultimo caso il tempo non indica per forza un evento futuro. Leggi il contesto per distinguere l’uso ipotetico dalla cortesia e dalla presa di distanza rispetto a un’informazione; la forma grammaticale rimane la stessa.","examples":[{"sentence":"Potresti prestarmi la squadra?","explanation":"Il condizionale rende più cortese la richiesta."}]},{"title":"Presente, passato e grafia","text":"Il condizionale presente può riguardare oggi o domani: verrei ora, partirei domani. Il condizionale passato esprime invece un fatto non realizzato nel passato, come sarei venuto ieri, oppure il futuro visto da un momento passato, come disse che sarebbe venuto. Controlla le doppie nelle desinenze -ebbe ed -ebbero e distingui la prima plurale dal futuro: canteremmo ha mm, canteremo una sola m. Nell’ipotesi introdotta da se non sostituire il congiuntivo con un secondo condizionale: se potessi, verrei.","examples":[{"sentence":"Disse che sarebbe venuto, ma ora verrebbe solo con noi.","explanation":"Sarebbe venuto indica un futuro nel passato; verrebbe esprime una disponibilità attuale condizionata."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il condizionale presente esprime conseguenze ipotetiche, desideri e richieste cortesi."},{"label":"Costruisci","detail":"Aggiungi -ei, -esti, -ebbe, -emmo, -este, -ebbero alla radice adatta."},{"label":"Confronta","detail":"Nell’ipotesi usa se potessi, verrei."},{"label":"Controlla","detail":"Distingui canteremmo dal futuro canteremo e il presente dal condizionale passato."}]},"pitfalls":[{"mistake":"Se potrei, partirei.","correction":"Se potessi, partirei.","why":"La condizione richiede qui il congiuntivo imperfetto."},{"mistake":"Noi canteremo, se avessimo tempo.","correction":"Noi canteremmo, se avessimo tempo.","why":"La conseguenza ipotetica richiede il condizionale, riconoscibile da mm."}],"recap":["Il condizionale presente esprime conseguenze ipotetiche, desideri e richieste cortesi.","Aggiungi -ei, -esti, -ebbe, -emmo, -este, -ebbero alla radice adatta.","Nell’ipotesi usa se potessi, verrei.","Distingui canteremmo dal futuro canteremo e il presente dal condizionale passato."],"review":[{"question":"Quali usi ha vorrei?","answer":"Può esprimere un desiderio o una richiesta cortese."},{"question":"Che differenza c’è tra canteremo e canteremmo?","answer":"Canteremo è futuro indicativo; canteremmo è condizionale presente."},{"question":"Qual è il condizionale presente di essere con loro?","answer":"Loro sarebbero."}],"levels":{"base":{"focus":"Il condizionale presente esprime conseguenze ipotetiche, desideri e richieste cortesi.","example":{"sentence":"Io canterei volentieri.","explanation":"Canterei è prima persona singolare del condizionale presente."}},"consolidamento":{"focus":"Aggiungi -ei, -esti, -ebbe, -emmo, -este, -ebbero alla radice adatta. Nell’ipotesi usa se potessi, verrei.","example":{"sentence":"Se provassi ancora, riusciresti.","explanation":"Riusciresti presenta il risultato legato alla condizione."}},"avanzato":{"focus":"Distingui canteremmo dal futuro canteremo e il presente dal condizionale passato.","example":{"sentence":"Disse che sarebbe venuto, ma ora verrebbe solo con noi.","explanation":"Sarebbe venuto indica un futuro nel passato; verrebbe esprime una disponibilità attuale condizionata."}}},"simplified":{"lead":"Il condizionale presente esprime una conseguenza subordinata a una condizione, un desiderio o una richiesta cortese.","steps":["Il condizionale presente esprime conseguenze ipotetiche, desideri e richieste cortesi.","Aggiungi -ei, -esti, -ebbe, -emmo, -este, -ebbero alla radice adatta.","Nell’ipotesi usa se potessi, verrei."],"example":{"sentence":"Una fetta di pizza la mangerei anche adesso.","explanation":"Mangerei è condizionale presente: esprime una disponibilità o un desiderio. La condizione può essere sottintesa: se ci fosse."}},"pei":{"rule":"Il condizionale esprime un desiderio: vorrei una pausa.","example":{"sentence":"Io canterei volentieri.","explanation":"Canterei è prima persona singolare del condizionale presente."}},"trackExamples":{"moda":{"sentence":"Userei una cucitura più resistente.","explanation":"Userei esprime una scelta possibile o un consiglio."},"arredo":{"sentence":"Con queste misure costruiremmo una libreria.","explanation":"Costruiremmo esprime una conseguenza condizionata."},"liuteria":{"sentence":"Potresti controllare l’accordatura?","explanation":"Potresti introduce una richiesta cortese."}},"anchor":{"sentence":"Una fetta di pizza la mangerei anche adesso.","explanation":"Mangerei è condizionale presente: esprime una disponibilità o un desiderio. La condizione può essere sottintesa: se ci fosse.","memory":"Mangerei lascia spazio a un se, anche quando non lo scrivi."}},{"topic":"Verbi · imperativo presente","area":"parole","lead":"L’imperativo serve a dare istruzioni, ordini, inviti e consigli a chi ascolta.","objectives":["Dare istruzioni adatte al destinatario.","Costruire il divieto rivolto a tu con non e infinito.","Collocare correttamente pronomi e apostrofi negli ordini."],"sections":[{"title":"Le persone dell’imperativo","text":"L’imperativo ha forme proprie per tu e voi: canta, cantate; temi, temete; dormi, dormite. Per noi si usa una forma con valore di esortazione, come cantiamo. Le forme di cortesia rivolte a Lei e quelle rivolte a loro sono fornite dal congiuntivo presente: canti, cantino. Non esiste una prima persona singolare dell’imperativo: un ordine diretto presuppone un destinatario. Nel modello sono quindi indicate le sei posizioni personali, ma la casella di io rimane priva di forma e questo limite va rispettato.","examples":[{"sentence":"Apri il quaderno.","explanation":"Apri è un imperativo rivolto a tu."},{"sentence":"Aspettate il vostro turno.","explanation":"Aspettate è un imperativo rivolto a voi."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","nessuna forma"],["tu","canta"],["lui / lei","canti (Lei: congiuntivo esortativo)"],["noi","cantiamo (esortazione)"],["voi","cantate"],["loro","cantino (congiuntivo esortativo)"]]}},{"title":"Istruzioni e tono della comunicazione","text":"Un imperativo può essere un comando, un invito, un consiglio o un’istruzione pratica. Il tono dipende dalle parole che lo accompagnano, dal rapporto fra le persone e dalla situazione: passa qui il foglio, per favore è diverso da un ordine gridato. Nelle procedure di laboratorio usa verbi precisi e una sequenza chiara. Per attenuare ulteriormente una richiesta puoi scegliere il condizionale: potresti passarmi il foglio? La funzione comunicativa resta simile, mentre cambiano modo verbale e grado di cortesia.","examples":[{"sentence":"Controlla la misura prima del taglio.","explanation":"L’imperativo dà un’istruzione operativa."},{"sentence":"Si accomodi, signora.","explanation":"Si accomodi è una forma di cortesia, costruita con il congiuntivo."}]},{"title":"La forma negativa e i pronomi","text":"Per vietare qualcosa a tu si usa non seguito dall’infinito: non correre, non toccare. Con voi si mantiene l’imperativo: non correte. Nell’ordine affermativo i pronomi atoni si uniscono normalmente al verbo: guardalo, portami, sedetevi. Con l’imperativo negativo rivolto a tu sono possibili non lo toccare e non toccarlo. Con la forma di cortesia il pronome precede il verbo: mi dica, si sieda. Riconoscere la posizione del pronome aiuta a individuare destinatario e forma verbale.","examples":[{"sentence":"Non toccare il ferro caldo; lascialo sul supporto.","explanation":"Non toccare è un divieto per tu; lascialo unisce lascia e lo."}]},{"title":"Forme irregolari e apostrofo","text":"Essere ha sii e siate; avere abbi e abbiate. Per andare, dare, fare e stare esistono le forme brevi va’, da’, fa’, sta’, accanto a vai, dai, fai, stai; dire ha di’. L’apostrofo delle forme brevi non va confuso con un accento. Quando si aggiunge un pronome a molte di queste forme, la consonante raddoppia: dimmi, dammi, fammi, stammi; con gli non raddoppia, come in digli. Leggi la frase intera per distinguere da’ imperativo da dà, presente indicativo di dare.","examples":[{"sentence":"Dimmi la misura e sii preciso.","explanation":"Dimmi unisce di’ e mi; sii è l’imperativo irregolare di essere."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"L’imperativo dà ordini, istruzioni, inviti e consigli a chi ascolta."},{"label":"Costruisci","detail":"Per tu usa canta; per voi cantate; io non ha un imperativo."},{"label":"Confronta","detail":"Il divieto rivolto a tu usa non più infinito: non correre."},{"label":"Controlla","detail":"Controlla pronomi, forme di cortesia e grafie come di’, dimmi e dà."}]},"pitfalls":[{"mistake":"Non corri nel corridoio!","correction":"Non correre nel corridoio!","why":"Il divieto rivolto a tu usa l’infinito."},{"mistake":"Dìmi il risultato.","correction":"Dimmi il risultato.","why":"Il pronome si unisce a di’ e la m raddoppia, senza accento."}],"recap":["L’imperativo dà ordini, istruzioni, inviti e consigli a chi ascolta.","Per tu usa canta; per voi cantate; io non ha un imperativo.","Il divieto rivolto a tu usa non più infinito: non correre.","Controlla pronomi, forme di cortesia e grafie come di’, dimmi e dà."],"review":[{"question":"Perché manca l’imperativo con io?","answer":"Perché l’ordine diretto si rivolge a un destinatario; non c’è una forma propria di prima singolare."},{"question":"Come trasformi tocca in un divieto per tu?","answer":"Non toccare."},{"question":"Qual è l’imperativo di essere con tu?","answer":"Sii."}],"levels":{"base":{"focus":"L’imperativo dà ordini, istruzioni, inviti e consigli a chi ascolta.","example":{"sentence":"Apri il quaderno.","explanation":"Apri è un imperativo rivolto a tu."}},"consolidamento":{"focus":"Per tu usa canta; per voi cantate; io non ha un imperativo. Il divieto rivolto a tu usa non più infinito: non correre.","example":{"sentence":"Controlla la misura prima del taglio.","explanation":"L’imperativo dà un’istruzione operativa."}},"avanzato":{"focus":"Controlla pronomi, forme di cortesia e grafie come di’, dimmi e dà.","example":{"sentence":"Dimmi la misura e sii preciso.","explanation":"Dimmi unisce di’ e mi; sii è l’imperativo irregolare di essere."}}},"simplified":{"lead":"L’imperativo serve a dare istruzioni, ordini, inviti e consigli a chi ascolta.","steps":["L’imperativo dà ordini, istruzioni, inviti e consigli a chi ascolta.","Per tu usa canta; per voi cantate; io non ha un imperativo.","Il divieto rivolto a tu usa non più infinito: non correre."],"example":{"sentence":"Apri il libro, il gatto può aspettare.","explanation":"Apri è un imperativo rivolto a tu. L’ordine negativo diventerebbe non aprire."}},"pei":{"rule":"Per un ordine scrivi apri; per un divieto scrivi non aprire.","example":{"sentence":"Apri il quaderno.","explanation":"Apri è un imperativo rivolto a tu."}},"trackExamples":{"moda":{"sentence":"Segna il margine sul tessuto.","explanation":"Segna dà un’istruzione rivolta a tu."},"arredo":{"sentence":"Controllate che il pannello sia fermo.","explanation":"Controllate è un imperativo di seconda plurale."},"liuteria":{"sentence":"Non forzare il pirolo.","explanation":"Il divieto a tu si costruisce con l’infinito."}},"anchor":{"sentence":"Apri il libro, il gatto può aspettare.","explanation":"Apri è un imperativo rivolto a tu. L’ordine negativo diventerebbe non aprire.","memory":"Per tu: apri; per vietarlo: non aprire."}},{"topic":"Verbi · Uso dei tempi","area":"parole","lead":"Per scegliere un tempo verbale considera quando avviene il fatto, come lo osservi e quale rapporto ha con gli altri fatti.","objectives":["Ricostruire l’ordine degli eventi.","Distinguere svolgimento, anteriorità e posteriorità.","Mantenere coerenti i tempi in un racconto o riassunto."],"sections":[{"title":"Il punto da cui osservi i fatti","text":"Il momento in cui parliamo è il primo riferimento: un fatto può essere presente, passato o futuro rispetto a ora. Nei racconti compare anche un secondo riferimento, interno alla storia: quando arrivai, Marta era già uscita. L’uscita precede l’arrivo, ed entrambi precedono il momento in cui la storia viene raccontata. Prima di coniugare, individua questi punti. Un avverbio come ieri aiuta, ma non stabilisce da solo il tempo: ieri studiavo e ieri ho studiato osservano diversamente il medesimo giorno.","examples":[{"sentence":"Ora studio; ieri ho studiato; domani studierò.","explanation":"I tre tempi collocano i fatti rispetto al momento presente."},{"sentence":"Quando arrivai, Marta era già uscita.","explanation":"Era uscita indica un fatto precedente all’arrivo passato."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","studio"],["tu","studi"],["lui / lei","studia"],["noi","studiamo"],["voi","studiate"],["loro","studiano"]]}},{"title":"Svolgimento e fatto delimitato","text":"L’aspetto riguarda il modo in cui si presenta l’azione. L’imperfetto mostra abitudini, descrizioni e situazioni in corso; passato prossimo e remoto presentano eventi delimitati. In mentre leggevo, cadde una matita la lettura è lo sfondo e la caduta è l’evento. Tra passato prossimo e remoto contano il rapporto percepito con il presente, il genere del testo e gli usi regionali. La sola distanza cronologica non basta: un fatto di ieri può essere raccontato con tempi diversi secondo la prospettiva scelta.","examples":[{"sentence":"Mentre studiavo, è arrivato un messaggio.","explanation":"L’imperfetto mostra lo svolgimento; il passato prossimo introduce un fatto delimitato."},{"sentence":"Ogni estate andavamo al lago; quell’anno ci andammo a giugno.","explanation":"Andavamo indica l’abitudine; andammo un episodio specifico."}]},{"title":"Anteriorità e tempi composti","text":"I tempi composti indicano spesso un fatto compiuto prima di un riferimento. Ho finito guarda il risultato da ora; avevo finito lo guarda da un momento passato; avrò finito lo guarda da un momento futuro. Nel congiuntivo, credo che studi presenta contemporaneità, credo che abbia studiato anteriorità; pensavo che studiasse presenta contemporaneità nel passato, pensavo che avesse studiato anteriorità. Il condizionale passato può esprimere posteriorità rispetto a un passato: disse che sarebbe tornato. Una linea del tempo rende visibili questi rapporti.","examples":[{"sentence":"Quando avrai terminato, controlleremo insieme.","explanation":"Avrai terminato indica l’azione da completare prima del controllo futuro."}]},{"title":"Coerenza e intenzione comunicativa","text":"Modo e tempo lavorano insieme: so che arriva presenta un’informazione, spero che arrivi esprime una speranza; se arrivasse, inizieremmo costruisce un’ipotesi. Anche il presente può riferirsi al futuro, come domani parto, e il futuro può esprimere una supposizione presente, come saranno le nove. In un riassunto scegli un tempo principale e mantienilo coerente; cambia tempo quando serve a mostrare un diverso rapporto fra gli eventi. Rileggi ogni passaggio chiedendoti che cosa il lettore sa già e quale fatto viene prima.","examples":[{"sentence":"Pensavo che sarebbe arrivato oggi, ma ora so che arriverà domani.","explanation":"Sarebbe arrivato è futuro nel passato; arriverà è futuro rispetto al presente."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Individua il momento presente e il punto di riferimento del racconto."},{"label":"Costruisci","detail":"Distingui svolgimento, abitudine ed evento delimitato."},{"label":"Confronta","detail":"Usa i tempi composti per esprimere l’anteriorità al riferimento."},{"label":"Controlla","detail":"Controlla modo, contesto e coerenza del testo, non soltanto gli avverbi."}]},"pitfalls":[{"mistake":"Il passato remoto indica sempre eventi antichi.","correction":"Il remoto presenta eventi conclusi secondo una certa prospettiva.","why":"Distanza cronologica e scelta del tempo non coincidono automaticamente."},{"mistake":"Pensavo che verrà il giorno dopo.","correction":"Pensavo che sarebbe venuto il giorno dopo.","why":"Il condizionale passato esprime normalmente il futuro visto dal passato."}],"recap":["Individua il momento presente e il punto di riferimento del racconto.","Distingui svolgimento, abitudine ed evento delimitato.","Usa i tempi composti per esprimere l’anteriorità al riferimento.","Controlla modo, contesto e coerenza del testo, non soltanto gli avverbi."],"review":[{"question":"Come distingui studiavo da ho studiato?","answer":"Il primo mostra svolgimento o abitudine; il secondo un fatto delimitato."},{"question":"Quale fatto viene prima in arrivai quando aveva già chiuso?","answer":"La chiusura, espressa dal trapassato prossimo."},{"question":"Che valore ha il futuro in saranno le nove?","answer":"Esprime una supposizione sul presente."}],"levels":{"base":{"focus":"Individua il momento presente e il punto di riferimento del racconto.","example":{"sentence":"Ora studio; ieri ho studiato; domani studierò.","explanation":"I tre tempi collocano i fatti rispetto al momento presente."}},"consolidamento":{"focus":"Distingui svolgimento, abitudine ed evento delimitato. Usa i tempi composti per esprimere l’anteriorità al riferimento.","example":{"sentence":"Mentre studiavo, è arrivato un messaggio.","explanation":"L’imperfetto mostra lo svolgimento; il passato prossimo introduce un fatto delimitato."}},"avanzato":{"focus":"Controlla modo, contesto e coerenza del testo, non soltanto gli avverbi.","example":{"sentence":"Pensavo che sarebbe arrivato oggi, ma ora so che arriverà domani.","explanation":"Sarebbe arrivato è futuro nel passato; arriverà è futuro rispetto al presente."}}},"simplified":{"lead":"Per scegliere un tempo verbale considera quando avviene il fatto, come lo osservi e quale rapporto ha con gli altri fatti.","steps":["Individua il momento presente e il punto di riferimento del racconto.","Distingui svolgimento, abitudine ed evento delimitato.","Usa i tempi composti per esprimere l’anteriorità al riferimento."],"example":{"sentence":"Avevo preparato tutto, poi ho dimenticato lo zaino.","explanation":"Avevo preparato colloca la preparazione prima di un altro passato; ho dimenticato racconta il fatto successivo."}},"pei":{"rule":"Chiediti che cosa succede prima e che cosa succede dopo.","example":{"sentence":"Ora studio; ieri ho studiato; domani studierò.","explanation":"I tre tempi collocano i fatti rispetto al momento presente."}},"trackExamples":{"moda":{"sentence":"Mentre disegnavo, ho cambiato il modello.","explanation":"Sfondo all’imperfetto ed evento al passato prossimo."},"arredo":{"sentence":"Quando avremo misurato la parete, progetteremo lo scaffale.","explanation":"La misurazione precede il progetto nel futuro."},"liuteria":{"sentence":"Il liutaio spiegò che avrebbe provato lo strumento.","explanation":"Il condizionale passato esprime un’azione futura rispetto a spiegò."}},"anchor":{"sentence":"Avevo preparato tutto, poi ho dimenticato lo zaino.","explanation":"Avevo preparato colloca la preparazione prima di un altro passato; ho dimenticato racconta il fatto successivo.","memory":"Prima avevo preparato; dopo ho dimenticato."}},{"topic":"Verbi · Passivo","area":"parole","lead":"Nel passivo il soggetto riceve l’azione: la frase mette in primo piano ciò che viene lavorato, spostato o controllato.","objectives":["Trasformare un’attiva transitiva in passiva.","Concordare il participio con il soggetto che riceve l’azione.","Usare essere e venire soltanto nelle costruzioni ammesse."],"sections":[{"title":"Dall’attivo al passivo","text":"Un verbo transitivo con complemento oggetto può essere trasformato in passivo. Nell’attiva il tecnico controlla la macchina, il tecnico compie l’azione e la macchina è l’oggetto. Nella passiva la macchina è controllata dal tecnico, la macchina diventa soggetto e dal tecnico indica chi compie l’azione. Il significato di base resta lo stesso, ma cambia ciò che mettiamo in evidenza. I verbi intransitivi, come arrivare e dormire, non offrono un complemento oggetto da trasformare in soggetto e normalmente non ammettono questa trasformazione.","examples":[{"sentence":"Il tecnico controlla la macchina.","explanation":"Nell’attiva il soggetto compie l’azione sulla macchina."},{"sentence":"La macchina è controllata dal tecnico.","explanation":"Nella passiva la macchina è soggetto e riceve l’azione."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","sono osservato / osservata"],["tu","sei osservato / osservata"],["lui / lei","è osservato / osservata"],["noi","siamo osservati / osservate"],["voi","siete osservati / osservate"],["loro","sono osservati / osservate"]]}},{"title":"Essere e concordanza del participio","text":"Il passivo si costruisce con essere nel modo e tempo richiesti, seguito dal participio passato del verbo. Il participio concorda in genere e numero con il soggetto: il tavolo è montato, le sedie sono montate. Nei tempi composti si usa la forma composta di essere: è stato montato, erano state montate, sarà stato montato. Il gruppo verbale va letto interamente; è stato riparato è un passato prossimo passivo, non tre azioni diverse. Anche i modi indefiniti ammettono il passivo: essere controllato, essere stato controllato.","examples":[{"sentence":"Le sedie sono state montate ieri.","explanation":"Sono state montate è passato prossimo passivo, femminile plurale."},{"sentence":"Spero che il lavoro sia controllato.","explanation":"Sia controllato è un congiuntivo presente passivo."}]},{"title":"Venire, andare e si passivante","text":"Nei tempi semplici il passivo può essere formato anche con venire e participio: il progetto viene controllato, veniva controllato, verrà controllato, venga controllato. Questa costruzione sottolinea l’azione e aiuta a distinguerla da uno stato: la porta è chiusa può descrivere uno stato; la porta viene chiusa descrive un evento. Venire non sostituisce essere nei tempi composti del passivo: è stato controllato è corretto; è venuto controllato non è il corrispondente passato prossimo passivo. Non cambiare ausiliare mantenendo meccanicamente il resto del gruppo.\n\nAndare con il participio può esprimere necessità nei tempi semplici: il modulo va firmato significa deve essere firmato. Non descrive soltanto un evento futuro. Con i verbi transitivi il si passivante offre un’altra costruzione: si controllano i pezzi equivale a i pezzi vengono controllati. Pezzi è soggetto e richiede il plurale. In si lavora, invece, si è impersonale e non c’è un soggetto che riceve l’azione.","examples":[{"sentence":"Il cancello veniva chiuso alle otto.","explanation":"Veniva chiuso è passivo all’imperfetto e presenta un’azione abituale."},{"sentence":"Il modulo va firmato prima della consegna.","explanation":"Va firmato è una costruzione passiva con andare e indica un obbligo: il modulo deve essere firmato."},{"sentence":"Si controllano i pezzi; qui si lavora con calma.","explanation":"Si controllano è passivante: i pezzi sono soggetto plurale. Si lavora è invece impersonale."}]},{"title":"Agente, causa efficiente e usi del passivo","text":"Il responsabile dell’azione può essere espresso oppure lasciato implicito: il documento è stato approvato. Nella terminologia scolastica si parla di complemento d’agente per una persona o un animale, di causa efficiente per una forza o causa inanimata: il ramo fu spezzato dal vento. Entrambi sono introdotti normalmente da da. Il passivo è frequente nelle procedure quando interessa il processo più dell’esecutore. Per analizzarlo, conserva il tempo dell’attiva: controllava diventa era controllato, ha controllato diventa è stato controllato. Trasformare cambia la costruzione, non l’ordine degli eventi.","examples":[{"sentence":"Il ramo fu spezzato dal vento.","explanation":"Dal vento indica la causa efficiente; fu spezzato è passato remoto passivo."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Nel passivo il soggetto riceve l’azione di un verbo transitivo."},{"label":"Costruisci","detail":"Usa essere nel tempo richiesto e il participio concordato con il soggetto."},{"label":"Confronta","detail":"Venire forma il passivo nei tempi semplici, non sostituisce essere nei composti."},{"label":"Controlla","detail":"L’agente o la causa efficiente possono essere espressi con da oppure omessi."},{"label":"Necessità","detail":"Andare e participio nei tempi semplici: il modulo va firmato significa deve essere firmato."},{"label":"Si passivante","detail":"Si controllano i pezzi: il verbo transitivo concorda con pezzi, soggetto. Si lavora è invece impersonale."}]},"pitfalls":[{"mistake":"Le sedie sono stato montato.","correction":"Le sedie sono state montate.","why":"Participi e soggetto devono concordare al femminile plurale."},{"mistake":"La macchina è venuta controllata ieri.","correction":"La macchina è stata controllata ieri.","why":"Il passato prossimo passivo richiede la forma composta di essere."}],"recap":["Nel passivo il soggetto riceve l’azione di un verbo transitivo.","Usa essere nel tempo richiesto e il participio concordato con il soggetto.","Venire forma il passivo nei tempi semplici, non sostituisce essere nei composti.","L’agente può essere omesso. Andare e participio può indicare necessità; il si passivante concorda con il soggetto."],"review":[{"question":"Quali verbi permettono normalmente il passivo?","answer":"I transitivi con un complemento oggetto trasformabile in soggetto."},{"question":"Che differenza c’è tra è chiusa e viene chiusa?","answer":"È chiusa può descrivere anche uno stato; viene chiusa mette in evidenza l’azione."},{"question":"Come trasformi Luca ha pulito il banco?","answer":"Il banco è stato pulito da Luca."}],"levels":{"base":{"focus":"Nel passivo il soggetto riceve l’azione di un verbo transitivo.","example":{"sentence":"Il tecnico controlla la macchina.","explanation":"Nell’attiva il soggetto compie l’azione sulla macchina."}},"consolidamento":{"focus":"Usa essere nel tempo richiesto e il participio concordato con il soggetto. Venire forma il passivo nei tempi semplici, non sostituisce essere nei composti.","example":{"sentence":"Le sedie sono state montate ieri.","explanation":"Sono state montate è passato prossimo passivo, femminile plurale."}},"avanzato":{"focus":"L’agente o la causa efficiente possono essere espressi con da oppure omessi.","example":{"sentence":"Il ramo fu spezzato dal vento.","explanation":"Dal vento indica la causa efficiente; fu spezzato è passato remoto passivo."}}},"simplified":{"lead":"Nel passivo il soggetto riceve l’azione: la frase mette in primo piano ciò che viene lavorato, spostato o controllato.","steps":["Nel passivo il soggetto riceve l’azione di un verbo transitivo.","Usa essere nel tempo richiesto e il participio concordato con il soggetto.","Venire forma il passivo nei tempi semplici, non sostituisce essere nei composti."],"example":{"sentence":"Il panino è stato divorato da mio fratello.","explanation":"Il panino riceve l’azione ed è soggetto del passivo. È stato divorato è passato prossimo passivo; da mio fratello indica l’agente."}},"pei":{"rule":"Nel passivo il soggetto riceve l’azione: il banco è pulito.","example":{"sentence":"Il tecnico controlla la macchina.","explanation":"Nell’attiva il soggetto compie l’azione sulla macchina."}},"trackExamples":{"moda":{"sentence":"La fodera viene cucita a mano.","explanation":"Viene cucita è presente passivo."},"arredo":{"sentence":"I ripiani sono stati fissati dal falegname.","explanation":"Il passato prossimo passivo concorda al maschile plurale."},"liuteria":{"sentence":"La tavola armonica verrà controllata dal liutaio.","explanation":"Verrà controllata è futuro semplice passivo."}},"anchor":{"sentence":"Il panino è stato divorato da mio fratello.","explanation":"Il panino riceve l’azione ed è soggetto del passivo. È stato divorato è passato prossimo passivo; da mio fratello indica l’agente.","memory":"Nel passivo guarda il panino: riceve l’azione."}},{"topic":"Verbi · Riflessivo","area":"parole","lead":"Una forma riflessiva collega l’azione al soggetto attraverso mi, ti, si, ci o vi; il significato della frase permette di distinguere i diversi usi.","objectives":["Distinguere riflessivo proprio, indiretto e reciproco.","Formare i tempi composti con essere e gli accordi corretti.","Riconoscere i verbi pronominali e altri usi di si."],"sections":[{"title":"Il riflessivo proprio","text":"Nel riflessivo proprio il soggetto compie un’azione che ricade su se stesso: Luca si lava equivale a Luca lava se stesso. Il pronome mi, ti, si, ci, vi, si ha funzione di complemento oggetto e cambia con la persona. Il verbo si coniuga normalmente e il pronome lo accompagna: mi lavo, ti lavi, si lava. Il soggetto può essere espresso o sottinteso. La domanda chi viene lavato? aiuta a riconoscere che esecutore e destinatario dell’azione coincidono.","examples":[{"sentence":"Mi lavo prima di uscire.","explanation":"Io compio l’azione e lavo me stesso."},{"sentence":"Le ragazze si pettinano.","explanation":"Le ragazze pettinano se stesse: si è oggetto."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","mi lavo"],["tu","ti lavi"],["lui / lei","si lava"],["noi","ci laviamo"],["voi","vi lavate"],["loro","si lavano"]]}},{"title":"Riflessivo indiretto e reciproco","text":"In mi lavo le mani, l’oggetto è le mani e mi significa a me: si parla di riflessivo indiretto o apparente. Nel riflessivo reciproco l’azione passa da una persona all’altra: Anna e Luca si salutano significa che Anna saluta Luca e Luca saluta Anna. Il numero plurale aiuta, ma il contesto resta necessario: i bambini si lavano può indicare che ciascuno lava se stesso oppure che si aiutano a vicenda. Aggiungere se stessi o a vicenda elimina l’ambiguità.","examples":[{"sentence":"Mi lavo le mani.","explanation":"Mi equivale ad a me; l’oggetto è le mani."},{"sentence":"I due amici si salutano a vicenda.","explanation":"Il pronome ha valore reciproco."}]},{"title":"Ausiliare e posizione del pronome","text":"Nei tempi composti le forme riflessive usano essere: mi sono lavato, ci siamo lavate. Il participio concorda con il soggetto. Il pronome precede di solito il verbo finito, ma si unisce all’infinito, al gerundio e all’imperativo affermativo: lavarsi, lavandosi, lavati. Con i servili sono possibili mi devo lavare e devo lavarmi. Nel passato la posizione del pronome influisce sulla scelta dell’ausiliare: mi sono dovuto lavare, ho dovuto lavarmi. Controlla l’intero gruppo prima di analizzarlo.","examples":[{"sentence":"Giulia si è preparata; i compagni si sono preparati.","explanation":"Con essere il participio concorda con il soggetto."}]},{"title":"Verbi pronominali e altri si","text":"Alcuni verbi includono il pronome senza avere un vero significato riflessivo: pentirsi, accorgersi, vergognarsi. In mi accorgo del rumore non significa accorgo me stesso: il pronome appartiene alla forma pronominale del verbo. Anche si mangia bene qui e si vendono libri contengono si, ma non sono riflessivi: il primo è impersonale, il secondo passivante. Per classificare il pronome prova a sostituirlo con se stesso o a vicenda e osserva il significato; la sola presenza di si non basta.","examples":[{"sentence":"Mi sono accorto dell’errore.","explanation":"Accorgersi è pronominale e non significa compiere un’azione su se stessi."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Nel riflessivo proprio il soggetto compie l’azione su se stesso."},{"label":"Costruisci","detail":"Controlla mi, ti, si, ci, vi, si e la persona del verbo."},{"label":"Confronta","detail":"Nei tempi composti usa essere e concorda il participio con il soggetto."},{"label":"Controlla","detail":"Distingui riflessivo proprio, indiretto, reciproco e verbo pronominale."}]},"pitfalls":[{"mistake":"Giulia si ha lavato.","correction":"Giulia si è lavata.","why":"Il riflessivo usa essere e il participio concorda con Giulia."},{"mistake":"Ogni si è riflessivo.","correction":"Si può essere riflessivo, impersonale o passivante.","why":"La funzione dipende dalla costruzione e dal significato."}],"recap":["Nel riflessivo proprio il soggetto compie l’azione su se stesso.","Controlla mi, ti, si, ci, vi, si e la persona del verbo.","Nei tempi composti usa essere e concorda il participio con il soggetto.","Distingui riflessivo proprio, indiretto, reciproco e verbo pronominale."],"review":[{"question":"Qual è la differenza tra mi lavo e mi lavo le mani?","answer":"Nel primo mi è oggetto; nel secondo significa a me e l’oggetto è le mani."},{"question":"Quale ausiliare usano i riflessivi nei tempi composti?","answer":"Essere, con participio concordato al soggetto."},{"question":"Accorgersi è riflessivo proprio?","answer":"No: è un verbo pronominale; il pronome fa parte del verbo."}],"levels":{"base":{"focus":"Nel riflessivo proprio il soggetto compie l’azione su se stesso.","example":{"sentence":"Mi lavo prima di uscire.","explanation":"Io compio l’azione e lavo me stesso."}},"consolidamento":{"focus":"Controlla mi, ti, si, ci, vi, si e la persona del verbo. Nei tempi composti usa essere e concorda il participio con il soggetto.","example":{"sentence":"Mi lavo le mani.","explanation":"Mi equivale ad a me; l’oggetto è le mani."}},"avanzato":{"focus":"Distingui riflessivo proprio, indiretto, reciproco e verbo pronominale.","example":{"sentence":"Mi sono accorto dell’errore.","explanation":"Accorgersi è pronominale e non significa compiere un’azione su se stessi."}}},"simplified":{"lead":"Una forma riflessiva collega l’azione al soggetto attraverso mi, ti, si, ci o vi; il significato della frase permette di distinguere i diversi usi.","steps":["Nel riflessivo proprio il soggetto compie l’azione su se stesso.","Controlla mi, ti, si, ci, vi, si e la persona del verbo.","Nei tempi composti usa essere e concorda il participio con il soggetto."],"example":{"sentence":"Mi preparo, ma i capelli non collaborano.","explanation":"Mi preparo collega l’azione al soggetto io. Al passato diventa mi sono preparato o mi sono preparata."}},"pei":{"rule":"Nel riflessivo l’azione torna al soggetto: io mi lavo.","example":{"sentence":"Mi lavo prima di uscire.","explanation":"Io compio l’azione e lavo me stesso."}},"trackExamples":{"moda":{"sentence":"La modella si prepara per la prova.","explanation":"Il pronome si collega l’azione al soggetto."},"arredo":{"sentence":"Mi sono messo i guanti prima di levigare.","explanation":"Mi è riflessivo indiretto; il verbo composto usa essere."},"liuteria":{"sentence":"I due allievi si scambiano gli strumenti a vicenda.","explanation":"Il pronome ha valore reciproco."}},"anchor":{"sentence":"Mi preparo, ma i capelli non collaborano.","explanation":"Mi preparo collega l’azione al soggetto io. Al passato diventa mi sono preparato o mi sono preparata.","memory":"Mi accompagna io; nel passato arriva essere."}},{"topic":"Verbi · Verbi servili","area":"parole","lead":"Potere, dovere e volere accompagnano un infinito e precisano possibilità, necessità o volontà.","objectives":["Individuare servile e infinito nel predicato.","Distinguere possibilità, necessità e volontà.","Scegliere ausiliare e posizione dei pronomi nei tempi composti."],"sections":[{"title":"Il gruppo formato da servile e infinito","text":"I verbi servili più comuni sono potere, dovere e volere. Quando accompagnano un infinito formano con esso un unico predicato verbale nell’analisi scolastica: posso entrare, devo studiare, voglio imparare. Il servile porta le informazioni di persona, modo e tempo; l’infinito indica l’azione principale. Potere esprime possibilità o permesso, dovere necessità o obbligo, volere intenzione o desiderio. Anche sapere può avere valore servile quando significa essere capaci di fare qualcosa: so nuotare.","examples":[{"sentence":"Posso entrare in aula?","explanation":"Potere esprime una richiesta di permesso."},{"sentence":"Devo ripassare il capitolo.","explanation":"Dovere indica una necessità."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","posso"],["tu","puoi"],["lui / lei","può"],["noi","possiamo"],["voi","potete"],["loro","possono"]]}},{"title":"Significati e uso autonomo","text":"Lo stesso verbo può essere servile oppure autonomo. In voglio partire volere accompagna un infinito; in voglio un quaderno regge un nome e ha significato proprio. In devo restituire il libro dovere è servile; in ti devo cinque euro indica un debito. Per sapere, confronta so cucire, che esprime capacità, con so la risposta, che esprime conoscenza. Non classificare un verbo soltanto guardando il suo infinito: cerca il verbo che lo segue e ricostruisci il significato del gruppo nella frase concreta.","examples":[{"sentence":"Voglio imparare, ma voglio anche una pausa.","explanation":"Nel primo caso volere è servile; nel secondo è usato autonomamente."},{"sentence":"So nuotare; so il tuo nome.","explanation":"Il primo sapere esprime capacità e accompagna un infinito; il secondo conoscenza."}]},{"title":"Ausiliare nei tempi composti","text":"Nei tempi composti il servile segue generalmente l’ausiliare richiesto dall’infinito: ho dovuto studiare, sono dovuta partire. Nell’uso contemporaneo è frequente anche avere davanti a molti intransitivi: ho dovuto partire. Quando l’infinito è essere si usa avere: ho dovuto essere paziente. Se il servile regge un riflessivo, la posizione del pronome dà due costruzioni regolari: mi sono dovuto alzare oppure ho dovuto alzarmi. Con essere il participio del servile concorda con il soggetto: Sara è dovuta partire.","examples":[{"sentence":"Sara è dovuta partire presto.","explanation":"Partire richiede essere e il participio dovuta concorda con Sara."}]},{"title":"Negazione, pronomi e irregolarità","text":"I pronomi possono precedere il servile o unirsi all’infinito: lo posso fare e posso farlo. Controlla però dove cade la negazione: non devi uscire esprime un divieto, mentre puoi non uscire lascia la possibilità di restare. I presenti dei servili sono irregolari: posso, puoi, può, possiamo, potete, possono; devo, devi, deve, dobbiamo, dovete, devono; voglio, vuoi, vuole, vogliamo, volete, vogliono. Nel condizionale potrei e vorrei rendono spesso una richiesta più cortese. Il verbo all’infinito resta invariato anche quando cambia la persona del servile.","examples":[{"sentence":"Lo puoi controllare oppure puoi controllarlo.","explanation":"La posizione del pronome cambia, ma il significato resta lo stesso."}]},{"title":"Verbi fraseologici e causativi","text":"Alcuni verbi accompagnano un infinito o un gerundio e precisano una fase o un aspetto dell’azione: stare per partire indica un’azione imminente, cominciare a lavorare l’inizio, continuare a lavorare la prosecuzione, finire di lavorare la conclusione. Sono spesso chiamati fraseologici aspettuali. Fare o lasciare più infinito possono esprimere un rapporto causativo: la docente fa preparare il modello dagli allievi significa che dispone la preparazione, svolta materialmente dagli allievi. Distingui chi provoca il fatto da chi materialmente compie l’azione.","examples":[{"sentence":"La classe sta per iniziare la prova.","explanation":"Sta per iniziare presenta l’azione come imminente."},{"sentence":"La docente fa controllare il disegno agli allievi.","explanation":"La docente dispone il controllo; gli allievi lo eseguono."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Potere, dovere e volere accompagnano un infinito con valore servile."},{"label":"Costruisci","detail":"La persona, il modo e il tempo si leggono nel servile."},{"label":"Confronta","detail":"Nei composti controlla l’ausiliare dell’infinito e la posizione dei pronomi."},{"label":"Controlla","detail":"Distingui l’uso servile da quello autonomo e osserva il significato della negazione."}]},"pitfalls":[{"mistake":"Io posso entro.","correction":"Io posso entrare.","why":"Dopo il servile si usa l’infinito."},{"mistake":"Maria ha dovuto stata paziente.","correction":"Maria ha dovuto essere paziente.","why":"Il verbo dipendente resta all’infinito; davanti a essere si usa avere."}],"recap":["Potere, dovere e volere accompagnano un infinito con valore servile.","La persona, il modo e il tempo si leggono nel servile.","Nei composti controlla l’ausiliare dell’infinito e la posizione dei pronomi.","Distingui l’uso servile da quello autonomo e osserva il significato della negazione."],"review":[{"question":"Perché posso leggere è un solo predicato nell’analisi scolastica?","answer":"Il servile precisa il valore dell’azione espressa dall’infinito."},{"question":"Volere è sempre servile?","answer":"No: in voglio un quaderno è autonomo."},{"question":"Come cambia la costruzione con alzarsi?","answer":"Mi sono dovuto alzare oppure ho dovuto alzarmi."}],"levels":{"base":{"focus":"Potere, dovere e volere accompagnano un infinito con valore servile.","example":{"sentence":"Posso entrare in aula?","explanation":"Potere esprime una richiesta di permesso."}},"consolidamento":{"focus":"La persona, il modo e il tempo si leggono nel servile. Nei composti controlla l’ausiliare dell’infinito e la posizione dei pronomi.","example":{"sentence":"Voglio imparare, ma voglio anche una pausa.","explanation":"Nel primo caso volere è servile; nel secondo è usato autonomamente."}},"avanzato":{"focus":"Distingui l’uso servile da quello autonomo e osserva il significato della negazione.","example":{"sentence":"Lo puoi controllare oppure puoi controllarlo.","explanation":"La posizione del pronome cambia, ma il significato resta lo stesso."}}},"simplified":{"lead":"Potere, dovere e volere accompagnano un infinito e precisano possibilità, necessità o volontà.","steps":["Potere, dovere e volere accompagnano un infinito con valore servile.","La persona, il modo e il tempo si leggono nel servile.","Nei composti controlla l’ausiliare dell’infinito e la posizione dei pronomi."],"example":{"sentence":"Posso uscire, devo studiare, voglio dormire.","explanation":"Posso, devo e voglio cambiano il significato dei rispettivi infiniti: possibilità, necessità e volontà. La persona si legge nel servile."}},"pei":{"rule":"Dopo posso, devo o voglio metti l’infinito: posso leggere.","example":{"sentence":"Posso entrare in aula?","explanation":"Potere esprime una richiesta di permesso."}},"trackExamples":{"moda":{"sentence":"Devi imbastire prima di cucire.","explanation":"Dovere indica una necessità operativa."},"arredo":{"sentence":"Possiamo montare il ripiano.","explanation":"Potere esprime possibilità."},"liuteria":{"sentence":"Voglio imparare ad accordare il violino.","explanation":"Volere esprime intenzione e regge imparare."}},"anchor":{"sentence":"Posso uscire, devo studiare, voglio dormire.","explanation":"Posso, devo e voglio cambiano il significato dei rispettivi infiniti: possibilità, necessità e volontà. La persona si legge nel servile.","memory":"Il servile cambia; uscire, studiare e dormire restano all’infinito."}},{"topic":"Verbi · Verbi impersonali","area":"parole","lead":"Un verbo impersonale presenta un fatto senza riferirlo a un soggetto determinato: piove, bisogna aspettare, si lavora.","objectives":["Riconoscere verbi atmosferici e costruzioni impersonali.","Distinguere si impersonale e si passivante.","Controllare ausiliari e concordanze nei composti impersonali."],"sections":[{"title":"Eventi senza soggetto determinato","text":"I verbi atmosferici, come piovere, nevicare, grandinare e tuonare, sono normalmente impersonali: si usano alla terza persona singolare senza un soggetto espresso o sottinteso da recuperare. Piove non equivale a lui piove e il cielo non va aggiunto come soggetto per completare l’analisi. Anche fa caldo e fa freddo sono espressioni impersonali. Se il verbo è usato in senso figurato può invece avere un soggetto: piovono critiche. Qui critiche è soggetto e il verbo concorda al plurale.","examples":[{"sentence":"Oggi piove.","explanation":"Il verbo atmosferico è impersonale e non ha un soggetto determinato."},{"sentence":"Piovono proteste.","explanation":"Nell’uso figurato proteste è soggetto; il verbo è plurale."}]},{"title":"Bisogna e le costruzioni simili","text":"Bisogna, occorre, sembra e accade possono introdurre un infinito o una frase con che: bisogna studiare, sembra che arrivi. Nell’analisi del periodo l’intera frase che segue può avere funzione soggettiva: bisogna che tutti collaborino. La costruzione è impersonale perché manca un soggetto personale determinato, ma questo non impedisce che una proposizione svolga il ruolo di soggetto. Occorrere può avere anche un nome come soggetto: occorre una matita, occorrono due fogli. Controlla quindi la costruzione prima di assegnare l’etichetta al verbo.","examples":[{"sentence":"Bisogna leggere le istruzioni.","explanation":"La necessità è espressa senza indicare un soggetto personale."},{"sentence":"Occorrono due fogli.","explanation":"Due fogli è soggetto e richiede il plurale."}]},{"title":"Il si impersonale e il si passivante","text":"Con si si può rendere impersonale un verbo: qui si lavora bene. Il verbo resta normalmente alla terza singolare e il soggetto indica genericamente le persone. Con un verbo transitivo seguito da un nome che riceve l’azione può comparire il si passivante: si vendono libri equivale a i libri vengono venduti. Libri è soggetto e il verbo concorda al plurale. Con i riflessivi il si impersonale diventa ci per evitare si si: ci si alza presto. La funzione si riconosce dalla struttura, non dalla sola presenza del pronome. Confronta la coniugazione personale di lavorare con la forma impersonale si lavora, che resta alla terza singolare.","examples":[{"sentence":"In biblioteca si studia; qui si vendono libri.","explanation":"Si studia è impersonale; si vendono è passivante, con libri soggetto."}],"table":{"headers":["Persona","Lavorare: costruzione personale di confronto"],"rows":[["io","lavoro"],["tu","lavori"],["lui / lei","lavora"],["noi","lavoriamo"],["voi","lavorate"],["loro","lavorano"]]}},{"title":"Tempi composti e concordanze","text":"Con i verbi atmosferici sono ammessi sia essere sia avere: è piovuto e ha piovuto. L’uso varia secondo verbo, contesto e abitudini linguistiche. Il si impersonale nei tempi composti usa essere: si è lavorato molto. Se il verbo personale richiede essere, il participio è normalmente plurale maschile, oppure femminile se il gruppo è tutto femminile: si è arrivati tardi; tra amiche, si è arrivate insieme. Anche gli aggettivi predicativi concordano al plurale: quando si è stanchi, si riposa. In un testo semplice puoi esplicitare il gruppo per evitare ambiguità.","examples":[{"sentence":"Dopo il viaggio si è arrivati stanchi.","explanation":"Il si impersonale richiede essere; arrivati e stanchi hanno valore plurale."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Un uso impersonale non indica un soggetto personale determinato."},{"label":"Costruisci","detail":"I verbi atmosferici sono normalmente alla terza persona singolare."},{"label":"Confronta","detail":"Distingui si studia da si vendono libri, dove libri è soggetto."},{"label":"Controlla","detail":"Nei composti controlla ausiliare e concordanze: si è lavorato, si è arrivati."}]},"pitfalls":[{"mistake":"Ieri si ha lavorato.","correction":"Ieri si è lavorato.","why":"Il si impersonale forma il composto con essere."},{"mistake":"Si vende libri.","correction":"Si vendono libri.","why":"Nella costruzione passivante libri è soggetto plurale."}],"recap":["Un uso impersonale non indica un soggetto personale determinato.","I verbi atmosferici sono normalmente alla terza persona singolare.","Distingui si studia da si vendono libri, dove libri è soggetto.","Nei composti controlla ausiliare e concordanze: si è lavorato, si è arrivati."],"review":[{"question":"Qual è il soggetto di piove nell’uso atmosferico?","answer":"Non c’è un soggetto determinato."},{"question":"Qual è la differenza tra si lavora e si vendono libri?","answer":"Il primo si è impersonale; il secondo è passivante e libri è soggetto."},{"question":"Sono corretti sia è piovuto sia ha piovuto?","answer":"Sì: entrambi gli ausiliari sono ammessi nell’uso atmosferico."}],"levels":{"base":{"focus":"Un uso impersonale non indica un soggetto personale determinato.","example":{"sentence":"Oggi piove.","explanation":"Il verbo atmosferico è impersonale e non ha un soggetto determinato."}},"consolidamento":{"focus":"I verbi atmosferici sono normalmente alla terza persona singolare. Distingui si studia da si vendono libri, dove libri è soggetto.","example":{"sentence":"Bisogna leggere le istruzioni.","explanation":"La necessità è espressa senza indicare un soggetto personale."}},"avanzato":{"focus":"Nei composti controlla ausiliare e concordanze: si è lavorato, si è arrivati.","example":{"sentence":"Dopo il viaggio si è arrivati stanchi.","explanation":"Il si impersonale richiede essere; arrivati e stanchi hanno valore plurale."}}},"simplified":{"lead":"Un verbo impersonale presenta un fatto senza riferirlo a un soggetto determinato: piove, bisogna aspettare, si lavora.","steps":["Un uso impersonale non indica un soggetto personale determinato.","I verbi atmosferici sono normalmente alla terza persona singolare.","Distingui si studia da si vendono libri, dove libri è soggetto."],"example":{"sentence":"Piove: anche l’ombrello oggi lavora.","explanation":"Piove è un verbo atmosferico impersonale: non bisogna cercare un lui o una lei che faccia piovere."}},"pei":{"rule":"Piove non ha un soggetto determinato: non cercare chi fa piovere.","example":{"sentence":"Oggi piove.","explanation":"Il verbo atmosferico è impersonale e non ha un soggetto determinato."}},"trackExamples":{"moda":{"sentence":"In sartoria si lavora con precisione.","explanation":"Si lavora ha valore impersonale."},"arredo":{"sentence":"Per questo mobile occorrono quattro cerniere.","explanation":"Quattro cerniere è soggetto: occorrere qui è personale."},"liuteria":{"sentence":"Prima della prova bisogna accordare.","explanation":"Bisogna esprime una necessità senza un soggetto personale determinato."}},"anchor":{"sentence":"Piove: anche l’ombrello oggi lavora.","explanation":"Piove è un verbo atmosferico impersonale: non bisogna cercare un lui o una lei che faccia piovere.","memory":"Piove sta da solo, alla terza singolare."}},{"topic":"Verbi · indicativo passato prossimo","area":"parole","lead":"Il passato prossimo presenta un fatto passato come compiuto e spesso lo mette in rapporto con la situazione presente.","objectives":["Formare il passato prossimo con l’ausiliare adatto.","Concordare il participio quando è richiesto.","Distinguere evento concluso, sfondo e fatto anteriore."],"sections":[{"title":"Ausiliare al presente e participio","text":"Il passato prossimo è un tempo composto dell’indicativo: presente di avere o essere più participio passato. Cantare dà ho cantato, dormire ho dormito e partire sono partito. Le forme regolari del participio terminano in -ato, -uto, -ito: parlato, temuto, dormito. Molti participi sono irregolari: fatto, detto, letto, scritto, preso, visto. Per riconoscere il tempo devi leggere il gruppo completo: ho letto è un solo verbo al passato prossimo, mentre ho è da solo presente di avere quando significa possiedo.","examples":[{"sentence":"Ho cantato due brani.","explanation":"Ho è ausiliare al presente e cantato è participio passato."},{"sentence":"Luca è partito stamattina.","explanation":"È partito è passato prossimo di partire."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","ho cantato"],["tu","hai cantato"],["lui / lei","ha cantato"],["noi","abbiamo cantato"],["voi","avete cantato"],["loro","hanno cantato"]]}},{"title":"Scegliere ausiliare e concordanza","text":"I verbi transitivi attivi usano avere: ho costruito una scatola. Gli intransitivi non seguono un’unica regola: partire richiede essere, dormire avere; in caso di dubbio consulta il dizionario. I riflessivi usano essere. Con essere il participio concorda con il soggetto: Sara è arrivata, gli amici sono arrivati. Con avere resta normalmente al maschile singolare, anche con soggetto femminile: Sara ha lavorato. Con i pronomi oggetto lo, la, li, le che precedono il verbo si accorda: le ho viste.","examples":[{"sentence":"Le ragazze sono arrivate insieme.","explanation":"Arrivate concorda con il soggetto femminile plurale."},{"sentence":"Le stoffe? Le ho ordinate ieri.","explanation":"Ordinate concorda con il pronome oggetto le, anteposto."}]},{"title":"Evento concluso e legame con il presente","text":"Il passato prossimo presenta spesso un fatto concluso di cui conta il risultato attuale: ho perso la chiave suggerisce che adesso non la trovo. È usato anche per narrare una serie di eventi: sono entrato, ho salutato e mi sono seduto. La parola prossimo non significa necessariamente accaduto poche ore fa: anche una scoperta antica può essere raccontata con questo tempo. Il rapporto con il presente, il tipo di testo e le abitudini regionali influiscono sul confronto con il passato remoto.","examples":[{"sentence":"Ho finito i compiti: ora posso uscire.","explanation":"Il fatto compiuto ha una conseguenza nella situazione presente."}]},{"title":"Confronto con imperfetto e trapassato","text":"L’imperfetto mostra l’azione nel suo svolgimento o come abitudine; il passato prossimo presenta un episodio delimitato. In mentre camminavo, ho incontrato Paolo l’incontro interrompe o attraversa lo sfondo. Il trapassato prossimo serve invece per un fatto precedente a un altro passato: quando sono arrivato, Paolo era già uscito. Non usare il passato prossimo per tutti gli eventi senza distinguere il loro ordine. Negli esercizi di coniugazione individua prima soggetto e infinito, poi ausiliare, participio e accordo necessario.","examples":[{"sentence":"Quando sono arrivata, il negozio aveva già chiuso.","explanation":"Sono arrivata indica l’arrivo; aveva chiuso il fatto precedente."}]},{"title":"Participio passato e participio presente","text":"Il participio passato contribuisce a formare i tempi composti: in hanno rifinito, rifinito è participio passato insieme all’ausiliare hanno. Esiste anche un participio presente, spesso terminante in -ante o -ente: cantante, dirigente, interessante. Nell’italiano attuale molte di queste forme funzionano come nomi o aggettivi: una cantante e una prova interessante. Per analizzarle osserva la funzione effettiva nella frase; non considerare automaticamente ogni parola in -ante o -ente un verbo.","examples":[{"sentence":"Le allieve hanno completato il pannello.","explanation":"Completato è participio passato e, con hanno, forma il passato prossimo."},{"sentence":"La cantante presenta una prova interessante.","explanation":"Cantante è usato come nome; interessante qualifica prova come aggettivo."}]},{"title":"Il participio come verbo e come aggettivo","text":"Un participio presente può essere usato come aggettivo o nome, ma in alcune costruzioni conserva valore verbale e può reggere un complemento: un disegno raffigurante una barca contiene raffigurante una barca, equivalente a che raffigura una barca. Il participio passato può comparire nei tempi composti, come aggettivo o nome: le misure controllate, gli invitati. In un’espressione come la porta chiusa il participio di un verbo transitivo si riferisce a ciò che ha ricevuto l’azione; in gli ospiti arrivati, arrivati riguarda chi ha compiuto il movimento. Analizza il verbo e il contesto prima di decidere il valore.","examples":[{"sentence":"Il libro contiene immagini raffiguranti strumenti.","explanation":"Raffiguranti regge il complemento strumenti e può essere reso con che raffigurano strumenti."},{"sentence":"Le scatole aperte sono sul banco; gli ospiti arrivati salutano.","explanation":"Aperte descrive scatole che hanno ricevuto l’azione; arrivati riguarda gli ospiti che sono arrivati."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Forma il passato prossimo con ausiliare al presente e participio passato."},{"label":"Costruisci","detail":"Controlla se il verbo richiede avere oppure essere."},{"label":"Confronta","detail":"Con essere concorda con il soggetto; con le ho viste concorda con il pronome oggetto."},{"label":"Controlla","detail":"Distingui il fatto concluso dallo sfondo all’imperfetto e dal fatto anteriore al trapassato."}]},"pitfalls":[{"mistake":"Sara ha andato a casa.","correction":"Sara è andata a casa.","why":"Andare richiede essere e il participio concorda con Sara."},{"mistake":"Le chiavi? Le ho trovato.","correction":"Le chiavi? Le ho trovate.","why":"Con il pronome oggetto le anteposto il participio concorda."}],"recap":["Forma il passato prossimo con ausiliare al presente e participio passato.","Controlla se il verbo richiede avere oppure essere.","Con essere concorda con il soggetto; con le ho viste concorda con il pronome oggetto.","Distingui il fatto concluso dallo sfondo all’imperfetto e dal fatto anteriore al trapassato."],"review":[{"question":"Come si forma ho cantato?","answer":"Presente di avere più participio passato di cantare."},{"question":"Il passato prossimo indica solo un passato recentissimo?","answer":"No: conta anche il rapporto percepito con il presente e il tipo di racconto."},{"question":"Perché Sara ha letto non diventa ha letta?","answer":"Con avere il participio normalmente resta al maschile singolare e non concorda con il soggetto."}],"levels":{"base":{"focus":"Forma il passato prossimo con ausiliare al presente e participio passato.","example":{"sentence":"Ho cantato due brani.","explanation":"Ho è ausiliare al presente e cantato è participio passato."}},"consolidamento":{"focus":"Controlla se il verbo richiede avere oppure essere. Con essere concorda con il soggetto; con le ho viste concorda con il pronome oggetto.","example":{"sentence":"Le ragazze sono arrivate insieme.","explanation":"Arrivate concorda con il soggetto femminile plurale."}},"avanzato":{"focus":"Distingui il fatto concluso dallo sfondo all’imperfetto e dal fatto anteriore al trapassato.","example":{"sentence":"Quando sono arrivata, il negozio aveva già chiuso.","explanation":"Sono arrivata indica l’arrivo; aveva chiuso il fatto precedente."}}},"simplified":{"lead":"Il passato prossimo presenta un fatto passato come compiuto e spesso lo mette in rapporto con la situazione presente.","steps":["Forma il passato prossimo con ausiliare al presente e participio passato.","Controlla se il verbo richiede avere oppure essere.","Con essere concorda con il soggetto; con le ho viste concorda con il pronome oggetto."],"example":{"sentence":"Ho finito i compiti: il gatto può riprendersi il quaderno.","explanation":"Ho finito è passato prossimo: presente dell’ausiliare avere e participio finito. Il lavoro è presentato come compiuto."}},"pei":{"rule":"Per il passato prossimo usa ho cantato oppure sono partito.","example":{"sentence":"Ho cantato due brani.","explanation":"Ho è ausiliare al presente e cantato è participio passato."}},"trackExamples":{"moda":{"sentence":"Abbiamo cucito la fodera.","explanation":"Passato prossimo con avere e participio cucito."},"arredo":{"sentence":"Le ante sono arrivate ieri.","explanation":"Essere e participio femminile plurale."},"liuteria":{"sentence":"Il liutaio ha regolato il ponticello.","explanation":"Il passato prossimo presenta un intervento compiuto."}},"anchor":{"sentence":"Ho finito i compiti: il gatto può riprendersi il quaderno.","explanation":"Ho finito è passato prossimo: presente dell’ausiliare avere e participio finito. Il lavoro è presentato come compiuto.","memory":"Ho più finito: due parole, un solo tempo composto."}},{"topic":"Verbi · indicativo trapassato prossimo","area":"parole","lead":"Il trapassato prossimo indica un fatto già compiuto prima di un altro momento passato.","objectives":["Individuare un fatto precedente a un altro passato.","Formare il trapassato con l’imperfetto dell’ausiliare.","Distinguerlo dall’imperfetto e dal passato prossimo."],"sections":[{"title":"La forma composta","text":"Il trapassato prossimo si forma con l’imperfetto di avere o essere seguito dal participio passato: avevo cantato, ero partito. L’imperfetto è contenuto nell’ausiliare; il gruppo completo appartiene al trapassato. Il modello di cantare è avevo, avevi, aveva, avevamo, avevate, avevano cantato. Per partire si usa ero, eri, era, eravamo, eravate, erano partito o partiti, con gli accordi richiesti. Il participio conserva le sue eventuali irregolarità: avevo fatto, avevi detto, avevamo scritto. Le due parole esprimono insieme un unico tempo.","examples":[{"sentence":"Avevo cantato prima della premiazione.","explanation":"Avevo più cantato forma il trapassato prossimo."},{"sentence":"Sara era partita prima di noi.","explanation":"Era partita indica un fatto già compiuto nel passato."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","avevo cantato"],["tu","avevi cantato"],["lui / lei","aveva cantato"],["noi","avevamo cantato"],["voi","avevate cantato"],["loro","avevano cantato"]]}},{"title":"Un passato precedente a un altro passato","text":"Per usare questo tempo occorre un riferimento passato, espresso nella frase oppure ricavabile dal contesto. In quando arrivai, il treno era già partito, l’arrivo è il riferimento e la partenza è precedente. Non serve che l’intervallo sia lungo: può trattarsi di pochi secondi. Il riferimento può essere un passato prossimo, un passato remoto o un imperfetto. Il trapassato rende esplicito l’ordine anche quando nel testo si racconta prima l’evento successivo e poi si torna indietro a spiegare ciò che era accaduto.","examples":[{"sentence":"Quando ho telefonato, il negozio aveva chiuso.","explanation":"La chiusura precede la telefonata passata."},{"sentence":"Ero tranquillo perché avevo studiato.","explanation":"Lo studio precede lo stato di tranquillità descritto all’imperfetto."}]},{"title":"Ausiliari e accordi del participio","text":"La scelta fra avere ed essere segue il verbo: avevo letto, ero arrivato, mi ero lavato. I transitivi attivi usano avere; gli intransitivi richiedono un controllo specifico. Con essere il participio concorda con il soggetto: le compagne erano uscite, i ragazzi si erano preparati. Con avere il soggetto non impone l’accordo: Maria aveva letto. I pronomi oggetto lo, la, li, le anteposti richiedono invece la concordanza: le avevo viste. Non cambiare ausiliare soltanto perché il soggetto è femminile o plurale.","examples":[{"sentence":"Le giacche? Le avevamo già sistemate.","explanation":"Sistemate concorda con il pronome oggetto le che precede il verbo."}]},{"title":"Confronto con i tempi vicini","text":"Il passato prossimo guarda un fatto compiuto dal momento presente: ho finito. Il trapassato prossimo lo guarda da un momento passato: avevo finito quando sei arrivato. L’imperfetto da solo mostra svolgimento o abitudine, non anteriorità compiuta: studiavo quando entrò è diverso da avevo studiato quando entrò. Il trapassato remoto, ormai soprattutto letterario, compare in contesti più ristretti come dopo che ebbe finito, uscì. Per i racconti quotidiani e per spiegare un antecedente nel passato, il trapassato prossimo è la scelta abituale.","examples":[{"sentence":"Studiavo quando entrò; avevo studiato prima che entrasse.","explanation":"La prima frase mostra un’attività in corso, la seconda uno studio già svolto."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il trapassato prossimo indica un fatto precedente a un altro passato."},{"label":"Costruisci","detail":"Unisci imperfetto dell’ausiliare e participio: avevo cantato, ero partito."},{"label":"Confronta","detail":"Con essere accorda il participio al soggetto."},{"label":"Controlla","detail":"Distingui l’anteriorità compiuta dallo svolgimento espresso dall’imperfetto."}]},"pitfalls":[{"mistake":"Quando arrivai, Luca ha già chiuso.","correction":"Quando arrivai, Luca aveva già chiuso.","why":"Il trapassato rende chiara l’anteriorità rispetto all’arrivo passato."},{"mistake":"Le ragazze erano partito.","correction":"Le ragazze erano partite.","why":"Con essere il participio concorda al femminile plurale."}],"recap":["Il trapassato prossimo indica un fatto precedente a un altro passato.","Unisci imperfetto dell’ausiliare e participio: avevo cantato, ero partito.","Con essere accorda il participio al soggetto.","Distingui l’anteriorità compiuta dallo svolgimento espresso dall’imperfetto."],"review":[{"question":"Quale ausiliare compare in avevamo finito?","answer":"Avere all’imperfetto."},{"question":"Quale fatto viene prima in entrai e vidi che aveva pulito?","answer":"La pulizia, espressa da aveva pulito."},{"question":"Che differenza c’è tra leggevo e avevo letto?","answer":"Leggevo mostra lo svolgimento o l’abitudine; avevo letto un fatto compiuto prima di un riferimento passato."}],"levels":{"base":{"focus":"Il trapassato prossimo indica un fatto precedente a un altro passato.","example":{"sentence":"Avevo cantato prima della premiazione.","explanation":"Avevo più cantato forma il trapassato prossimo."}},"consolidamento":{"focus":"Unisci imperfetto dell’ausiliare e participio: avevo cantato, ero partito. Con essere accorda il participio al soggetto.","example":{"sentence":"Quando ho telefonato, il negozio aveva chiuso.","explanation":"La chiusura precede la telefonata passata."}},"avanzato":{"focus":"Distingui l’anteriorità compiuta dallo svolgimento espresso dall’imperfetto.","example":{"sentence":"Studiavo quando entrò; avevo studiato prima che entrasse.","explanation":"La prima frase mostra un’attività in corso, la seconda uno studio già svolto."}}},"simplified":{"lead":"Il trapassato prossimo indica un fatto già compiuto prima di un altro momento passato.","steps":["Il trapassato prossimo indica un fatto precedente a un altro passato.","Unisci imperfetto dell’ausiliare e participio: avevo cantato, ero partito.","Con essere accorda il participio al soggetto."],"example":{"sentence":"Quando suonò la sveglia, avevo già spento il telefono.","explanation":"Avevo spento indica l’azione compiuta prima del suono della sveglia, che è un altro fatto passato."}},"pei":{"rule":"Il trapassato indica un fatto già compiuto prima di un altro passato.","example":{"sentence":"Avevo cantato prima della premiazione.","explanation":"Avevo più cantato forma il trapassato prossimo."}},"trackExamples":{"moda":{"sentence":"Avevo preparato il cartamodello prima della prova.","explanation":"La preparazione precede la prova passata."},"arredo":{"sentence":"Quando arrivò il cliente, avevamo montato la libreria.","explanation":"Il montaggio era già compiuto all’arrivo."},"liuteria":{"sentence":"Il violino suonava bene perché il liutaio lo aveva regolato.","explanation":"La regolazione precede la situazione descritta all’imperfetto."}},"anchor":{"sentence":"Quando suonò la sveglia, avevo già spento il telefono.","explanation":"Avevo spento indica l’azione compiuta prima del suono della sveglia, che è un altro fatto passato.","memory":"Il trapassato prossimo mette già prima di un passato."}},{"topic":"Verbi · indicativo trapassato remoto","area":"parole","lead":"Il trapassato remoto indica un fatto compiuto prima di un evento al passato remoto, soprattutto in subordinate temporali della narrazione.","objectives":["Riconoscere il trapassato remoto nei racconti.","Formarlo con il passato remoto dell’ausiliare.","Collegarlo a subordinate temporali e reggenti al passato remoto."],"sections":[{"title":"Passato remoto dell’ausiliare e participio","text":"Il trapassato remoto è un tempo composto: passato remoto di avere o essere più participio passato. Cantare dà ebbi cantato, avesti cantato, ebbe cantato, avemmo cantato, aveste cantato, ebbero cantato. Partire dà fui partito, fosti partito, fu partito, fummo partiti, foste partiti, furono partiti, adattando genere e numero al soggetto. Gli ausiliari sono irregolari al remoto e vanno riconosciuti nel gruppo. Fu non richiede accento. Il participio resta quello del verbo lessicale, anche quando è irregolare: ebbe scritto, ebbero fatto.","examples":[{"sentence":"Dopo che ebbe cantato, uscì di scena.","explanation":"Ebbe è passato remoto di avere; ebbe cantato è trapassato remoto."},{"sentence":"Appena furono partiti, iniziò a piovere.","explanation":"Furono partiti è un trapassato remoto con essere."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","ebbi cantato"],["tu","avesti cantato"],["lui / lei","ebbe cantato"],["noi","avemmo cantato"],["voi","aveste cantato"],["loro","ebbero cantato"]]}},{"title":"La successione nel racconto","text":"Questo tempo compare soprattutto dopo congiunzioni temporali come dopo che, appena, non appena e quando. Presenta come completata un’azione prima di un’altra espressa di norma al passato remoto: non appena ebbe aperto, entrò. La conclusione dell’azione precedente è messa in evidenza; la vicinanza dei due eventi è frequente, ma non costituisce una misura cronologica rigida. La frase dipendente prepara il fatto principale e ne chiarisce l’ordine. È quindi utile riconoscere insieme la subordinata temporale e il verbo della frase reggente.","examples":[{"sentence":"Non appena ebbero finito, consegnarono il lavoro.","explanation":"La conclusione del lavoro precede la consegna."},{"sentence":"Dopo che avemmo letto, discutemmo il testo.","explanation":"La lettura è completata prima della discussione."}]},{"title":"Un tempo da riconoscere nei testi","text":"Il trapassato remoto è poco frequente nella conversazione contemporanea e si incontra soprattutto nei racconti letterari, storici o volutamente tradizionali. Nel parlato si preferisce spesso una costruzione con passato prossimo e trapassato prossimo: dopo che avevamo finito, siamo usciti. Questa minore frequenza non lo rende scorretto. Quando leggi una fiaba o un racconto, riconoscilo senza interpretare ebbe come verbo autonomo di possesso. Per produrre un testo scegli il registro adatto e mantieni coerente la cornice narrativa.","examples":[{"sentence":"Dopo che ebbe salutato, il cavaliere partì.","explanation":"Il trapassato remoto è coerente con il registro narrativo e con partì."}]},{"title":"Ausiliari e confronto con il trapassato prossimo","text":"Come negli altri tempi composti, il verbo determina l’ausiliare: ebbe letto, fu arrivato, si fu preparato. Con essere il participio concorda con il soggetto: appena le ospiti furono arrivate. Con avere resta normalmente invariato, salvo accordi richiesti da pronomi oggetto anteposti: appena le ebbe viste. Il trapassato prossimo può presentare un antecedente in molti tipi di frase e con riferimenti passati diversi; il trapassato remoto ha un uso molto più ristretto. Non basta sostituire avevo con ebbi in ogni frase: bisogna controllare la costruzione temporale.","examples":[{"sentence":"Appena le ebbe viste, riconobbe le compagne.","explanation":"Viste concorda con le; il gruppo indica un fatto precedente a riconobbe."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il trapassato remoto presenta un fatto compiuto prima di un passato remoto."},{"label":"Costruisci","detail":"Unisci passato remoto dell’ausiliare e participio: ebbe cantato, fu partito."},{"label":"Confronta","detail":"Cercalo soprattutto dopo appena, dopo che e non appena."},{"label":"Controlla","detail":"È soprattutto narrativo; non sostituisce liberamente il trapassato prossimo."}]},"pitfalls":[{"mistake":"Dopo che ebbe cantò, uscì.","correction":"Dopo che ebbe cantato, uscì.","why":"Dopo l’ausiliare serve il participio, non un secondo verbo finito."},{"mistake":"Appena le ragazze furono arrivato, cominciammo.","correction":"Appena le ragazze furono arrivate, cominciammo.","why":"Con essere il participio concorda con il soggetto."}],"recap":["Il trapassato remoto presenta un fatto compiuto prima di un passato remoto.","Unisci passato remoto dell’ausiliare e participio: ebbe cantato, fu partito.","Cercalo soprattutto dopo appena, dopo che e non appena.","È soprattutto narrativo; non sostituisce liberamente il trapassato prossimo."],"review":[{"question":"Come si forma ebbero letto?","answer":"Passato remoto di avere più participio passato di leggere."},{"question":"Dove incontri più spesso questo tempo?","answer":"In subordinate temporali di racconti letterari o storici."},{"question":"Posso usare ebbi finito ovunque userei avevo finito?","answer":"No: il trapassato remoto ha un uso più ristretto, soprattutto in rapporto a un passato remoto."}],"levels":{"base":{"focus":"Il trapassato remoto presenta un fatto compiuto prima di un passato remoto.","example":{"sentence":"Dopo che ebbe cantato, uscì di scena.","explanation":"Ebbe è passato remoto di avere; ebbe cantato è trapassato remoto."}},"consolidamento":{"focus":"Unisci passato remoto dell’ausiliare e participio: ebbe cantato, fu partito. Cercalo soprattutto dopo appena, dopo che e non appena.","example":{"sentence":"Non appena ebbero finito, consegnarono il lavoro.","explanation":"La conclusione del lavoro precede la consegna."}},"avanzato":{"focus":"È soprattutto narrativo; non sostituisce liberamente il trapassato prossimo.","example":{"sentence":"Appena le ebbe viste, riconobbe le compagne.","explanation":"Viste concorda con le; il gruppo indica un fatto precedente a riconobbe."}}},"simplified":{"lead":"Il trapassato remoto indica un fatto compiuto prima di un evento al passato remoto, soprattutto in subordinate temporali della narrazione.","steps":["Il trapassato remoto presenta un fatto compiuto prima di un passato remoto.","Unisci passato remoto dell’ausiliare e participio: ebbe cantato, fu partito.","Cercalo soprattutto dopo appena, dopo che e non appena."],"example":{"sentence":"Appena ebbe chiuso il libro, il gatto ci si sedette.","explanation":"Ebbe chiuso è trapassato remoto: presenta la chiusura come conclusa prima di si sedette. Appena introduce la subordinata temporale."}},"pei":{"rule":"In appena ebbe finito, uscì, prima finisce e poi esce.","example":{"sentence":"Dopo che ebbe cantato, uscì di scena.","explanation":"Ebbe è passato remoto di avere; ebbe cantato è trapassato remoto."}},"trackExamples":{"moda":{"sentence":"Dopo che ebbe cucito l’orlo, ripose l’abito.","explanation":"La cucitura precede l’azione narrativa al remoto."},"arredo":{"sentence":"Non appena ebbero montato il mobile, lo provarono.","explanation":"Il montaggio è compiuto prima della prova."},"liuteria":{"sentence":"Dopo che ebbe accordato il violino, iniziò il concerto.","explanation":"Il trapassato remoto segna l’azione conclusa prima dell’inizio."}},"anchor":{"sentence":"Appena ebbe chiuso il libro, il gatto ci si sedette.","explanation":"Ebbe chiuso è trapassato remoto: presenta la chiusura come conclusa prima di si sedette. Appena introduce la subordinata temporale.","memory":"Appena ebbe chiuso, si sedette: due passi nel racconto."}},{"topic":"Verbi · indicativo futuro anteriore","area":"parole","lead":"Il futuro anteriore presenta un fatto che sarà già compiuto prima di un altro momento futuro; può anche esprimere una supposizione sul passato.","objectives":["Esprimere un fatto compiuto prima di un riferimento futuro.","Formare il futuro anteriore con gli accordi corretti.","Riconoscere una supposizione su un fatto precedente."],"sections":[{"title":"La costruzione del tempo composto","text":"Il futuro anteriore si forma con il futuro semplice di avere o essere e il participio passato: avrò cantato, sarò partito. La persona si legge nell’ausiliare, mentre il participio esprime l’azione. Il modello cantare usa avrò, avrai, avrà, avremo, avrete, avranno cantato. Con partire si usano sarò, sarai, sarà, saremo, sarete, saranno seguiti dal participio accordato. Le irregolarità dei due elementi rimangono: avrò fatto, avrai scritto, sarà venuto. Controlla gli accenti nelle forme dell’ausiliare avrò, avrà, sarò e sarà.","examples":[{"sentence":"Domani a quest’ora avrò finito.","explanation":"Avrò finito presenta il lavoro come già concluso da un punto futuro."},{"sentence":"Quando Sara sarà partita, chiuderemo.","explanation":"Sarà partita è futuro anteriore con essere."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","avrò cantato"],["tu","avrai cantato"],["lui / lei","avrà cantato"],["noi","avremo cantato"],["voi","avrete cantato"],["loro","avranno cantato"]]}},{"title":"Prima e dopo nel futuro","text":"Il riferimento può essere un’ora futura, una data o un altro evento al futuro. In quando avrò studiato, uscirò, lo studio deve essere compiuto prima dell’uscita. L’ordine dei verbi nella frase può essere invertito senza cambiare il rapporto: uscirò quando avrò studiato. Il futuro semplice presenta il fatto futuro; l’anteriore ne mette in evidenza il completamento rispetto a un riferimento successivo. Prima di scegliere il tempo traccia mentalmente la successione e individua quale azione dovrà risultare già conclusa.","examples":[{"sentence":"Dopo che avremo controllato, consegneremo.","explanation":"Il controllo deve precedere la consegna futura."},{"sentence":"Entro venerdì avranno terminato il progetto.","explanation":"Venerdì è il punto futuro rispetto al quale il progetto risulterà completo."}]},{"title":"Supposizioni su un fatto precedente","text":"Come il futuro semplice, anche il futuro anteriore può avere valore di supposizione. Se qualcuno non risponde, sarà uscito significa probabilmente è uscito. Il fatto ipotizzato è precedente al momento presente, benché la forma porti il nome di futuro. Il contesto permette di distinguere questo uso dalla vera anteriorità futura: quando sarà uscito, puliremo indica invece due fatti futuri in successione. Non assegnare il significato basandoti soltanto sull’etichetta del tempo; prova a sostituire probabilmente e verifica se la frase conserva il senso.","examples":[{"sentence":"Non risponde: avrà dimenticato il telefono.","explanation":"Avrà dimenticato esprime una supposizione su un fatto passato."}]},{"title":"Ausiliare, accordo e confronto","text":"Avere ed essere seguono le regole del verbo: avrò dormito, sarò arrivato, mi sarò preparato. Con essere il participio concorda con il soggetto: le compagne saranno partite. Con avere normalmente resta invariato, ma concorda con lo, la, li, le anteposti: le avrò controllate. Il passato prossimo presenta un fatto compiuto visto da ora; il futuro anteriore lo guarda da un riferimento futuro o lo formula come supposizione. Il condizionale passato, come avrei finito, esprime invece altri rapporti: una possibilità non realizzata o un futuro visto dal passato.","examples":[{"sentence":"Le tavole? Quando le avremo misurate, sceglieremo il taglio.","explanation":"Misurate concorda con il pronome le e precede la scelta futura."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il futuro anteriore presenta un fatto già compiuto rispetto a un riferimento futuro."},{"label":"Costruisci","detail":"Usa futuro dell’ausiliare e participio: avrò finito, sarò partito."},{"label":"Confronta","detail":"Può esprimere una supposizione sul passato: sarà uscito."},{"label":"Controlla","detail":"Controlla ausiliare, accordo e rapporto con il futuro semplice."}]},"pitfalls":[{"mistake":"Quando avrò finire, uscirò.","correction":"Quando avrò finito, uscirò.","why":"Dopo l’ausiliare serve il participio finito, non l’infinito finire."},{"mistake":"Le ragazze saranno arrivato.","correction":"Le ragazze saranno arrivate.","why":"Con essere il participio concorda con il soggetto."}],"recap":["Il futuro anteriore presenta un fatto già compiuto rispetto a un riferimento futuro.","Usa futuro dell’ausiliare e participio: avrò finito, sarò partito.","Può esprimere una supposizione sul passato: sarà uscito.","Controlla ausiliare, accordo e rapporto con il futuro semplice."],"review":[{"question":"Quale azione viene prima in quando avrò letto, risponderò?","answer":"La lettura, espressa dal futuro anteriore."},{"question":"In avrà perso il treno il fatto è sempre futuro?","answer":"No: può essere una supposizione su un fatto già accaduto."},{"question":"Come si forma saremo arrivati?","answer":"Futuro semplice di essere più participio passato accordato al soggetto."}],"levels":{"base":{"focus":"Il futuro anteriore presenta un fatto già compiuto rispetto a un riferimento futuro.","example":{"sentence":"Domani a quest’ora avrò finito.","explanation":"Avrò finito presenta il lavoro come già concluso da un punto futuro."}},"consolidamento":{"focus":"Usa futuro dell’ausiliare e participio: avrò finito, sarò partito. Può esprimere una supposizione sul passato: sarà uscito.","example":{"sentence":"Dopo che avremo controllato, consegneremo.","explanation":"Il controllo deve precedere la consegna futura."}},"avanzato":{"focus":"Controlla ausiliare, accordo e rapporto con il futuro semplice.","example":{"sentence":"Le tavole? Quando le avremo misurate, sceglieremo il taglio.","explanation":"Misurate concorda con il pronome le e precede la scelta futura."}}},"simplified":{"lead":"Il futuro anteriore presenta un fatto che sarà già compiuto prima di un altro momento futuro; può anche esprimere una supposizione sul passato.","steps":["Il futuro anteriore presenta un fatto già compiuto rispetto a un riferimento futuro.","Usa futuro dell’ausiliare e participio: avrò finito, sarò partito.","Può esprimere una supposizione sul passato: sarà uscito."],"example":{"sentence":"Quando avrò finito, il mio zaino andrà in vacanza.","explanation":"Avrò finito è futuro anteriore: il lavoro sarà completo prima del momento futuro espresso da andrà."}},"pei":{"rule":"In avrò finito, uscirò, prima finisco e poi esco.","example":{"sentence":"Domani a quest’ora avrò finito.","explanation":"Avrò finito presenta il lavoro come già concluso da un punto futuro."}},"trackExamples":{"moda":{"sentence":"Quando avremo tagliato la fodera, la cuciremo.","explanation":"Il taglio è anteriore alla cucitura futura."},"arredo":{"sentence":"Entro domani avranno montato lo scaffale.","explanation":"Il montaggio sarà compiuto entro un riferimento futuro."},"liuteria":{"sentence":"Non c’è più il rumore: il liutaio avrà finito di levigare.","explanation":"Avrà finito esprime una supposizione su un fatto precedente."}},"anchor":{"sentence":"Quando avrò finito, il mio zaino andrà in vacanza.","explanation":"Avrò finito è futuro anteriore: il lavoro sarà completo prima del momento futuro espresso da andrà.","memory":"Prima avrò finito; poi andrà."}},{"topic":"Verbi · congiuntivo passato","area":"parole","lead":"Il congiuntivo passato presenta un fatto anteriore rispetto a una reggente presente che richiede il congiuntivo.","objectives":["Formare il congiuntivo passato con abbia o sia.","Esprimere anteriorità rispetto a una reggente presente.","Distinguerlo dall’indicativo passato prossimo."],"sections":[{"title":"Presente del congiuntivo e participio","text":"Il congiuntivo passato è composto dal congiuntivo presente di avere o essere e dal participio passato: abbia cantato, sia partito. Per cantare il paradigma è abbia, abbia, abbia, abbiamo, abbiate, abbiano cantato. Le tre persone singolari condividono la forma, quindi il soggetto e il contesto sono utili per distinguerle. Per partire si usa sia, sia, sia, siamo, siate, siano con il participio accordato. Anche i participi irregolari mantengono la loro forma: abbia scritto, abbia detto, sia venuto. Che può introdurre la frase, ma non appartiene al verbo.","examples":[{"sentence":"Credo che Luca abbia cantato ieri.","explanation":"Abbia cantato è congiuntivo passato, terza persona singolare."},{"sentence":"Spero che siate arrivati bene.","explanation":"Siate arrivati è seconda persona plurale con essere."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","abbia cantato"],["tu","abbia cantato"],["lui / lei","abbia cantato"],["noi","abbiamo cantato"],["voi","abbiate cantato"],["loro","abbiano cantato"]]}},{"title":"Anteriorità rispetto al presente","text":"In penso che abbia studiato, il pensiero appartiene al presente e lo studio è precedente. Il congiuntivo dipende dalla costruzione penso che; il passato esprime il rapporto temporale. Questo tempo compare anche dopo espressioni come temo che, è possibile che, sono contento che e benché. Il contenuto può essere incerto oppure noto: sono contento che tu abbia superato la prova presenta un risultato già conosciuto. Per scegliere il modo considera la reggente o la congiunzione; per scegliere il tempo considera l’ordine dei fatti.","examples":[{"sentence":"Sono contenta che tu abbia superato la prova.","explanation":"Il superamento è precedente alla contentezza attuale."},{"sentence":"Benché abbia studiato, chiede un chiarimento.","explanation":"Il congiuntivo è richiesto da benché anche se lo studio è un fatto noto."}]},{"title":"Differenza dal presente e dal trapassato","text":"Credo che studi descrive uno studio contemporaneo al pensiero presente, oppure abituale. Credo che abbia studiato colloca lo studio prima del pensiero. Se la reggente diventa passata, per l’anteriorità si usa normalmente il congiuntivo trapassato: credevo che avesse studiato. Non basta individuare l’avverbio ieri: devi capire da quale momento il fatto viene osservato. Dopo un’espressione futura il congiuntivo passato può indicare un fatto già completato rispetto a quel riferimento, come sarà importante che abbiate finito entro venerdì.","examples":[{"sentence":"Credo che legga ora; credo che abbia letto ieri.","explanation":"Il presente indica contemporaneità; il passato indica anteriorità."}]},{"title":"Ausiliari, accordi e forma completa","text":"La scelta dell’ausiliare segue il verbo: abbia dormito, sia partito, si sia lavato. Con essere il participio concorda con il soggetto: spero che le ragazze siano arrivate. Con avere il soggetto non impone l’accordo: credo che Sara abbia lavorato. Con i pronomi oggetto lo, la, li, le anteposti l’accordo è necessario: penso che le abbia viste. Non confondere abbia cantato con ha cantato: il secondo è indicativo passato prossimo. Entrambi presentano anteriorità rispetto a ora, ma appartengono a costruzioni e modi diversi.","examples":[{"sentence":"Credo che le abbia viste; so che le ha viste.","explanation":"Il primo verbo è congiuntivo passato; il secondo è passato prossimo indicativo."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il congiuntivo passato presenta un fatto anteriore rispetto a una reggente presente."},{"label":"Costruisci","detail":"Unisci abbia o sia nelle varie persone al participio passato."},{"label":"Confronta","detail":"Controlla la costruzione che richiede il congiuntivo e l’ordine dei fatti."},{"label":"Controlla","detail":"Con essere accorda al soggetto; distingui abbia letto da ha letto."}]},"pitfalls":[{"mistake":"Credo che lui ha finito.","correction":"Credo che lui abbia finito.","why":"Nello scritto sorvegliato credere che richiede normalmente il congiuntivo."},{"mistake":"Spero che le compagne siano arrivato.","correction":"Spero che le compagne siano arrivate.","why":"Il participio con essere concorda al femminile plurale."}],"recap":["Il congiuntivo passato presenta un fatto anteriore rispetto a una reggente presente.","Unisci abbia o sia nelle varie persone al participio passato.","Controlla la costruzione che richiede il congiuntivo e l’ordine dei fatti.","Con essere accorda al soggetto; distingui abbia letto da ha letto."],"review":[{"question":"Quale tempo è abbia letto?","answer":"Congiuntivo passato."},{"question":"Che differenza c’è tra penso che studi e penso che abbia studiato?","answer":"Il primo mostra contemporaneità o abitudine; il secondo anteriorità."},{"question":"Il congiuntivo passato esprime sempre incertezza?","answer":"No: può dipendere da una costruzione che lo richiede anche per fatti noti."}],"levels":{"base":{"focus":"Il congiuntivo passato presenta un fatto anteriore rispetto a una reggente presente.","example":{"sentence":"Credo che Luca abbia cantato ieri.","explanation":"Abbia cantato è congiuntivo passato, terza persona singolare."}},"consolidamento":{"focus":"Unisci abbia o sia nelle varie persone al participio passato. Controlla la costruzione che richiede il congiuntivo e l’ordine dei fatti.","example":{"sentence":"Sono contenta che tu abbia superato la prova.","explanation":"Il superamento è precedente alla contentezza attuale."}},"avanzato":{"focus":"Con essere accorda al soggetto; distingui abbia letto da ha letto.","example":{"sentence":"Credo che le abbia viste; so che le ha viste.","explanation":"Il primo verbo è congiuntivo passato; il secondo è passato prossimo indicativo."}}},"simplified":{"lead":"Il congiuntivo passato presenta un fatto anteriore rispetto a una reggente presente che richiede il congiuntivo.","steps":["Il congiuntivo passato presenta un fatto anteriore rispetto a una reggente presente.","Unisci abbia o sia nelle varie persone al participio passato.","Controlla la costruzione che richiede il congiuntivo e l’ordine dei fatti."],"example":{"sentence":"Credo che il gatto abbia nascosto la penna.","explanation":"Abbia nascosto è congiuntivo passato: l’azione sospettata è precedente al pensiero espresso adesso da credo."}},"pei":{"rule":"Credo adesso; abbia finito indica un fatto precedente.","example":{"sentence":"Credo che Luca abbia cantato ieri.","explanation":"Abbia cantato è congiuntivo passato, terza persona singolare."}},"trackExamples":{"moda":{"sentence":"Credo che abbiano consegnato il cartamodello.","explanation":"La consegna precede l’opinione attuale."},"arredo":{"sentence":"È possibile che il falegname abbia finito il montaggio.","explanation":"Abbia finito indica un fatto precedente possibile."},"liuteria":{"sentence":"Sono contento che il violino sia arrivato integro.","explanation":"Sia arrivato presenta un arrivo già avvenuto."}},"anchor":{"sentence":"Credo che il gatto abbia nascosto la penna.","explanation":"Abbia nascosto è congiuntivo passato: l’azione sospettata è precedente al pensiero espresso adesso da credo.","memory":"Credo adesso; abbia nascosto prima."}},{"topic":"Verbi · congiuntivo trapassato","area":"parole","lead":"Il congiuntivo trapassato esprime anteriorità rispetto a un passato e compare nelle ipotesi non realizzate del passato.","objectives":["Formare il congiuntivo trapassato con avessi o fossi.","Esprimere anteriorità rispetto a una reggente passata.","Costruire la condizione di un’ipotesi irreale passata."],"sections":[{"title":"La struttura del tempo composto","text":"Il congiuntivo trapassato si forma con il congiuntivo imperfetto di avere o essere seguito dal participio passato: avessi cantato, fossi partito. Cantare presenta avessi, avessi, avesse, avessimo, aveste, avessero cantato. Con essere le forme sono fossi, fossi, fosse, fossimo, foste, fossero e il participio concorda con il soggetto. La prima e la seconda persona singolare coincidono: un soggetto espresso può eliminare il dubbio. I participi irregolari restano tali: avesse fatto, avessero scritto, fosse venuto. L’intero gruppo costituisce un’unica forma verbale composta.","examples":[{"sentence":"Pensavo che tu avessi cantato.","explanation":"Avessi cantato è seconda persona singolare del congiuntivo trapassato."},{"sentence":"Credevo che Marta fosse partita.","explanation":"Fosse partita indica un fatto precedente al pensiero passato."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","avessi cantato"],["tu","avessi cantato"],["lui / lei","avesse cantato"],["noi","avessimo cantato"],["voi","aveste cantato"],["loro","avessero cantato"]]}},{"title":"Il passato prima di un altro passato","text":"Dopo una reggente passata che richiede il congiuntivo, il trapassato presenta un fatto anteriore: speravo che avessi capito. La speranza è passata e la comprensione è collocata prima. Con il congiuntivo imperfetto si esprimerebbe invece una situazione contemporanea o successiva, secondo il significato: speravo che capissi durante la spiegazione. Ricostruisci il rapporto fra gli eventi prima di scegliere il tempo. Nelle subordinate introdotte da benché, come se e altre congiunzioni, la stessa forma mantiene il valore di fatto anteriore rispetto al riferimento.","examples":[{"sentence":"Il docente temeva che avessimo perso gli appunti.","explanation":"La perdita precede il timore espresso nel passato."},{"sentence":"Parlava come se avesse visto tutto.","explanation":"La visione è presentata come precedente al parlare."}]},{"title":"L’ipotesi non realizzata nel passato","text":"Nel periodo ipotetico dell’irrealtà passata si usa il congiuntivo trapassato nella condizione e il condizionale passato nella conseguenza: se avessi studiato, avresti capito. Chi parla considera lo studio non avvenuto e immagina il risultato alternativo. La conseguenza può anche riguardare il presente: se avessi dormito, ora sarei riposato. Il rapporto temporale decide quindi se usare il condizionale passato o presente. Evita il doppio condizionale se avrei studiato, avrei capito: nella condizione introdotta da se serve qui il congiuntivo.","examples":[{"sentence":"Se avessimo preso l’autobus, saremmo arrivati prima.","explanation":"La condizione passata non realizzata usa il trapassato del congiuntivo."}]},{"title":"Accordi e confronto con forme simili","text":"L’ausiliare dipende dal verbo: avessi dormito, fossi arrivato, mi fossi preparato. Con essere il participio concorda con il soggetto: pensavo che le allieve fossero uscite. Con avere resta normalmente invariato, salvo accordi con pronomi oggetto anteposti come le avessi incontrate. Distingui avesse letto da aveva letto: il primo è congiuntivo trapassato, il secondo indicativo trapassato prossimo. Entrambi esprimono anteriorità nel passato, ma la costruzione richiede un modo diverso: pensavo che avesse letto, sapevo che aveva letto. L’analisi deve indicare modo e tempo insieme.","examples":[{"sentence":"Sapevo che aveva letto; pensavo che avesse letto.","explanation":"I due trapassati esprimono anteriorità con modi diversi, secondo la reggente."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il congiuntivo trapassato indica un fatto precedente a un riferimento passato."},{"label":"Costruisci","detail":"Unisci congiuntivo imperfetto dell’ausiliare e participio."},{"label":"Confronta","detail":"Nell’ipotesi passata usa se avessi studiato, avrei capito."},{"label":"Controlla","detail":"Distingui avesse letto, congiuntivo, da aveva letto, indicativo."}]},"pitfalls":[{"mistake":"Se avrei ascoltato, avrei capito.","correction":"Se avessi ascoltato, avrei capito.","why":"La condizione irreale passata richiede il congiuntivo trapassato."},{"mistake":"Credevo che le ragazze fossero partito.","correction":"Credevo che le ragazze fossero partite.","why":"Il participio con essere concorda al femminile plurale."}],"recap":["Il congiuntivo trapassato indica un fatto precedente a un riferimento passato.","Unisci congiuntivo imperfetto dell’ausiliare e participio.","Nell’ipotesi passata usa se avessi studiato, avrei capito.","Distingui avesse letto, congiuntivo, da aveva letto, indicativo."],"review":[{"question":"Come si forma avessimo capito?","answer":"Congiuntivo imperfetto di avere più participio passato."},{"question":"Quale tempo esprime anteriorità in pensavo che avesse finito?","answer":"Il congiuntivo trapassato avesse finito."},{"question":"Quale conseguenza può seguire se avessi dormito?","answer":"Una conseguenza passata, sarei stato riposato, oppure presente, ora sarei riposato, secondo il significato."}],"levels":{"base":{"focus":"Il congiuntivo trapassato indica un fatto precedente a un riferimento passato.","example":{"sentence":"Pensavo che tu avessi cantato.","explanation":"Avessi cantato è seconda persona singolare del congiuntivo trapassato."}},"consolidamento":{"focus":"Unisci congiuntivo imperfetto dell’ausiliare e participio. Nell’ipotesi passata usa se avessi studiato, avrei capito.","example":{"sentence":"Il docente temeva che avessimo perso gli appunti.","explanation":"La perdita precede il timore espresso nel passato."}},"avanzato":{"focus":"Distingui avesse letto, congiuntivo, da aveva letto, indicativo.","example":{"sentence":"Sapevo che aveva letto; pensavo che avesse letto.","explanation":"I due trapassati esprimono anteriorità con modi diversi, secondo la reggente."}}},"simplified":{"lead":"Il congiuntivo trapassato esprime anteriorità rispetto a un passato e compare nelle ipotesi non realizzate del passato.","steps":["Il congiuntivo trapassato indica un fatto precedente a un riferimento passato.","Unisci congiuntivo imperfetto dell’ausiliare e participio.","Nell’ipotesi passata usa se avessi studiato, avrei capito."],"example":{"sentence":"Se avessi messo la sveglia, avrei preso il bus.","explanation":"Avessi messo è congiuntivo trapassato e introduce una condizione passata non realizzata. La conseguenza immaginata è avrei preso."}},"pei":{"rule":"Per un’ipotesi nel passato scrivi se avessi studiato.","example":{"sentence":"Pensavo che tu avessi cantato.","explanation":"Avessi cantato è seconda persona singolare del congiuntivo trapassato."}},"trackExamples":{"moda":{"sentence":"Credevo che avessi già tagliato il tessuto.","explanation":"Il taglio precede il pensiero passato."},"arredo":{"sentence":"Se avessimo misurato meglio, il mobile sarebbe entrato.","explanation":"Il trapassato formula una condizione passata non realizzata."},"liuteria":{"sentence":"Il maestro temeva che la corda si fosse spezzata.","explanation":"La rottura ipotizzata precede il timore passato."}},"anchor":{"sentence":"Se avessi messo la sveglia, avrei preso il bus.","explanation":"Avessi messo è congiuntivo trapassato e introduce una condizione passata non realizzata. La conseguenza immaginata è avrei preso.","memory":"Se avessi prima, avrei dopo: entrambi nel passato."}},{"topic":"Verbi · condizionale passato","area":"parole","lead":"Il condizionale passato presenta una possibilità non realizzata nel passato oppure un fatto futuro visto da un momento passato.","objectives":["Formare il condizionale passato con ausiliare e participio.","Esprimere conseguenze passate non realizzate.","Riconoscere il futuro visto dal passato."],"sections":[{"title":"Condizionale presente e participio","text":"Il condizionale passato è composto dal condizionale presente di avere o essere e dal participio passato. Cantare dà avrei cantato, avresti cantato, avrebbe cantato, avremmo cantato, avreste cantato, avrebbero cantato. Partire usa sarei, saresti, sarebbe, saremmo, sareste, sarebbero e il participio accordato: Sara sarebbe partita, i ragazzi sarebbero partiti. Il modo e la persona sono espressi dall’ausiliare; il participio mantiene eventuali irregolarità: avrei fatto, avremmo scritto, sarebbe venuto. Leggi il gruppo completo per non attribuire al verbo composto il tempo presente dell’ausiliare.","examples":[{"sentence":"Avrei cantato volentieri.","explanation":"Avrei cantato è condizionale passato, prima persona singolare."},{"sentence":"Le compagne sarebbero partite con noi.","explanation":"Sarebbero partite usa essere e concorda al femminile plurale."}],"table":{"headers":["Persona","Forma del modello"],"rows":[["io","avrei cantato"],["tu","avresti cantato"],["lui / lei","avrebbe cantato"],["noi","avremmo cantato"],["voi","avreste cantato"],["loro","avrebbero cantato"]]}},{"title":"Conseguenza non realizzata","text":"Nel periodo ipotetico dell’irrealtà passata il condizionale passato esprime la conseguenza di una condizione non avvenuta: se avessi studiato, avrei capito. Può comparire anche con una condizione implicita: con più tempo avrei finito significa se avessi avuto più tempo. È adatto a desideri, rimpianti e intenzioni rimaste senza risultato: avrei voluto partecipare. Per capire il valore non basta osservare l’ausiliare: cerca il fatto mancato e la condizione, espressa oppure ricavabile dal contesto della conversazione.","examples":[{"sentence":"Se avessimo prenotato, avremmo trovato posto.","explanation":"Avremmo trovato è la conseguenza immaginata nel passato."},{"sentence":"Avrei voluto assistere al concerto.","explanation":"Il condizionale passato esprime un desiderio non realizzato."}]},{"title":"Il futuro visto dal passato","text":"Il condizionale passato può esprimere posteriorità rispetto a un riferimento passato: ieri Luca disse che sarebbe arrivato oggi. L’arrivo era futuro rispetto al momento in cui Luca parlò. Questo uso non dice, da solo, se il fatto si è poi realizzato: il contesto può aggiungere ed è arrivato oppure ma non è venuto. Nella trasformazione dal discorso diretto al discorso indiretto al passato, verrò diventa spesso sarebbe venuto. Il nome passato riguarda la prospettiva grammaticale e non obbliga l’azione dipendente a precedere la reggente.","examples":[{"sentence":"Ieri Anna annunciò che sarebbe partita domani.","explanation":"La partenza è successiva all’annuncio, anche se può essere ancora futura per chi parla."}]},{"title":"Accordi e confronto con il presente","text":"Gli ausiliari seguono il verbo: avrei dormito, sarei arrivato, mi sarei preparato. Con essere il participio concorda al soggetto; con avere normalmente resta invariato, ma si accorda con lo, la, li, le anteposti: le avrei chiamate. Il condizionale presente esprime una disponibilità o conseguenza attuale: verrei ora se potessi. Il passato può indicare una disponibilità mancata: sarei venuto ieri se avessi potuto. Per scegliere fra le due forme controlla quando avviene la conseguenza. Anche nel linguaggio giornalistico avrebbe dichiarato può segnalare una notizia passata non confermata direttamente.","examples":[{"sentence":"Le avrei chiamate ieri, ma non avevo il numero.","explanation":"Chiamate concorda con le; la chiamata è rimasta non realizzata."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il condizionale passato può esprimere una conseguenza passata non realizzata."},{"label":"Costruisci","detail":"Unisci condizionale presente dell’ausiliare e participio passato."},{"label":"Confronta","detail":"Esprime anche il futuro nel passato: disse che sarebbe tornato."},{"label":"Controlla","detail":"Controlla il contesto: sarebbe tornato non significa sempre che non tornò."}]},"pitfalls":[{"mistake":"Se avrei saputo, sarei venuto.","correction":"Se avessi saputo, sarei venuto.","why":"La condizione richiede il congiuntivo trapassato."},{"mistake":"Disse che verrà il giorno dopo.","correction":"Disse che sarebbe venuto il giorno dopo.","why":"Il condizionale passato esprime normalmente la posteriorità rispetto a una reggente passata."}],"recap":["Il condizionale passato può esprimere una conseguenza passata non realizzata.","Unisci condizionale presente dell’ausiliare e participio passato.","Esprime anche il futuro nel passato: disse che sarebbe tornato.","Controlla il contesto: sarebbe tornato non significa sempre che non tornò."],"review":[{"question":"Come si forma avrebbero letto?","answer":"Condizionale presente di avere più participio passato."},{"question":"Sarebbe venuto significa sempre che non è venuto?","answer":"No: può essere semplicemente il futuro visto dal passato."},{"question":"Quando usi sarei partita invece di partirei?","answer":"Per una possibilità passata non realizzata o per un futuro visto dal passato; partirei riguarda normalmente una possibilità presente o futura."}],"levels":{"base":{"focus":"Il condizionale passato può esprimere una conseguenza passata non realizzata.","example":{"sentence":"Avrei cantato volentieri.","explanation":"Avrei cantato è condizionale passato, prima persona singolare."}},"consolidamento":{"focus":"Unisci condizionale presente dell’ausiliare e participio passato. Esprime anche il futuro nel passato: disse che sarebbe tornato.","example":{"sentence":"Se avessimo prenotato, avremmo trovato posto.","explanation":"Avremmo trovato è la conseguenza immaginata nel passato."}},"avanzato":{"focus":"Controlla il contesto: sarebbe tornato non significa sempre che non tornò.","example":{"sentence":"Le avrei chiamate ieri, ma non avevo il numero.","explanation":"Chiamate concorda con le; la chiamata è rimasta non realizzata."}}},"simplified":{"lead":"Il condizionale passato presenta una possibilità non realizzata nel passato oppure un fatto futuro visto da un momento passato.","steps":["Il condizionale passato può esprimere una conseguenza passata non realizzata.","Unisci condizionale presente dell’ausiliare e participio passato.","Esprime anche il futuro nel passato: disse che sarebbe tornato."],"example":{"sentence":"Avevo promesso che avrei portato la merenda.","explanation":"Avrei portato è condizionale passato: la consegna della merenda era futura rispetto alla promessa. La frase non dice se l’ho poi portata."}},"pei":{"rule":"Avrei partecipato può raccontare qualcosa che volevo fare e non ho fatto.","example":{"sentence":"Avrei cantato volentieri.","explanation":"Avrei cantato è condizionale passato, prima persona singolare."}},"trackExamples":{"moda":{"sentence":"Avrei scelto un tessuto diverso, se lo avessi trovato.","explanation":"La scelta alternativa non si è realizzata."},"arredo":{"sentence":"Il falegname disse che avrebbe montato la libreria.","explanation":"Il montaggio è futuro rispetto alla dichiarazione passata."},"liuteria":{"sentence":"Sarei venuto alla prova se avessi avuto tempo.","explanation":"La partecipazione immaginata dipende da una condizione passata mancata."}},"anchor":{"sentence":"Avevo promesso che avrei portato la merenda.","explanation":"Avrei portato è condizionale passato: la consegna della merenda era futura rispetto alla promessa. La frase non dice se l’ho poi portata.","memory":"Dalla promessa guardo avanti: avrei portato."}},{"topic":"Verbi · infinito presente","area":"parole","lead":"L’infinito presente nomina un’azione senza indicare da solo chi la compie: cantare, leggere, dormire.","objectives":["Riconoscere l’infinito come forma senza persona e numero.","Usarlo dopo servili, verbi e preposizioni.","Distinguerlo dall’infinito passato e unirlo ai pronomi."],"sections":[{"title":"Forma e coniugazione","text":"L’infinito è un modo indefinito: non esprime direttamente persona e numero. La forma presente è semplice e coincide con quella con cui il verbo è registrato nel dizionario. Le terminazioni -are, -ere e -ire permettono di riconoscere le tre coniugazioni: cantare, temere, dormire. Essere e avere sono irregolari; fare e dire appartengono tradizionalmente alla seconda coniugazione per la loro origine. Non cercare sei persone dell’infinito: la stessa forma può riferirsi a soggetti diversi, che si ricavano dalla frase.","examples":[{"sentence":"Voglio cantare.","explanation":"Cantare nomina l’azione; la persona si ricava da voglio."},{"sentence":"Vogliamo cantare.","explanation":"L’infinito resta identico anche se il soggetto passa da io a noi."}]},{"title":"Dopo servili, verbi e preposizioni","text":"L’infinito segue i verbi servili: posso entrare, devo studiare, voglio provare. Compare anche dopo altri verbi e dopo preposizioni richieste dalla costruzione: inizio a lavorare, smetto di parlare, esco per camminare. La preposizione non si sceglie a caso; dipende dal verbo reggente o dal rapporto di significato. In una subordinata implicita il soggetto dell’infinito coincide spesso con quello della reggente: studio per imparare. Esistono costruzioni diverse, come vedo Luca correre, in cui è Luca a compiere l’azione dell’infinito.","examples":[{"sentence":"Devo finire gli esercizi.","explanation":"Il servile devo porta persona e tempo; finire esprime l’azione."},{"sentence":"Studio per capire meglio.","explanation":"Il soggetto sottinteso di capire è lo stesso di studio: io."}]},{"title":"Usi autonomi e infinito sostantivato","text":"L’infinito può avere valore di nome: leggere è utile, il viaggiare insegna. Può essere accompagnato da un articolo e svolgere la funzione di soggetto o di un altro elemento nominale, mantenendo parte delle proprietà verbali. Nelle istruzioni è frequente l’infinito con valore di comando generale: agitare prima dell’uso. Il divieto rivolto a tu si costruisce con non e infinito: non correre. Questi impieghi non trasformano l’infinito in una forma personale: la funzione comunicativa di ordine dipende dalla costruzione e dal contesto.","examples":[{"sentence":"Non toccare il vetro.","explanation":"L’infinito presente esprime un divieto rivolto a tu."}]},{"title":"Tempo relativo, forma passata e pronomi","text":"Il nome presente non impone che l’azione avvenga proprio ora: prometto di partire domani riguarda il futuro. Il tempo dell’infinito è relativo alla reggente e al contesto. L’infinito passato esprime invece anteriorità compiuta: sono felice di avere cantato. Confronta cantare e avere cantato senza confondere le due forme. I pronomi si uniscono all’infinito dopo la caduta della e finale: cantarlo, leggerlo, prepararsi. Anche l’ausiliare può perdere la e: aver cantato, esser partito sono varianti ammesse, specialmente nello scritto.","examples":[{"sentence":"Prometto di leggere; sono felice di avere letto.","explanation":"Leggere indica un’azione da svolgere; avere letto un’azione già compiuta."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"L’infinito presente nomina l’azione senza indicare persona e numero."},{"label":"Costruisci","detail":"Riconosci -are, -ere e -ire: cantare, temere, dormire."},{"label":"Confronta","detail":"Usalo dopo servili e nelle costruzioni richieste, come iniziare a leggere."},{"label":"Controlla","detail":"Distingui cantare da avere cantato; con i pronomi scrivi cantarlo e prepararsi."}]},"pitfalls":[{"mistake":"Devo studio.","correction":"Devo studiare.","why":"Il verbo dipendente da devo va all’infinito."},{"mistake":"Prometto di leggere domani è scorretto perché leggere è presente.","correction":"Prometto di leggere domani è corretto.","why":"L’infinito presente può riferirsi a un momento futuro rispetto alla reggente."}],"recap":["L’infinito presente nomina l’azione senza indicare persona e numero.","Riconosci -are, -ere e -ire: cantare, temere, dormire.","Usalo dopo servili e nelle costruzioni richieste, come iniziare a leggere.","Distingui cantare da avere cantato; con i pronomi scrivi cantarlo e prepararsi."],"review":[{"question":"Perché l’infinito è indefinito?","answer":"Perché non esprime da solo persona e numero."},{"question":"Che differenza c’è tra cantare e avere cantato?","answer":"Cantare è infinito presente; avere cantato è infinito passato e indica anteriorità."},{"question":"Come unisci leggere e lo?","answer":"Leggerlo: cade la e finale e il pronome si unisce al verbo."}],"levels":{"base":{"focus":"L’infinito presente nomina l’azione senza indicare persona e numero.","example":{"sentence":"Voglio cantare.","explanation":"Cantare nomina l’azione; la persona si ricava da voglio."}},"consolidamento":{"focus":"Riconosci -are, -ere e -ire: cantare, temere, dormire. Usalo dopo servili e nelle costruzioni richieste, come iniziare a leggere.","example":{"sentence":"Devo finire gli esercizi.","explanation":"Il servile devo porta persona e tempo; finire esprime l’azione."}},"avanzato":{"focus":"Distingui cantare da avere cantato; con i pronomi scrivi cantarlo e prepararsi.","example":{"sentence":"Prometto di leggere; sono felice di avere letto.","explanation":"Leggere indica un’azione da svolgere; avere letto un’azione già compiuta."}}},"simplified":{"lead":"L’infinito presente nomina un’azione senza indicare da solo chi la compie: cantare, leggere, dormire.","steps":["L’infinito presente nomina l’azione senza indicare persona e numero.","Riconosci -are, -ere e -ire: cantare, temere, dormire.","Usalo dopo servili e nelle costruzioni richieste, come iniziare a leggere."],"example":{"sentence":"Dormire è facile; svegliarsi richiede più impegno.","explanation":"Dormire e svegliarsi sono infiniti presenti: nominano azioni senza indicare da soli persona e numero."}},"pei":{"rule":"L’infinito nomina l’azione: cantare, leggere, dormire.","example":{"sentence":"Voglio cantare.","explanation":"Cantare nomina l’azione; la persona si ricava da voglio."}},"trackExamples":{"moda":{"sentence":"Voglio imparare a cucire.","explanation":"Imparare e cucire sono infiniti presenti."},"arredo":{"sentence":"Levigare prima di verniciare.","explanation":"Gli infiniti danno istruzioni generali."},"liuteria":{"sentence":"Accordare richiede ascolto e pazienza.","explanation":"Accordare è infinito con funzione di soggetto."}},"anchor":{"sentence":"Dormire è facile; svegliarsi richiede più impegno.","explanation":"Dormire e svegliarsi sono infiniti presenti: nominano azioni senza indicare da soli persona e numero.","memory":"Nel dizionario trovi dormire, non io dormire."}},{"topic":"Verbi · infinito passato","area":"parole","lead":"L’infinito passato presenta un’azione già compiuta rispetto al fatto espresso dalla reggente: avere cantato, essere partito.","objectives":["Formare avere cantato ed essere partito.","Esprimere un fatto anteriore alla reggente.","Controllare soggetto e concordanza nelle frasi implicite."],"sections":[{"title":"Due parole, un’unica forma verbale","text":"L’infinito passato si forma con l’infinito presente di avere o essere più il participio passato: avere cantato, avere letto, essere partito. L’infinito è un modo indefinito: non presenta sei forme personali e il soggetto va ricavato dalla frase. Il participio può però variare quando è richiesta la concordanza: essere partita, essere partiti, essere partite. Sono ammesse anche le forme con caduta della e dell’ausiliare: aver cantato, esser partito. Il presente cantare e il passato avere cantato sono due tempi distinti dello stesso modo.","examples":[{"sentence":"Sono contento di avere cantato.","explanation":"Avere cantato è infinito passato: il canto precede la contentezza."},{"sentence":"Dopo essere partite, le ragazze hanno telefonato.","explanation":"Essere partite è infinito passato con participio femminile plurale."}]},{"title":"Il rapporto di anteriorità","text":"L’infinito passato esprime un fatto anteriore al verbo principale, indipendentemente dal tempo della reggente. In sono felice di aver partecipato la partecipazione precede uno stato presente; in ero felice di aver partecipato precede uno stato passato. Il riferimento può essere anche futuro: domani sarò felice di aver finito. Non confondere quindi il nome passato con una data fissa rispetto a oggi. Per scegliere questa forma, chiediti se l’azione dell’infinito deve risultare già conclusa nel momento in cui vale l’affermazione principale.","examples":[{"sentence":"Ero sicuro di avere chiuso la porta.","explanation":"La chiusura precede la sicurezza espressa nel passato."},{"sentence":"Domani sarò contenta di avere finito.","explanation":"Il completamento sarà precedente alla contentezza futura."}]},{"title":"Ausiliare e concordanza","text":"La scelta dell’ausiliare segue le regole del verbo: avere dormito, essere arrivato, essersi lavato. Con essere il participio concorda con il soggetto: Anna è felice di essere arrivata; i compagni ricordano di essere partiti presto. Con avere resta normalmente al maschile singolare: Anna pensa di avere studiato. Se un pronome oggetto lo, la, li, le precede il participio dentro la forma verbale, l’accordo è richiesto: le chiavi, ricordo di averle viste. La posizione del pronome dopo l’ausiliare non elimina questo rapporto.","examples":[{"sentence":"Le stoffe? Ricordo di averle viste qui.","explanation":"Le precede il participio viste e ne richiede l’accordo."}]},{"title":"Preposizioni e soggetto della subordinata","text":"L’infinito passato compare dopo verbi e preposizioni che ammettono una frase implicita: penso di avere capito, mi scuso per avere tardato, dopo avere letto rispondo. Dopo richiede normalmente la forma passata quando l’azione è compiuta; prima di introduce invece l’infinito presente: prima di partire. Nelle costruzioni più comuni il soggetto della subordinata coincide con quello della reggente. Se i soggetti sono diversi, rendili espliciti con una forma personale: dopo che Luca è partito, Anna ha telefonato. Questa scelta evita di attribuire la partenza ad Anna.","examples":[{"sentence":"Dopo avere letto, Giulia risponde.","explanation":"Giulia compie entrambe le azioni; la lettura precede la risposta."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"L’infinito passato indica un’azione già compiuta rispetto alla reggente."},{"label":"Costruisci","detail":"Unisci avere o essere all’infinito e il participio: avere cantato, essere partito."},{"label":"Confronta","detail":"Con essere concorda con il soggetto: essere arrivata, essere arrivati."},{"label":"Controlla","detail":"Controlla soggetto e anteriorità: dopo aver letto, ma prima di leggere."}]},"pitfalls":[{"mistake":"Dopo avere leggo, rispondo.","correction":"Dopo avere letto, rispondo.","why":"La forma composta richiede il participio passato."},{"mistake":"Anna è contenta di essere arrivato.","correction":"Anna è contenta di essere arrivata.","why":"Con essere il participio concorda con il soggetto Anna."}],"recap":["L’infinito passato indica un’azione già compiuta rispetto alla reggente.","Unisci avere o essere all’infinito e il participio: avere cantato, essere partito.","Con essere concorda con il soggetto: essere arrivata, essere arrivati.","Controlla soggetto e anteriorità: dopo aver letto, ma prima di leggere."],"review":[{"question":"Qual è l’infinito passato di cantare?","answer":"Avere cantato, anche aver cantato."},{"question":"Quale fatto viene prima in è felice di aver finito?","answer":"La conclusione del lavoro."},{"question":"Come eviti soggetti ambigui dopo dopo?","answer":"Se i soggetti sono diversi, usa una frase esplicita: dopo che Luca è partito, Anna ha telefonato."}],"levels":{"base":{"focus":"L’infinito passato indica un’azione già compiuta rispetto alla reggente.","example":{"sentence":"Sono contento di avere cantato.","explanation":"Avere cantato è infinito passato: il canto precede la contentezza."}},"consolidamento":{"focus":"Unisci avere o essere all’infinito e il participio: avere cantato, essere partito. Con essere concorda con il soggetto: essere arrivata, essere arrivati.","example":{"sentence":"Ero sicuro di avere chiuso la porta.","explanation":"La chiusura precede la sicurezza espressa nel passato."}},"avanzato":{"focus":"Controlla soggetto e anteriorità: dopo aver letto, ma prima di leggere.","example":{"sentence":"Dopo avere letto, Giulia risponde.","explanation":"Giulia compie entrambe le azioni; la lettura precede la risposta."}}},"simplified":{"lead":"L’infinito passato presenta un’azione già compiuta rispetto al fatto espresso dalla reggente: avere cantato, essere partito.","steps":["L’infinito passato indica un’azione già compiuta rispetto alla reggente.","Unisci avere o essere all’infinito e il participio: avere cantato, essere partito.","Con essere concorda con il soggetto: essere arrivata, essere arrivati."],"example":{"sentence":"Sono felice di avere ritrovato la merenda.","explanation":"Avere ritrovato è infinito passato: prima ho trovato la merenda, ora sono felice."}},"pei":{"rule":"Avere cantato è infinito passato: l’azione è già compiuta.","example":{"sentence":"Sono contento di avere cantato.","explanation":"Avere cantato è infinito passato: il canto precede la contentezza."}},"trackExamples":{"moda":{"sentence":"Sono soddisfatta di avere cucito l’orlo.","explanation":"La cucitura precede la soddisfazione attuale."},"arredo":{"sentence":"Dopo avere montato il mobile, controlliamo le ante.","explanation":"Il montaggio deve essere completato prima del controllo."},"liuteria":{"sentence":"Il liutaio ricorda di avere sostituito la corda.","explanation":"La sostituzione precede il ricordo."}},"anchor":{"sentence":"Sono felice di avere ritrovato la merenda.","explanation":"Avere ritrovato è infinito passato: prima ho trovato la merenda, ora sono felice.","memory":"Avere più ritrovato: l’azione viene prima."}},{"topic":"Verbi · gerundio presente","area":"parole","lead":"Il gerundio presente collega un’azione a un’altra, spesso indicando contemporaneità, modo, mezzo, causa o condizione.","objectives":["Formare il gerundio presente in -ando e -endo.","Spiegare contemporaneità, modo, mezzo, causa o condizione.","Mantenere chiaro il soggetto e riconoscere stare più gerundio."],"sections":[{"title":"Come si forma","text":"Il gerundio è un modo indefinito: non esprime direttamente persona e numero. Il presente è semplice e si forma normalmente con -ando nei verbi in -are e con -endo nei verbi in -ere e -ire: cantando, temendo, dormendo. Le forme sono invariabili e non cambiano secondo il soggetto. Alcuni verbi hanno una radice particolare: fare dà facendo, dire dicendo, bere bevendo; essere dà essendo e avere avendo. I pronomi atoni si uniscono alla forma: guardandolo, lavandosi, preparandoci. Il gerundio passato è invece composto: avendo cantato.","examples":[{"sentence":"Cammino cantando.","explanation":"Cantando è gerundio presente, invariabile."},{"sentence":"Dormendo poco, Luca si stanca.","explanation":"Dormendo appartiene alla terza coniugazione e termina in -endo."}]},{"title":"Che rapporto esprime","text":"Il gerundio dipende da un’altra azione e il rapporto va ricostruito dal senso. In «aspettando l’autobus, leggo», il gerundio significa «mentre aspetto l’autobus»; in «entra sorridendo» descrive il modo; in «avendo poco tempo, scelgo la via breve» significa «poiché ho poco tempo». Può esprimere anche una condizione: studiando con regolarità, migliorerai equivale a se studierai con regolarità. La forma è la stessa e non contiene una congiunzione che chiarisca il rapporto. Se il lettore può fraintendere, sostituiscila con una subordinata esplicita. Può indicare anche un mezzo: confrontando i campioni, riconosco il colore. Qui il confronto è il procedimento che permette il risultato.","examples":[{"sentence":"Aspettando l’autobus, leggo un libro.","explanation":"Il gerundio indica contemporaneità con l’azione principale."},{"sentence":"Il ragazzo entrò sorridendo.","explanation":"Sorridendo descrive la maniera che accompagna l’ingresso del ragazzo."}]},{"title":"Il soggetto deve essere riconoscibile","text":"Nell’uso ordinario il soggetto del gerundio coincide con quello della reggente: entrando in classe, Marta saluta significa che Marta entra e saluta. Evita frasi come entrando in classe, il banco era sporco: il soggetto grammaticale banco non può entrare. Scrivi quando sono entrato in classe, ho visto il banco sporco. Esistono gerundi con un proprio soggetto espresso, come essendo Luca assente, cominciammo senza di lui, ma sono costruzioni più complesse. Nel tuo testo rendi sempre chiaro chi compie ciascuna azione.","examples":[{"sentence":"Entrando in classe, Marta saluta.","explanation":"Marta è il soggetto sia di entrando sia di saluta."}]},{"title":"Contemporaneità e stare più gerundio","text":"Il gerundio presente esprime spesso un fatto contemporaneo alla reggente, anche quando questa è passata o futura: camminavo ascoltando, camminerò ascoltando. Il gerundio passato indica invece anteriorità compiuta: avendo finito, uscì. Con stare il gerundio forma una perifrasi progressiva che mette in risalto l’azione in corso: sto leggendo, stava leggendo. Stare porta persona e tempo, mentre il gerundio resta invariabile. Non usare il gerundio presente per una semplice azione successiva e indipendente: meglio cadde e si ruppe un braccio quando vuoi raccontare due eventi in successione.","examples":[{"sentence":"Stiamo leggendo il testo.","explanation":"Stiamo porta persona e tempo; leggendo indica l’azione in corso."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il gerundio presente è invariabile e collega un’azione alla reggente."},{"label":"Costruisci","detail":"Usa -ando o -endo: cantando, temendo, dormendo."},{"label":"Confronta","detail":"Il soggetto coincide normalmente con quello della reggente e deve essere chiaro."},{"label":"Controlla","detail":"Distingui contemporaneità e anteriorità; riconosci sto leggendo come azione in corso."}]},"pitfalls":[{"mistake":"Entrando in classe, il banco era sporco.","correction":"Quando sono entrato in classe, ho visto il banco sporco.","why":"Il soggetto di entrando non può essere il banco."},{"mistake":"Facendo io e facendo loro hanno forme diverse.","correction":"Il gerundio facendo resta invariabile.","why":"Persona e numero si ricavano dal contesto o dalla reggente."}],"recap":["Il gerundio presente è invariabile e collega un’azione alla reggente.","Usa -ando o -endo: cantando, temendo, dormendo.","Il soggetto coincide normalmente con quello della reggente e deve essere chiaro.","Distingui contemporaneità e anteriorità; riconosci sto leggendo come azione in corso."],"review":[{"question":"Come si forma il gerundio presente di fare?","answer":"Facendo."},{"question":"Chi entra in entrando in aula, Marta saluta?","answer":"Marta, soggetto anche della reggente."},{"question":"Che differenza c’è tra leggendo e avendo letto?","answer":"Leggendo è presente e indica spesso contemporaneità; avendo letto è passato e indica anteriorità."}],"levels":{"base":{"focus":"Il gerundio presente è invariabile e collega un’azione alla reggente.","example":{"sentence":"Cammino cantando.","explanation":"Cantando è gerundio presente, invariabile."}},"consolidamento":{"focus":"Usa -ando o -endo: cantando, temendo, dormendo. Il soggetto coincide normalmente con quello della reggente e deve essere chiaro.","example":{"sentence":"Aspettando l’autobus, leggo un libro.","explanation":"Il gerundio indica contemporaneità con l’azione principale."}},"avanzato":{"focus":"Distingui contemporaneità e anteriorità; riconosci sto leggendo come azione in corso.","example":{"sentence":"Stiamo leggendo il testo.","explanation":"Stiamo porta persona e tempo; leggendo indica l’azione in corso."}}},"simplified":{"lead":"Il gerundio presente collega un’azione a un’altra, spesso indicando contemporaneità, modo, causa o condizione.","steps":["Il gerundio presente è invariabile e collega un’azione alla reggente.","Usa -ando o -endo: cantando, temendo, dormendo.","Il soggetto coincide normalmente con quello della reggente e deve essere chiaro."],"example":{"sentence":"Camminando, ripasso i verbi a bassa voce.","explanation":"Camminando è gerundio presente: io cammino mentre io ripasso. Il soggetto è lo stesso nelle due azioni."}},"pei":{"rule":"Cantando non cambia con la persona: io canto, noi cantiamo, sempre cantando.","example":{"sentence":"Cammino cantando.","explanation":"Cantando è gerundio presente, invariabile."}},"trackExamples":{"moda":{"sentence":"Cucendo lentamente, controllo ogni punto.","explanation":"Il soggetto io compie entrambe le azioni."},"arredo":{"sentence":"Stiamo montando il ripiano.","explanation":"Stare più gerundio mostra un lavoro in corso."},"liuteria":{"sentence":"Ascoltando la corda, il liutaio regola il pirolo.","explanation":"Il liutaio ascolta e regola: il soggetto è condiviso."}},"anchor":{"sentence":"Camminando, ripasso i verbi a bassa voce.","explanation":"Camminando è gerundio presente: io cammino mentre io ripasso. Il soggetto è lo stesso nelle due azioni.","memory":"Chi cammina? Io. Chi ripassa? Sempre io."}},{"topic":"Verbi · gerundio passato","area":"parole","lead":"Il gerundio passato collega alla reggente un’azione già compiuta: avendo cantato, essendo partito.","objectives":["Formare il gerundio passato con avendo o essendo.","Esprimere anteriorità rispetto alla reggente.","Evitare soggetti ambigui e controllare gli accordi."],"sections":[{"title":"La forma composta e invariabile","text":"Il gerundio passato è formato dal gerundio presente di avere o essere e dal participio passato: avendo cantato, essendo partito. Avendo ed essendo restano invariabili, senza distinzione di persona o numero. Con essere può variare il participio secondo il soggetto: essendo arrivata, essendo arrivati, essendo arrivate. I participi irregolari rimangono riconoscibili: avendo fatto, avendo scritto, essendo venuto. Per l’analisi considera insieme ausiliare e participio: avendo finito è gerundio passato, mentre avendo tempo contiene il gerundio presente di avere usato con significato proprio.","examples":[{"sentence":"Avendo cantato a lungo, Luca era stanco.","explanation":"Avendo cantato è gerundio passato: il canto precede la stanchezza."},{"sentence":"Essendo arrivate presto, le amiche trovarono posto.","explanation":"Arrivate concorda con il soggetto femminile plurale."}]},{"title":"Anteriorità e rapporto di significato","text":"Il gerundio passato indica che il fatto dipendente precede quello della reggente. Può esprimere soprattutto un rapporto temporale o causale: avendo finito, uscì equivale a dopo che ebbe finito oppure poiché aveva finito, secondo il contesto. Il tempo della reggente può essere presente, passato o futuro: avendo già studiato, ora ripasso; avendo studiato, capii meglio; avendo già prenotato, domani partirò tranquillo. La forma composta segnala anteriorità rispetto a quel riferimento e non stabilisce da sola la data precisa del fatto.","examples":[{"sentence":"Avendo letto le istruzioni, ora posso iniziare.","explanation":"La lettura precede la possibilità attuale e ne costituisce la ragione."},{"sentence":"Avendo perso il bus, arrivò tardi.","explanation":"La perdita precedente spiega la causa del ritardo."}]},{"title":"Soggetto e chiarezza della frase","text":"Il soggetto del gerundio coincide normalmente con quello della reggente: avendo finito, Sara uscì significa che Sara ha finito ed è uscita. Se scrivi avendo studiato, la verifica sembrava facile, il soggetto verifica viene associato impropriamente a studiare. Correggi con dopo avere studiato, trovavo facile la verifica oppure dopo che avevo studiato, la verifica mi sembrava facile. I gerundi assoluti con un soggetto autonomo espresso esistono, ma richiedono attenzione. Per la scrittura scolastica scegli la costruzione che rende immediatamente riconoscibile chi agisce.","examples":[{"sentence":"Avendo finito gli esercizi, Sara uscì.","explanation":"Sara è il soggetto di entrambe le azioni e la prima precede la seconda."}]},{"title":"Ausiliare, pronomi e confronto con il presente","text":"L’ausiliare segue il verbo: avendo dormito, essendo partito, essendosi preparato. Con essere il participio concorda con il soggetto. Con avere normalmente resta invariato; con i pronomi oggetto lo, la, li, le anteposti al participio compare l’accordo: avendole viste. I pronomi si uniscono all’ausiliare del gerundio: avendolo letto, essendosi lavata. Il gerundio presente mostra spesso contemporaneità, leggendo imparo; il passato presenta un’azione già conclusa, avendo letto rispondo. Se il rapporto fra i fatti resta poco chiaro, sostituisci il gerundio con dopo che o poiché.","examples":[{"sentence":"Avendole già viste, riconobbi le compagne.","explanation":"Le precede viste e richiede l’accordo; la visione è anteriore al riconoscimento."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il gerundio passato presenta un’azione precedente a quella della reggente."},{"label":"Costruisci","detail":"Unisci avendo o essendo al participio: avendo letto, essendo partito."},{"label":"Confronta","detail":"Mantieni chiaro il soggetto condiviso fra gerundio e reggente."},{"label":"Controlla","detail":"Con essere concorda il participio; con i pronomi scrivi avendolo ed essendosi."}]},"pitfalls":[{"mistake":"Avendo studiato, la verifica sembrava facile.","correction":"Dopo avere studiato, trovavo facile la verifica.","why":"Il soggetto del gerundio deve essere riconoscibile e non può essere la verifica."},{"mistake":"Essendo arrivato, le ragazze si sedettero.","correction":"Essendo arrivate, le ragazze si sedettero.","why":"Arrivate concorda con il soggetto femminile plurale."}],"recap":["Il gerundio passato presenta un’azione precedente a quella della reggente.","Unisci avendo o essendo al participio: avendo letto, essendo partito.","Mantieni chiaro il soggetto condiviso fra gerundio e reggente.","Con essere concorda il participio; con i pronomi scrivi avendolo ed essendosi."],"review":[{"question":"Come si forma il gerundio passato di cantare?","answer":"Avendo cantato."},{"question":"Perché avendo tempo non è gerundio passato?","answer":"Avendo è gerundio presente di avere e non è seguito da un participio."},{"question":"Qual è la differenza tra leggendo rispondo e avendo letto rispondo?","answer":"Nel primo caso leggo mentre rispondo; nel secondo la lettura è già conclusa."}],"levels":{"base":{"focus":"Il gerundio passato presenta un’azione precedente a quella della reggente.","example":{"sentence":"Avendo cantato a lungo, Luca era stanco.","explanation":"Avendo cantato è gerundio passato: il canto precede la stanchezza."}},"consolidamento":{"focus":"Unisci avendo o essendo al participio: avendo letto, essendo partito. Mantieni chiaro il soggetto condiviso fra gerundio e reggente.","example":{"sentence":"Avendo letto le istruzioni, ora posso iniziare.","explanation":"La lettura precede la possibilità attuale e ne costituisce la ragione."}},"avanzato":{"focus":"Con essere concorda il participio; con i pronomi scrivi avendolo ed essendosi.","example":{"sentence":"Avendole già viste, riconobbi le compagne.","explanation":"Le precede viste e richiede l’accordo; la visione è anteriore al riconoscimento."}}},"simplified":{"lead":"Il gerundio passato collega alla reggente un’azione già compiuta: avendo cantato, essendo partito.","steps":["Il gerundio passato presenta un’azione precedente a quella della reggente.","Unisci avendo o essendo al participio: avendo letto, essendo partito.","Mantieni chiaro il soggetto condiviso fra gerundio e reggente."],"example":{"sentence":"Avendo finito i compiti, chiudo il quaderno con soddisfazione.","explanation":"Avendo finito è gerundio passato: prima finisco, poi chiudo. Il soggetto io compie entrambe le azioni."}},"pei":{"rule":"Avendo finito indica che una cosa è già fatta prima dell’altra.","example":{"sentence":"Avendo cantato a lungo, Luca era stanco.","explanation":"Avendo cantato è gerundio passato: il canto precede la stanchezza."}},"trackExamples":{"moda":{"sentence":"Avendo finito l’orlo, ripongo l’abito.","explanation":"La persona che ripone ha prima finito l’orlo."},"arredo":{"sentence":"Avendo controllato le misure, montammo il mobile.","explanation":"Il controllo precede il montaggio e il soggetto noi è condiviso."},"liuteria":{"sentence":"Essendosi preparata, la violinista iniziò la prova.","explanation":"Il gerundio composto riflessivo concorda con la violinista."}},"anchor":{"sentence":"Avendo finito i compiti, chiudo il quaderno con soddisfazione.","explanation":"Avendo finito è gerundio passato: prima finisco, poi chiudo. Il soggetto io compie entrambe le azioni.","memory":"Avendo finito mette il lavoro prima della chiusura."}},{"topic":"Complemento partitivo","area":"frase","lead":"Il complemento partitivo indica l’insieme da cui viene scelta una parte: due degli allievi, il più alto dei tre.","objectives":["Separare la parte scelta dall’insieme di riferimento.","Riconoscere il partitivo dopo quantità e superlativi relativi.","Distinguerlo dall’articolo partitivo e da altri complementi."],"sections":[{"title":"Una parte dentro un insieme","text":"Il complemento partitivo esprime un insieme considerato come il tutto da cui si seleziona una parte. In due degli allievi sono assenti, due indica la parte scelta e degli allievi indica il gruppo completo di riferimento. La domanda utile è fra quali persone o cose?, oppure di quale insieme? Il complemento non coincide con la parte selezionata: per l’analisi devi separare due da degli allievi. Il verbo concorda con il nucleo del soggetto, non automaticamente con il nome contenuto nel complemento.","examples":[{"sentence":"Due degli allievi sono assenti.","explanation":"Degli allievi indica l’insieme da cui vengono selezionati due allievi."},{"sentence":"Uno dei quaderni è nuovo.","explanation":"Dei quaderni è partitivo; il verbo è singolare perché il nucleo è uno."}]},{"title":"Quali parole lo introducono","text":"Il partitivo è introdotto generalmente da di, tra o fra, anche in forma articolata: dei compagni, tra i presenti, fra questi. Dipende spesso da numerali, pronomi indefiniti o interrogativi e parole di quantità: tre di noi, alcuni dei libri, chi di voi, molti fra gli iscritti. Il pronome personale dopo la preposizione ha forma tonica: uno di noi, alcuni di loro. Tra e fra hanno lo stesso significato. Conta il rapporto tra la parola che seleziona e il gruppo da cui si seleziona.","examples":[{"sentence":"Alcuni dei libri sono illustrati.","explanation":"Dei libri indica il gruppo di riferimento del pronome alcuni."},{"sentence":"Chi tra voi conosce la risposta?","explanation":"Tra voi è partitivo e dipende dall’interrogativo chi."}]},{"title":"Confronti e superlativo relativo","text":"Il partitivo accompagna anche il superlativo relativo: il più alto dei tre, la meno costosa fra le stoffe. Il superlativo attribuisce una qualità al grado massimo o minimo rispetto a un insieme delimitato. Quel gruppo è il complemento partitivo. Diverso è il confronto diretto tra due elementi, come Luca è più alto di Marco: di Marco è secondo termine di paragone. Per distinguere i casi chiediti se stai scegliendo un elemento entro un gruppo oppure confrontando esplicitamente un elemento con un altro.","examples":[{"sentence":"Il più alto dei tre entra per primo.","explanation":"Dei tre delimita l’insieme del superlativo relativo il più alto."}]},{"title":"Differenza dall’articolo partitivo e dalla specificazione","text":"Le forme del, dello, della, dei, degli e delle non identificano da sole il complemento partitivo. In compro dei fogli, dei è articolo partitivo e l’intero gruppo dei fogli è complemento oggetto. In il bordo del foglio, del foglio specifica quale bordo: non c’è una parte scelta attraverso un numerale o un’espressione di quantità. In tre dei fogli, invece, dei fogli indica il gruppo da cui prendo tre elementi. Leggi dunque il nucleo a cui il gruppo si collega e controlla il significato prima di decidere.","examples":[{"sentence":"Compro dei fogli; scelgo tre dei fogli.","explanation":"Nel primo caso dei è articolo partitivo; nel secondo dei fogli è complemento partitivo."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"Il partitivo indica l’insieme da cui si sceglie una parte."},{"label":"Costruisci","detail":"Cerca una quantità, un pronome o un superlativo: due, alcuni, il più alto."},{"label":"Confronta","detail":"Il gruppo è introdotto soprattutto da di, tra o fra."},{"label":"Controlla","detail":"Distingui il complemento partitivo dall’articolo partitivo e dal secondo termine di paragone."}]},"pitfalls":[{"mistake":"In due degli allievi, due è il complemento partitivo.","correction":"Il complemento partitivo è degli allievi.","why":"Due indica la parte scelta; il complemento indica l’insieme."},{"mistake":"Ogni gruppo con dei è un complemento partitivo.","correction":"In compro dei fogli, dei è articolo partitivo.","why":"La stessa forma può svolgere funzioni diverse secondo la costruzione."}],"recap":["Il partitivo indica l’insieme da cui si sceglie una parte.","Cerca una quantità, un pronome o un superlativo: due, alcuni, il più alto.","Il gruppo è introdotto soprattutto da di, tra o fra.","Distingui il complemento partitivo dall’articolo partitivo e dal secondo termine di paragone."],"review":[{"question":"Qual è il partitivo in uno dei libri?","answer":"Dei libri, l’insieme da cui si sceglie uno."},{"question":"Quale complemento trovi in il più alto dei tre?","answer":"Dei tre è complemento partitivo."},{"question":"Perché uno degli allievi è assente ha il verbo singolare?","answer":"Il nucleo del soggetto è uno; degli allievi è un’espansione partitiva."}],"levels":{"base":{"focus":"Il partitivo indica l’insieme da cui si sceglie una parte.","example":{"sentence":"Due degli allievi sono assenti.","explanation":"Degli allievi indica l’insieme da cui vengono selezionati due allievi."}},"consolidamento":{"focus":"Cerca una quantità, un pronome o un superlativo: due, alcuni, il più alto. Il gruppo è introdotto soprattutto da di, tra o fra.","example":{"sentence":"Alcuni dei libri sono illustrati.","explanation":"Dei libri indica il gruppo di riferimento del pronome alcuni."}},"avanzato":{"focus":"Distingui il complemento partitivo dall’articolo partitivo e dal secondo termine di paragone.","example":{"sentence":"Compro dei fogli; scelgo tre dei fogli.","explanation":"Nel primo caso dei è articolo partitivo; nel secondo dei fogli è complemento partitivo."}}},"simplified":{"lead":"Il complemento partitivo indica l’insieme da cui viene scelta una parte: due degli allievi, il più alto dei tre.","steps":["Il partitivo indica l’insieme da cui si sceglie una parte.","Cerca una quantità, un pronome o un superlativo: due, alcuni, il più alto.","Il gruppo è introdotto soprattutto da di, tra o fra."],"example":{"sentence":"Uno dei miei calzini vive una vita indipendente.","explanation":"Dei miei calzini è complemento partitivo: indica l’insieme da cui viene individuato un solo calzino."}},"pei":{"rule":"In due dei libri, dei libri indica tutto il gruppo.","example":{"sentence":"Due degli allievi sono assenti.","explanation":"Degli allievi indica l’insieme da cui vengono selezionati due allievi."}},"trackExamples":{"moda":{"sentence":"Scelgo due delle stoffe disponibili.","explanation":"Delle stoffe disponibili indica l’insieme della scelta."},"arredo":{"sentence":"Questo è il più stabile fra i tavoli.","explanation":"Fra i tavoli delimita il gruppo del superlativo relativo."},"liuteria":{"sentence":"Tre dei violini richiedono un controllo.","explanation":"Dei violini è l’insieme dal quale sono individuati tre strumenti."}},"anchor":{"sentence":"Uno dei miei calzini vive una vita indipendente.","explanation":"Dei miei calzini è complemento partitivo: indica l’insieme da cui viene individuato un solo calzino.","memory":"Uno è la parte; dei miei calzini è il gruppo."}},{"topic":"Compagnia e unione","area":"frase","lead":"Compagnia e unione indicano chi o che cosa accompagna il soggetto: esco con Amir, esco con lo zaino.","objectives":["Distinguere un accompagnatore animato da una cosa.","Riconoscere compagnia e unione nella frase.","Distinguerle da mezzo e modo anche quando compare con."],"sections":[{"title":"La compagnia di persone o animali","text":"Il complemento di compagnia indica la persona o l’animale insieme a cui si svolge un’azione o ci si trova in una situazione. Risponde alle domande con chi? e insieme a chi? In esco con Amir, con Amir è compagnia; Amir accompagna chi esce. Anche con il cane può esprimere compagnia, perché si tratta di un essere animato che accompagna. Il gruppo è normalmente introdotto da con, insieme a, assieme a oppure in compagnia di. La preposizione va letta insieme al significato del verbo.","examples":[{"sentence":"Esco con Amir.","explanation":"Con Amir indica la persona che accompagna chi esce."},{"sentence":"Passeggio insieme al cane.","explanation":"Insieme al cane è compagnia: l’animale accompagna il soggetto."}]},{"title":"L’unione con cose","text":"Il complemento di unione indica una cosa che accompagna una persona o un altro elemento: esco con lo zaino, arrivo con una valigia. Risponde alla domanda con che cosa?, ma questa domanda da sola non basta a distinguerlo da altri complementi. La cosa è presentata come qualcosa che si porta con sé o che si trova unito a un altro elemento. Le preposizioni più comuni sono con e insieme a. Nella classificazione scolastica la distinzione dalla compagnia dipende dunque soprattutto dal tipo di accompagnatore: essere animato oppure cosa.","examples":[{"sentence":"Esco con lo zaino.","explanation":"Con lo zaino indica una cosa portata con sé: unione."},{"sentence":"Arriva con una scatola sotto il braccio.","explanation":"Con una scatola indica unione, perché la scatola accompagna chi arriva."}]},{"title":"Distinguere unione e mezzo","text":"La preposizione con introduce molti complementi diversi. In cammino con un bastone, se il bastone è usato per sostenersi, il gruppo indica mezzo o strumento. In arrivo con un bastone in mano, se interessa soltanto l’oggetto portato, può indicare unione. In scrivo con la penna lo strumento rende possibile l’azione: è mezzo. In esco con la penna in tasca la penna accompagna la persona: è unione. Per decidere, chiediti se la cosa serve a compiere l’azione o è soltanto presentata insieme al soggetto.","examples":[{"sentence":"Scrivo con la penna; esco con la penna in tasca.","explanation":"Nel primo caso con la penna è mezzo; nel secondo è unione."}]},{"title":"La relazione nella frase completa","text":"Anche un nome di persona introdotto da con può esprimere un’altra funzione: in litigo con Amir il gruppo è richiesto dal significato del verbo e indica la persona con cui si entra in conflitto. In parlo con calma, con calma indica modo, non compagnia. Non assegnare la funzione leggendo soltanto la preposizione o classificando il nome come persona o cosa. Prima individua l’azione, poi chiediti quale relazione il gruppo aggiunge. Se un esempio ammette più interpretazioni, usa il contesto oppure riscrivilo in modo che l’accompagnamento sia esplicito.","examples":[{"sentence":"Parlo con calma mentre cammino con Amir.","explanation":"Con calma indica modo; con Amir indica compagnia nell’azione di camminare."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"La compagnia indica una persona o un animale che accompagna."},{"label":"Costruisci","detail":"L’unione indica una cosa portata con sé o unita a un altro elemento."},{"label":"Confronta","detail":"Cerca con, insieme a, assieme a e in compagnia di."},{"label":"Controlla","detail":"Se l’oggetto serve a compiere l’azione, il complemento è di mezzo, non di unione."}]},"pitfalls":[{"mistake":"Esco con lo zaino: con lo zaino è compagnia.","correction":"Con lo zaino è unione.","why":"Lo zaino è una cosa che accompagna il soggetto."},{"mistake":"Ogni gruppo con con è compagnia o unione.","correction":"In taglio con le forbici, con le forbici è mezzo.","why":"La preposizione non basta: bisogna capire il rapporto con l’azione."}],"recap":["La compagnia indica una persona o un animale che accompagna.","L’unione indica una cosa portata con sé o unita a un altro elemento.","Cerca con, insieme a, assieme a e in compagnia di.","Se l’oggetto serve a compiere l’azione, il complemento è di mezzo, non di unione."],"review":[{"question":"Che funzione ha con Amir in esco con Amir?","answer":"Complemento di compagnia."},{"question":"Che funzione ha con lo zaino in esco con lo zaino?","answer":"Complemento di unione."},{"question":"Perché con le forbici in taglio con le forbici è mezzo?","answer":"Le forbici sono lo strumento usato per compiere il taglio."}],"levels":{"base":{"focus":"La compagnia indica una persona o un animale che accompagna.","example":{"sentence":"Esco con Amir.","explanation":"Con Amir indica la persona che accompagna chi esce."}},"consolidamento":{"focus":"L’unione indica una cosa portata con sé o unita a un altro elemento. Cerca con, insieme a, assieme a e in compagnia di.","example":{"sentence":"Esco con lo zaino.","explanation":"Con lo zaino indica una cosa portata con sé: unione."}},"avanzato":{"focus":"Se l’oggetto serve a compiere l’azione, il complemento è di mezzo, non di unione.","example":{"sentence":"Parlo con calma mentre cammino con Amir.","explanation":"Con calma indica modo; con Amir indica compagnia nell’azione di camminare."}}},"simplified":{"lead":"Compagnia e unione indicano chi o che cosa accompagna il soggetto: esco con Amir, esco con lo zaino.","steps":["La compagnia indica una persona o un animale che accompagna.","L’unione indica una cosa portata con sé o unita a un altro elemento.","Cerca con, insieme a, assieme a e in compagnia di."],"example":{"sentence":"Esco con Amir e con uno zaino gigantesco.","explanation":"Con Amir indica compagnia; con uno zaino gigantesco indica unione. Un amico e una cosa accompagnano chi esce."}},"pei":{"rule":"Con Amir è compagnia; con lo zaino è unione.","example":{"sentence":"Esco con Amir.","explanation":"Con Amir indica la persona che accompagna chi esce."}},"trackExamples":{"moda":{"sentence":"La studentessa arriva con la borsa dei campioni.","explanation":"Con la borsa dei campioni indica unione."},"arredo":{"sentence":"Visitiamo la mostra con il docente.","explanation":"Con il docente indica compagnia."},"liuteria":{"sentence":"L’allieva entra con il violino nella custodia.","explanation":"Con il violino indica lo strumento portato con sé, quindi unione."}},"anchor":{"sentence":"Esco con Amir e con uno zaino gigantesco.","explanation":"Con Amir indica compagnia; con uno zaino gigantesco indica unione. Un amico e una cosa accompagnano chi esce.","memory":"Amir mi accompagna: compagnia. Lo zaino viene con me: unione."}},{"topic":"Materia e qualità","area":"frase","lead":"Il complemento di materia dice di che cosa è fatto qualcosa; quello di qualità descrive una caratteristica di una persona o di una cosa.","objectives":["Individuare la sostanza di cui è fatto un oggetto.","Riconoscere una caratteristica espressa da un complemento.","Distinguere materia, qualità, modo e destinazione."],"sections":[{"title":"Di che cosa è fatto un oggetto","text":"Il complemento di materia indica la sostanza da cui è costituito un oggetto: una cornice di legno, una statua di marmo, una camicia di lino. Risponde alle domande di che materia? e fatto di che cosa? È introdotto soprattutto da di o in, anche con articolo: una struttura in acciaio, un anello d’oro. La materia può essere espressa in senso figurato, come un cuore di pietra: la costruzione richiama una sostanza per comunicare una caratteristica, senza affermare che il cuore sia realmente di pietra.","examples":[{"sentence":"Una cornice di legno.","explanation":"Di legno indica la materia della cornice."},{"sentence":"Una camicia di lino.","explanation":"Di lino dice di quale fibra è fatto il tessuto della camicia."}]},{"title":"Una caratteristica della persona o della cosa","text":"Il complemento di qualità indica una caratteristica fisica, morale o strutturale: un ragazzo di grande pazienza, una persona dagli occhi verdi, un tavolo a tre gambe. Risponde a domande come con quale caratteristica? o di quale qualità? È introdotto spesso da di, da, a o con e può comprendere aggettivi o altre precisazioni. Il gruppo si collega a un nome e lo descrive. In una ragazza gentile, invece, gentile è un aggettivo con funzione di attributo: il significato descrittivo è simile, ma la struttura grammaticale è diversa.","examples":[{"sentence":"Un ragazzo di grande pazienza.","explanation":"Di grande pazienza indica una qualità morale del ragazzo."},{"sentence":"Un tavolo a tre gambe.","explanation":"A tre gambe descrive una caratteristica strutturale del tavolo."}]},{"title":"Come distinguere materia e qualità","text":"Per decidere tra le due funzioni prova a completare due frasi: l’oggetto è fatto di… oppure la persona o la cosa ha la caratteristica di… In un mobile di legno il nome legno indica la sostanza; in un mobile di grande solidità il gruppo descrive una qualità. La preposizione di compare in entrambi e non risolve l’analisi. Anche il lessico va interpretato nel contesto: un oggetto d’oro indica normalmente materia, mentre una persona dal cuore d’oro esprime una qualità attraverso un’immagine figurata.","examples":[{"sentence":"Una cornice di legno e una cornice di grande eleganza.","explanation":"Di legno è materia; di grande eleganza è qualità."}]},{"title":"Rapporti vicini e analisi precisa","text":"Altri gruppi possono assomigliare a materia o qualità senza avere la stessa funzione. In un tavolo da cucina, da cucina indica destinazione; in il colore del tavolo, del tavolo è specificazione. In lavora con pazienza il gruppo si collega al verbo e indica modo; in un artigiano di grande pazienza si collega al nome e indica qualità. Cerca quindi il nucleo da cui dipende il gruppo e il rapporto che aggiunge. Nei casi figurati, dove le classificazioni scolastiche possono variare, spiega il significato e segui il criterio adottato nel corso.","examples":[{"sentence":"Lavora con pazienza; è un artigiano di grande pazienza.","explanation":"Con pazienza indica modo dell’azione; di grande pazienza descrive una qualità della persona."}]}],"diagram":{"title":"Il percorso del ragionamento","steps":[{"label":"Riconosci","detail":"La materia indica la sostanza di cui è fatto qualcosa."},{"label":"Costruisci","detail":"La qualità descrive una caratteristica di una persona o di una cosa."},{"label":"Confronta","detail":"Non basta la preposizione: confronta fatto di legno con dotato di pazienza."},{"label":"Controlla","detail":"Distingui qualità riferita al nome e modo riferito al verbo."}]},"pitfalls":[{"mistake":"In cornice di legno, di legno è qualità.","correction":"Di legno è complemento di materia.","why":"Il legno è la sostanza che costituisce la cornice."},{"mistake":"In lavora con pazienza, con pazienza è qualità.","correction":"Con pazienza è complemento di modo.","why":"Il gruppo descrive come si lavora e dipende dal verbo, non da un nome."}],"recap":["La materia indica la sostanza di cui è fatto qualcosa.","La qualità descrive una caratteristica di una persona o di una cosa.","Non basta la preposizione: confronta fatto di legno con dotato di pazienza.","Distingui qualità riferita al nome e modo riferito al verbo."],"review":[{"question":"Quale funzione ha di legno in una cornice di legno?","answer":"Complemento di materia."},{"question":"Quale funzione ha di grande pazienza in un ragazzo di grande pazienza?","answer":"Complemento di qualità."},{"question":"Come distingui un mobile di legno da un mobile di grande solidità?","answer":"Di legno indica la sostanza; di grande solidità una caratteristica del mobile."}],"levels":{"base":{"focus":"La materia indica la sostanza di cui è fatto qualcosa.","example":{"sentence":"Una cornice di legno.","explanation":"Di legno indica la materia della cornice."}},"consolidamento":{"focus":"La qualità descrive una caratteristica di una persona o di una cosa. Non basta la preposizione: confronta fatto di legno con dotato di pazienza.","example":{"sentence":"Un ragazzo di grande pazienza.","explanation":"Di grande pazienza indica una qualità morale del ragazzo."}},"avanzato":{"focus":"Distingui qualità riferita al nome e modo riferito al verbo.","example":{"sentence":"Lavora con pazienza; è un artigiano di grande pazienza.","explanation":"Con pazienza indica modo dell’azione; di grande pazienza descrive una qualità della persona."}}},"simplified":{"lead":"Il complemento di materia dice di che cosa è fatto qualcosa; quello di qualità descrive una caratteristica di una persona o di una cosa.","steps":["La materia indica la sostanza di cui è fatto qualcosa.","La qualità descrive una caratteristica di una persona o di una cosa.","Non basta la preposizione: confronta fatto di legno con dotato di pazienza."],"example":{"sentence":"Ho una matita di legno e un amico di grande pazienza.","explanation":"Di legno indica materia; di grande pazienza indica qualità. Il primo gruppo dice di che cosa è fatta la matita, il secondo descrive l’amico."}},"pei":{"rule":"Di legno indica materia; di grande pazienza indica una qualità.","example":{"sentence":"Una cornice di legno.","explanation":"Di legno indica la materia della cornice."}},"trackExamples":{"moda":{"sentence":"Un abito di lino dalla linea semplice.","explanation":"Di lino è materia; dalla linea semplice è qualità."},"arredo":{"sentence":"Un tavolo in rovere a quattro gambe.","explanation":"In rovere è materia; a quattro gambe è qualità."},"liuteria":{"sentence":"Una tavola di abete di spessore uniforme.","explanation":"Di abete indica materia; di spessore uniforme indica qualità."}},"anchor":{"sentence":"Ho una matita di legno e un amico di grande pazienza.","explanation":"Di legno indica materia; di grande pazienza indica qualità. Il primo gruppo dice di che cosa è fatta la matita, il secondo descrive l’amico.","memory":"Legno: di che cosa è fatta? Pazienza: quale caratteristica ha?"}},{"topic":"Principale, coordinate e subordinate","area":"periodo","lead":"Un periodo collega una o più proposizioni: per capirlo, osserva i predicati e poi i rapporti fra le informazioni.","objectives":["Individuare i nuclei verbali","Distinguere coordinazione e subordinazione","Rappresentare i collegamenti del periodo"],"sections":[{"title":"Dal predicato alla proposizione","text":"Una proposizione è un gruppo di parole organizzato intorno a un predicato. Un periodo contiene una o più proposizioni e termina normalmente con un punto fermo, interrogativo o esclamativo. Cerca prima i nuclei verbali, senza contare semplicemente tutte le forme del verbo: un tempo composto, una forma passiva e un verbo servile con il suo infinito costituiscono normalmente un unico predicato.\n\nAnche il soggetto sottinteso appartiene alla proposizione. Gli infiniti delle subordinate, invece, possono formare un nuovo nucleo. Una freccia di dipendenza parte dalla reggente e raggiunge la proposizione che ne precisa o completa il contenuto.","examples":[{"sentence":"La classe ha preparato il modello.","explanation":"Ha preparato è un solo predicato: il periodo contiene una proposizione."},{"sentence":"Possiamo iniziare a cucire.","explanation":"Possiamo iniziare a cucire forma qui una catena verbale servile e fraseologica: non si contano tre proposizioni."}]},{"title":"Un rapporto sullo stesso piano","text":"La coordinazione collega proposizioni dello stesso livello sintattico. Può unire una principale a una coordinata, oppure due subordinate che dipendono dalla stessa reggente.\n\nSi realizza con congiunzioni come e, ma, oppure; può anche affidarsi alla sola punteggiatura. Il rapporto sullo stesso piano non significa che le informazioni abbiano identica importanza comunicativa. Per riconoscerlo, osserva se il secondo segmento aggiunge, contrappone o collega un contenuto senza svolgere una funzione dipendente dal primo.","examples":[{"sentence":"La sarta taglia e l’allieva imbastisce.","explanation":"La seconda proposizione è coordinata copulativa alla principale: i due predicati hanno soggetti diversi."}]},{"title":"Un rapporto di dipendenza","text":"La subordinazione collega una proposizione a un’altra dalla quale dipende. La subordinata può indicare tempo, causa, scopo oppure completare un verbo o un nome.\n\nLa principale non dipende sintatticamente da altre proposizioni; la reggente è invece qualunque proposizione da cui ne dipende una seconda. Una subordinata può quindi essere anche reggente. Non cercare la principale soltanto all’inizio: una dipendente può precederla, seguirla o inserirsi al suo interno, secondo l’organizzazione del messaggio.","examples":[{"sentence":"Quando la colla asciuga, togliamo i morsetti.","explanation":"Togliamo i morsetti è la principale; la temporale la precede e ne precisa il momento."}]},{"title":"Costruire uno schema leggibile","text":"Dopo la divisione, riscrivi ogni proposizione con le parole che le appartengono, compresi i collegamenti. Segna la principale come punto di partenza e usa una linea orizzontale per la coordinazione, una linea di dipendenza per la subordinazione.\n\nChiediti sempre da quale proposizione dipenda ciascun segmento. Le domande quando, perché, a quale scopo aiutano, ma vanno controllate sul significato. Uno stesso periodo può contenere insieme entrambi i rapporti e più livelli di dipendenza.","examples":[{"sentence":"Penso che Luca sappia dove abita Marta.","explanation":"Penso è principale; che Luca sappia è dipendente di primo grado e regge dove abita Marta, di secondo grado."}]},{"title":"Esempio guida: un periodo intero","text":"Leggi il periodo dell’esempio e cerca prima i nuclei verbali: arriva, mostra, spiega, ha scelto, preferisce. Sono cinque. La principale è Lia mostra il disegno; e spiega è coordinata alla principale. Quando arriva la docente è temporale e dipende da mostra.\n\nChe ha scelto il blu è oggettiva e dipende da spiega: rispetto a questa reggente è di primo grado. Poiché la cliente lo preferisce è causale e dipende da ha scelto: è quindi di secondo grado rispetto a spiega. Nello schema metti mostra e spiega sullo stesso piano; sotto mostra colloca quando arriva; sotto spiega metti che ha scelto, e sotto quest’ultima poiché la cliente lo preferisce.","examples":[{"sentence":"Quando arriva la docente, Lia mostra il disegno e spiega che, poiché la cliente lo preferisce, ha scelto il blu.","explanation":"Cinque nuclei: la temporale dipende da mostra; l’oggettiva da spiega; la causale dall’oggettiva."},{"sentence":"Mentre il colore asciuga, Noor pulisce e prepara i pennelli.","explanation":"Pulisce è principale; prepara è coordinata; mentre il colore asciuga è temporale."}]}],"diagram":{"title":"I legami del periodo","steps":[{"label":"Un nucleo","detail":"Ha cucito: ausiliare e participio formano un solo predicato."},{"label":"Principale","detail":"Non dipende da un’altra proposizione."},{"label":"Coordinata","detail":"Sta sullo stesso piano della proposizione a cui si collega: e, ma, oppure."},{"label":"Subordinata","detail":"Dipende da una reggente: quando arrivi, perché piove, per capire."},{"label":"Più gradi","detail":"Una subordinata può reggerne un’altra: penso → che sappia → dove andare."}]},"pitfalls":[{"mistake":"Contare ha lavorato come due proposizioni.","correction":"Contare un unico predicato composto.","why":"L’ausiliare e il participio costruiscono insieme il tempo verbale."},{"mistake":"Chiamare principale ogni reggente.","correction":"Verificare se la reggente dipenda a sua volta da un’altra proposizione.","why":"Principale indica autonomia sintattica; reggente indica un rapporto con una dipendente."}],"recap":["Una proposizione è un gruppo di parole organizzato intorno a un predicato.","La coordinazione collega proposizioni dello stesso livello sintattico.","La subordinazione collega una proposizione a un’altra dalla quale dipende.","Dopo la divisione, riscrivi ogni proposizione con le parole che le appartengono, compresi i collegamenti."],"review":[{"question":"Qual è il primo passo dell’analisi?","answer":"Individuare i predicati, distinguendo forme composte e catene verbali dagli autonomi nuclei di subordinata."},{"question":"Una coordinata può collegarsi a una subordinata?","answer":"Sì: due subordinate dello stesso livello possono essere coordinate fra loro."},{"question":"In Penso che tu sappia dove andare, quale proposizione regge dove andare?","answer":"Che tu sappia, che è subordinata di primo grado e reggente dell’interrogativa indiretta di secondo grado."}],"levels":{"base":{"focus":"Dividere periodi con due nuclei verbali.","example":{"sentence":"La classe ha preparato il modello.","explanation":"Ha preparato è un solo predicato: il periodo contiene una proposizione."}},"consolidamento":{"focus":"Riconoscere insieme coordinazione e subordinazione.","example":{"sentence":"La sarta taglia e l’allieva imbastisce.","explanation":"La seconda proposizione è coordinata copulativa alla principale: i due predicati hanno soggetti diversi."}},"avanzato":{"focus":"Motivare il collegamento di una dipendente quando le letture possibili sono più di una.","example":{"sentence":"Penso che Luca sappia dove abita Marta.","explanation":"Penso è principale; che Luca sappia è dipendente di primo grado e regge dove abita Marta, di secondo grado."}}},"simplified":{"lead":"Un periodo contiene parti collegate tra loro.","steps":["Cerca i predicati completi.","Trova la parte che non dipende da un’altra.","Collega le altre parti: stesso piano oppure dipendenza."],"example":{"sentence":"Luca legge e Sara disegna.","explanation":"Legge e disegna sono due predicati. E collega due proposizioni sullo stesso piano."}},"pei":{"rule":"Cerca prima i verbi. Poi osserva come sono collegate le parti.","example":{"sentence":"Luca legge e Sara disegna.","explanation":"Legge e disegna sono due predicati. E collega due proposizioni sullo stesso piano."}},"trackExamples":{"moda":{"sentence":"La sarta misura e l’allieva annota.","explanation":"E collega due proposizioni sullo stesso piano."},"arredo":{"sentence":"Il falegname misura e l’allieva annota.","explanation":"E collega due proposizioni sullo stesso piano."},"liuteria":{"sentence":"Il liutaio misura e l’allieva annota.","explanation":"E collega due proposizioni sullo stesso piano."}},"anchor":{"sentence":"Quando finisce la prova, Sara riordina e Amir cerca il tappo della colla.","explanation":"I nuclei sono finisce, riordina, cerca. Sara riordina è principale; e Amir cerca il tappo della colla è coordinata; Quando finisce la prova è temporale dipendente dalla principale.","memory":"Disegna un piano per riordina e cerca, poi collega quando finisce sotto la principale."}},{"topic":"Principale e proposizioni","area":"periodo","lead":"La principale è il punto di riferimento sintattico del periodo, anche quando non occupa il primo posto.","objectives":["Riconoscere un predicato completo","Individuare la principale","Distinguere autonomia sintattica e completezza del messaggio"],"sections":[{"title":"Una proposizione e il suo nucleo","text":"La proposizione contiene un predicato e gli elementi che si organizzano intorno a esso. Può avere un soggetto espresso oppure sottinteso; può anche essere impersonale. Per dividerla dalle altre proposizioni individua i nuclei verbali e i loro argomenti.\n\nNon separare un ausiliare dal participio, né il verbo essere dal nome del predicato. Una parola con forma verbale può inoltre essere usata come nome o aggettivo: in quel caso non introduce automaticamente una nuova proposizione. Negli esercizi sottolinea prima il predicato completo e ricomponi poi le parole della principale eventualmente separate.","examples":[{"sentence":"Gli allievi hanno finito.","explanation":"Hanno finito è un solo predicato e costituisce una sola proposizione."},{"sentence":"Il mobile è stabile.","explanation":"È stabile è un predicato nominale: non va spezzato in due proposizioni."}]},{"title":"Riconoscere la principale","text":"La principale è la proposizione che non dipende sintatticamente da un’altra. Per trovarla verifica i legami: una temporale introdotta da quando, per esempio, si appoggia a un’altra proposizione, mentre la principale non ha quel legame di dipendenza.\n\nNon applicare però una regola basata solo sull’ordine o sulla lunghezza. La principale può essere breve e collocarsi dopo una subordinata molto estesa. In un periodo con coordinazione ci possono essere altre proposizioni indipendenti coordinate alla principale.","examples":[{"sentence":"Dopo che il campione si è asciugato, lo pesiamo.","explanation":"Lo pesiamo è principale: la proposizione iniziale ne precisa il momento."}]},{"title":"Autonomia non significa dire tutto","text":"Una principale è autonoma dal punto di vista sintattico, ma non sempre basta da sola a comunicare un messaggio completo. Verbi come dire, pensare o desiderare possono richiedere un contenuto espresso da una subordinata.\n\nLa prova di cancellare le dipendenti è dunque un aiuto, non un criterio assoluto: Penso può essere la principale anche se desideriamo sapere che cosa viene pensato. Conta il rapporto strutturale, non l’impressione che una parte sia più importante delle altre.","examples":[{"sentence":"Credo che il disegno sia corretto.","explanation":"Credo è principale; il contenuto del pensiero è espresso dalla subordinata completiva."}]},{"title":"Funzioni e forme comunicative","text":"Una principale può comunicare un fatto, porre una domanda, dare un ordine o esprimere un desiderio. In questi casi parliamo rispettivamente di enunciativa, interrogativa diretta, volitiva o desiderativa; le denominazioni scolastiche possono variare.\n\nIl modo verbale e la punteggiatura aiutano a riconoscere l’intenzione. Quando analizzi, conserva tutte le parole che appartengono al nucleo principale, anche se sono separate dall’inserimento di una subordinata. Non confondere una domanda diretta autonoma con una domanda riportata e dipendente.","examples":[{"sentence":"Il tavolo, che abbiamo appena montato, regge bene.","explanation":"La principale è Il tavolo regge bene; la relativa si inserisce fra soggetto e predicato."}]},{"title":"Domande dirette ed esclamazioni","text":"Una proposizione principale esclamativa esprime una reazione, come gioia, sorpresa o dispiacere. Una interrogativa diretta pone invece una domanda autonoma. Le domande totali ammettono in genere sì o no; le parziali chiedono un’informazione, per esempio un luogo o una persona. Le disgiuntive propongono alternative; una domanda retorica può servire a sottolineare un’affermazione senza attendere una risposta.\n\nLa punteggiatura e il contesto aiutano a riconoscere l’intenzione. Una domanda principale può anche contenere una domanda indiretta dipendente: in «Sai dove lavora?» l’intero enunciato è interrogativo diretto, mentre dove lavora è una dipendente.","examples":[{"sentence":"Che bel disegno hai preparato!","explanation":"La frase esprime una reazione esclamativa."},{"sentence":"Preferisci disegnare o modellare?","explanation":"La domanda offre due alternative: è interrogativa diretta disgiuntiva."},{"sentence":"Chi non vorrebbe una giornata libera?","explanation":"Nel contesto la domanda può essere retorica: suggerisce una risposta condivisa."}]}],"diagram":{"title":"La principale nel periodo","steps":[{"label":"Predicato","detail":"Un tempo composto o una catena servile conta normalmente come un solo nucleo."},{"label":"Autonomia","detail":"La principale non dipende da altre proposizioni."},{"label":"Posizione","detail":"Può stare prima, dopo o attorno a una subordinata inserita."},{"label":"Contenuto","detail":"Credo è principale anche se una completiva dice che cosa viene creduto."}]},"pitfalls":[{"mistake":"Scegliere sempre la prima proposizione.","correction":"Seguire i rapporti sintattici.","why":"Una subordinata può aprire il periodo."},{"mistake":"Escludere Credo perché da solo sembra incompleto.","correction":"Distinguere autonomia sintattica e contenuto richiesto dal verbo.","why":"Un verbo principale può essere completato da una subordinata."}],"recap":["La proposizione contiene un predicato e gli elementi che si organizzano intorno a esso.","La principale è la proposizione che non dipende sintatticamente da un’altra.","Una principale è autonoma dal punto di vista sintattico, ma non sempre basta da sola a comunicare un messaggio completo.","Una principale può comunicare un fatto, porre una domanda, dare un ordine o esprimere un desiderio."],"review":[{"question":"Che cosa distingue la principale?","answer":"Non dipende sintatticamente da un’altra proposizione."},{"question":"Quante proposizioni contiene La cornice è stata montata?","answer":"Una: è stata montata è un unico predicato verbale passivo."},{"question":"La principale deve essere continua nella frase?","answer":"No. Una subordinata incidentale o relativa può interromperla; nell’analisi se ne riuniscono le parole."}],"levels":{"base":{"focus":"Individuare la principale in periodi di due proposizioni.","example":{"sentence":"Gli allievi hanno finito.","explanation":"Hanno finito è un solo predicato e costituisce una sola proposizione."}},"consolidamento":{"focus":"Riconoscere la principale interrotta da una relativa.","example":{"sentence":"Il banco, che abbiamo montato ieri, regge bene.","explanation":"La principale è Il banco regge bene. La relativa che abbiamo montato ieri si inserisce fra il soggetto e il predicato della principale."}},"avanzato":{"focus":"Spiegare perché una principale può richiedere una completiva.","example":{"sentence":"Credo che il mobile sia stabile.","explanation":"Credo è la principale e non dipende da un’altra proposizione. Che il mobile sia stabile è una completiva oggettiva: esprime il contenuto del pensiero."}}},"simplified":{"lead":"La principale è la parte che non dipende da un’altra proposizione.","steps":["Cerca il verbo della prima parte.","Cerca il verbo della seconda parte.","Trova la parte che non dipende dall’altra."],"example":{"sentence":"Quando arrivi, usciamo.","explanation":"Usciamo è la principale. Quando arrivi dice quando usciamo."}},"pei":{"rule":"La principale non dipende da un’altra proposizione.","example":{"sentence":"Quando arrivi, usciamo.","explanation":"Usciamo è la principale. Quando arrivi dice quando usciamo."}},"trackExamples":{"moda":{"sentence":"Quando il tessuto asciuga, lo stiriamo.","explanation":"Lo stiriamo è la principale."},"arredo":{"sentence":"Quando la vernice asciuga, la controlliamo.","explanation":"La controlliamo è la principale."},"liuteria":{"sentence":"Quando la colla asciuga, la controlliamo.","explanation":"La controlliamo è la principale."}},"anchor":{"sentence":"Quando sparisce il righello, la classe cerca sotto il tavolo.","explanation":"La classe cerca sotto il tavolo è principale anche se viene dopo. Quando sparisce il righello dipende da essa e dice quando avviene la ricerca.","memory":"La principale si trova seguendo i legami, anche in fondo alla frase."}},{"topic":"Coordinate","area":"periodo","lead":"Le coordinate collegano informazioni sullo stesso piano: il tipo di collegamento dipende dal rapporto di significato.","objectives":["Individuare proposizioni sullo stesso piano","Distinguere i tipi di coordinazione","Riconoscere coordinazioni fra subordinate"],"sections":[{"title":"Che cosa collega la coordinazione","text":"La coordinazione unisce elementi con la stessa funzione o proposizioni dello stesso livello. Prima di parlare di proposizioni coordinate verifica che ci siano due predicati: in ago e filo sono coordinati due nomi, non due proposizioni. Il soggetto della seconda proposizione può essere sottinteso.\n\nLa coordinazione può collegare una proposizione alla principale, ma anche due dipendenti fra loro. In quest’ultimo caso rimangono entrambe subordinate rispetto alla reggente e mantengono il proprio grado di dipendenza. Quando il soggetto non viene ripetuto, lo recuperi dalla prima proposizione senza cancellare il nuovo predicato.","examples":[{"sentence":"Luca disegna e Sara cuce.","explanation":"E collega due proposizioni con predicati e soggetti distinti."},{"sentence":"Luca usa ago e filo.","explanation":"E collega due nomi; il predicato è uno e la proposizione è una."}]},{"title":"Aggiungere, contrapporre, scegliere","text":"Le copulative aggiungono informazioni: e ha valore affermativo, né collega elementi negativi. Le avversative introducono un contrasto o una correzione, mediante ma, però, tuttavia, invece. Le disgiuntive presentano alternative, con o, oppure, altrimenti.\n\nLa scelta dipende da ciò che vuoi comunicare, non dalla lunghezza delle proposizioni. Alcune parole assumono sfumature diverse nel contesto: e può suggerire una conseguenza, pur restando formalmente una congiunzione copulativa. Nell’analisi distingui il collegamento grammaticale dall’effetto complessivo del messaggio.","examples":[{"sentence":"Il pannello è leggero, ma resiste al carico.","explanation":"La coordinata è avversativa: contrasta un’aspettativa legata alla leggerezza."}]},{"title":"Spiegare, concludere, distribuire","text":"Le esplicative o dichiarative chiariscono una precedente affermazione, con cioè, infatti, ossia. Le conclusive presentano una conclusione, con dunque, quindi, perciò.\n\nLe correlative distribuiscono il collegamento in due parti: sia… sia, né… né, o… o, non solo… ma anche. Le etichette dichiarativa e esplicativa, riferite alle coordinate, non vanno confuse con la subordinata dichiarativa che precisa un nome. Per scegliere il tipo leggi sempre entrambe le proposizioni e riconosci quale operazione logica svolge la seconda.","examples":[{"sentence":"La colla è terminata, quindi interrompiamo il lavoro.","explanation":"Quindi presenta la decisione come conclusione tratta dalla prima informazione."}]},{"title":"Congiunzioni e punteggiatura","text":"La coordinazione con una congiunzione si chiama per sindeto; quella realizzata senza congiunzioni, attraverso virgola, punto e virgola o due punti, si chiama per asindeto. La punteggiatura da sola non garantisce però che esista una coordinazione: occorre guardare la costruzione del periodo.\n\nSe due subordinate sono coordinate, la congiunzione subordinante può essere ripetuta oppure rimanere sottintesa nella seconda. Nello schema disponile sullo stesso livello, mantenendo il legame comune con la loro reggente.","examples":[{"sentence":"Credo che il tavolo sia stabile e che il piano sia uniforme.","explanation":"Le due oggettive sono coordinate fra loro e dipendono entrambe da Credo."}]},{"title":"Polisindeto e correlazioni","text":"Il polisindeto è una forma di collegamento in cui una congiunzione viene ripetuta davanti a più elementi o proposizioni: la ripetizione può dare ritmo o evidenza. Se invece le proposizioni sono accostate senza congiunzioni, parliamo di asindeto.\n\nLa correlazione distribuisce i collegamenti in due o più elementi che si richiamano: per esempio ora… ora può alternare due azioni. Per analizzare le proposizioni individua ogni predicato e poi verifica se i collegamenti le pongono sullo stesso piano.","examples":[{"sentence":"E cerca il metro, e prende il foglio, e misura il banco.","explanation":"La ripetizione di e collega le azioni per polisindeto."},{"sentence":"Ora il cane corre, ora si ferma.","explanation":"Ora… ora correla due momenti alternati."}]}],"diagram":{"title":"Proposizioni sullo stesso piano","steps":[{"label":"Aggiunta o scelta","detail":"E, né: copulative. O, oppure: disgiuntive."},{"label":"Contrasto","detail":"Ma, però, tuttavia: avversative."},{"label":"Spiegazione o conclusione","detail":"Infatti, cioè: esplicative. Quindi, dunque: conclusive."},{"label":"Correlazione","detail":"Sia… sia, o… o, non solo… ma anche distribuiscono il collegamento."},{"label":"Stesso livello","detail":"Anche due subordinate possono essere coordinate; senza congiunzioni si ha asindeto."}]},"pitfalls":[{"mistake":"Ogni e introduce una proposizione.","correction":"Verificare che siano presenti due predicati.","why":"La congiunzione può collegare anche singole parole."},{"mistake":"Una coordinata non può essere subordinata.","correction":"Precisare entrambi i rapporti.","why":"Una proposizione può essere coordinata a un’altra dipendente e subordinata alla reggente comune."}],"recap":["La coordinazione unisce elementi con la stessa funzione o proposizioni dello stesso livello.","Le copulative aggiungono informazioni: e ha valore affermativo, né collega elementi negativi.","Le esplicative o dichiarative chiariscono una precedente affermazione, con cioè, infatti, ossia.","La coordinazione con una congiunzione si chiama per sindeto; quella realizzata senza congiunzioni, attraverso virgola, punto e virgola o due punti, si chiama per asindeto."],"review":[{"question":"Quale rapporto esprime oppure?","answer":"Un’alternativa: la coordinazione è disgiuntiva."},{"question":"Che differenza c’è tra infatti e quindi?","answer":"Infatti presenta una spiegazione o giustificazione; quindi presenta una conclusione."},{"question":"Che cosa significa coordinazione per asindeto?","answer":"Le proposizioni sono collegate senza congiunzione esplicita, attraverso la punteggiatura e il rapporto di senso."}],"levels":{"base":{"focus":"Riconoscere copulative, avversative e disgiuntive.","example":{"sentence":"Luca disegna e Sara cuce.","explanation":"E collega due proposizioni con predicati e soggetti distinti."}},"consolidamento":{"focus":"Riconoscere una coordinata conclusiva.","example":{"sentence":"La colla è asciutta, quindi possiamo procedere.","explanation":"Quindi possiamo procedere è una coordinata conclusiva. Presenta la possibilità di procedere come conclusione tratta dalla prima informazione."}},"avanzato":{"focus":"Analizzare coordinate fra subordinate e collegamenti senza congiunzione.","example":{"sentence":"Credo che il tavolo sia stabile e che il piano sia uniforme.","explanation":"Le due oggettive sono coordinate fra loro e dipendono entrambe da Credo."}}},"simplified":{"lead":"Le coordinate stanno sullo stesso piano.","steps":["Cerca due predicati.","Trova la parola che li collega.","Scegli il rapporto: aggiunta, contrasto, scelta o altro."],"example":{"sentence":"Luca legge e Sara disegna.","explanation":"E aggiunge una seconda azione: la proposizione è coordinata copulativa."}},"pei":{"rule":"Le coordinate stanno sullo stesso piano. E aggiunge; ma contrappone; oppure offre una scelta.","example":{"sentence":"Luca legge e Sara disegna.","explanation":"E aggiunge una seconda azione: la proposizione è coordinata copulativa."}},"trackExamples":{"moda":{"sentence":"Tagliamo la stoffa oppure prepariamo il cartamodello.","explanation":"Oppure collega due alternative: coordinata disgiuntiva."},"arredo":{"sentence":"Montiamo le ante oppure prepariamo i ripiani.","explanation":"Oppure collega due alternative: coordinata disgiuntiva."},"liuteria":{"sentence":"Accordiamo il violino oppure controlliamo l’archetto.","explanation":"Oppure collega due alternative: coordinata disgiuntiva."}},"anchor":{"sentence":"Il righello è sparito, quindi misuriamo con quello di Sara.","explanation":"Il righello è sparito è principale; quindi misuriamo con quello di Sara è coordinata conclusiva. Quindi presenta la decisione come conclusione.","memory":"Quindi porta una conclusione sullo stesso piano."}},{"topic":"Subordinate e gradi","area":"periodo","lead":"Una subordinata dipende da una reggente; il suo grado indica quanti passaggi la separano dalla principale.","objectives":["Trovare la reggente di ogni dipendente","Assegnare il grado di subordinazione","Distinguere successione delle frasi e struttura dei legami"],"sections":[{"title":"Dipendere da una proposizione","text":"Una subordinata svolge una funzione rispetto a una proposizione reggente: ne completa un elemento oppure aggiunge un’informazione di tempo, causa, scopo e così via. La dipendenza può essere segnalata da una congiunzione, da un pronome relativo o da una costruzione con infinito, participio o gerundio.\n\nPer individuarla non basta cercare una parola introduttiva: ricostruisci il significato e il collegamento. Una dipendente può stare prima o dopo la reggente, e può anche interromperne la sequenza. Scrivere accanto a ogni dipendente il nome della sua reggente rende visibili i passaggi della struttura.","examples":[{"sentence":"Quando suona la campanella, usciamo.","explanation":"La temporale dipende da usciamo e ne precisa il momento."},{"sentence":"Usciamo quando suona la campanella.","explanation":"Lo spostamento non cambia il rapporto di dipendenza."}]},{"title":"Principale e reggente sono ruoli diversi","text":"Principale indica la proposizione che non dipende sintatticamente da altre. Reggente indica la proposizione da cui una subordinata dipende direttamente.\n\nLa principale può quindi essere reggente, ma anche una subordinata può reggerne un’altra. Per assegnare questi ruoli chiediti prima quale segmento abbia una dipendente e poi se esso dipenda a sua volta da un altro. Questa doppia osservazione permette di analizzare periodi lunghi senza chiamare principale ogni proposizione che introduce una nuova informazione.","examples":[{"sentence":"So che Marta pensa di partire.","explanation":"So è principale; che Marta pensa è subordinata e regge di partire."}]},{"title":"Come si contano i gradi","text":"Una subordinata di primo grado dipende direttamente dalla principale o da una proposizione coordinata indipendente. Una subordinata di secondo grado dipende da una subordinata di primo; una di terzo dipende da una di secondo.\n\nIl grado misura la profondità del legame, non la posizione nella frase e neppure l’importanza dell’informazione. Due subordinate collocate una dopo l’altra possono essere entrambe di primo grado, se si collegano direttamente alla stessa reggente. Disegnare frecce aiuta a evitare conteggi automatici.","examples":[{"sentence":"Quando arriviamo, apriamo l’aula perché è buio.","explanation":"Quando arriviamo e perché è buio dipendono entrambe da apriamo l’aula: sono di primo grado."}]},{"title":"Riconoscere legami e alternative","text":"Per completare l’analisi scrivi per ogni subordinata il tipo, la forma, il grado e la reggente. Le coordinate a una subordinata condividono il livello della proposizione a cui si coordinano.\n\nIn alcuni periodi un’espansione può collegarsi a più segmenti: il contesto e il senso permettono di motivare la scelta, ma non sempre impongono un’unica lettura. Non nascondere l’ambiguità: indica le alternative e chiarisci quale informazione cambierebbe. La linearità del testo non riproduce sempre la gerarchia delle dipendenze.","examples":[{"sentence":"Vedo l’allievo che ripara il leggio mentre ascolta musica.","explanation":"La temporale può collegarsi a ripara, e allora è di secondo grado; il contesto deve chiarire chi ascolta e quando."}]}],"diagram":{"title":"La gerarchia delle dipendenze","steps":[{"label":"Principale","detail":"Non dipende da altre proposizioni."},{"label":"Primo grado","detail":"Dipende direttamente dalla principale o da una coordinata indipendente."},{"label":"Secondo grado","detail":"Dipende da una subordinata di primo grado."},{"label":"Reggente","detail":"Qualunque proposizione che abbia una dipendente, anche se è essa stessa subordinata."},{"label":"Stesso grado","detail":"Due dipendenti della stessa reggente non formano automaticamente una catena."}]},"pitfalls":[{"mistake":"La terza proposizione è di terzo grado.","correction":"Seguire i passaggi di dipendenza.","why":"Il grado non coincide con il numero d’ordine."},{"mistake":"Ogni reggente è principale.","correction":"Controllare se dipende da un’altra proposizione.","why":"La subordinata può avere a sua volta una dipendente."}],"recap":["Una subordinata svolge una funzione rispetto a una proposizione reggente: ne completa un elemento oppure aggiunge un’informazione di tempo, causa, scopo e così via.","Principale indica la proposizione che non dipende sintatticamente da altre.","Una subordinata di primo grado dipende direttamente dalla principale o da una proposizione coordinata indipendente.","Per completare l’analisi scrivi per ogni subordinata il tipo, la forma, il grado e la reggente."],"review":[{"question":"Da che cosa dipende una subordinata di secondo grado?","answer":"Da una subordinata di primo grado."},{"question":"Due subordinate consecutive hanno necessariamente gradi diversi?","answer":"No: possono dipendere entrambe dalla stessa reggente ed essere dello stesso grado."},{"question":"Come si analizza una dipendente con collegamento ambiguo?","answer":"Si legge il contesto, si motivano le possibilità e si dichiara quando non è disponibile una sola interpretazione."}],"levels":{"base":{"focus":"Collegare una subordinata alla principale.","example":{"sentence":"Quando suona la campanella, usciamo.","explanation":"La temporale dipende da usciamo e ne precisa il momento."}},"consolidamento":{"focus":"Distinguere dipendenti di primo e secondo grado.","example":{"sentence":"So che Marta pensa di partire.","explanation":"So è principale; che Marta pensa è subordinata e regge di partire."}},"avanzato":{"focus":"Motivare l’aggancio di una subordinata in un periodo complesso.","example":{"sentence":"Vedo l’allievo che ripara il leggio mentre ascolta musica.","explanation":"La temporale può collegarsi a ripara, e allora è di secondo grado; il contesto deve chiarire chi ascolta e quando."}}},"simplified":{"lead":"Una parte può dipendere da un’altra parte, che a sua volta dipende dalla principale.","steps":["Trova la principale.","Collega a essa le dipendenti di primo grado.","Collega alle dipendenti le eventuali parti di secondo grado."],"example":{"sentence":"So che parti.","explanation":"So è principale. Che parti dipende direttamente da so: primo grado."}},"pei":{"rule":"Segui i collegamenti: dalla principale al primo grado, poi al secondo.","example":{"sentence":"So che parti.","explanation":"So è principale. Che parti dipende direttamente da so: primo grado."}},"trackExamples":{"moda":{"sentence":"So che la sarta spera di finire.","explanation":"Che la sarta spera è di primo grado; di finire è di secondo."},"arredo":{"sentence":"So che il falegname spera di finire.","explanation":"Che il falegname spera è di primo grado; di finire è di secondo."},"liuteria":{"sentence":"So che il liutaio spera di finire.","explanation":"Che il liutaio spera è di primo grado; di finire è di secondo."}},"anchor":{"sentence":"So che Sara spera di trovare le forbici.","explanation":"So è principale. Che Sara spera è oggettiva di primo grado e regge di trovare le forbici, oggettiva implicita di secondo grado.","memory":"Segui tre gradini: so → spera → trovare."}},{"topic":"Esplicite e implicite","area":"periodo","lead":"Una subordinata è esplicita o implicita secondo la forma del suo verbo; la funzione si riconosce invece dal rapporto di significato.","objectives":["Distinguere modi finiti e indefiniti","Ricostruire il soggetto delle implicite","Trasformare una subordinata senza cambiarne il significato"],"sections":[{"title":"La forma esplicita","text":"Una subordinata esplicita ha il verbo in un modo finito: indicativo, congiuntivo o condizionale. Persona e numero aiutano a individuare il soggetto, che può comunque essere sottinteso. La proposizione è introdotta spesso da una congiunzione, da un pronome o da un avverbio.\n\nEsplicita non significa che tutte le parole siano espresse, né che il messaggio sia necessariamente più chiaro: il termine riguarda la forma verbale. La funzione, come causale o finale, richiede un’analisi separata del significato. Nell’analisi indica separatamente forma e funzione: per esempio causale implicita, finale esplicita oppure temporale implicita.","examples":[{"sentence":"Credo che Elena abbia finito.","explanation":"Abbia finito è un congiuntivo: la subordinata è esplicita."},{"sentence":"Non so se verrebbe.","explanation":"Verrebbe è un condizionale: anche questa subordinata è esplicita."}]},{"title":"La forma implicita","text":"Una subordinata implicita ha il verbo in un modo indefinito: infinito, participio o gerundio. Può essere introdotta da una preposizione oppure presentarsi senza un collegamento espresso.\n\nIl suo soggetto deve essere ricostruito dal contesto. Spesso coincide con quello della reggente, soprattutto con l’infinito e il gerundio, ma esistono costruzioni con soggetto diverso o proprio, come i participi assoluti. Non trattare quindi la coincidenza dei soggetti come una legge valida senza eccezioni per ogni costruzione.","examples":[{"sentence":"Finito il lavoro, gli allievi riordinarono.","explanation":"Finito il lavoro è implicita al participio e ha come soggetto il lavoro, diverso da gli allievi."}]},{"title":"Trasformare conservando i rapporti","text":"Per passare da una forma all’altra mantieni il soggetto, il tempo relativo e il rapporto logico. Un infinito passato esprime anteriorità rispetto alla reggente; quello presente può esprimere contemporaneità o posteriorità secondo il verbo e il contesto.\n\nLa trasformazione non è sempre possibile con la stessa struttura: se i soggetti cambiano, può essere necessaria una forma esplicita. Non basta sostituire che con di: occorre controllare quale costruzione è ammessa dal verbo reggente e che cosa viene comunicato.","examples":[{"sentence":"Spero di completare il modello → Spero che tu completi il modello.","explanation":"La seconda frase cambia soggetto e significato: non è una trasformazione equivalente della prima."}]},{"title":"Riconoscere la funzione dell’implicita","text":"Gerundi e participi possono esprimere rapporti diversi, che non si ricavano dalla sola forma. Lavorando può significare mentre lavorava, poiché lavorava, se lavorasse oppure mediante il lavoro, secondo il contesto.\n\nUna buona analisi propone una parafrasi esplicita e verifica che rispetti la situazione. Distingui infine le subordinate dalle catene verbali: un servile con infinito forma normalmente un solo predicato. Anche un participio usato come semplice aggettivo non crea automaticamente una proposizione dipendente nel periodo.","examples":[{"sentence":"Misurando con attenzione, abbiamo scoperto l’errore.","explanation":"Nel contesto il gerundio indica il mezzo: mediante una misurazione attenta. Non basta chiamarlo temporale perché è un gerundio."}]}],"diagram":{"title":"Due forme della subordinata","steps":[{"label":"Esplicita","detail":"Indicativo, congiuntivo o condizionale: che lavori, se verrebbe."},{"label":"Implicita","detail":"Infinito, participio o gerundio: di lavorare, finito il lavoro, lavorando."},{"label":"Soggetto","detail":"Nell’implicita va ricostruito: non coincide sempre con quello della reggente."},{"label":"Funzione","detail":"Tempo, causa, fine o altro dipendono dal senso, non dal solo modo verbale."},{"label":"Trasformazione","detail":"Conserva soggetti e rapporti temporali; verifica la costruzione del verbo reggente."}]},"pitfalls":[{"mistake":"Implicita significa soggetto sempre uguale.","correction":"Ricostruire il soggetto della specifica costruzione.","why":"Esistono implicite con soggetto proprio o diverso da quello della reggente."},{"mistake":"Ogni infinito apre una subordinata.","correction":"Distinguere il nuovo nucleo dalla catena verbale.","why":"Devo studiare forma normalmente un solo predicato servile."}],"recap":["Una subordinata esplicita ha il verbo in un modo finito: indicativo, congiuntivo o condizionale.","Una subordinata implicita ha il verbo in un modo indefinito: infinito, participio o gerundio.","Per passare da una forma all’altra mantieni il soggetto, il tempo relativo e il rapporto logico.","Gerundi e participi possono esprimere rapporti diversi, che non si ricavano dalla sola forma."],"review":[{"question":"Quali modi formano le subordinate implicite?","answer":"Infinito, participio e gerundio."},{"question":"Che cosa devi conservare trasformando una subordinata?","answer":"Soggetti, rapporto temporale e significato logico, verificando la costruzione ammessa dalla reggente."},{"question":"Come riconosci il valore di un gerundio?","answer":"Dal contesto e da una parafrasi esplicita coerente, non dalla sola desinenza."}],"levels":{"base":{"focus":"Distinguere forme finite e indefinite.","example":{"sentence":"Credo che Elena abbia finito.","explanation":"Abbia finito è un congiuntivo: la subordinata è esplicita."}},"consolidamento":{"focus":"Trasformare subordinate con lo stesso soggetto.","example":{"sentence":"Finito il lavoro, gli allievi riordinarono.","explanation":"Finito il lavoro è implicita al participio e ha come soggetto il lavoro, diverso da gli allievi."}},"avanzato":{"focus":"Valutare soggetti diversi e più letture di un gerundio.","example":{"sentence":"Misurando con attenzione, abbiamo scoperto l’errore.","explanation":"Nel contesto il gerundio indica il mezzo: mediante una misurazione attenta. Non basta chiamarlo temporale perché è un gerundio."}}},"simplified":{"lead":"La forma della subordinata dipende dal suo verbo.","steps":["Trova il verbo della subordinata.","Con che lavori la forma è esplicita.","Con di lavorare la forma è implicita."],"example":{"sentence":"Spero di finire.","explanation":"Di finire ha il verbo all’infinito: è una subordinata implicita."}},"pei":{"rule":"Esplicita: che Luca lavori. Implicita: di lavorare. Guarda la forma del verbo.","example":{"sentence":"Spero di finire.","explanation":"Di finire ha il verbo all’infinito: è una subordinata implicita."}},"trackExamples":{"moda":{"sentence":"La sarta pensa di aver finito.","explanation":"Di aver finito è implicita; l’infinito passato indica un’azione precedente al pensiero."},"arredo":{"sentence":"Il falegname pensa di aver finito.","explanation":"Di aver finito è implicita; l’infinito passato indica un’azione precedente al pensiero."},"liuteria":{"sentence":"Il liutaio pensa di aver finito.","explanation":"Di aver finito è implicita; l’infinito passato indica un’azione precedente al pensiero."}},"anchor":{"sentence":"Spero di ritrovare il righello prima della verifica.","explanation":"Di ritrovare il righello prima della verifica è oggettiva implicita: il verbo è all’infinito e il soggetto è io. Spero che io ritrovi il righello ne rende esplicito il soggetto, ma è meno naturale.","memory":"Per la forma guarda il verbo: ritrovare è infinito."}},{"topic":"Completive","area":"periodo","lead":"Le completive esprimono un contenuto richiesto o precisato dalla reggente: possono fare da soggetto, oggetto o spiegazione di un nome.","objectives":["Distinguere soggettiva e oggettiva","Riconoscere la dichiarativa","Usare forme esplicite e implicite coerenti"],"sections":[{"title":"Una funzione necessaria al contenuto","text":"Le completive, dette anche sostantive, svolgono funzioni simili a quelle di un nome: possono essere soggetto, oggetto o precisazione di un elemento della reggente. Non esprimono semplicemente una circostanza, come il momento o la causa.\n\nPer riconoscerle domanda quale posto occupino nella costruzione: che cosa è necessario, che cosa penso, quale contenuto ha una certezza. La parola che non basta per classificarle, perché introduce anche altre subordinate ed è inoltre un pronome nelle relative. La sostituzione con un nome è una prova di funzione, da verificare nella frase completa.","examples":[{"sentence":"È necessario che tutti ascoltino.","explanation":"Che tutti ascoltino svolge la funzione di soggetto: ciò che è necessario è l’ascolto di tutti."},{"sentence":"Penso che tutti ascoltino.","explanation":"Che tutti ascoltino esprime ciò che penso: è una completiva oggettiva."}]},{"title":"La soggettiva","text":"La soggettiva fa da soggetto alla reggente. Compare frequentemente con verbi impersonali, espressioni con si impersonale e costruzioni come è utile, è probabile, sembra opportuno. Può essere esplicita, spesso con che e congiuntivo, oppure implicita con l’infinito, talvolta preceduto da di.\n\nLa forma dipende dalla reggente e dal valore comunicativo. Per controllare la funzione sostituisci la subordinata con un nome o con ciò: È utile ciò, cioè questo comportamento. L’ordine delle parole non decide la funzione.","examples":[{"sentence":"È utile controllare le misure.","explanation":"Controllare le misure è soggettiva implicita: il controllo è ciò che risulta utile."}]},{"title":"L’oggettiva","text":"L’oggettiva esprime l’oggetto del pensiero, dell’affermazione, della percezione o della volontà indicati dal verbo reggente. L’esplicita è spesso introdotta da che; l’implicita usa l’infinito, frequentemente preceduto da di.\n\nLa coincidenza del soggetto favorisce l’infinito, ma la costruzione effettiva dipende dal verbo. L’indicativo presenta generalmente un contenuto come asserito, il congiuntivo può accompagnare opinione, dubbio o volontà: non scegliere il modo con una formula unica, ignorando verbo, registro e intenzione del parlante.","examples":[{"sentence":"La docente desidera che il gruppo controlli le misure.","explanation":"Che il gruppo controlli le misure è oggettiva esplicita; il congiuntivo è coerente con il desiderio."}]},{"title":"Dichiarative e interrogative indirette","text":"La dichiarativa precisa il contenuto di un nome, aggettivo o pronome presente nella reggente: certezza, timore, questo. Non è l’oggetto direttamente richiesto dal verbo.\n\nNell’analisi scolastica si distinguono inoltre le interrogative indirette, che riportano una domanda o un dubbio e possono avere funzione completiva. Confronta Credo che arriverà, Ho la certezza che arriverà e Non so se arriverà. Nel primo caso il contenuto dipende dal verbo, nel secondo precisa certezza, nel terzo conserva una domanda alla quale manca risposta.","examples":[{"sentence":"Ho la certezza che il telaio regga.","explanation":"La dichiarativa precisa il nome certezza: non va chiamata oggettiva soltanto perché è introdotta da che."}]}],"diagram":{"title":"Tre funzioni del contenuto","steps":[{"label":"Soggettiva","detail":"È utile che ascoltiate: il contenuto fa da soggetto."},{"label":"Oggettiva","detail":"Penso che ascoltiate: il contenuto completa il verbo come oggetto."},{"label":"Dichiarativa","detail":"Ho la speranza che ascoltiate: il contenuto precisa speranza."},{"label":"Domanda riportata","detail":"Non so se ascoltiate: interrogativa indiretta."},{"label":"Forma","detail":"Che con modo finito; infinito nelle costruzioni che lo ammettono."}]},"pitfalls":[{"mistake":"Dopo che c’è sempre un’oggettiva.","correction":"Riconoscere la funzione del segmento.","why":"Che può introdurre soggettive, dichiarative e altri tipi di subordinata."},{"mistake":"In È necessario studiare, studiare è oggetto.","correction":"Riconoscere una soggettiva implicita.","why":"La reggente non ha un altro soggetto: è lo studio a essere necessario."}],"recap":["Le completive, dette anche sostantive, svolgono funzioni simili a quelle di un nome: possono essere soggetto, oggetto o precisazione di un elemento della reggente.","La soggettiva fa da soggetto alla reggente.","L’oggettiva esprime l’oggetto del pensiero, dell’affermazione, della percezione o della volontà indicati dal verbo reggente.","La dichiarativa precisa il contenuto di un nome, aggettivo o pronome presente nella reggente: certezza, timore, questo."],"review":[{"question":"Come distingui soggettiva e oggettiva?","answer":"La soggettiva svolge la funzione di soggetto; l’oggettiva esprime l’oggetto richiesto dal verbo reggente."},{"question":"Quale elemento precisa una dichiarativa?","answer":"Un nome, un aggettivo o un pronome della reggente, secondo la costruzione."},{"question":"Non so se verrà riporta una certezza?","answer":"No: conserva una domanda o un dubbio; se verrà è interrogativa indiretta."}],"levels":{"base":{"focus":"Confrontare È utile che e Penso che.","example":{"sentence":"È necessario che tutti ascoltino.","explanation":"Che tutti ascoltino svolge la funzione di soggetto: ciò che è necessario è l’ascolto di tutti."}},"consolidamento":{"focus":"Distinguere oggettiva e dichiarativa.","example":{"sentence":"Penso che tutti ascoltino. Ho la certezza che il telaio regga.","explanation":"Che tutti ascoltino è oggettiva: completa direttamente il verbo penso. Che il telaio regga è dichiarativa: precisa il contenuto del nome certezza."}},"avanzato":{"focus":"Motivare forma e modo verbale in base alla reggente.","example":{"sentence":"Ho la certezza che il telaio regga.","explanation":"La dichiarativa precisa il nome certezza: non va chiamata oggettiva soltanto perché è introdotta da che."}}},"simplified":{"lead":"Alcune subordinate esprimono il contenuto necessario alla frase.","steps":["Trova il verbo della reggente.","Chiedi quale funzione svolge il contenuto.","Distingui soggetto, oggetto o spiegazione di una parola."],"example":{"sentence":"È utile ascoltare.","explanation":"Ascoltare fa da soggetto: è l’ascolto a essere utile."}},"pei":{"rule":"Chiedi: questa parte è il soggetto, l’oggetto o spiega una parola?","example":{"sentence":"È utile ascoltare.","explanation":"Ascoltare fa da soggetto: è l’ascolto a essere utile."}},"trackExamples":{"moda":{"sentence":"La sarta pensa che la misura sia corretta.","explanation":"La subordinata esprime il contenuto del pensiero: oggettiva."},"arredo":{"sentence":"Il falegname pensa che la misura sia corretta.","explanation":"La subordinata esprime il contenuto del pensiero: oggettiva."},"liuteria":{"sentence":"Il liutaio pensa che la misura sia corretta.","explanation":"La subordinata esprime il contenuto del pensiero: oggettiva."}},"anchor":{"sentence":"È necessario che qualcuno ritrovi le forbici.","explanation":"Che qualcuno ritrovi le forbici fa da soggetto di è necessario: ciò che è necessario è il ritrovamento. È una soggettiva esplicita.","memory":"Prova il nome: il ritrovamento delle forbici è necessario."}},{"topic":"Relative","area":"periodo","lead":"La relativa si collega a un antecedente e lo precisa; il pronome relativo collega le proposizioni e svolge una funzione nella dipendente.","objectives":["Individuare antecedente e pronome relativo","Distinguere relative restrittive ed esplicative","Riconoscere forme implicite e relative con sfumature logiche"],"sections":[{"title":"Due lavori per un pronome","text":"La relativa precisa un nome o un pronome della reggente, chiamato antecedente. È introdotta da pronomi come che, cui, il quale oppure da avverbi relativi come dove, quando hanno un antecedente di luogo o di tempo adatto.\n\nIl pronome svolge due lavori: collega le proposizioni e sostituisce l’antecedente dentro la subordinata. Per individuarne la funzione riscrivi mentalmente la dipendente ripetendo quel nome. Che relativo può essere soggetto o complemento oggetto; per altre funzioni servono forme appropriate.","examples":[{"sentence":"Il mobile che vedi è nuovo.","explanation":"Che riprende il mobile ed è oggetto di vedi: tu vedi il mobile."},{"sentence":"Il mobile che occupa l’angolo è nuovo.","explanation":"Che riprende il mobile ed è soggetto di occupa."}]},{"title":"Cui, il quale e l’antecedente","text":"Cui è invariabile e si combina con le preposizioni richieste dal verbo o dal rapporto espresso: a cui, di cui, con cui. Il quale concorda invece con l’antecedente in genere e numero e aiuta quando il riferimento è poco chiaro.\n\nLa costruzione il cui indica un rapporto di possesso e l’articolo concorda con il nome che segue. Non scegliere una preposizione per abitudine: ricostruisci la frase semplice e conserva la reggenza, per esempio collaborare con qualcuno o affidarsi a qualcuno.","examples":[{"sentence":"La compagna con cui lavoro è precisa.","explanation":"Con cui riprende la compagna; la preposizione dipende da lavoro con la compagna."}]},{"title":"Restringere o aggiungere informazioni","text":"Una relativa restrittiva serve a identificare un gruppo o un referente fra più possibili: la sua eliminazione cambia l’estensione del nome. Una relativa esplicativa aggiunge invece un’informazione su un referente già individuato ed è normalmente isolata da virgole.\n\nLa differenza modifica il messaggio e non è soltanto una pausa di lettura. Per interpretarla considera il contesto: Gli allievi che hanno finito escono seleziona alcuni allievi; con le virgole si presenta invece l’intero gruppo come già pronto a uscire.","examples":[{"sentence":"Gli strumenti, che sono stati controllati, sono pronti.","explanation":"La relativa esplicativa aggiunge che tutti gli strumenti di cui si parla sono stati controllati."}]},{"title":"Forme implicite e valori particolari","text":"La relativa esplicita usa normalmente l’indicativo per presentare un fatto; il congiuntivo può esprimere ricerca, possibilità o qualità desiderata. Esistono relative implicite con da e infinito, o altre costruzioni infinitive e participiali.\n\nNon tutte le grammatiche delimitano allo stesso modo i participi con funzione di attributo: segui il contesto dell’analisi. Relative come Cerco qualcuno che mi aiuti assumono anche una sfumatura finale. Chi, chiunque e quanto possono fondere antecedente e relativo: chi lavora equivale a colui che lavora.","examples":[{"sentence":"Cerco un tessuto che resista al calore.","explanation":"Che resista è relativa al congiuntivo: descrive una proprietà richiesta, senza affermare che il tessuto sia già stato trovato."}]},{"title":"Le sfumature delle relative improprie","text":"Una relativa resta collegata al suo antecedente; in alcuni contesti può anche suggerire una circostanza. Si parla allora di relativa impropria o circostanziale. La sfumatura può essere temporale, causale, finale, consecutiva o concessiva.\n\nUna parafrasi aiuta a formulare l’interpretazione, ma non è sempre l’unica possibile: verifica se il rapporto sia effettivamente sostenuto dal contesto e specifica che la costruzione rimane relativa.","examples":[{"sentence":"Ho salutato Amir, che entrava in aula.","explanation":"Che entrava può essere interpretata anche con una sfumatura temporale: mentre entrava."},{"sentence":"Cerco una scatola che contenga tutti i pennelli.","explanation":"La relativa può descrivere una proprietà richiesta e avere una sfumatura finale."},{"sentence":"Nora, che aveva studiato molto, non superò la prova.","explanation":"Nel contesto la relativa può assumere una sfumatura concessiva."},{"sentence":"Ammiriamo Lia, che conosce bene i materiali.","explanation":"La relativa può anche suggerire una ragione dell’ammirazione: perché conosce bene i materiali."},{"sentence":"Vorrei un materiale che resista alla pioggia.","explanation":"Che riprende materiale e precisa una caratteristica desiderata; alcune analisi riconoscono anche una sfumatura finale o finale-consecutiva. L’interpretazione dipende dal contesto."}]}],"diagram":{"title":"Un nome ripreso nella dipendente","steps":[{"label":"Antecedente","detail":"Il nome o pronome precisato: il mobile che vedi."},{"label":"Pronome","detail":"Che può essere soggetto o oggetto; cui e il quale ammettono le preposizioni richieste."},{"label":"Restrittiva","detail":"Seleziona quali elementi: gli allievi che hanno finito."},{"label":"Esplicativa","detail":"Aggiunge informazioni e si isola con virgole."},{"label":"Altre forme","detail":"Un lavoro da finire: implicita. Chi lavora: chi equivale a colui che."}]},"pitfalls":[{"mistake":"Che relativo è sempre soggetto.","correction":"Ricostruire la dipendente ripetendo l’antecedente.","why":"In il modello che preparo, che è oggetto di preparo."},{"mistake":"Le virgole non cambiano il senso.","correction":"Distinguere il gruppo selezionato dall’informazione aggiunta.","why":"Restrittiva ed esplicativa possono riferirsi a insiemi diversi."}],"recap":["La relativa precisa un nome o un pronome della reggente, chiamato antecedente.","Cui è invariabile e si combina con le preposizioni richieste dal verbo o dal rapporto espresso: a cui, di cui, con cui.","Una relativa restrittiva serve a identificare un gruppo o un referente fra più possibili: la sua eliminazione cambia l’estensione del nome.","La relativa esplicita usa normalmente l’indicativo per presentare un fatto; il congiuntivo può esprimere ricerca, possibilità o qualità desiderata."],"review":[{"question":"Quali sono i due compiti del pronome relativo?","answer":"Collegare le proposizioni e svolgere una funzione sintattica nella relativa."},{"question":"Come riconosci che relativo rispetto a che congiunzione?","answer":"Il relativo riprende un antecedente e occupa un posto nella dipendente; la congiunzione non sostituisce un nome."},{"question":"Che cosa significa un lavoro da completare?","answer":"Un lavoro che deve essere completato: da completare è una relativa implicita con valore anche di necessità."}],"levels":{"base":{"focus":"Trovare antecedente e pronome relativo.","example":{"sentence":"Il mobile che vedi è nuovo.","explanation":"Che riprende il mobile ed è oggetto di vedi: tu vedi il mobile."}},"consolidamento":{"focus":"Distinguere che soggetto e che oggetto.","example":{"sentence":"La squadra che lavora qui usa la sega che hai riparato.","explanation":"Il primo che riprende la squadra ed è soggetto di lavora: la squadra lavora qui. Il secondo che riprende la sega ed è oggetto di hai riparato: tu hai riparato la sega."}},"avanzato":{"focus":"Interpretare restrittive, esplicative e congiuntivo nella relativa.","example":{"sentence":"Cerco un tessuto che resista al calore.","explanation":"Che resista è relativa al congiuntivo: descrive una proprietà richiesta, senza affermare che il tessuto sia già stato trovato."}}},"simplified":{"lead":"La relativa precisa un nome.","steps":["Trova il nome precisato.","Trova che, cui o un’altra parola relativa.","Ripeti il nome nella dipendente per capire la sua funzione."],"example":{"sentence":"Il libro che leggo è nuovo.","explanation":"Che leggo precisa il libro. Che significa il libro ed è oggetto di leggo."}},"pei":{"rule":"La relativa dice qualcosa su un nome: il tavolo che vedi.","example":{"sentence":"Il libro che leggo è nuovo.","explanation":"Che leggo precisa il libro. Che significa il libro ed è oggetto di leggo."}},"trackExamples":{"moda":{"sentence":"Il tessuto che scegliamo è leggero.","explanation":"Che riprende il tessuto ed è oggetto di scegliamo."},"arredo":{"sentence":"Il legno che scegliamo è leggero.","explanation":"Che riprende il legno ed è oggetto di scegliamo."},"liuteria":{"sentence":"L’archetto che scegliamo è leggero.","explanation":"Che riprende l’archetto ed è oggetto di scegliamo."}},"anchor":{"sentence":"Le forbici che cerchi sono accanto al tuo gomito.","explanation":"Che cerchi precisa le forbici. Che riprende forbici ed è oggetto di cerchi: tu cerchi le forbici. La relativa è restrittiva.","memory":"Ripeti il nome: cerchi le forbici. Così trovi il lavoro di che."}},{"topic":"Causali","area":"periodo","lead":"La causale presenta la ragione di un fatto o di un’affermazione: chiarisce per quale motivo qualcosa avviene.","objectives":["Riconoscere il motivo di un fatto","Distinguere causa e scopo","Interpretare causali esplicite e implicite"],"sections":[{"title":"Il motivo che spiega un fatto","text":"La subordinata causale esprime il motivo per cui avviene quanto è detto nella reggente. Risponde alla domanda per quale ragione, ma la risposta deve essere coerente con il contesto.\n\nLa causa è presentata come spiegazione del fatto, mentre lo scopo è un risultato cercato. La causale può precedere la reggente, soprattutto quando introduce una situazione già nota, oppure seguirla quando offre una spiegazione nuova. In entrambe le posizioni il legame rimane quello fra un fatto e la sua motivazione.","examples":[{"sentence":"Poiché mancava una vite, abbiamo fermato il montaggio.","explanation":"La mancanza della vite motiva l’interruzione: è una causale."},{"sentence":"Abbiamo fermato il montaggio perché mancava una vite.","explanation":"La causale segue la reggente e fornisce la stessa spiegazione."}]},{"title":"Le forme esplicite","text":"Le causali esplicite sono introdotte da perché, poiché, siccome, dato che, visto che, dal momento che e altre locuzioni. Usano normalmente l’indicativo quando presentano il motivo come un fatto.\n\nIl congiuntivo può comparire se la causa viene negata, discussa o presentata in particolari costruzioni; il condizionale può segnalare un motivo riferito come eventuale o non confermato. Non basta dunque associare causale e indicativo senza eccezioni. Anche l’ordine delle proposizioni e il registro influenzano la scelta dell’introduttore.","examples":[{"sentence":"Non ho rifatto il disegno perché fosse brutto, ma perché mancava una quota.","explanation":"La prima causa viene respinta; il congiuntivo non la trasforma in finale."}]},{"title":"Le forme implicite","text":"Le causali implicite possono avere il gerundio, il participio oppure l’infinito, spesso introdotto da per. L’infinito passato è frequente quando il motivo è precedente al fatto della reggente.\n\nIl gerundio richiede un soggetto ricostruibile; il participio può avere un soggetto proprio. Prima di assegnare il valore causale, prova a esplicitare con poiché: se la parafrasi modifica il senso, il rapporto potrebbe essere temporale, strumentale o di altro tipo. Forma indefinita e funzione logica devono essere tenute distinte.","examples":[{"sentence":"Avendo perso il campione, abbiamo ripetuto la prova.","explanation":"Avendo perso il campione equivale qui a poiché avevamo perso il campione: causale implicita."}]},{"title":"Causa, scopo e spiegazione del dire","text":"Perché introduce sia causali sia finali. Nella causale il motivo spiega un fatto; nella finale un obiettivo orienta un’azione. Osserva il contenuto e il modo verbale, senza usarlo come unico indizio.\n\nEsistono inoltre causali che motivano l’affermazione del parlante più che l’evento descritto: Deve essere in laboratorio, perché la luce è accesa. La luce non causa la presenza della persona; è l’indizio su cui si basa la conclusione. Questa lettura richiede di considerare l’intero ragionamento comunicativo.","examples":[{"sentence":"Abbassiamo la tenda perché la luce disturba.","explanation":"La luce che disturba è il motivo già presente; perché non introduce uno scopo."}]}],"diagram":{"title":"Il motivo di un fatto","steps":[{"label":"Rapporto","detail":"Il motivo spiega perché avviene il fatto: ci fermiamo perché manca il filo."},{"label":"Esplicita","detail":"Perché, poiché, siccome, dato che; di solito indicativo per una causa presentata come reale."},{"label":"Implicita","detail":"Gerundio, participio, per e infinito: avendo perso il campione."},{"label":"Confronto","detail":"Causa = ragione; fine = obiettivo. Perché può introdurre entrambi."},{"label":"Ragionamento","detail":"Una causale può giustificare una deduzione, senza essere la causa materiale dell’evento."}]},"pitfalls":[{"mistake":"Perché introduce sempre una causale.","correction":"Distinguere ragione e obiettivo.","why":"In lavoro perché tutto riesca, perché indica uno scopo."},{"mistake":"Ogni gerundio ha valore causale.","correction":"Provare una parafrasi e leggere il contesto.","why":"Il gerundio può esprimere diversi rapporti logici."}],"recap":["La subordinata causale esprime il motivo per cui avviene quanto è detto nella reggente.","Le causali esplicite sono introdotte da perché, poiché, siccome, dato che, visto che, dal momento che e altre locuzioni.","Le causali implicite possono avere il gerundio, il participio oppure l’infinito, spesso introdotto da per.","Perché introduce sia causali sia finali."],"review":[{"question":"Qual è la differenza tra causa e scopo?","answer":"La causa spiega il fatto; lo scopo è il risultato verso cui si dirige un’azione."},{"question":"Una causale può essere implicita?","answer":"Sì: per esempio Avendo finito il filo, ci fermammo."},{"question":"La luce è accesa causa necessariamente la presenza nel laboratorio?","answer":"No: in Deve essere lì, perché la luce è accesa, la luce giustifica la deduzione del parlante."}],"levels":{"base":{"focus":"Individuare la ragione in periodi chiari.","example":{"sentence":"Poiché mancava una vite, abbiamo fermato il montaggio.","explanation":"La mancanza della vite motiva l’interruzione: è una causale."}},"consolidamento":{"focus":"Confrontare causali esplicite e implicite.","example":{"sentence":"Non ho rifatto il disegno perché fosse brutto, ma perché mancava una quota.","explanation":"La prima causa viene respinta; il congiuntivo non la trasforma in finale."}},"avanzato":{"focus":"Distinguere causa dell’evento e motivo di un’affermazione.","example":{"sentence":"Deve essere già in aula, perché la sua bicicletta è all’ingresso.","explanation":"La bicicletta all’ingresso è un indizio su cui si basa l’affermazione Deve essere già in aula. La causale giustifica la deduzione di chi parla; non dice che la bicicletta provochi la presenza della persona in aula."}}},"simplified":{"lead":"La causale dice il motivo di un fatto.","steps":["Trova il fatto della reggente.","Chiedi per quale motivo avviene.","Controlla che la risposta sia una ragione, non uno scopo."],"example":{"sentence":"Mi fermo perché sono stanco.","explanation":"Sono stanco è il motivo per cui mi fermo: causale."}},"pei":{"rule":"La causale dice il motivo: ci fermiamo perché manca il materiale.","example":{"sentence":"Mi fermo perché sono stanco.","explanation":"Sono stanco è il motivo per cui mi fermo: causale."}},"trackExamples":{"moda":{"sentence":"Rifacciamo la cucitura perché il filo si è spezzato.","explanation":"Il filo spezzato è la causa del nuovo lavoro."},"arredo":{"sentence":"Rifacciamo l’incastro perché il legno si è spaccato.","explanation":"Il legno spaccato è la causa del nuovo lavoro."},"liuteria":{"sentence":"Ripetiamo l’accordatura perché la corda si è allentata.","explanation":"La corda allentata è la causa del nuovo lavoro."}},"anchor":{"sentence":"Rifaccio la cucitura perché il filo si è spezzato.","explanation":"Perché il filo si è spezzato presenta il motivo del nuovo lavoro. È causale esplicita; non indica un risultato cercato.","memory":"Filo spezzato prima, nuova cucitura poi: il motivo spiega la decisione."}},{"topic":"Finali","area":"periodo","lead":"La finale indica l’obiettivo di un’azione: ciò che si vuole ottenere, evitare o rendere possibile.","objectives":["Riconoscere un obiettivo","Scegliere fra forma esplicita e implicita","Distinguere scopo, causa e conseguenza"],"sections":[{"title":"Un risultato cercato","text":"La subordinata finale presenta il fine verso cui si dirige l’azione della reggente. Risponde a per quale scopo e non afferma che l’obiettivo sia stato davvero raggiunto.\n\nAnche evitare un evento può essere uno scopo: proteggo il piano perché non si graffi. Il soggetto dell’azione intenzionale non è necessariamente una persona nominata nella frase, ma deve esserci un comportamento orientato a un risultato. Per riconoscere il valore finale immagina di aggiungere con l’obiettivo di, verificando che la parafrasi sia naturale.","examples":[{"sentence":"Accendiamo la lampada per vedere i dettagli.","explanation":"Vedere i dettagli è lo scopo dell’accensione, non un risultato già garantito."},{"sentence":"Copriamo il tavolo perché non si sporchi.","explanation":"Lo scopo è evitare che il tavolo si sporchi: finale esplicita negativa."}]},{"title":"La finale esplicita","text":"La forma esplicita è introdotta soprattutto da affinché, perché, in modo che o in maniera che, quando queste locuzioni esprimono un’intenzione. Il verbo è al congiuntivo, spesso presente con una reggente al presente e imperfetto con una reggente al passato.\n\nI soggetti possono essere diversi: la docente spiega affinché gli allievi capiscano. Il modo verbale aiuta, ma non basta: un congiuntivo può appartenere anche ad altre subordinate. Occorre verificare che la dipendente presenti il risultato voluto dalla reggente.","examples":[{"sentence":"La docente spostò il leggio affinché tutti vedessero.","explanation":"Vedessero è congiuntivo imperfetto: la visibilità di tutti era l’obiettivo dello spostamento."}]},{"title":"La finale implicita","text":"La forma implicita usa di solito per e infinito, ma può essere introdotta anche da a, di, allo scopo di, al fine di, secondo la costruzione. Il soggetto dell’infinito coincide normalmente con chi compie l’azione intenzionale, mentre in altre strutture può essere ricavato da un diverso elemento della reggente.\n\nPer trasformare con sicurezza una finale con soggetti differenti preferisci la forma esplicita. Non tutte le sequenze per più infinito sono finali: per aver dimenticato indica spesso una causa precedente.","examples":[{"sentence":"La classe osserva il prototipo per correggere il progetto.","explanation":"Il soggetto sottinteso di correggere è la classe, come quello di osserva: finale implicita."}]},{"title":"Non confondere i risultati","text":"La causa è un motivo che spiega l’azione; il fine è un obiettivo cercato; la conseguenza è un effetto presentato come derivante da un fatto o da una sua intensità. Confronta alzo la voce perché c’è rumore, alzo la voce perché mi sentiate e parlo così forte che tutti mi sentono.\n\nAnche in modo che può avere valore finale oppure consecutivo: servono intenzione, tempi e contesto. Una trasformazione deve quindi conservare il rapporto logico, non soltanto sostituire la congiunzione introduttiva.","examples":[{"sentence":"La docente ha parlato lentamente perché tutti capissero.","explanation":"La comprensione è un obiettivo: la frase non assicura che tutti abbiano capito."}]}],"diagram":{"title":"L’obiettivo dell’azione","steps":[{"label":"Scopo","detail":"Ciò che si vuole ottenere o evitare; non è garantito che accada."},{"label":"Esplicita","detail":"Affinché o perché con congiuntivo: affinché tutti vedano."},{"label":"Implicita","detail":"Per e infinito: per vedere; altre forme dipendono dalla costruzione."},{"label":"Soggetti","detail":"Con soggetti diversi è spesso necessaria la forma esplicita."},{"label":"Confronto","detail":"Causa = motivo; fine = obiettivo; conseguenza = effetto."}]},"pitfalls":[{"mistake":"La finale indica un risultato avvenuto.","correction":"Trattarla come obiettivo dell’azione.","why":"Lo scopo può anche non essere raggiunto."},{"mistake":"Per e infinito significa sempre finale.","correction":"Leggere tempo e significato dell’infinito.","why":"Per aver sbagliato spiega di norma una causa, non un obiettivo."}],"recap":["La subordinata finale presenta il fine verso cui si dirige l’azione della reggente.","La forma esplicita è introdotta soprattutto da affinché, perché, in modo che o in maniera che, quando queste locuzioni esprimono un’intenzione.","La forma implicita usa di solito per e infinito, ma può essere introdotta anche da a, di, allo scopo di, al fine di, secondo la costruzione.","La causa è un motivo che spiega l’azione; il fine è un obiettivo cercato; la conseguenza è un effetto presentato come derivante da un fatto o da una sua intensità."],"review":[{"question":"Qual è la domanda utile per la finale?","answer":"A quale scopo? La risposta deve esprimere un risultato cercato."},{"question":"Perché mi sentiate è causale perché inizia con perché?","answer":"No: esprime lo scopo per cui qualcuno parla più forte."},{"question":"Come trasformi Sposto il tavolo affinché voi passiate mantenendo soggetti e senso?","answer":"Conservo la finale esplicita, oppure riformulo per permettervi di passare; per passare attribuirebbe normalmente il passaggio a chi sposta."}],"levels":{"base":{"focus":"Riconoscere lo scopo con per e infinito.","example":{"sentence":"Accendiamo la lampada per vedere i dettagli.","explanation":"Vedere i dettagli è lo scopo dell’accensione, non un risultato già garantito."}},"consolidamento":{"focus":"Confrontare finali con soggetto uguale o diverso.","example":{"sentence":"La docente spostò il leggio affinché tutti vedessero.","explanation":"Vedessero è congiuntivo imperfetto: la visibilità di tutti era l’obiettivo dello spostamento."}},"avanzato":{"focus":"Distinguere le letture finali e consecutive delle locuzioni comuni.","example":{"sentence":"La docente ha parlato lentamente perché tutti capissero.","explanation":"La comprensione è un obiettivo: la frase non assicura che tutti abbiano capito."}}},"simplified":{"lead":"La finale dice lo scopo di un’azione.","steps":["Trova l’azione della reggente.","Chiedi che cosa si vuole ottenere.","Controlla chi deve compiere l’azione della finale."],"example":{"sentence":"Studio per capire.","explanation":"Per capire indica lo scopo dello studio: finale implicita."}},"pei":{"rule":"La finale dice lo scopo: studio per capire.","example":{"sentence":"Studio per capire.","explanation":"Per capire indica lo scopo dello studio: finale implicita."}},"trackExamples":{"moda":{"sentence":"Misuriamo il tessuto per evitare sprechi.","explanation":"Evitare sprechi è lo scopo della misurazione."},"arredo":{"sentence":"Misuriamo il pannello per evitare sprechi.","explanation":"Evitare sprechi è lo scopo della misurazione."},"liuteria":{"sentence":"Misuriamo la tavola armonica per evitare sprechi.","explanation":"Evitare sprechi è lo scopo della misurazione."}},"anchor":{"sentence":"Metto un’etichetta al campione affinché nessuno lo scambi per uno scarto.","explanation":"Affinché nessuno lo scambi per uno scarto indica ciò che voglio evitare. È finale esplicita al congiuntivo; il suo soggetto è diverso da io.","memory":"L’etichetta ha una missione precisa: evitare lo scambio."}},{"topic":"Temporali","area":"periodo","lead":"La temporale colloca un evento rispetto a un altro: prima, nello stesso momento oppure dopo.","objectives":["Riconoscere il riferimento temporale","Distinguere anteriorità contemporaneità e posteriorità","Trasformare temporali esplicite e implicite"],"sections":[{"title":"Due eventi da mettere in ordine","text":"La subordinata temporale indica quando avviene il fatto della reggente. Il rapporto si legge confrontando i due eventi, non guardando soltanto il tempo grammaticale dei verbi.\n\nLa subordinata può presentare un evento precedente, contemporaneo o successivo rispetto a quello della reggente. Per evitare confusioni, disponi prima gli eventi su una linea del tempo e poi descrivi il rapporto. Quando diciamo che la temporale è anteriore, intendiamo che il suo evento viene prima dell’evento principale, non che compare prima nel testo.","examples":[{"sentence":"Dopo che la colla asciuga, togliamo i morsetti.","explanation":"L’asciugatura precede la rimozione: l’evento della temporale è anteriore."},{"sentence":"Prima che la colla asciughi, allineiamo i pezzi.","explanation":"L’asciugatura è successiva all’allineamento: l’evento della temporale è posteriore."}]},{"title":"Le temporali esplicite","text":"Le forme esplicite sono introdotte da quando, mentre, appena, come nel senso di appena, dopo che, prima che, finché, da quando e altre locuzioni. L’indicativo è comune per eventi presentati come reali o abituali; prima che richiede il congiuntivo.\n\nAltri congiuntivi dipendono da eventualità e contesto. Mentre segnala spesso contemporaneità, ma può introdurre anche un contrasto avversativo. Finché può indicare la durata di una situazione oppure il limite finale, da interpretare nell’intero periodo.","examples":[{"sentence":"Mentre Sara cuce, Amir prepara la fodera.","explanation":"Le azioni si svolgono nello stesso intervallo: contemporaneità."}]},{"title":"Le temporali implicite","text":"La temporale implicita può usare prima di o dopo con l’infinito, nel o al con l’infinito, il gerundio oppure un participio. Il soggetto va ricostruito con attenzione: Finito il lavoro ha un soggetto proprio diverso da quello che può seguire nella reggente.\n\nIl gerundio presente esprime spesso contemporaneità e quello passato anteriorità, ma il valore temporale non è automatico. Esplicitare la frase aiuta a controllare l’ordine degli eventi e a evitare un soggetto implicito attribuito alla persona sbagliata.","examples":[{"sentence":"Dopo aver controllato il piano, montiamo le gambe.","explanation":"La verifica precede il montaggio; entrambi i verbi hanno come soggetto noi."}]},{"title":"Limiti, ripetizioni e altri valori","text":"Una temporale può presentare un fatto singolo, un’abitudine o il punto iniziale e finale di una durata. In Aspetta finché non arriva il tecnico, non non nega necessariamente l’arrivo: nella costruzione indica l’attesa fino al suo verificarsi.\n\nLe parole temporali possono inoltre avere altri usi: Quando avrai tempo può introdurre una condizione vicina a se, e mentre può opporre due situazioni. Per una classificazione motivata osserva se la dipendente colloca davvero l’evento nel tempo o svolge soprattutto un’altra funzione.","examples":[{"sentence":"Lavoreremo finché la luce sarà sufficiente.","explanation":"La temporale indica il limite di durata del lavoro; non esprime uno scopo."}]}],"diagram":{"title":"L’ordine dei due eventi","steps":[{"label":"Prima","detail":"Dopo che asciuga, togliamo i morsetti: l’asciugatura precede la rimozione."},{"label":"Durante","detail":"Mentre cuce, ascolta: contemporaneità."},{"label":"Dopo","detail":"Prima che asciughi, allineiamo: l’asciugatura segue l’allineamento."},{"label":"Forme","detail":"Quando, mentre, dopo che con modo finito; prima di, dopo con infinito; gerundio o participio."},{"label":"Limiti","detail":"Da quando indica un inizio; finché può indicare durata o termine."}]},"pitfalls":[{"mistake":"Prima che significa evento della subordinata precedente.","correction":"Mettere gli eventi in ordine.","why":"In lavoro prima che arrivi, l’arrivo avviene dopo il lavoro."},{"mistake":"Mentre introduce sempre una temporale.","correction":"Verificare contemporaneità o contrasto.","why":"In Luca ama cucire mentre Sara preferisce disegnare, può prevalere l’opposizione."}],"recap":["La subordinata temporale indica quando avviene il fatto della reggente.","Le forme esplicite sono introdotte da quando, mentre, appena, come nel senso di appena, dopo che, prima che, finché, da quando e altre locuzioni.","La temporale implicita può usare prima di o dopo con l’infinito, nel o al con l’infinito, il gerundio oppure un participio.","Una temporale può presentare un fatto singolo, un’abitudine o il punto iniziale e finale di una durata."],"review":[{"question":"Come riconosci l’anteriorità della temporale?","answer":"L’evento espresso dalla dipendente avviene prima di quello della reggente."},{"question":"Quale modo segue normalmente prima che?","answer":"Il congiuntivo."},{"question":"Che cosa controlli in una temporale implicita?","answer":"Il soggetto, la forma verbale e l’ordine relativo degli eventi."}],"levels":{"base":{"focus":"Collocare due azioni prima, durante o dopo.","example":{"sentence":"Dopo che la colla asciuga, togliamo i morsetti.","explanation":"L’asciugatura precede la rimozione: l’evento della temporale è anteriore."}},"consolidamento":{"focus":"Distinguere forme esplicite e implicite.","example":{"sentence":"Mentre Sara cuce, Amir prepara la fodera.","explanation":"Le azioni si svolgono nello stesso intervallo: contemporaneità."}},"avanzato":{"focus":"Interpretare finché e gli usi non temporali di mentre e quando.","example":{"sentence":"Lavoreremo finché la luce sarà sufficiente.","explanation":"La temporale indica il limite di durata del lavoro; non esprime uno scopo."}}},"simplified":{"lead":"La temporale dice quando avviene un fatto.","steps":["Trova i due eventi.","Mettili in ordine sul tempo.","Distingui prima, nello stesso momento e dopo."],"example":{"sentence":"Quando arrivi, usciamo.","explanation":"Quando arrivi dice in quale momento usciamo: temporale."}},"pei":{"rule":"La temporale dice quando: prima, durante oppure dopo un’altra azione.","example":{"sentence":"Quando arrivi, usciamo.","explanation":"Quando arrivi dice in quale momento usciamo: temporale."}},"trackExamples":{"moda":{"sentence":"Dopo aver misurato il tessuto, lo tagliamo.","explanation":"La misurazione precede il taglio: temporale implicita."},"arredo":{"sentence":"Dopo aver misurato il pannello, lo tagliamo.","explanation":"La misurazione precede il taglio: temporale implicita."},"liuteria":{"sentence":"Dopo aver misurato la tavola, la tagliamo.","explanation":"La misurazione precede il taglio: temporale implicita."}},"anchor":{"sentence":"Prima che la colla asciughi, allineiamo i pezzi.","explanation":"Prima che la colla asciughi è temporale esplicita. Prima avviene l’allineamento, poi l’asciugatura: l’evento della temporale è posteriore a quello della reggente.","memory":"Metti in fila gli eventi: allineare → asciugare."}},{"topic":"Interrogative indirette","area":"periodo","lead":"L’interrogativa indiretta riporta una domanda dentro un’altra frase, senza usare la forma autonoma del discorso diretto.","objectives":["Riconoscere una domanda riportata","Distinguere domande totali parziali e alternative","Usare modi e forme implicite adatti"],"sections":[{"title":"Una domanda dentro una frase","text":"L’interrogativa indiretta esprime una domanda o un dubbio dipendente da un verbo, da un nome o da un’espressione della reggente: chiedere, domandarsi, sapere, ignorare, dubbio, essere incerto. Nella domanda diretta il parlante interroga autonomamente; nell’indiretta il contenuto interrogativo entra in una costruzione più ampia.\n\nIl punto interrogativo dipende dall’intero enunciato: Non so dove sia termina normalmente con il punto fermo, mentre Sai dove sia? è una domanda diretta che contiene una interrogativa indiretta. Per controllare il valore interrogativo, ricostruisci la domanda diretta a cui il contenuto della dipendente corrisponde.","examples":[{"sentence":"Dove sono le forbici?","explanation":"È una domanda diretta autonoma."},{"sentence":"Non so dove siano le forbici.","explanation":"Dove siano le forbici conserva il contenuto della domanda e dipende da Non so."}]},{"title":"Le parole che introducono la domanda","text":"Le interrogative totali ammettono in genere una risposta sì o no e sono introdotte da se. Le parziali chiedono una singola informazione e usano chi, che cosa, quale, quanto, dove, come, quando, perché.\n\nLe alternative propongono possibilità fra cui scegliere, spesso con se… o, oppure. Queste parole non garantiscono da sole il valore interrogativo: quando può introdurre una temporale, e se una condizionale. Chiediti se la reggente presenti una domanda alla quale manca o viene richiesta una risposta.","examples":[{"sentence":"La docente chiede se abbiamo misurato il tavolo.","explanation":"Se introduce una domanda totale: abbiamo misurato il tavolo, sì oppure no?"}]},{"title":"Indicativo, congiuntivo e condizionale","text":"La forma esplicita usa un modo finito. Indicativo e congiuntivo possono alternarsi secondo il verbo reggente, il registro e il modo in cui si presenta il contenuto; il congiuntivo è frequente in contesti di dubbio e nella scrittura sorvegliata.\n\nIl condizionale esprime eventualità o una prospettiva condizionata: Non so se accetterebbe. Non applicare alle interrogative il divieto scolastico del condizionale dopo se riferito alla protasi: qui se introduce una domanda, non l’ipotesi da cui dipende una conseguenza.","examples":[{"sentence":"Mi chiedo se il cliente sceglierebbe il rovere.","explanation":"Sceglierebbe è ammesso: la subordinata riporta una domanda su una scelta eventuale."}]},{"title":"Forme implicite e confronti","text":"La forma implicita ha l’infinito ed è comune quando il soggetto della domanda coincide con quello della reggente o è ricavabile dal contesto: Non so come procedere. Esplicitando, rendi chiaro chi dovrebbe agire e conserva l’eventuale valore di possibilità o dovere.\n\nPer distinguere una interrogativa da una relativa osserva la funzione del contenuto: Mi chiedo dove abiti è una domanda sul luogo; Visito la città dove abiti precisa città. La stessa parola può dunque partecipare a costruzioni diverse.","examples":[{"sentence":"Non sappiamo quale finitura scegliere.","explanation":"Quale finitura scegliere è interrogativa indiretta implicita: la scelta è l’informazione ancora da decidere."}]},{"title":"Più domande collegate","text":"Una reggente può introdurre più interrogative indirette. Se le domande hanno ciascuna il proprio predicato e sono collegate sullo stesso piano, si può analizzare la prima come subordinata e la seconda come coordinata alla subordinata.\n\nLe alternative possono essere espresse con se… o, oppure: osserva se entrambe le possibilità contengono un verbo oppure se si tratta di due semplici parole all’interno di una sola proposizione.","examples":[{"sentence":"Mi chiedo se Sara arrivi e se Luca partecipi.","explanation":"Le due domande hanno i predicati arrivi e partecipi: la seconda è coordinata alla prima."},{"sentence":"Dimmi se preferisci il blu o il verde.","explanation":"Blu e verde sono alternative nella stessa proposizione: non aggiungono un secondo predicato."}]}],"diagram":{"title":"Una domanda dipendente","steps":[{"label":"Totale","detail":"Non so se arriva: risposta possibile sì o no."},{"label":"Parziale","detail":"Chiedo dove arriva: si cerca una singola informazione."},{"label":"Alternativa","detail":"Chiedo se arriva oggi o domani: si confrontano possibilità."},{"label":"Forma","detail":"Modo finito nell’esplicita; infinito in non so come procedere."},{"label":"Se interrogativo","detail":"Può ammettere il condizionale: non so se verrebbe."}]},"pitfalls":[{"mistake":"Dopo se il condizionale è sempre sbagliato.","correction":"Distinguere interrogativa indiretta e protasi.","why":"Non so se verrebbe è una domanda eventuale, non un periodo ipotetico."},{"mistake":"Ogni frase con dove è interrogativa.","correction":"Verificare se il contenuto risponde a una domanda o precisa un antecedente.","why":"La città dove abito contiene una relativa."}],"recap":["L’interrogativa indiretta esprime una domanda o un dubbio dipendente da un verbo, da un nome o da un’espressione della reggente: chiedere, domandarsi, sapere, ignorare, dubbio, essere incerto.","Le interrogative totali ammettono in genere una risposta sì o no e sono introdotte da se.","La forma esplicita usa un modo finito.","La forma implicita ha l’infinito ed è comune quando il soggetto della domanda coincide con quello della reggente o è ricavabile dal contesto: Non so come procedere."],"review":[{"question":"Come riconosci una domanda totale?","answer":"Chiede se l’intero contenuto sia valido e ammette di norma sì o no."},{"question":"Non so quando arriva contiene una temporale?","answer":"Quando arriva è interrogativa indiretta: esprime il momento che non conosco."},{"question":"Non so come procedere è esplicita o implicita?","answer":"Implicita, perché il verbo è all’infinito."}],"levels":{"base":{"focus":"Riconoscere domande introdotte da se e dove.","example":{"sentence":"Dove sono le forbici?","explanation":"È una domanda diretta autonoma."}},"consolidamento":{"focus":"Distinguere interrogative totali, parziali e alternative.","example":{"sentence":"La docente chiede se abbiamo misurato il tavolo.","explanation":"Se introduce una domanda totale: abbiamo misurato il tavolo, sì oppure no?"}},"avanzato":{"focus":"Motivare il condizionale dopo se interrogativo.","example":{"sentence":"Non sappiamo quale finitura scegliere.","explanation":"Quale finitura scegliere è interrogativa indiretta implicita: la scelta è l’informazione ancora da decidere."}}},"simplified":{"lead":"Una domanda può essere contenuta dentro un’altra frase.","steps":["Trova il verbo come chiedo o non so.","Ricostruisci la domanda riportata.","Trova la parola che la introduce: se, dove, quando o un’altra."],"example":{"sentence":"Non so dove andare.","explanation":"La domanda è dove andare? È contenuta nella frase Non so: interrogativa indiretta."}},"pei":{"rule":"La domanda è dentro un’altra frase: non so dove andare.","example":{"sentence":"Non so dove andare.","explanation":"La domanda è dove andare? È contenuta nella frase Non so: interrogativa indiretta."}},"trackExamples":{"moda":{"sentence":"Mi chiedo quale stoffa scegliere.","explanation":"La subordinata riporta una domanda sulla scelta: interrogativa indiretta implicita."},"arredo":{"sentence":"Mi chiedo quale legno scegliere.","explanation":"La subordinata riporta una domanda sulla scelta: interrogativa indiretta implicita."},"liuteria":{"sentence":"Mi chiedo quale corda scegliere.","explanation":"La subordinata riporta una domanda sulla scelta: interrogativa indiretta implicita."}},"anchor":{"sentence":"Mi chiedo dove siano finite le forbici.","explanation":"Dove siano finite le forbici contiene la domanda che mi pongo. È interrogativa indiretta parziale: cerco un luogo, non una risposta sì o no.","memory":"La domanda resta; entra dentro mi chiedo."}},{"topic":"Dichiarative","area":"periodo","lead":"La dichiarativa precisa il contenuto di un elemento già presente nella reggente, per esempio una certezza, un timore o il pronome questo.","objectives":["Trovare la parola spiegata","Distinguere dichiarativa e oggettiva","Riconoscere dichiarative esplicite e implicite"],"sections":[{"title":"Quale contenuto viene precisato","text":"La subordinata dichiarativa chiarisce il contenuto di un nome, di un pronome o, secondo la costruzione, di un aggettivo della reggente. È frequente dopo nomi come certezza, timore, speranza, idea, desiderio oppure dopo espressioni che anticipano un contenuto, come questo.\n\nNon si limita ad aggiungere una caratteristica al nome: ne esprime il contenuto. Per riconoscerla domanda quale sia la certezza, quale il timore o che cosa significhi questo. Nello schema indica anche l’elemento che la subordinata precisa.","examples":[{"sentence":"Ho la certezza che il mobile sia stabile.","explanation":"Che il mobile sia stabile precisa il contenuto del nome certezza."},{"sentence":"Di questo sono sicura: che il disegno è completo.","explanation":"La subordinata sviluppa il contenuto anticipato da questo."}]},{"title":"Il confronto con l’oggettiva","text":"Nell’oggettiva il contenuto completa direttamente il verbo reggente; nella dichiarativa precisa un elemento nominale già espresso. Confronta Credo che il legno sia asciutto e Ho la convinzione che il legno sia asciutto.\n\nIl contenuto è simile, ma la costruzione cambia: nella seconda frase che il legno sia asciutto spiega convinzione. Non usare soltanto la domanda che cosa?, perché può risultare generica e portare fuori strada. Osserva quale parola richiede o anticipa il contenuto e ricostruisci il rapporto sintattico.","examples":[{"sentence":"Temo che la vernice si rovini → Ho il timore che la vernice si rovini.","explanation":"Nel primo periodo la dipendente è oggettiva; nel secondo è dichiarativa e precisa timore."}]},{"title":"Forma e modo verbale","text":"La dichiarativa esplicita è introdotta spesso da che. Il verbo può essere all’indicativo quando il contenuto è presentato come un fatto, al congiuntivo quando è legato a timore, desiderio, valutazione o dubbio, oppure al condizionale se il contenuto lo richiede.\n\nLa forma implicita usa frequentemente di e infinito, quando i rapporti di soggetto permettono questa costruzione. La scelta non deriva dalla sola etichetta dichiarativa: dipende dall’elemento precisato e da come il parlante considera quanto viene detto.","examples":[{"sentence":"Conservo la speranza di finire oggi.","explanation":"Di finire oggi è dichiarativa implicita e precisa il contenuto della speranza."}]},{"title":"Distinguere i casi vicini","text":"La relativa riprende un antecedente attraverso un pronome che ha una funzione nella dipendente; la dichiarativa è introdotta da una congiunzione che non sostituisce il nome. In La certezza che mi rassicura, che è soggetto di rassicura e riprende certezza: è relativa.\n\nIn La certezza che tutto funzioni, la dipendente spiega quale sia la certezza. Anche la coordinata dichiarativa con cioè o infatti ha una struttura diversa: collega proposizioni sullo stesso piano, senza precisare in questo modo un elemento nominale.","examples":[{"sentence":"La notizia che hai letto è vera.","explanation":"Che è oggetto di hai letto e riprende notizia: qui la subordinata è relativa, non dichiarativa."}]}],"diagram":{"title":"Il contenuto di una parola","steps":[{"label":"Elemento precisato","detail":"Un nome o un pronome anticipa un contenuto: certezza, timore, questo."},{"label":"Dichiarativa","detail":"Ho il timore che piova: che piova precisa timore."},{"label":"Oggettiva","detail":"Temo che piova: il contenuto completa direttamente il verbo."},{"label":"Forma","detail":"Che con modo finito; di con infinito nelle costruzioni ammesse."},{"label":"Relativa diversa","detail":"La notizia che leggo: che sostituisce notizia ed è oggetto di leggo."}]},"pitfalls":[{"mistake":"Dopo certezza la subordinata è sempre dichiarativa.","correction":"Controllare il lavoro di che nella dipendente.","why":"La certezza che mi accompagna contiene una relativa con che soggetto."},{"mistake":"Chiamare oggettiva ogni contenuto introdotto da che.","correction":"Individuare la parola direttamente precisata.","why":"Una dichiarativa può spiegare un nome già presente nella reggente."}],"recap":["La subordinata dichiarativa chiarisce il contenuto di un nome, di un pronome o, secondo la costruzione, di un aggettivo della reggente.","Nell’oggettiva il contenuto completa direttamente il verbo reggente; nella dichiarativa precisa un elemento nominale già espresso.","La dichiarativa esplicita è introdotta spesso da che.","La relativa riprende un antecedente attraverso un pronome che ha una funzione nella dipendente; la dichiarativa è introdotta da una congiunzione che non sostituisce il nome."],"review":[{"question":"Quale nome viene precisato in Ho il timore che piova?","answer":"Timore."},{"question":"Che differenza c’è tra So che parte e Ho la certezza che parte?","answer":"La prima dipendente è oggettiva del verbo so; la seconda precisa il nome certezza ed è dichiarativa."},{"question":"Che funzione ha che in la notizia che leggo?","answer":"È pronome relativo, complemento oggetto di leggo."}],"levels":{"base":{"focus":"Individuare il nome precisato dalla dipendente.","example":{"sentence":"Ho la certezza che il mobile sia stabile.","explanation":"Che il mobile sia stabile precisa il contenuto del nome certezza."}},"consolidamento":{"focus":"Trasformare un’oggettiva in una costruzione con dichiarativa.","example":{"sentence":"Temo che la vernice si rovini → Ho il timore che la vernice si rovini.","explanation":"Nel primo periodo la dipendente è oggettiva; nel secondo è dichiarativa e precisa timore."}},"avanzato":{"focus":"Distinguere che congiunzione e che pronome in casi vicini.","example":{"sentence":"La notizia che hai letto è vera.","explanation":"Che è oggetto di hai letto e riprende notizia: qui la subordinata è relativa, non dichiarativa."}}},"simplified":{"lead":"La dichiarativa spiega il contenuto di una parola.","steps":["Trova un nome come timore o certezza.","Chiedi quale sia il suo contenuto.","Collega la spiegazione a quel nome."],"example":{"sentence":"Ho il timore che piova.","explanation":"Che piova spiega quale timore ho: dichiarativa."}},"pei":{"rule":"La dichiarativa spiega una parola: la certezza di che cosa?","example":{"sentence":"Ho il timore che piova.","explanation":"Che piova spiega quale timore ho: dichiarativa."}},"trackExamples":{"moda":{"sentence":"Ho la certezza che la cucitura regga.","explanation":"La subordinata spiega il contenuto di certezza."},"arredo":{"sentence":"Ho la certezza che la giunzione regga.","explanation":"La subordinata spiega il contenuto di certezza."},"liuteria":{"sentence":"Ho la certezza che l’incollaggio regga.","explanation":"La subordinata spiega il contenuto di certezza."}},"anchor":{"sentence":"Ho il timore che il righello sia finito nella scatola degli scarti.","explanation":"Che il righello sia finito nella scatola degli scarti precisa il contenuto del nome timore. È dichiarativa esplicita, non oggettiva del verbo ho.","memory":"Aggancia la dipendente a timore: quale timore?"}},{"topic":"Consecutive","area":"periodo","lead":"La consecutiva presenta l’effetto che deriva da un fatto, da una qualità o dalla sua intensità.","objectives":["Riconoscere un effetto","Individuare le correlazioni consecutive","Distinguere conseguenza reale e risultato cercato"],"sections":[{"title":"Dalla situazione al suo effetto","text":"La subordinata consecutiva esprime una conseguenza di ciò che si afferma nella reggente. Spesso la reggente contiene un elemento che annuncia un’intensità, come così, tanto, talmente, tale, troppo o abbastanza.\n\nLa dipendente completa il rapporto: la luce è così forte che abbaglia. L’effetto può essere presentato come realmente verificato oppure come possibile, necessario o da evitare. Per riconoscerlo domanda quale risultato derivi dalla situazione descritta, senza attribuire automaticamente un’intenzione a chi agisce nella proposizione reggente.","examples":[{"sentence":"Il filo era così sottile che si spezzò.","explanation":"Che si spezzò esprime l’effetto dell’eccessiva sottigliezza."},{"sentence":"La stanza è troppo piccola perché vi entrino tutti.","explanation":"La consecutiva segnala un risultato non possibile nelle condizioni descritte."}]},{"title":"La consecutiva esplicita","text":"La forma esplicita usa soprattutto che, collegato a un antecedente nella reggente: così… che, tanto… che, tale… che. Esistono anche locuzioni come cosicché, sicché, di modo che. L’indicativo presenta comunemente una conseguenza reale; il congiuntivo può accompagnare una conseguenza eventuale, negata o possibile.\n\nIl condizionale dipende dal contenuto ipotetico. La presenza di che non basta: occorre riconoscere il rapporto di effetto. Alcune classificazioni scolastiche distinguono diversamente i collegamenti conclusivi con sicché; qui consideriamo la dipendenza consecutiva.","examples":[{"sentence":"Il corridoio era tanto stretto che il mobile non passava.","explanation":"Tanto annuncia l’intensità; la subordinata indica la conseguenza effettivamente osservata."}]},{"title":"La consecutiva implicita","text":"La forma implicita è frequente con da e infinito, spesso dopo così, tanto, troppo, abbastanza oppure un aggettivo che esprime idoneità. In Sono abbastanza esperto da riuscirci, la dipendente presenta un risultato reso possibile dal grado di esperienza.\n\nLe costruzioni con per e infinito dopo troppo o abbastanza possono essere vicine alle consecutive; l’interpretazione richiede l’intera frase. Esplicitando, conserva il rapporto di intensità e il soggetto dell’azione. Un semplice per e infinito, senza questo rapporto, può invece esprimere uno scopo.","examples":[{"sentence":"Il piano era così fragile da rompersi al primo urto.","explanation":"Da rompersi al primo urto è consecutiva implicita e sviluppa l’intensità annunciata da così."}]},{"title":"Conseguenza, fine e conclusione","text":"Il fine è il risultato che qualcuno cerca; la conseguenza è l’effetto presentato come derivante da una situazione. In Parlo piano affinché nessuno si distragga c’è uno scopo; in Parlo così piano che nessuno mi sente c’è un effetto.\n\nLe locuzioni in modo che e di modo che possono assumere entrambi i valori: indicativo, congiuntivo e contesto orientano la lettura. Una coordinata conclusiva con quindi presenta invece una conclusione sullo stesso piano. Il rapporto di senso può essere vicino, ma cambia la struttura sintattica.","examples":[{"sentence":"Il gruppo ha disposto le sedie in modo che tutti vedessero.","explanation":"Senza altro contesto può prevalere lo scopo dell’organizzazione; non basta in modo che per imporre l’etichetta consecutiva."}]}],"diagram":{"title":"Dall’intensità all’effetto","steps":[{"label":"Antecedente","detail":"Così, tanto, tale, troppo, abbastanza possono annunciare l’effetto."},{"label":"Esplicita","detail":"Così stretto che non passa: che con modo finito."},{"label":"Implicita","detail":"Così fragile da rompersi: da con infinito."},{"label":"Effetto","detail":"Può essere reale, possibile o escluso dalle condizioni."},{"label":"Fine diverso","detail":"La finale presenta un obiettivo; la consecutiva presenta un effetto."}]},"pitfalls":[{"mistake":"Consecutiva significa sempre effetto già avvenuto.","correction":"Verificare realtà, possibilità o impossibilità dell’effetto.","why":"Troppo piccolo perché entrino descrive una conseguenza esclusa, non un evento accaduto."},{"mistake":"In modo che è sempre consecutivo.","correction":"Leggere se il risultato è cercato o presentato come effetto.","why":"La stessa locuzione può introdurre una finale."}],"recap":["La subordinata consecutiva esprime una conseguenza di ciò che si afferma nella reggente.","La forma esplicita usa soprattutto che, collegato a un antecedente nella reggente: così… che, tanto… che, tale… che.","La forma implicita è frequente con da e infinito, spesso dopo così, tanto, troppo, abbastanza oppure un aggettivo che esprime idoneità.","Il fine è il risultato che qualcuno cerca; la conseguenza è l’effetto presentato come derivante da una situazione."],"review":[{"question":"Quali elementi anticipano spesso una consecutiva?","answer":"Così, tanto, talmente, tale, troppo e abbastanza."},{"question":"Da rompersi è esplicita o implicita?","answer":"Implicita, perché il verbo è all’infinito."},{"question":"Che differenza c’è fra così forte che mi senti e forte perché tu mi senta?","answer":"La prima presenta un effetto; la seconda un obiettivo dell’azione."}],"levels":{"base":{"focus":"Riconoscere così… che e tanto… che.","example":{"sentence":"Il filo era così sottile che si spezzò.","explanation":"Che si spezzò esprime l’effetto dell’eccessiva sottigliezza."}},"consolidamento":{"focus":"Confrontare consecutive esplicite e implicite.","example":{"sentence":"Il corridoio era tanto stretto che il mobile non passava.","explanation":"Tanto annuncia l’intensità; la subordinata indica la conseguenza effettivamente osservata."}},"avanzato":{"focus":"Distinguere effetto possibile, effetto reale e scopo.","example":{"sentence":"Il gruppo ha disposto le sedie in modo che tutti vedessero.","explanation":"Senza altro contesto può prevalere lo scopo dell’organizzazione; non basta in modo che per imporre l’etichetta consecutiva."}}},"simplified":{"lead":"La consecutiva dice quale effetto deriva da un fatto.","steps":["Trova così, tanto o un’altra parola di intensità.","Cerca l’effetto descritto dopo.","Controlla se l’effetto avviene davvero o è solo possibile."],"example":{"sentence":"È così buio che non vedo.","explanation":"Che non vedo è l’effetto del buio: consecutiva."}},"pei":{"rule":"La consecutiva dice l’effetto: così stretto che non passa.","example":{"sentence":"È così buio che non vedo.","explanation":"Che non vedo è l’effetto del buio: consecutiva."}},"trackExamples":{"moda":{"sentence":"La cucitura è così fitta che non si vede la fodera.","explanation":"Che non si vede la fodera presenta una conseguenza della fittezza."},"arredo":{"sentence":"La trama del pannello è così fitta che non si vede il fondo.","explanation":"Che non si vede il fondo presenta una conseguenza della fittezza."},"liuteria":{"sentence":"L’intreccio del rivestimento è così fitto che non si vede il supporto.","explanation":"Che non si vede il supporto presenta una conseguenza della fittezza."}},"anchor":{"sentence":"La colla è così tenace che il tappo non si apre.","explanation":"Così annuncia un grado di tenacia; che il tappo non si apre esprime il suo effetto. È consecutiva esplicita.","memory":"Così prepara l’effetto; che lo completa."}},{"topic":"Concessive","area":"periodo","lead":"La concessiva presenta un fatto che farebbe prevedere un risultato diverso da quello espresso nella reggente.","objectives":["Riconoscere un ostacolo non decisivo","Usare concessive esplicite e implicite","Distinguere concessione e causa"],"sections":[{"title":"Un’attesa che viene smentita","text":"La subordinata concessiva indica una circostanza nonostante la quale si verifica il fatto della reggente. Il parlante costruisce un’attesa e poi mostra che non si realizza: essere stanchi potrebbe ostacolare il lavoro, eppure il lavoro viene completato.\n\nLa concessiva non afferma necessariamente un ostacolo materiale; può riguardare anche opinioni, proprietà o situazioni inattese. Per riconoscerla prova la parafrasi nonostante il fatto che. Devi poter individuare quale risultato ci si sarebbe aspettati e come la reggente lo smentisce.","examples":[{"sentence":"Benché fosse stanco, Amir completò il disegno.","explanation":"La stanchezza faceva prevedere una difficoltà; il completamento avviene ugualmente."},{"sentence":"Anche se il pannello è leggero, regge bene.","explanation":"La leggerezza non impedisce la resistenza, contrariamente all’attesa suggerita."}]},{"title":"Le forme esplicite","text":"Le concessive esplicite usano benché, sebbene, quantunque, nonostante che, per quanto e altre locuzioni, generalmente con il congiuntivo. Anche se introduce spesso l’indicativo quando presenta un fatto reale; può accompagnare altre forme quando il contesto è ipotetico.\n\nEsistono concessive con pronomi o aggettivi indefiniti come chiunque, qualunque e dovunque: Qualunque materiale tu scelga, servirà una prova. La subordinata può precedere o seguire la reggente. Un eventuale comunque o tuttavia nella reggente rende più evidente il contrasto.","examples":[{"sentence":"Sebbene la prova fosse difficile, il gruppo la superò.","explanation":"Sebbene introduce una concessiva al congiuntivo imperfetto."}]},{"title":"Le forme implicite","text":"Le concessive implicite sono frequenti con pur e gerundio, pur e participio, benché e participio oppure altre costruzioni ellittiche interpretabili nel contesto. Pur lavorando con poco spazio, abbiamo completato il progetto equivale a Sebbene lavorassimo con poco spazio.\n\nOccorre controllare il soggetto: deve essere ricostruibile senza attribuire il gerundio alla persona sbagliata. Un participio può avere anche un uso aggettivale; la classificazione come subordinata dipende dalla costruzione considerata. La parola pur segnala spesso il valore concessivo, mentre il solo gerundio resta più aperto.","examples":[{"sentence":"Pur avendo poco tempo, Sara controllò ogni quota.","explanation":"Pur avendo poco tempo è concessiva implicita: il limite non impedisce il controllo accurato."}]},{"title":"Concessione, causa e ipotesi","text":"La causale spiega perché avviene un fatto; la concessiva presenta una circostanza che farebbe attendere l’esito contrario. Poiché era stanco, si fermò e Benché fosse stanco, continuò costruiscono ragionamenti diversi.\n\nAnche se può inoltre introdurre una situazione reale oppure una condizione concessiva eventuale: Anche se piovesse, partirei. In quest’ultimo caso non si afferma che piova davvero. La classificazione richiede di osservare l’intero rapporto e il contesto, invece di considerare se un segnale sempre condizionale.","examples":[{"sentence":"Anche se la consegna fosse anticipata, riusciremmo a finire.","explanation":"La circostanza è ipotetica, ma viene presentata come incapace di impedire il risultato: valore concessivo."}]}],"diagram":{"title":"Il fatto avviene ugualmente","steps":[{"label":"Circostanza","detail":"Presenta qualcosa che farebbe attendere un esito diverso."},{"label":"Risultato","detail":"Benché sia stanco, continua: la stanchezza non lo ferma."},{"label":"Esplicita","detail":"Benché, sebbene con congiuntivo; anche se spesso con indicativo per fatti reali."},{"label":"Implicita","detail":"Pur e gerundio o participio: pur essendo stanco."},{"label":"Eventualità","detail":"Anche se piovesse, partirei: la circostanza può essere soltanto ipotizzata."}]},"pitfalls":[{"mistake":"L’ostacolo impedisce il fatto della reggente.","correction":"Riconoscere che il fatto avviene ugualmente.","why":"La concessiva smentisce proprio l’esito atteso dall’ostacolo."},{"mistake":"Dopo anche se serve sempre il congiuntivo.","correction":"Distinguere situazione reale e situazione ipotetica.","why":"Anche se è stanco, lavora presenta normalmente un fatto reale all’indicativo."}],"recap":["La subordinata concessiva indica una circostanza nonostante la quale si verifica il fatto della reggente.","Le concessive esplicite usano benché, sebbene, quantunque, nonostante che, per quanto e altre locuzioni, generalmente con il congiuntivo.","Le concessive implicite sono frequenti con pur e gerundio, pur e participio, benché e participio oppure altre costruzioni ellittiche interpretabili nel contesto.","La causale spiega perché avviene un fatto; la concessiva presenta una circostanza che farebbe attendere l’esito contrario."],"review":[{"question":"Quale domanda aiuta a riconoscere la concessiva?","answer":"Nonostante quale fatto avviene quanto dice la reggente?"},{"question":"Come rendi esplicita Pur avendo poco spazio, lavoriamo?","answer":"Sebbene abbiamo poco spazio, lavoriamo."},{"question":"Che cosa distingue una concessiva da una causale?","answer":"La causa motiva il fatto; la concessiva presenta una circostanza che farebbe prevedere un esito diverso."}],"levels":{"base":{"focus":"Riconoscere benché e anche se in contesti reali.","example":{"sentence":"Benché fosse stanco, Amir completò il disegno.","explanation":"La stanchezza faceva prevedere una difficoltà; il completamento avviene ugualmente."}},"consolidamento":{"focus":"Trasformare pur e gerundio in una forma esplicita.","example":{"sentence":"Sebbene la prova fosse difficile, il gruppo la superò.","explanation":"Sebbene introduce una concessiva al congiuntivo imperfetto."}},"avanzato":{"focus":"Interpretare concessive con circostanze eventuali.","example":{"sentence":"Anche se la consegna fosse anticipata, riusciremmo a finire.","explanation":"La circostanza è ipotetica, ma viene presentata come incapace di impedire il risultato: valore concessivo."}}},"simplified":{"lead":"Un fatto avviene anche se c’è una difficoltà.","steps":["Trova la difficoltà o la circostanza.","Chiedi che cosa farebbe aspettare.","Osserva che il risultato avviene ugualmente."],"example":{"sentence":"Anche se è stanco, Luca lavora.","explanation":"Luca lavora nonostante la stanchezza: concessiva."}},"pei":{"rule":"La concessiva dice: c’è una difficoltà, eppure il fatto avviene.","example":{"sentence":"Anche se è stanco, Luca lavora.","explanation":"Luca lavora nonostante la stanchezza: concessiva."}},"trackExamples":{"moda":{"sentence":"Benché il tessuto fosse rigido, abbiamo completato la piega.","explanation":"La rigidità non ha impedito il risultato: concessiva."},"arredo":{"sentence":"Benché il legno fosse rigido, abbiamo completato la curvatura.","explanation":"La rigidità non ha impedito il risultato: concessiva."},"liuteria":{"sentence":"Benché la fascia fosse rigida, abbiamo completato la curvatura.","explanation":"La rigidità non ha impedito il risultato: concessiva."}},"anchor":{"sentence":"Benché il bozzetto fosse pieno di cancellature, l’idea era chiara.","explanation":"Le cancellature farebbero aspettare poca chiarezza, ma l’idea risulta chiara. Benché il bozzetto fosse pieno di cancellature è concessiva esplicita.","memory":"Aspettativa: confusione. Risultato: chiarezza."}},{"topic":"Condizionali e periodo ipotetico","area":"periodo","lead":"Il periodo ipotetico collega una condizione al risultato che ne dipende: se accade questo, allora accade quello.","objectives":["Distinguere protasi e apodosi","Riconoscere realtà possibilità e irrealtà","Scegliere tempi e modi senza formule meccaniche"],"sections":[{"title":"Condizione e conseguenza","text":"La subordinata condizionale esprime la condizione da cui dipende il fatto della reggente. Insieme formano il periodo ipotetico: la condizionale si chiama protasi, la reggente apodosi.\n\nL’ordine può cambiare senza modificare i ruoli: Se piove, restiamo e Restiamo se piove conservano la stessa struttura. La conseguenza non è necessariamente un evento futuro; può essere una decisione, una valutazione o un ordine. Nell’analisi individua prima quale fatto venga posto come condizione e quale contenuto dipenda da esso.","examples":[{"sentence":"Se la colla è asciutta, togliamo i morsetti.","explanation":"La protasi pone la condizione; l’apodosi indica ciò che facciamo quando è soddisfatta."},{"sentence":"Togliete i morsetti se la colla è asciutta.","explanation":"L’apodosi è un ordine; la condizione resta nella subordinata."}]},{"title":"Le forme e i collegamenti","text":"La forma esplicita è introdotta soprattutto da se, ma anche da purché, a condizione che, qualora, nel caso che. Questi ultimi collegamenti richiedono normalmente il congiuntivo.\n\nLe implicite possono usare il gerundio, il participio o a e infinito: A guardarlo bene, noteresti il difetto. La parafrasi con se serve a controllare il valore, perché queste forme possono esprimere anche altri rapporti. La protasi non coincide sempre con la prima proposizione del periodo, e l’apodosi può essere reggente di ulteriori subordinate.","examples":[{"sentence":"Lavorando con calma, eviteresti gli errori.","explanation":"Nel contesto il gerundio può significare se lavorassi con calma: condizionale implicita."}]},{"title":"Realtà, possibilità e irrealtà","text":"La classificazione scolastica distingue il periodo della realtà, normalmente con indicativo, quello della possibilità, con congiuntivo imperfetto e condizionale presente, e quello dell’irrealtà. Per un’ipotesi passata non realizzata sono comuni congiuntivo trapassato e condizionale passato.\n\nUna stessa coppia congiuntivo imperfetto più condizionale presente può esprimere possibilità o irrealtà presente: il contesto decide se la condizione sia aperta o contraria a un fatto noto. Esistono inoltre periodi misti, quando una condizione passata ha una conseguenza nel presente.","examples":[{"sentence":"Ieri non avevo la chiave: se l’avessi avuta, avrei aperto.","explanation":"Il contesto rende l’ipotesi irreale nel passato: la chiave mancava e l’apertura non è avvenuta."}]},{"title":"Controllare modi e significato","text":"Nella protasi ipotetica standard non si usa il condizionale al posto del congiuntivo: Se avessi tempo, lavorerei. Questo criterio non riguarda il se interrogativo di Non so se verrebbe.\n\nIn un racconto colloquiale si può incontrare l’imperfetto indicativo per un’ipotesi irreale, ma nella scrittura scolastica è utile padroneggiare la costruzione esplicita con congiuntivo e condizionale. I nomi realtà e possibilità descrivono il modo di presentare l’ipotesi; l’indicativo non garantisce che una condizione sia realmente accaduta.","examples":[{"sentence":"Se avessi salvato il file ieri, ora sarei tranquillo.","explanation":"Protasi irreale passata e conseguenza presente: periodo ipotetico misto."}]}],"diagram":{"title":"Condizione e risultato","steps":[{"label":"Protasi / apodosi","detail":"Se arrivi, iniziamo: condizione nella protasi, risultato nell’apodosi."},{"label":"Realtà","detail":"Se piove, restiamo: indicativo; la condizione è presentata come aperta o verificabile."},{"label":"Possibilità","detail":"Se avessi tempo, verrei: congiuntivo imperfetto e condizionale presente."},{"label":"Irrealtà passata","detail":"Se avessi avuto tempo, sarei venuto: trapassato congiuntivo e condizionale passato."},{"label":"Contesto e forme miste","detail":"Il contesto distingue possibilità e irrealtà presente; una condizione passata può avere effetti presenti."}]},"pitfalls":[{"mistake":"Se avrei tempo, verrei.","correction":"Se avessi tempo, verrei.","why":"Nella protasi ipotetica standard si usa qui il congiuntivo imperfetto."},{"mistake":"Congiuntivo imperfetto e condizionale indicano sempre possibilità.","correction":"Verificare ciò che sappiamo della situazione.","why":"Se fossi un albero, sarei alto esprime irrealtà presente."}],"recap":["La subordinata condizionale esprime la condizione da cui dipende il fatto della reggente.","La forma esplicita è introdotta soprattutto da se, ma anche da purché, a condizione che, qualora, nel caso che.","La classificazione scolastica distingue il periodo della realtà, normalmente con indicativo, quello della possibilità, con congiuntivo imperfetto e condizionale presente, e quello dell’irrealtà.","Nella protasi ipotetica standard non si usa il condizionale al posto del congiuntivo: Se avessi tempo, lavorerei."],"review":[{"question":"Quale parte si chiama protasi?","answer":"La subordinata che esprime la condizione."},{"question":"Come si costruisce normalmente un’ipotesi passata non realizzata?","answer":"Con congiuntivo trapassato nella protasi e condizionale passato nell’apodosi."},{"question":"Se avessi studiato, ora saprei la risposta è scorretto?","answer":"No: è un periodo misto con condizione passata e conseguenza presente."}],"levels":{"base":{"focus":"Trovare protasi e apodosi.","example":{"sentence":"Se la colla è asciutta, togliamo i morsetti.","explanation":"La protasi pone la condizione; l’apodosi indica ciò che facciamo quando è soddisfatta."}},"consolidamento":{"focus":"Usare le principali coppie di modi e tempi.","example":{"sentence":"Lavorando con calma, eviteresti gli errori.","explanation":"Nel contesto il gerundio può significare se lavorassi con calma: condizionale implicita."}},"avanzato":{"focus":"Distinguere possibilità, irrealtà contestuale e periodi misti.","example":{"sentence":"Se avessi salvato il file ieri, ora sarei tranquillo.","explanation":"Protasi irreale passata e conseguenza presente: periodo ipotetico misto."}}},"simplified":{"lead":"Una parte dice la condizione; l’altra dice che cosa ne segue.","steps":["Trova la parte introdotta da se.","Individua la condizione: è la protasi.","Trova il risultato: è l’apodosi."],"example":{"sentence":"Se piove, resto a casa.","explanation":"Se piove è la condizione. Resto a casa è il risultato."}},"pei":{"rule":"Se introduce la condizione. L’altra parte dice che cosa ne segue.","example":{"sentence":"Se piove, resto a casa.","explanation":"Se piove è la condizione. Resto a casa è il risultato."}},"trackExamples":{"moda":{"sentence":"Se avessimo più stoffa, cuciremmo un secondo campione.","explanation":"Congiuntivo imperfetto e condizionale presente presentano qui un’ipotesi eventuale."},"arredo":{"sentence":"Se avessimo più legno, costruiremmo un secondo campione.","explanation":"Congiuntivo imperfetto e condizionale presente presentano qui un’ipotesi eventuale."},"liuteria":{"sentence":"Se avessimo più tempo, proveremmo una seconda corda.","explanation":"Congiuntivo imperfetto e condizionale presente presentano qui un’ipotesi eventuale."}},"anchor":{"sentence":"Se avessimo un righello lungo due metri, misureremmo il banco in un attimo.","explanation":"Se avessimo un righello lungo due metri è la protasi; misureremmo il banco in un attimo è l’apodosi. Congiuntivo imperfetto e condizionale presente presentano qui una possibilità immaginata.","memory":"La condizione apre la porta al risultato: se avessimo → misureremmo."}},{"topic":"Comparative","area":"periodo","lead":"La comparativa confronta una qualità, una quantità o un comportamento con un secondo termine espresso attraverso un’altra proposizione.","objectives":["Riconoscere il confronto fra proposizioni","Distinguere maggioranza minoranza e uguaglianza","Separare comparativa e complemento di paragone"],"sections":[{"title":"Un secondo termine con un verbo","text":"La subordinata comparativa esprime il secondo termine di un confronto attraverso una proposizione. Nella reggente compaiono spesso più, meno, tanto, così, meglio o peggio.\n\nLa dipendente dice rispetto a quale attesa, comportamento o situazione vale il confronto. Se il secondo termine è soltanto un nome o un pronome, si parla normalmente di complemento di paragone, non di subordinata. La presenza di un predicato autonomo, espresso o ricostruibile in una struttura ellittica, è quindi un indizio da controllare.","examples":[{"sentence":"Il piano è più largo di quanto avevamo previsto.","explanation":"Il confronto è con la larghezza prevista; avevamo previsto è il predicato della comparativa."},{"sentence":"Il piano è più largo del ripiano.","explanation":"Del ripiano è un complemento di paragone: manca una seconda proposizione autonoma."}]},{"title":"I tre rapporti principali","text":"La comparativa di maggioranza si collega a più o meglio e usa di quanto, di come oppure che, secondo la costruzione. Quella di minoranza si collega a meno o peggio.\n\nLa comparativa di uguaglianza usa correlazioni come tanto… quanto e così… come. Non cercare una sola formula valida per ogni frase: i collegamenti cambiano con il tipo di confronto. La dipendente può confrontare quantità, grado di una qualità o modalità di un’azione; deve comunque sviluppare il secondo termine del rapporto comparativo.","examples":[{"sentence":"La stampa è tanto nitida quanto ci aveva promesso il tecnico.","explanation":"La comparativa esprime uguaglianza fra il grado di nitidezza reale e quello promesso."}]},{"title":"Forme esplicite e implicite","text":"La comparativa esplicita usa un modo finito: indicativo per un confronto presentato come reale, congiuntivo in costruzioni eventuali o valutative, condizionale quando il contenuto esprime una possibilità. Il non in più di quanto non pensassi può essere espletivo e non rovesciare il significato.\n\nLe implicite usano soprattutto l’infinito, spesso in confronti di preferenza con piuttosto che o anziché. Queste costruzioni possono essere chiamate anche comparative di preferenza o avversative, secondo la grammatica adottata: conta chiarire quale scelta venga contrapposta.","examples":[{"sentence":"Preferisco correggere il disegno piuttosto che rifarlo.","explanation":"Piuttosto che rifarlo esprime il secondo termine di una preferenza attraverso l’infinito."}]},{"title":"Confrontare non è descrivere il modo","text":"Una modale descrive come si svolge un’azione; una comparativa stabilisce un rapporto fra due termini. In Lavora come gli hanno insegnato prevale il modo conforme a un modello; in Lavora più lentamente di quanto pensassi è esplicito il confronto di grado.\n\nAlcune costruzioni con come ammettono letture vicine e le classificazioni possono variare: serve una motivazione basata sulla frase intera. Nell’analisi indica il primo termine, il secondo e il rapporto, evitando di classificare dal solo introduttore.","examples":[{"sentence":"La nuova prova dura meno di quanto durava quella precedente.","explanation":"Il confronto riguarda la durata: comparativa esplicita di minoranza."}]}],"diagram":{"title":"Il secondo termine è una proposizione","steps":[{"label":"Maggioranza","detail":"Più lungo di quanto pensassi: confronto verso un grado maggiore."},{"label":"Minoranza","detail":"Meno lungo di quanto pensassi: confronto verso un grado minore."},{"label":"Uguaglianza","detail":"Tanto nitido quanto promettevi: confronto fra gradi uguali."},{"label":"Forme","detail":"Modo finito nell’esplicita; infinito frequente nelle preferenze con piuttosto che."},{"label":"Complemento diverso","detail":"Più alto di Marco: di Marco è un gruppo nominale, non una proposizione."}]},"pitfalls":[{"mistake":"Più alto di Marco contiene una comparativa.","correction":"Riconoscere un complemento di paragone.","why":"Di Marco è un gruppo nominale, non una proposizione."},{"mistake":"Come introduce sempre una comparativa.","correction":"Verificare se si confrontano due termini o si descrive il modo.","why":"Come ti ho mostrato può esprimere il modo di agire."}],"recap":["La subordinata comparativa esprime il secondo termine di un confronto attraverso una proposizione.","La comparativa di maggioranza si collega a più o meglio e usa di quanto, di come oppure che, secondo la costruzione.","La comparativa esplicita usa un modo finito: indicativo per un confronto presentato come reale, congiuntivo in costruzioni eventuali o valutative, condizionale quando il contenuto esprime una possibilità.","Una modale descrive come si svolge un’azione; una comparativa stabilisce un rapporto fra due termini."],"review":[{"question":"Quale elemento distingue di quanto pensavo da del tavolo?","answer":"Il primo contiene un predicato e può essere una proposizione; il secondo è un gruppo nominale."},{"question":"Quale rapporto esprime tanto… quanto?","answer":"Uguaglianza."},{"question":"Non in più di quanto non pensassi nega necessariamente il pensiero?","answer":"No: in questa costruzione può essere espletivo e il confronto mantiene valore positivo."}],"levels":{"base":{"focus":"Riconoscere più, meno e tanto con una dipendente.","example":{"sentence":"Il piano è più largo di quanto avevamo previsto.","explanation":"Il confronto è con la larghezza prevista; avevamo previsto è il predicato della comparativa."}},"consolidamento":{"focus":"Separare comparativa e complemento di paragone.","example":{"sentence":"La stampa è tanto nitida quanto ci aveva promesso il tecnico.","explanation":"La comparativa esprime uguaglianza fra il grado di nitidezza reale e quello promesso."}},"avanzato":{"focus":"Motivare confronti di preferenza e casi vicini alla modale.","example":{"sentence":"La nuova prova dura meno di quanto durava quella precedente.","explanation":"Il confronto riguarda la durata: comparativa esplicita di minoranza."}}},"simplified":{"lead":"La comparativa confronta due situazioni.","steps":["Trova più, meno oppure tanto.","Individua le due situazioni confrontate.","Controlla che il secondo termine abbia un predicato."],"example":{"sentence":"È più lungo di quanto pensavo.","explanation":"Di quanto pensavo esprime una previsione confrontata con la lunghezza reale."}},"pei":{"rule":"La comparativa confronta due situazioni: più lungo di quanto pensavo.","example":{"sentence":"È più lungo di quanto pensavo.","explanation":"Di quanto pensavo esprime una previsione confrontata con la lunghezza reale."}},"trackExamples":{"moda":{"sentence":"La cucitura è più lunga di quanto avevamo calcolato.","explanation":"Il secondo termine è una previsione espressa da una proposizione."},"arredo":{"sentence":"La mensola è più lunga di quanto avevamo calcolato.","explanation":"Il secondo termine è una previsione espressa da una proposizione."},"liuteria":{"sentence":"La fascia è più lunga di quanto avevamo calcolato.","explanation":"Il secondo termine è una previsione espressa da una proposizione."}},"anchor":{"sentence":"Il cartamodello è più grande di quanto avevamo previsto.","explanation":"Di quanto avevamo previsto è comparativa esplicita di maggioranza. Il secondo termine è la grandezza prevista, espressa attraverso una proposizione.","memory":"Confronta il modello reale con il modello immaginato."}},{"topic":"Modali","area":"periodo","lead":"La modale spiega come si svolge un’azione: descrive il comportamento o il procedimento seguito.","objectives":["Riconoscere il modo di un’azione","Distinguere modale e strumentale","Interpretare forme esplicite e implicite"],"sections":[{"title":"Come si svolge il fatto","text":"La subordinata modale precisa il modo in cui avviene il fatto della reggente. Descrive una maniera di agire, un comportamento oppure la conformità a un modello. La domanda «come?» aiuta, ma non basta: può ricevere anche una risposta che indica il mezzo usato per ottenere un risultato. Per riconoscere una modale prova a parafrasare nel modo in cui. La dipendente deve spiegare lo svolgimento dell’azione, mentre una strumentale evidenzia ciò attraverso cui viene raggiunto un esito.","examples":[{"sentence":"Disponete gli strumenti come vi ha insegnato il maestro.","explanation":"La dipendente descrive il modo corretto di disporre gli strumenti."},{"sentence":"Sara lavorava canticchiando.","explanation":"Nel contesto canticchiando descrive la maniera che accompagna il lavoro, senza indicarne il mezzo."}]},{"title":"Le modali esplicite","text":"La forma esplicita è introdotta soprattutto da come, nel modo in cui, secondo come, quasi, come se. L’indicativo presenta un modo reale o conforme a un modello; il condizionale può accompagnare un modo eventuale.\n\nCon come se si usa il congiuntivo per un modo immaginato o ipotetico: Cammina come se fosse su un palco. Le costruzioni con come se vengono spesso chiamate comparative ipotetiche, perché contengono anche un confronto: la terminologia può cambiare, mentre rimane chiaro il rapporto descritto.","examples":[{"sentence":"Ripeti la piega nel modo in cui l’ha mostrata la docente.","explanation":"La modale esplicita presenta il procedimento da seguire come modello reale."}]},{"title":"Le modali implicite","text":"Le modali implicite usano frequentemente il gerundio, l’infinito preceduto da con o altre espressioni equivalenti. La forma con e infinito è più comune con un valore nominale del verbo e va letta nella costruzione concreta.\n\nIl gerundio può indicare una maniera, ma anche causa, tempo, condizione o mezzo: per questo occorre sempre verificare il senso. Nelle costruzioni ordinarie il suo soggetto coincide con quello della reggente; se il riferimento cambia, è preferibile esplicitare per evitare equivoci.","examples":[{"sentence":"Il gruppo presentò il progetto parlando con calma.","explanation":"Parlando con calma descrive la maniera della presentazione: modale implicita al gerundio."}]},{"title":"Modo, mezzo e confronto","text":"Per distinguere modale e strumentale chiediti se il segmento descriva il comportamento durante l’azione oppure il procedimento che rende possibile un risultato. Cammina zoppicando descrive il modo; risolve il problema confrontando le misure indica il mezzo.\n\nNella comparativa sono invece espliciti due termini di confronto, spesso con più, meno, tanto. Alcuni gerundi ammettono valori vicini: nel dubbio ricostruisci la situazione, proponi una parafrasi e segnala se resta possibile più di una lettura. La classificazione deve spiegare la frase, non forzarla.","examples":[{"sentence":"Il tecnico osserva il campione ruotandolo.","explanation":"Ruotandolo può indicare la maniera di osservazione o il procedimento che la rende efficace; il contesto orienta l’analisi."}]}],"diagram":{"title":"La maniera di agire","steps":[{"label":"Rapporto","detail":"Dice nel modo in cui si svolge il fatto."},{"label":"Esplicita","detail":"Come, nel modo in cui: lavora come gli hanno insegnato."},{"label":"Implicita","detail":"Gerundio: presentò il progetto parlando con calma."},{"label":"Modo ipotetico","detail":"Come se con congiuntivo: agisce come se fosse esperto; anche detto comparativo ipotetico."},{"label":"Mezzo diverso","detail":"La strumentale mette in rilievo il procedimento che permette un risultato."}]},"pitfalls":[{"mistake":"Qualunque risposta a come? è modale.","correction":"Distinguere maniera e mezzo.","why":"La stessa domanda può far emergere una subordinata strumentale."},{"mistake":"Il gerundio ha sempre lo stesso valore.","correction":"Ricostruire il rapporto nel contesto.","why":"Le forme indefinite possono esprimere diversi legami logici."}],"recap":["La subordinata modale precisa il modo in cui avviene il fatto della reggente.","La forma esplicita è introdotta soprattutto da come, nel modo in cui, secondo come, quasi, come se.","Le modali implicite usano frequentemente il gerundio, l’infinito preceduto da con o altre espressioni equivalenti.","Per distinguere modale e strumentale chiediti se il segmento descriva il comportamento durante l’azione oppure il procedimento che rende possibile un risultato."],"review":[{"question":"Quale parafrasi aiuta a riconoscere una modale?","answer":"Nel modo in cui, quando la dipendente descrive davvero lo svolgimento dell’azione."},{"question":"Come se fosse esperto presenta un modo reale?","answer":"No: presenta un modo immaginato; questa costruzione è chiamata anche comparativa ipotetica."},{"question":"Perché parlando con calma può essere modale?","answer":"Descrive la maniera della presentazione senza indicare necessariamente il mezzo per un risultato distinto."}],"levels":{"base":{"focus":"Riconoscere il modo espresso con come.","example":{"sentence":"Disponete gli strumenti come vi ha insegnato il maestro.","explanation":"La dipendente descrive il modo corretto di disporre gli strumenti."}},"consolidamento":{"focus":"Confrontare modali esplicite e gerundi modali.","example":{"sentence":"Ripeti la piega nel modo in cui l’ha mostrata la docente.","explanation":"La modale esplicita presenta il procedimento da seguire come modello reale."}},"avanzato":{"focus":"Motivare le differenze fra modo, mezzo e confronto.","example":{"sentence":"Il tecnico osserva il campione ruotandolo.","explanation":"Ruotandolo può indicare la maniera di osservazione o il procedimento che la rende efficace; il contesto orienta l’analisi."}}},"simplified":{"lead":"La modale descrive il modo di fare un’azione.","steps":["Trova l’azione della reggente.","Chiedi in quale modo viene fatta.","Prova la parafrasi nel modo in cui."],"example":{"sentence":"Fai come ti ho mostrato.","explanation":"Come ti ho mostrato indica il modo di fare l’azione: modale."}},"pei":{"rule":"La modale dice come: fai la piega come ti ha mostrato la docente.","example":{"sentence":"Fai come ti ho mostrato.","explanation":"Come ti ho mostrato indica il modo di fare l’azione: modale."}},"trackExamples":{"moda":{"sentence":"Cuci il bordo come ti ha insegnato la docente.","explanation":"La dipendente descrive il modo di eseguire la cucitura."},"arredo":{"sentence":"Leviga il bordo come ti ha insegnato la docente.","explanation":"La dipendente descrive il modo di eseguire la levigatura."},"liuteria":{"sentence":"Rifinisci il bordo come ti ha insegnato il maestro.","explanation":"La dipendente descrive il modo di eseguire la rifinitura."}},"anchor":{"sentence":"Ripiega il tessuto come ti ha mostrato la docente.","explanation":"Come ti ha mostrato la docente descrive il modo di eseguire la piega. È modale esplicita: il modello è il procedimento mostrato.","memory":"Per il modo, ripensa alla dimostrazione."}},{"topic":"Strumentali","area":"periodo","lead":"La strumentale indica il mezzo o il procedimento attraverso cui si raggiunge un risultato.","objectives":["Riconoscere un procedimento che produce un risultato","Interpretare gerundi e infiniti strumentali","Distinguere mezzo modo e causa"],"sections":[{"title":"Attraverso quale procedimento","text":"La subordinata strumentale esprime l’azione usata come mezzo per realizzare quanto dice la reggente. Il suo contenuto risponde a mediante quale procedimento oppure attraverso quale azione.\n\nRispetto al complemento di mezzo, contiene un nucleo verbale: con il calibro nomina uno strumento, misurando con il calibro presenta un’operazione. Il risultato e il procedimento sono legati, ma rimangono distinti: possiamo individuare un difetto attraverso un confronto, oppure calcolare un costo dividendo una spesa. Il contesto deve rendere riconoscibile questo rapporto.","examples":[{"sentence":"Abbiamo individuato l’errore confrontando le misure.","explanation":"Il confronto è il procedimento che permette di individuare l’errore."},{"sentence":"Abbiamo misurato il pezzo con il calibro.","explanation":"Con il calibro è un complemento di mezzo; non contiene un predicato e non è una subordinata."}]},{"title":"Le forme più comuni","text":"La strumentale ha normalmente forma implicita, soprattutto con il gerundio presente. Sono possibili anche costruzioni con l’infinito sostantivato, spesso preceduto da con: Con il ripetere la prova abbiamo chiarito il problema.\n\nQueste forme sono meno comuni nell’uso quotidiano e una parafrasi più semplice può facilitarne la comprensione. Nelle costruzioni ordinarie il soggetto della strumentale coincide con chi realizza il risultato della reggente. Se il soggetto non è chiaro, esplicita il procedimento evitando un gerundio che sembri riferito alla persona sbagliata.","examples":[{"sentence":"Calcoliamo il costo per allievo dividendo la spesa totale per il numero dei partecipanti.","explanation":"Dividendo introduce l’operazione che permette di ottenere il risultato numerico."}]},{"title":"Il confronto con la modale","text":"La modale descrive la maniera di svolgere l’azione; la strumentale evidenzia il mezzo con cui si ottiene un risultato. Il gruppo presentò il progetto parlando lentamente descrive soprattutto il modo.\n\nIl gruppo convinse la commissione mostrando le prove mette invece in rilievo il procedimento efficace. La differenza può essere sottile: una stessa azione può essere vista come modo oppure come mezzo. Per scegliere non limitarti a come?: domanda quale risultato distinto venga ottenuto grazie all’azione della subordinata.","examples":[{"sentence":"Abbiamo riconosciuto la tinta confrontando i due campioni.","explanation":"Il confronto non è soltanto il modo di riconoscere: è l’operazione da cui ricaviamo il risultato."}]},{"title":"Mezzo, causa e trasformazioni","text":"La causa spiega perché avviene un fatto; il mezzo è il procedimento attraverso il quale qualcuno lo realizza. Avendo perso il foglio, abbiamo ripetuto il calcolo presenta un motivo.\n\nRifacendo il calcolo, abbiamo trovato l’errore presenta invece il procedimento della scoperta. Le grammatiche scolastiche descrivono normalmente la strumentale come implicita: una parafrasi con grazie al fatto che può chiarire il senso, ma non diventa automaticamente una strumentale esplicita dello stesso tipo. Nell’analisi conserva la distinzione fra trasformazione grammaticale e semplice spiegazione del significato.","examples":[{"sentence":"Rileggendo il progetto, abbiamo trovato una quota sbagliata.","explanation":"La rilettura è lo strumento della scoperta; una lettura temporale resterebbe possibile solo con un contesto diverso."}]}],"diagram":{"title":"Il procedimento che produce il risultato","steps":[{"label":"Risultato","detail":"Abbiamo trovato l’errore: il fatto ottenuto."},{"label":"Procedimento","detail":"Confrontando le misure: l’azione usata come mezzo."},{"label":"Forma","detail":"Normalmente implicita, soprattutto con gerundio; anche con e infinito sostantivato."},{"label":"Modo diverso","detail":"Parlando piano descrive una maniera; confrontando per trovare evidenzia un mezzo."},{"label":"Complemento diverso","detail":"Con il calibro nomina uno strumento senza formare una proposizione."}]},"pitfalls":[{"mistake":"Il mezzo deve essere un oggetto.","correction":"Riconoscere anche un’azione usata come procedimento.","why":"Una subordinata strumentale esprime un mezzo mediante un predicato."},{"mistake":"Grazie al fatto che crea sempre una strumentale esplicita.","correction":"Usare la parafrasi per capire e controllare poi la costruzione.","why":"La parafrasi può introdurre un rapporto causale invece di conservare la struttura originaria."}],"recap":["La subordinata strumentale esprime l’azione usata come mezzo per realizzare quanto dice la reggente.","La strumentale ha normalmente forma implicita, soprattutto con il gerundio presente.","La modale descrive la maniera di svolgere l’azione; la strumentale evidenzia il mezzo con cui si ottiene un risultato.","La causa spiega perché avviene un fatto; il mezzo è il procedimento attraverso il quale qualcuno lo realizza."],"review":[{"question":"Quale domanda aiuta per la strumentale?","answer":"Attraverso quale azione o mediante quale procedimento si ottiene il risultato?"},{"question":"Qual è la forma più frequente?","answer":"Il gerundio presente con valore di mezzo."},{"question":"Con il calibro è una subordinata strumentale?","answer":"No: è un complemento di mezzo privo di un proprio nucleo verbale."}],"levels":{"base":{"focus":"Riconoscere il procedimento in gerundi chiari.","example":{"sentence":"Abbiamo individuato l’errore confrontando le misure.","explanation":"Il confronto è il procedimento che permette di individuare l’errore."}},"consolidamento":{"focus":"Distinguere subordinata e complemento di mezzo.","example":{"sentence":"Calcoliamo il costo per allievo dividendo la spesa totale per il numero dei partecipanti.","explanation":"Dividendo introduce l’operazione che permette di ottenere il risultato numerico."}},"avanzato":{"focus":"Confrontare letture strumentali, modali e causali.","example":{"sentence":"Rileggendo il progetto, abbiamo trovato una quota sbagliata.","explanation":"La rilettura è lo strumento della scoperta; una lettura temporale resterebbe possibile solo con un contesto diverso."}}},"simplified":{"lead":"La strumentale indica l’azione usata come mezzo.","steps":["Trova il risultato ottenuto.","Cerca l’azione che permette quel risultato.","Prova la domanda mediante quale procedimento."],"example":{"sentence":"Trovo l’errore confrontando le misure.","explanation":"Il confronto è il mezzo che permette di trovare l’errore: strumentale."}},"pei":{"rule":"La strumentale dice il mezzo: troviamo l’errore confrontando due misure.","example":{"sentence":"Trovo l’errore confrontando le misure.","explanation":"Il confronto è il mezzo che permette di trovare l’errore: strumentale."}},"trackExamples":{"moda":{"sentence":"Abbiamo trovato il difetto confrontando le due cuciture.","explanation":"Il confronto è il procedimento della scoperta."},"arredo":{"sentence":"Abbiamo trovato il difetto confrontando i due incastri.","explanation":"Il confronto è il procedimento della scoperta."},"liuteria":{"sentence":"Abbiamo trovato il difetto confrontando le due accordature.","explanation":"Il confronto è il procedimento della scoperta."}},"anchor":{"sentence":"Abbiamo scoperto l’errore sovrapponendo i due cartamodelli.","explanation":"Sovrapponendo i due cartamodelli è il procedimento che ha prodotto la scoperta. È strumentale implicita al gerundio.","memory":"La sovrapposizione è lo strumento della scoperta."}},{"topic":"Limitative","area":"periodo","lead":"La limitativa restringe la validità di un’affermazione a un punto di vista, a un ambito o alle informazioni disponibili.","objectives":["Riconoscere un giudizio delimitato","Distinguere forme esplicite e implicite","Separare limitazione concessione e condizione"],"sections":[{"title":"Il campo di validità del giudizio","text":"La subordinata limitativa precisa entro quali limiti vale il contenuto della reggente. Può riferirsi alle conoscenze di chi parla, a un argomento oppure a un punto di vista.\n\nIn Per quanto ne so, la mostra apre venerdì, il parlante non garantisce una verità assoluta: dichiara che l’informazione vale nei limiti di ciò che conosce. La dipendente non esprime necessariamente un dubbio, ma rende esplicita la base del giudizio. Per riconoscerla domanda rispetto a quale ambito o secondo quali informazioni valga l’affermazione.","examples":[{"sentence":"Per quanto ne so, il laboratorio è chiuso.","explanation":"Il giudizio è limitato alle conoscenze del parlante."},{"sentence":"Per quello che riguarda il colore, il progetto è convincente.","explanation":"La valutazione vale rispetto al colore; non viene estesa automaticamente a ogni aspetto del progetto."}]},{"title":"Le limitative esplicite","text":"La forma esplicita usa locuzioni come per quanto, per quello che, per ciò che, secondo quanto, quando introducono un limite del giudizio. Il verbo è spesso all’indicativo, perché presenta il contenuto assunto come base della valutazione.\n\nAlcune costruzioni sono vicine a relative o espressioni di argomento: le denominazioni possono variare nella descrizione grammaticale. Nell’analisi scolastica il punto da spiegare è quale porzione della reggente venga delimitata. Non etichettare una locuzione senza leggere ciò che viene detto nelle due proposizioni.","examples":[{"sentence":"Secondo quanto risulta dal registro, il campione è stato consegnato.","explanation":"La fonte documentale delimita l’affermazione: si riferisce ciò che risulta da quella fonte."}]},{"title":"Le limitative implicite","text":"La forma implicita è comune con a e infinito, soprattutto in espressioni come a giudicare da, a sentire, a vedere, a parlare di. Il soggetto può essere generico o riferirsi al parlante che compie la valutazione.\n\nLa costruzione A giudicare dai disegni non indica lo scopo del disegno né la condizione necessaria perché il mobile esista: segnala il materiale su cui si basa una stima. Per esplicitare, usa una parafrasi come se consideriamo soltanto ciò che mostrano i disegni, conservando il limite del giudizio.","examples":[{"sentence":"A giudicare dai bozzetti, l’armadio occuperà tutta la parete.","explanation":"A giudicare dai bozzetti limita la previsione alle informazioni ricavate dai disegni."}]},{"title":"Gli stessi introduttori, rapporti diversi","text":"Per quanto può introdurre una limitativa oppure una concessiva. In Per quanto ne so, il corso è confermato si delimita la conoscenza; in Per quanto sia difficile, il corso mi piace si presenta una difficoltà che non impedisce il gradimento.\n\nUna condizionale pone invece una condizione da cui dipende il fatto. Il complemento di limitazione svolge un compito vicino, ma senza una propria proposizione: bravo nel disegno. Cerca dunque il nucleo verbale e poi individua il rapporto, senza affidarti soltanto alla preposizione o alla locuzione iniziale.","examples":[{"sentence":"Per quanto sia resistente, questo tessuto va protetto.","explanation":"Qui per quanto introduce una concessiva: la resistenza non elimina la necessità di protezione."}]}],"diagram":{"title":"Entro quali limiti vale il giudizio","steps":[{"label":"Conoscenza","detail":"Per quanto ne so: limita l’affermazione alle informazioni disponibili."},{"label":"Ambito","detail":"Per ciò che riguarda il colore: delimita l’aspetto valutato."},{"label":"Esplicita","detail":"Per quanto, secondo quanto con modo finito, se esprimono un limite."},{"label":"Implicita","detail":"A giudicare dai disegni: infinito che presenta la base della valutazione."},{"label":"Concessiva diversa","detail":"Per quanto sia difficile, continuo: ostacolo non decisivo, non limite del giudizio."}]},"pitfalls":[{"mistake":"Per quanto introduce sempre una concessiva.","correction":"Controllare se esprime un ostacolo o un limite del giudizio.","why":"Per quanto ne so delimita ciò che si afferma."},{"mistake":"Nel disegno è una subordinata limitativa.","correction":"Verificare la presenza di un nucleo verbale.","why":"Senza un predicato, nel disegno è un complemento."}],"recap":["La subordinata limitativa precisa entro quali limiti vale il contenuto della reggente.","La forma esplicita usa locuzioni come per quanto, per quello che, per ciò che, secondo quanto, quando introducono un limite del giudizio.","La forma implicita è comune con a e infinito, soprattutto in espressioni come a giudicare da, a sentire, a vedere, a parlare di.","Per quanto può introdurre una limitativa oppure una concessiva."],"review":[{"question":"Che cosa limita Per quanto ne so?","answer":"La validità dell’affermazione alle conoscenze del parlante."},{"question":"A giudicare dai disegni è esplicita o implicita?","answer":"Implicita: contiene un infinito."},{"question":"Come distingui limitativa e concessiva con per quanto?","answer":"La prima delimita il punto di vista; la seconda presenta una circostanza che farebbe attendere un esito diverso."}],"levels":{"base":{"focus":"Riconoscere i limiti delle conoscenze del parlante.","example":{"sentence":"Per quanto ne so, il laboratorio è chiuso.","explanation":"Il giudizio è limitato alle conoscenze del parlante."}},"consolidamento":{"focus":"Confrontare limitative esplicite e implicite.","example":{"sentence":"Secondo quanto risulta dal registro, il campione è stato consegnato.","explanation":"La fonte documentale delimita l’affermazione: si riferisce ciò che risulta da quella fonte."}},"avanzato":{"focus":"Distinguere per quanto limitativo e concessivo.","example":{"sentence":"Per quanto sia resistente, questo tessuto va protetto.","explanation":"Qui per quanto introduce una concessiva: la resistenza non elimina la necessità di protezione."}}},"simplified":{"lead":"La limitativa indica entro quali limiti vale una frase.","steps":["Trova l’affermazione principale.","Chiedi su quali informazioni si basa.","Cerca la parte che limita il giudizio."],"example":{"sentence":"Per quanto ne so, l’aula è chiusa.","explanation":"Per quanto ne so significa nei limiti delle mie informazioni: limitativa."}},"pei":{"rule":"La limitativa dice: questa affermazione vale per ciò che conosco o considero.","example":{"sentence":"Per quanto ne so, l’aula è chiusa.","explanation":"Per quanto ne so significa nei limiti delle mie informazioni: limitativa."}},"trackExamples":{"moda":{"sentence":"Per quanto ne so, il tessuto arriverà domani.","explanation":"L’informazione vale entro i limiti delle conoscenze di chi parla."},"arredo":{"sentence":"Per quanto ne so, il pannello arriverà domani.","explanation":"L’informazione vale entro i limiti delle conoscenze di chi parla."},"liuteria":{"sentence":"Per quanto ne so, l’archetto arriverà domani.","explanation":"L’informazione vale entro i limiti delle conoscenze di chi parla."}},"anchor":{"sentence":"Per quanto ne so, le forbici sono ancora nel cassetto.","explanation":"Per quanto ne so limita l’affermazione alle informazioni di chi parla. È limitativa esplicita; non presenta un ostacolo.","memory":"Il giudizio ha un confine: le mie informazioni."}},{"topic":"Eccettuative","area":"periodo","lead":"L’eccettuativa presenta un’eccezione: il fatto della reggente vale, tranne nel caso indicato dalla dipendente.","objectives":["Individuare il caso escluso da una regola","Riconoscere forme esplicite e implicite","Distinguere eccezione esclusione e condizione"],"sections":[{"title":"La regola e la sua eccezione","text":"La subordinata eccettuativa indica un caso che fa eccezione rispetto al contenuto della reggente. In La visita è confermata, a meno che il museo chiuda, la conferma vale con una riserva precisa: la chiusura del museo.\n\nPer riconoscerla prova la parafrasi tranne nel caso in cui. La proposizione non presenta un semplice fatto mancante, ma sottrae un’eventualità alla validità dell’affermazione principale. Il rapporto può essere vicino alla condizione; l’etichetta eccettuativa mette in evidenza la particolare organizzazione della regola e della sua eccezione.","examples":[{"sentence":"La mostra aprirà in cortile, a meno che piova.","explanation":"La pioggia è il caso eccettuato che può impedire l’apertura prevista."},{"sentence":"Accetteremo ogni modifica, salvo che alteri le misure.","explanation":"L’alterazione delle misure è l’eccezione alla disponibilità generale."}]},{"title":"Le forme esplicite","text":"Le eccettuative esplicite sono introdotte da a meno che, salvo che, tranne che, eccetto che, fuorché e locuzioni simili. Il verbo è comunemente al congiuntivo quando l’eccezione è eventuale.\n\nCon a meno che si può trovare un non espletivo: A meno che non piova può significare la stessa cosa di A meno che piova. Non interpretare quindi quel non come una negazione automatica dell’evento. Contesto e uso chiariscono se sia espletivo oppure realmente negativo nella specifica costruzione.","examples":[{"sentence":"La prova si farà fuori, a meno che non piova.","explanation":"Nell’uso comune «non» è espletivo: l’eccezione è la pioggia, non la sua assenza."}]},{"title":"Le forme implicite","text":"La forma implicita impiega soprattutto l’infinito con fuorché, tranne che, eccetto che o salvo. È frequente dopo una reggente che presenta una serie generale di possibilità o comportamenti: È disposto a tutto, fuorché a cambiare idea.\n\nIl soggetto dell’infinito deve essere ricostruibile. Alcune espressioni eccettuative collegano invece semplici nomi, non proposizioni: Tutti tranne Sara contiene un complemento o un’espressione di eccezione priva di nuovo predicato. Nell’analisi del periodo distingui quindi il rapporto di significato dalla presenza effettiva di una subordinata.","examples":[{"sentence":"Il gruppo era disposto a tutto fuorché a rinunciare al progetto.","explanation":"A rinunciare al progetto esprime l’unica eventualità esclusa: eccettuativa implicita."}]},{"title":"Confrontare eccezione ed esclusione","text":"L’esclusiva presenta un’azione che non accompagna il fatto della reggente: Uscì senza salutare. L’eccettuativa ritaglia invece un’eccezione: Farò tutto tranne che rinunciare.\n\nLa condizionale pone una condizione positiva o negativa da cui dipende una conseguenza; l’eccettuativa può essere parafrasata con una condizione negativa, ma mantiene il valore di riserva rispetto a un’affermazione già data. Alcune locuzioni hanno più usi: salvo che può introdurre anche una rettifica. Leggi sempre il periodo intero e indica il caso concreto che viene sottratto alla regola.","examples":[{"sentence":"Andremo alla mostra, salvo che il treno sia cancellato.","explanation":"La cancellazione è l’eccezione alla decisione; la parafrasi è andremo se il treno non sarà cancellato."}]}],"diagram":{"title":"La regola con un’eccezione","steps":[{"label":"Regola","detail":"Andremo alla mostra: decisione che normalmente vale."},{"label":"Eccezione","detail":"A meno che piova: caso sottratto alla decisione."},{"label":"Esplicita","detail":"A meno che, salvo che, tranne che, spesso con congiuntivo."},{"label":"Implicita","detail":"Tutto fuorché rinunciare: infinito che esprime l’eccezione."},{"label":"Non espletivo","detail":"A meno che non piova può equivalere ad a meno che piova."}]},"pitfalls":[{"mistake":"Il non dopo a meno che nega sempre il verbo.","correction":"Verificare se sia espletivo.","why":"A meno che non piova normalmente pone la pioggia come eccezione."},{"mistake":"Tutti tranne Sara contiene una subordinata.","correction":"Cercare un predicato autonomo.","why":"Tranne Sara è un gruppo nominale e non forma una proposizione."}],"recap":["La subordinata eccettuativa indica un caso che fa eccezione rispetto al contenuto della reggente.","Le eccettuative esplicite sono introdotte da a meno che, salvo che, tranne che, eccetto che, fuorché e locuzioni simili.","La forma implicita impiega soprattutto l’infinito con fuorché, tranne che, eccetto che o salvo.","L’esclusiva presenta un’azione che non accompagna il fatto della reggente: Uscì senza salutare."],"review":[{"question":"Quale parafrasi aiuta per l’eccettuativa?","answer":"Tranne nel caso in cui."},{"question":"Qual è l’eccezione in Usciremo, a meno che piova?","answer":"Il verificarsi della pioggia."},{"question":"Come differiscono eccettuativa ed esclusiva?","answer":"L’eccettuativa sottrae un caso a una regola; l’esclusiva presenta un’azione non compiuta insieme al fatto principale."}],"levels":{"base":{"focus":"Individuare l’eccezione con a meno che.","example":{"sentence":"La mostra aprirà in cortile, a meno che piova.","explanation":"La pioggia è il caso eccettuato che può impedire l’apertura prevista."}},"consolidamento":{"focus":"Distinguere forme esplicite, implicite e gruppi nominali.","example":{"sentence":"La prova si farà fuori, a meno che non piova.","explanation":"Nell’uso comune «non» è espletivo: l’eccezione è la pioggia, non la sua assenza."}},"avanzato":{"focus":"Interpretare il non espletivo e la vicinanza con la condizionale.","example":{"sentence":"Andremo alla mostra, salvo che il treno sia cancellato.","explanation":"La cancellazione è l’eccezione alla decisione; la parafrasi è andremo se il treno non sarà cancellato."}}},"simplified":{"lead":"Una decisione vale tranne in un caso preciso.","steps":["Trova la decisione o regola.","Cerca il caso che la cambia.","Prova la parafrasi tranne nel caso in cui."],"example":{"sentence":"Usciremo, a meno che piova.","explanation":"La pioggia è l’eccezione: se piove, la decisione può cambiare."}},"pei":{"rule":"La regola vale con un’eccezione: usciamo, a meno che piova.","example":{"sentence":"Usciremo, a meno che piova.","explanation":"La pioggia è l’eccezione: se piove, la decisione può cambiare."}},"trackExamples":{"moda":{"sentence":"Useremo il tessuto, a meno che risulti danneggiato.","explanation":"Il danno è l’eccezione alla decisione di usare il materiale."},"arredo":{"sentence":"Useremo il pannello, a meno che risulti danneggiato.","explanation":"Il danno è l’eccezione alla decisione di usare il materiale."},"liuteria":{"sentence":"Useremo l’archetto, a meno che risulti danneggiato.","explanation":"Il danno è l’eccezione alla decisione di usare il materiale."}},"anchor":{"sentence":"Useremo il campione, a meno che la colla lo abbia macchiato.","explanation":"A meno che la colla lo abbia macchiato indica il caso che fa eccezione alla decisione. È eccettuativa esplicita al congiuntivo.","memory":"Regola: lo usiamo. Eccezione: una macchia."}},{"topic":"Esclusive","area":"periodo","lead":"L’esclusiva presenta un’azione o una circostanza che non accompagna il fatto espresso nella reggente.","objectives":["Riconoscere un’azione esclusa","Usare senza e senza che","Distinguere esclusiva ed eccettuativa"],"sections":[{"title":"Il fatto e ciò che manca","text":"La subordinata esclusiva indica che il fatto della reggente avviene senza un’altra azione o circostanza. In Luca uscì senza salutare, l’uscita si verifica e il saluto non l’accompagna.\n\nLa dipendente non formula una regola con un’eccezione: presenta direttamente qualcosa che manca nello svolgimento del fatto. Può avere sfumature vicine al modo, alla concessione o alla conseguenza, ma il suo nucleo rimane l’esclusione di un evento. Per riconoscerla chiediti quale azione non viene compiuta o non si verifica insieme alla reggente.","examples":[{"sentence":"Marta consegnò il bozzetto senza firmarlo.","explanation":"La consegna avviene, ma manca la firma: esclusiva implicita."},{"sentence":"Luca uscì senza che nessuno lo vedesse.","explanation":"La dipendente esclude il fatto che qualcuno veda l’uscita: esclusiva esplicita."}]},{"title":"La forma implicita","text":"L’esclusiva implicita è introdotta da senza e ha il verbo all’infinito. Il soggetto coincide normalmente con quello della reggente: in Sara parlò senza leggere, è Sara sia a parlare sia a non leggere.\n\nL’infinito presente esprime un’azione esclusa nello stesso quadro temporale della reggente; l’infinito passato può presentare un’azione precedente non compiuta. Per trasformare la frase conserva soggetti e rapporti di tempo. La presenza di senza non basta, perché può introdurre anche un semplice nome invece di una proposizione.","examples":[{"sentence":"L’allievo montò il ripiano senza aver letto le istruzioni.","explanation":"L’infinito passato indica una lettura precedente che non è avvenuta; il montaggio invece avviene."}]},{"title":"La forma esplicita","text":"L’esclusiva esplicita usa senza che e il congiuntivo. Permette di rendere evidente il soggetto della dipendente, soprattutto quando è diverso da quello della reggente: Spostai il leggio senza che il musicista se ne accorgesse.\n\nIn presenza di nessuno o niente non occorre aggiungere automaticamente un altro non dopo senza che. Controlla il significato complessivo della negazione. Se i soggetti coincidono, la forma implicita è spesso più semplice, mentre l’esplicita può essere utile quando vuoi sottolineare o chiarire il riferimento.","examples":[{"sentence":"Spostammo il tavolo senza che Sara se ne accorgesse.","explanation":"Il soggetto della reggente è noi; quello della dipendente è Sara. La forma esplicita rende chiara la differenza."}]},{"title":"Esclusione e rapporti vicini","text":"In senza una firma non c’è un predicato e dunque non c’è una subordinata; in senza firmare c’è un infinito con valore verbale e una dipendente. L’eccettuativa introduce invece un caso sottratto a una regola: Accetterò tutto tranne che rinunciare.\n\nUna frase come Partì senza avvisarci può inoltre suggerire sorpresa o disapprovazione, ma questa sfumatura comunicativa non cancella la costruzione esclusiva. Per analizzare distingui il rapporto grammaticale di base dagli effetti che il contesto e le aspettative del parlante possono aggiungere.","examples":[{"sentence":"Il progetto fu approvato senza che fosse completo.","explanation":"La struttura è esclusiva; nel contesto può aggiungere una sfumatura concessiva, perché l’incompletezza avrebbe potuto impedire l’approvazione."}]}],"diagram":{"title":"Il fatto avviene senza un’altra azione","steps":[{"label":"Fatto","detail":"Marta consegna il bozzetto: l’evento della reggente avviene."},{"label":"Azione esclusa","detail":"Senza firmarlo: manca la firma."},{"label":"Implicita","detail":"Senza e infinito, normalmente con soggetto uguale alla reggente."},{"label":"Esplicita","detail":"Senza che e congiuntivo, anche con soggetto diverso."},{"label":"Eccezione diversa","detail":"Tutto tranne che rinunciare sottrae un caso a una regola: è eccettuativa."}]},"pitfalls":[{"mistake":"Senza una firma è una subordinata.","correction":"Distinguere nome e verbo.","why":"Una firma è un gruppo nominale; firmare può invece creare una dipendente."},{"mistake":"Trasformare senza che Sara legga in senza leggere conserva sempre il senso.","correction":"Controllare il soggetto dell’infinito.","why":"L’implicita attribuirebbe normalmente la lettura al soggetto della reggente."}],"recap":["La subordinata esclusiva indica che il fatto della reggente avviene senza un’altra azione o circostanza.","L’esclusiva implicita è introdotta da senza e ha il verbo all’infinito.","L’esclusiva esplicita usa senza che e il congiuntivo.","In senza una firma non c’è un predicato e dunque non c’è una subordinata; in senza firmare c’è un infinito con valore verbale e una dipendente."],"review":[{"question":"Che cosa esclude la subordinata in Esce senza salutare?","answer":"L’azione del saluto, che non accompagna l’uscita."},{"question":"Quale modo segue senza che?","answer":"Il congiuntivo."},{"question":"Come trasformi Marta consegnò il bozzetto senza firmarlo?","answer":"Marta consegnò il bozzetto senza che lei stessa lo firmasse, conservando Marta come soggetto di entrambe le azioni."}],"levels":{"base":{"focus":"Riconoscere senza e infinito.","example":{"sentence":"Marta consegnò il bozzetto senza firmarlo.","explanation":"La consegna avviene, ma manca la firma: esclusiva implicita."}},"consolidamento":{"focus":"Confrontare soggetti uguali e diversi.","example":{"sentence":"L’allievo montò il ripiano senza aver letto le istruzioni.","explanation":"L’infinito passato indica una lettura precedente che non è avvenuta; il montaggio invece avviene."}},"avanzato":{"focus":"Distinguere struttura esclusiva e sfumature concessive.","example":{"sentence":"Il progetto fu approvato senza che fosse completo.","explanation":"La struttura è esclusiva; nel contesto può aggiungere una sfumatura concessiva, perché l’incompletezza avrebbe potuto impedire l’approvazione."}}},"simplified":{"lead":"Un fatto avviene senza un’altra azione.","steps":["Trova l’azione che avviene.","Cerca senza oppure senza che.","Individua l’azione che manca."],"example":{"sentence":"Luca esce senza salutare.","explanation":"Luca esce, ma non saluta. Senza salutare è esclusiva."}},"pei":{"rule":"L’esclusiva dice che cosa non avviene: esce senza salutare.","example":{"sentence":"Luca esce senza salutare.","explanation":"Luca esce, ma non saluta. Senza salutare è esclusiva."}},"trackExamples":{"moda":{"sentence":"La sarta spostò il tessuto senza piegarlo.","explanation":"La piegatura è l’azione esclusa durante lo spostamento."},"arredo":{"sentence":"Il falegname spostò il pannello senza graffiarlo.","explanation":"La graffiatura è l’azione esclusa durante lo spostamento."},"liuteria":{"sentence":"Il liutaio spostò lo strumento senza toccare le corde.","explanation":"Il contatto con le corde è l’azione esclusa durante lo spostamento."}},"anchor":{"sentence":"Amir consegnò il bozzetto senza firmarlo.","explanation":"La consegna avviene; la firma manca. Senza firmarlo è esclusiva implicita e il soggetto dell’infinito è Amir.","memory":"Due azioni sulla lista: consegnare sì, firmare no."}},{"topic":"Discorso diretto e indiretto","area":"periodo","lead":"Il discorso diretto conserva le parole come citazione; l’indiretto ne riferisce il contenuto dal punto di vista di chi racconta.","objectives":["Riconoscere citazione e contenuto riportato","Adeguare persone tempi e riferimenti","Trasformare domande e richieste conservando il senso"],"sections":[{"title":"Citare o riferire","text":"Il discorso diretto presenta parole attribuite a un parlante attraverso una citazione, normalmente segnalata da due punti e virgolette. Il discorso indiretto integra il contenuto in una frase retta da dire, affermare, chiedere, spiegare o altri verbi.\n\nNon conserva necessariamente le stesse parole, ma deve rispettare ciò che è stato comunicato e l’intenzione originaria. Può esprimere un’affermazione, una domanda, un ordine o una richiesta. Prima della trasformazione identifica chi parla, a chi si rivolge e chi riferisce il messaggio.","examples":[{"sentence":"Anna dice: «Ho finito il modello».","explanation":"Le virgolette presentano una citazione in discorso diretto."},{"sentence":"Anna dice che ha finito il modello.","explanation":"Il contenuto diventa una oggettiva dipendente da dice."}]},{"title":"Persone, luoghi e riferimenti","text":"Nel passaggio all’indiretto cambiano i riferimenti personali e possessivi secondo il nuovo punto di vista: io può diventare lei, mio può diventare suo. Anche qui, oggi, domani, questo richiedono attenzione.\n\nSe chi racconta si trova nello stesso luogo o nello stesso giorno, alcuni riferimenti possono rimanere; se il contesto cambia, occorrono lì, quel giorno, il giorno dopo o altre espressioni coerenti. Non sostituire parole in modo automatico: ricostruisci chi possiede che cosa e a quale momento o luogo ci si riferisce.","examples":[{"sentence":"Lunedì Elena disse: «Domani porterò il campione». Venerdì riferisco: Elena disse che il giorno dopo avrebbe portato il campione.","explanation":"Il giorno dopo conserva il riferimento a martedì, mentre domani, detto venerdì, indicherebbe sabato."}]},{"title":"I tempi rispetto al racconto","text":"Con una reggente al presente spesso si conservano i tempi relativi al momento originario. Con una reggente al passato, nella normale trasposizione narrativa la contemporaneità passa frequentemente all’imperfetto, l’anteriorità al trapassato e la posteriorità al condizionale passato.\n\nIl futuro nel passato non indica necessariamente un’ipotesi: avrebbe portato può riferire un evento allora futuro. La trasposizione dipende però dalla prospettiva: una verità ancora valida può restare al presente. È essenziale preservare il rapporto fra gli eventi, senza applicare sostituzioni meccaniche.","examples":[{"sentence":"Il maestro disse: «Il legno assorbe umidità» → Il maestro disse che il legno assorbe umidità.","explanation":"Il presente può rimanere perché si riferisce una proprietà generale considerata ancora valida."}]},{"title":"Domande, ordini e intenzioni","text":"Le domande diventano interrogative indirette, introdotte da se per quelle totali oppure dalla parola interrogativa originaria per quelle parziali. Ordini e richieste possono essere riportati con di e infinito o con che e congiuntivo, secondo il verbo reggente.\n\nConserva il destinatario e il valore comunicativo: Vieni qui non deve diventare una semplice previsione. La punteggiatura interrogativa riguarda l’intera frase, non automaticamente la subordinata. Quando mancano informazioni su chi riferisce o su quando, possono esserci più trasformazioni corrette: spiega il contesto scelto.","examples":[{"sentence":"La docente chiese a Marco: «Hai misurato il tavolo?» → La docente chiese a Marco se avesse misurato il tavolo.","explanation":"La domanda totale diventa interrogativa indiretta; il trapassato conserva l’anteriorità della misurazione."}]}],"diagram":{"title":"Riferire le parole nel loro contesto","steps":[{"label":"Diretto","detail":"Citazione segnalata da virgolette: Sara dice: «Ho finito»."},{"label":"Indiretto","detail":"Contenuto integrato: Sara dice che ha finito."},{"label":"Riferimenti","detail":"Io, mio, qui, domani cambiano secondo chi riferisce, dove e quando."},{"label":"Tempi relativi","detail":"Con reggente passata: contemporaneità spesso all’imperfetto, anteriorità al trapassato, posteriorità al condizionale passato."},{"label":"Intenzioni","detail":"Domande con se o parola interrogativa; richieste con di e infinito o che e congiuntivo."}]},"pitfalls":[{"mistake":"Domani diventa sempre il giorno dopo.","correction":"Controllare il momento di chi riferisce.","why":"Se il messaggio viene riferito nello stesso giorno, domani può conservare il riferimento."},{"mistake":"Il presente diventa sempre imperfetto dopo disse.","correction":"Verificare prospettiva e validità del contenuto.","why":"Una proprietà generale ancora valida può restare al presente."}],"recap":["Il discorso diretto presenta parole attribuite a un parlante attraverso una citazione, normalmente segnalata da due punti e virgolette.","Nel passaggio all’indiretto cambiano i riferimenti personali e possessivi secondo il nuovo punto di vista: io può diventare lei, mio può diventare suo.","Con una reggente al presente spesso si conservano i tempi relativi al momento originario.","Le domande diventano interrogative indirette, introdotte da se per quelle totali oppure dalla parola interrogativa originaria per quelle parziali."],"review":[{"question":"Come si riporta una domanda totale?","answer":"Con un’interrogativa indiretta introdotta da se."},{"question":"Che cosa esprime avrebbe finito in Disse che avrebbe finito?","answer":"Normalmente posteriorità rispetto al momento passato del dire: è futuro nel passato."},{"question":"Perché una trasformazione può avere più versioni corrette?","answer":"Persone, tempi e indicatori dipendono dal luogo, dal momento e dalla prospettiva di chi riferisce."}],"levels":{"base":{"focus":"Riferire affermazioni con una reggente al presente.","example":{"sentence":"Anna dice: «Ho finito il modello».","explanation":"Le virgolette presentano una citazione in discorso diretto."}},"consolidamento":{"focus":"Trasporre al passato persone, tempi e riferimenti.","example":{"sentence":"Lunedì Elena disse: «Domani porterò il campione». Venerdì riferisco: Elena disse che il giorno dopo avrebbe portato il campione.","explanation":"Il giorno dopo conserva il riferimento a martedì, mentre domani, detto venerdì, indicherebbe sabato."}},"avanzato":{"focus":"Motivare le scelte contestuali e riportare ordini e domande.","example":{"sentence":"La docente chiese a Marco: «Hai misurato il tavolo?» → La docente chiese a Marco se avesse misurato il tavolo.","explanation":"La domanda totale diventa interrogativa indiretta; il trapassato conserva l’anteriorità della misurazione."}}},"simplified":{"lead":"Puoi citare le parole oppure riferire il loro contenuto.","steps":["Trova chi ha parlato e chi ascolta.","Chiarisci quando e dove sono state dette le parole.","Riferisci il contenuto conservando i riferimenti corretti."],"example":{"sentence":"Mia dice: «Leggo». → Mia dice che legge.","explanation":"Le parole tra virgolette diventano un contenuto introdotto da che."}},"pei":{"rule":"Prima guarda chi parla e quando. Poi riferisci le parole conservando il senso.","example":{"sentence":"Mia dice: «Leggo». → Mia dice che legge.","explanation":"Le parole tra virgolette diventano un contenuto introdotto da che."}},"trackExamples":{"moda":{"sentence":"La sarta dice: «Ho finito» → La sarta dice che ha finito.","explanation":"L’affermazione citata diventa un contenuto introdotto da che."},"arredo":{"sentence":"Il falegname dice: «Ho finito» → Il falegname dice che ha finito.","explanation":"L’affermazione citata diventa un contenuto introdotto da che."},"liuteria":{"sentence":"Il liutaio dice: «Ho finito» → Il liutaio dice che ha finito.","explanation":"L’affermazione citata diventa un contenuto introdotto da che."}},"anchor":{"sentence":"Lunedì Sara disse: «Domani finirò». Venerdì riferisco: Sara disse che il giorno dopo avrebbe finito.","explanation":"Il giorno dopo continua a indicare martedì. Avrebbe finito esprime un evento futuro rispetto al lunedì del dire, senza confermare che sia poi avvenuto.","memory":"Conserva il giorno sul calendario: cambia la frase, non il martedì."}},{"topic":"Denominazione e argomento","area":"frase","lead":"Il complemento di denominazione dà un nome proprio; quello di argomento indica il tema di cui si parla, si scrive o si discute.","objectives":["Riconoscere il nome proprio che denomina","Individuare il tema di un discorso","Distinguere denominazione argomento e specificazione"],"sections":[{"title":"Dare un nome a un elemento","text":"Il complemento di denominazione specifica con un nome proprio la denominazione di un nome comune. È frequente con nomi geografici, giorni, mesi, titoli o altre designazioni, secondo la costruzione.\n\nLa preposizione tipica è di: la città di Cremona, il mese di maggio. Per riconoscerlo controlla se il nome comune e il nome proprio indicano lo stesso referente: Cremona è proprio la città di cui si parla. Il nome non esprime possesso o appartenenza, ma identifica attraverso una denominazione.","examples":[{"sentence":"La città di Cremona ospita laboratori di liuteria.","explanation":"Di Cremona denomina la città: la città si chiama Cremona."},{"sentence":"Il mese di novembre è iniziato.","explanation":"Di novembre precisa quale mese attraverso il suo nome."}]},{"title":"Denominazione e specificazione","text":"La presenza di un nome proprio dopo di non garantisce un complemento di denominazione. In Il laboratorio di Sara, Sara non è il nome del laboratorio: il rapporto è di appartenenza o riferimento, quindi si analizza come specificazione.\n\nIn Il porto di Genova, il porto non coincide con la città Genova e di Genova esprime normalmente una relazione di specificazione. Senza preposizione, nomi come il fiume Po sono spesso analizzati attraverso l’apposizione. La terminologia può variare: esplicita sempre il rapporto tra i due nomi.","examples":[{"sentence":"Il violino di Marta è nella custodia.","explanation":"Di Marta indica appartenenza, non il nome proprio dello strumento: complemento di specificazione."}]},{"title":"Indicare il tema","text":"Il complemento di argomento indica ciò di cui si parla, si scrive, si legge o si discute. Dipende spesso da verbi di comunicazione e pensiero, ma può collegarsi anche a nomi come libro, lezione, conferenza, articolo.\n\nÈ introdotto da di, su, intorno a, riguardo a, a proposito di e locuzioni simili. Può riferirsi a una materia, a un evento, a un oggetto o a una persona. Per riconoscerlo chiedi su quale tema si svolga la comunicazione e ricostruisci il contenuto complessivo della frase.","examples":[{"sentence":"Abbiamo discusso della scelta dei materiali.","explanation":"Della scelta dei materiali indica il tema della discussione: complemento di argomento."}]},{"title":"Confrontare funzioni e costruzioni","text":"Uno stesso gruppo con di può esprimere denominazione, argomento, materia o specificazione: il significato si ricava dal nome o dal verbo a cui si collega. In Un libro sulla musica, sulla musica indica il tema; in Un libro sul tavolo, sul tavolo indica il luogo.\n\nAnche parlare di Marta presenta una persona come argomento, senza trasformarla in un possessore. Se il contenuto comprende un predicato autonomo, può aprirsi invece una subordinata. Nell’analisi logica resta quindi attento sia alla funzione sia alla forma del segmento.","examples":[{"sentence":"Leggiamo un articolo sulla verniciatura.","explanation":"Sulla verniciatura indica l’argomento dell’articolo; non descrive il luogo in cui si trova."}]}],"diagram":{"title":"Nome proprio oppure tema","steps":[{"label":"Denominazione","detail":"La città di Cremona: Cremona è il nome della città."},{"label":"Specificazione","detail":"Il violino di Sara: Sara non è il nome del violino, ma ne indica l’appartenenza."},{"label":"Argomento","detail":"Parliamo di musica: musica è il tema del discorso."},{"label":"Forme","detail":"Denominazione soprattutto con di; argomento con di, su, riguardo a, a proposito di."},{"label":"Contesto","detail":"Un libro sulla musica: tema. Un libro sul tavolo: luogo."}]},"pitfalls":[{"mistake":"Ogni di seguito da nome proprio è denominazione.","correction":"Verificare se il nome proprio denomini davvero il nome comune.","why":"Di Sara in il quaderno di Sara esprime appartenenza."},{"mistake":"Su introduce sempre un luogo.","correction":"Leggere il rapporto con il verbo o il nome.","why":"Un articolo sul legno parla del legno e contiene un complemento di argomento."}],"recap":["Il complemento di denominazione specifica con un nome proprio la denominazione di un nome comune.","La presenza di un nome proprio dopo di non garantisce un complemento di denominazione.","Il complemento di argomento indica ciò di cui si parla, si scrive, si legge o si discute.","Uno stesso gruppo con di può esprimere denominazione, argomento, materia o specificazione: il significato si ricava dal nome o dal verbo a cui si collega."],"review":[{"question":"Quale prova aiuta per la denominazione?","answer":"Controllare se il nome proprio sia proprio il nome del referente indicato dal nome comune."},{"question":"Quale funzione ha di musica in Parliamo di musica?","answer":"Complemento di argomento."},{"question":"Perché di Genova in il porto di Genova non è normalmente denominazione?","answer":"Perché Genova è il nome della città, non il nome proprio del porto considerato come identico referente."}],"levels":{"base":{"focus":"Distinguere nome proprio e tema del discorso.","example":{"sentence":"La città di Cremona ospita laboratori di liuteria.","explanation":"Di Cremona denomina la città: la città si chiama Cremona."}},"consolidamento":{"focus":"Confrontare denominazione e specificazione.","example":{"sentence":"Il violino di Marta è nella custodia.","explanation":"Di Marta indica appartenenza, non il nome proprio dello strumento: complemento di specificazione."}},"avanzato":{"focus":"Motivare funzioni diverse di di e su nella stessa struttura.","example":{"sentence":"Leggiamo un articolo sulla verniciatura.","explanation":"Sulla verniciatura indica l’argomento dell’articolo; non descrive il luogo in cui si trova."}}},"simplified":{"lead":"Un nome può indicare come si chiama un luogo oppure il tema di un discorso.","steps":["Cerca il gruppo da analizzare.","Chiedi se dà un nome proprio a qualcosa.","Se indica ciò di cui si parla, è argomento."],"example":{"sentence":"La città di Cremona. Parliamo di musica.","explanation":"Di Cremona dà il nome alla città. Di musica indica il tema della conversazione."}},"pei":{"rule":"Denominazione: come si chiama? Argomento: di quale tema si parla?","example":{"sentence":"La città di Cremona. Parliamo di musica.","explanation":"Di Cremona dà il nome alla città. Di musica indica il tema della conversazione."}},"trackExamples":{"moda":{"sentence":"Il mese di maggio parleremo di tessuti.","explanation":"Di maggio denomina il mese; di tessuti indica l’argomento."},"arredo":{"sentence":"Il mese di maggio parleremo di arredi.","explanation":"Di maggio denomina il mese; di arredi indica l’argomento."},"liuteria":{"sentence":"Il mese di maggio parleremo di strumenti.","explanation":"Di maggio denomina il mese; di strumenti indica l’argomento."}},"anchor":{"sentence":"Nella città di Cremona parliamo di violini.","explanation":"Di Cremona denomina la città: essa si chiama Cremona. Di violini indica invece il tema della conversazione.","memory":"Cremona è il nome sulla mappa; violini è il tema della chiacchierata."}},{"topic":"Limitazione e paragone","area":"frase","lead":"La limitazione precisa in quale ambito vale un giudizio; il paragone indica il secondo termine di un confronto.","objectives":["Riconoscere l’ambito di validità","Individuare i due termini di un confronto","Distinguere complementi e subordinate corrispondenti"],"sections":[{"title":"Limitare un giudizio","text":"Il complemento di limitazione indica rispetto a quale ambito vale una qualità, una valutazione o una condizione. In È abile nel disegno non si afferma che la persona sia abile in ogni attività: il giudizio riguarda il disegno.\n\nSi trova con aggettivi, nomi e verbi, ed è introdotto da in, di, a, per, quanto a, rispetto a e altre espressioni. Può comparire anche senza preposizione in formule particolari. La domanda utile è limitatamente a che cosa oppure sotto quale aspetto, da verificare sempre nel contesto.","examples":[{"sentence":"Sara è precisa nelle misure.","explanation":"Nelle misure delimita l’ambito in cui vale il giudizio precisa."},{"sentence":"Quanto a resistenza, il rovere è adatto.","explanation":"Quanto a resistenza presenta l’aspetto rispetto al quale viene valutato il materiale."}]},{"title":"Non confondere ambito e modo","text":"Il complemento di modo descrive come si compie un’azione; la limitazione restringe il campo di una qualità o valutazione. In Disegna con precisione, con precisione indica la maniera dell’azione. In È bravo nel disegno, nel disegno indica l’ambito dell’abilità.\n\nIl complemento di argomento presenta invece il tema di una comunicazione: Discutiamo del disegno. Le parole possono coincidere, mentre cambia il rapporto con il resto della frase. Evita classificazioni fondate sulla sola preposizione e ricostruisci ciò che il parlante sta valutando o descrivendo.","examples":[{"sentence":"È rapido nel montaggio, ma lavora con cautela.","explanation":"Nel montaggio limita il giudizio rapido; con cautela indica il modo di lavorare."}]},{"title":"Il secondo termine di paragone","text":"Il complemento di paragone esprime il secondo termine di un confronto di maggioranza, minoranza o uguaglianza. Con più e meno si usa spesso di; con tanto o così sono comuni quanto e come.\n\nChe compare soprattutto nel confronto fra qualità riferite allo stesso elemento, fra infiniti o fra gruppi introdotti da preposizione: È più pratico che elegante. Identifica sempre che cosa viene confrontato e secondo quale qualità. Il primo termine appartiene alla costruzione reggente, mentre il complemento esprime il secondo termine del confronto.","examples":[{"sentence":"Il pino è più leggero del rovere.","explanation":"Del rovere è il secondo termine: il confronto riguarda il peso dei due legni."}]},{"title":"Dal complemento alla proposizione","text":"Un secondo termine formato da un nome o un pronome è un complemento di paragone: più alto di me. Se invece contiene una proposizione, si passa all’analisi del periodo: più alto di quanto pensassi contiene una comparativa.\n\nAllo stesso modo, in disegno può essere complemento di limitazione, mentre per quanto ne so contiene una subordinata limitativa. Non ogni di vicino a più introduce però un paragone: più di tre metri può quantificare una misura. Controlla che esistano davvero due termini confrontati.","examples":[{"sentence":"La mensola è lunga quanto il banco.","explanation":"Quanto il banco è complemento di paragone di uguaglianza; se aggiungessi quanto avevamo previsto, avresti una subordinata comparativa."}]}],"diagram":{"title":"Ambito del giudizio e confronto","steps":[{"label":"Limitazione","detail":"Abile nel disegno: l’abilità vale in quell’ambito."},{"label":"Maggioranza / minoranza","detail":"Più o meno alto di me: di me è il secondo termine."},{"label":"Uguaglianza","detail":"Tanto alto quanto me: quanto me è il secondo termine."},{"label":"Che nel confronto","detail":"Più pratico che elegante: confronto fra qualità dello stesso elemento."},{"label":"Proposizione diversa","detail":"Più alto di quanto pensassi contiene una comparativa; per quanto ne so una limitativa."}]},"pitfalls":[{"mistake":"Con precisione e nel disegno indicano lo stesso rapporto.","correction":"Distinguere maniera dell’azione e ambito del giudizio.","why":"Si può lavorare con precisione ed essere abili soltanto in un settore."},{"mistake":"Ogni più di contiene un complemento di paragone.","correction":"Verificare i due termini del confronto.","why":"Più di due metri indica una quantità superiore a una soglia."}],"recap":["Il complemento di limitazione indica rispetto a quale ambito vale una qualità, una valutazione o una condizione.","Il complemento di modo descrive come si compie un’azione; la limitazione restringe il campo di una qualità o valutazione.","Il complemento di paragone esprime il secondo termine di un confronto di maggioranza, minoranza o uguaglianza.","Un secondo termine formato da un nome o un pronome è un complemento di paragone: più alto di me."],"review":[{"question":"Quale domanda aiuta per la limitazione?","answer":"Sotto quale aspetto o limitatamente a quale ambito vale il giudizio?"},{"question":"Quale funzione ha del rovere in più leggero del rovere?","answer":"Complemento di paragone, secondo termine del confronto."},{"question":"Come distingui comparativa e complemento di paragone?","answer":"La comparativa contiene un predicato autonomo; il complemento è un gruppo senza una propria proposizione."}],"levels":{"base":{"focus":"Riconoscere l’ambito e il secondo termine di paragone.","example":{"sentence":"Sara è precisa nelle misure.","explanation":"Nelle misure delimita l’ambito in cui vale il giudizio precisa."}},"consolidamento":{"focus":"Scegliere di, che, quanto e come nei confronti comuni.","example":{"sentence":"È rapido nel montaggio, ma lavora con cautela.","explanation":"Nel montaggio limita il giudizio rapido; con cautela indica il modo di lavorare."}},"avanzato":{"focus":"Distinguere confronto, quantificazione e subordinate corrispondenti.","example":{"sentence":"La mensola è lunga quanto il banco.","explanation":"Quanto il banco è complemento di paragone di uguaglianza; se aggiungessi quanto avevamo previsto, avresti una subordinata comparativa."}}},"simplified":{"lead":"Una frase può limitare un giudizio oppure confrontare due elementi.","steps":["Chiedi in quale ambito vale il giudizio.","Se c’è un confronto, trova i due termini.","Distingui l’ambito dal secondo termine del paragone."],"example":{"sentence":"Sara è brava nel disegno. Luca è più alto di me.","explanation":"Nel disegno indica l’ambito dell’abilità. Di me è il secondo termine del confronto."}},"pei":{"rule":"Limitazione: in quale ambito? Paragone: rispetto a quale altro elemento?","example":{"sentence":"Sara è brava nel disegno. Luca è più alto di me.","explanation":"Nel disegno indica l’ambito dell’abilità. Di me è il secondo termine del confronto."}},"trackExamples":{"moda":{"sentence":"La seta è più leggera del denim.","explanation":"Del denim è complemento di paragone: il secondo termine del confronto."},"arredo":{"sentence":"Il pino è più leggero del rovere.","explanation":"Del rovere è complemento di paragone: il secondo termine del confronto."},"liuteria":{"sentence":"Questo archetto è più leggero dell’altro.","explanation":"Dell’altro è complemento di paragone: il secondo termine del confronto."}},"anchor":{"sentence":"Nel disegno Sara è più precisa di me.","explanation":"Nel disegno limita il giudizio a un ambito; di me è il secondo termine del confronto di maggioranza. Nessuno dei due gruppi forma una subordinata.","memory":"Prima delimita il campo, poi confronta le persone."}},{"topic":"Complementi di misura","area":"frase","lead":"I complementi di misura esprimono quantità legate a dimensioni, peso, distanza, età, valore e costo.","objectives":["Collegare una quantità alla grandezza misurata","Distinguere misura stima e prezzo","Riconoscere unità e riferimenti della misura"],"sections":[{"title":"Dimensioni e peso","text":"I complementi di misura quantificano una grandezza. Il complemento di estensione indica lunghezza, larghezza, altezza, profondità o superficie: un pannello largo ottanta centimetri, una stanza di venti metri quadrati. Il complemento di peso o misura quantifica il peso: il tavolo pesa venti chili.\n\nQueste espressioni possono comparire senza preposizione oppure con di, per, a, secondo il verbo e la costruzione. Per analizzarle individua la grandezza, il valore e l’unità. Non classificare la quantità come oggetto solo perché segue direttamente un verbo.","examples":[{"sentence":"Il tavolo pesa venti chili.","explanation":"Venti chili quantifica il peso: non è un oggetto che il tavolo compie o riceve."},{"sentence":"Il pannello è largo ottanta centimetri.","explanation":"Ottanta centimetri esprime una dimensione e si analizza come complemento di estensione."}]},{"title":"Distanza ed età","text":"Il complemento di distanza indica quanto un elemento è lontano da un punto di riferimento: il laboratorio dista due chilometri dalla scuola. La quantità e il punto di riferimento hanno funzioni diverse e vanno distinti.\n\nIl complemento di età esprime quanti anni ha una persona o un oggetto, oppure a quale età si verifica un fatto: un’allieva di quindici anni, a sedici anni iniziò il corso. La forma cambia con la costruzione, ma il valore rimane legato all’età. Non confondere una durata con l’età di qualcuno.","examples":[{"sentence":"Il laboratorio dista due chilometri dalla scuola.","explanation":"Due chilometri è la distanza; dalla scuola è il punto rispetto al quale viene misurata."}]},{"title":"Stima e prezzo","text":"Il complemento di stima indica il valore attribuito a qualcosa, anche in modo non preciso: un oggetto stimato mille euro, un lavoro valutato molto. Il complemento di prezzo indica invece quanto si paga, si vende, si compra o si affitta: abbiamo comprato il materiale per trenta euro.\n\nLa stessa somma può assumere una funzione diversa secondo il verbo e il rapporto: vale cinquanta euro esprime una valutazione; costa cinquanta euro indica il prezzo. Gratis, poco, molto e simili possono avere valore avverbiale corrispondente.","examples":[{"sentence":"L’abito è stimato cento euro, ma è stato venduto per ottanta euro.","explanation":"Cento euro esprime la stima; per ottanta euro esprime il prezzo effettivo di vendita."}]},{"title":"Differenze e quantità da interpretare","text":"Un confronto può contenere una misura della differenza: il nuovo ripiano è più lungo di cinque centimetri. Qui di cinque centimetri quantifica lo scarto; non è il secondo termine del paragone. Le grammatiche possono includerlo nella misura o chiamarlo complemento di differenza.\n\nAnche le quantità prive di numero preciso, come pochi centimetri o circa tre chili, mantengono il valore di misura. Distingui infine dimensione e durata: lavorare per due ore misura il tempo, non l’estensione spaziale. Le unità e il contesto permettono di riconoscere la grandezza pertinente.","examples":[{"sentence":"La nuova tavola è più lunga della precedente di tre centimetri.","explanation":"Della precedente è il secondo termine di paragone; di tre centimetri misura la differenza."}]}],"diagram":{"title":"Quale grandezza quantifica il numero","steps":[{"label":"Estensione e peso","detail":"Largo un metro; pesa venti chili: dimensione oppure peso."},{"label":"Distanza ed età","detail":"Dista due chilometri; un’allieva di quindici anni."},{"label":"Stima","detail":"Stimato cento euro: valore attribuito."},{"label":"Prezzo","detail":"Venduto per ottanta euro: importo dello scambio."},{"label":"Differenza","detail":"Più lungo di tre centimetri: misura dello scarto, non secondo termine di paragone."}]},"pitfalls":[{"mistake":"Venti chili è oggetto perché non ha una preposizione.","correction":"Individuare la grandezza quantificata.","why":"Dopo pesa la quantità esprime il peso."},{"mistake":"Stima e prezzo coincidono sempre.","correction":"Distinguere valore attribuito e importo dello scambio.","why":"Un oggetto può essere stimato cento euro e venduto a una cifra diversa."}],"recap":["I complementi di misura quantificano una grandezza.","Il complemento di distanza indica quanto un elemento è lontano da un punto di riferimento: il laboratorio dista due chilometri dalla scuola.","Il complemento di stima indica il valore attribuito a qualcosa, anche in modo non preciso: un oggetto stimato mille euro, un lavoro valutato molto.","Un confronto può contenere una misura della differenza: il nuovo ripiano è più lungo di cinque centimetri."],"review":[{"question":"Quale grandezza esprime largo un metro?","answer":"Una dimensione: complemento di estensione."},{"question":"Come distingui età e durata?","answer":"L’età riguarda gli anni di una persona o cosa; la durata riguarda quanto si prolunga un evento."},{"question":"In più alto di Marco di due centimetri, quali sono i due gruppi con di?","answer":"Di Marco è il secondo termine di paragone; di due centimetri quantifica la differenza."}],"levels":{"base":{"focus":"Riconoscere peso, dimensione, età e costo.","example":{"sentence":"Il tavolo pesa venti chili.","explanation":"Venti chili quantifica il peso: non è un oggetto che il tavolo compie o riceve."}},"consolidamento":{"focus":"Distinguere distanza, durata, stima e prezzo.","example":{"sentence":"Il laboratorio dista due chilometri dalla scuola.","explanation":"Due chilometri è la distanza; dalla scuola è il punto rispetto al quale viene misurata."}},"avanzato":{"focus":"Analizzare nello stesso confronto secondo termine e misura della differenza.","example":{"sentence":"La nuova tavola è più lunga della precedente di tre centimetri.","explanation":"Della precedente è il secondo termine di paragone; di tre centimetri misura la differenza."}}},"simplified":{"lead":"Una quantità può dire quanto è lungo, pesante, lontano, vecchio o costoso un elemento.","steps":["Trova il numero e l’unità.","Chiedi quale grandezza viene misurata.","Distingui dimensione, peso, distanza, età, valore o costo."],"example":{"sentence":"Il tavolo pesa venti chili.","explanation":"Venti chili indica il peso del tavolo."}},"pei":{"rule":"Guarda che cosa misura il numero: centimetri, chili, anni oppure euro.","example":{"sentence":"Il tavolo pesa venti chili.","explanation":"Venti chili indica il peso del tavolo."}},"trackExamples":{"moda":{"sentence":"Il nastro è lungo due metri.","explanation":"Due metri misura la lunghezza: complemento di estensione."},"arredo":{"sentence":"Il ripiano è lungo due metri.","explanation":"Due metri misura la lunghezza: complemento di estensione."},"liuteria":{"sentence":"Il banco da liutaio è lungo due metri.","explanation":"Due metri misura la lunghezza: complemento di estensione."}},"anchor":{"sentence":"Il banco è lungo due metri e pesa venti chili.","explanation":"Due metri misura la lunghezza: estensione. Venti chili misura il peso. Le quantità non diventano oggetti solo perché non hanno una preposizione.","memory":"Metri per il metro, chili per la bilancia."}},{"topic":"Predicativi del soggetto e dell’oggetto","area":"frase","lead":"Il predicativo attribuisce una qualità, uno stato o un ruolo a un soggetto o a un oggetto attraverso il verbo.","objectives":["Individuare a chi si riferisce il predicativo","Distinguere soggetto e oggetto","Separare predicativo attributo apposizione e nome del predicato"],"sections":[{"title":"Una qualità collegata attraverso il verbo","text":"Il complemento predicativo è un nome o un aggettivo che attribuisce una qualità, uno stato o un ruolo attraverso il verbo. Non si collega soltanto a un nome: completa o accompagna ciò che il verbo dice di quel referente.\n\nSe si riferisce al soggetto è predicativo del soggetto; se si riferisce al complemento oggetto è predicativo dell’oggetto. Per riconoscerlo trova prima il predicato e i suoi argomenti, poi chiedi a chi venga attribuita la qualità o il ruolo. La concordanza aiuta quando la parola è variabile.","examples":[{"sentence":"Marta sembra stanca.","explanation":"Stanca si riferisce al soggetto Marta attraverso il verbo sembra: predicativo del soggetto."},{"sentence":"Considero Marta affidabile.","explanation":"Affidabile si riferisce all’oggetto Marta attraverso considero: predicativo dell’oggetto."}]},{"title":"Il predicativo del soggetto","text":"Il predicativo del soggetto compare con verbi copulativi come sembrare, diventare, restare e risultare, che richiedono o favoriscono un completamento. Può comparire anche con verbi dal significato pieno: tornò soddisfatta, camminava sola.\n\nCon verbi passivi di nomina, giudizio o trasformazione il ruolo attribuito riguarda il soggetto: Sara è stata eletta rappresentante. Nelle classificazioni scolastiche la copula essere con il suo nome o aggettivo viene normalmente trattata invece come predicato nominale, non come verbo seguito da complemento predicativo.","examples":[{"sentence":"Sara è stata eletta rappresentante.","explanation":"Rappresentante attribuisce un ruolo al soggetto Sara attraverso il verbo passivo è stata eletta."}]},{"title":"Il predicativo dell’oggetto","text":"Il predicativo dell’oggetto è comune con verbi che esprimono nomina, denominazione, valutazione o trasformazione: eleggere, nominare, chiamare, considerare, ritenere, rendere. Gli allievi hanno eletto Sara rappresentante contiene l’oggetto Sara e il ruolo rappresentante.\n\nIl predicativo può essere introdotto da come, da, in qualità di o altre espressioni, secondo la costruzione. Nella trasformazione passiva l’oggetto diventa soggetto e il suo predicativo diventa predicativo del soggetto, mentre il contenuto attribuito resta lo stesso. Questo confronto è un controllo utile, quando il verbo ammette il passivo.","examples":[{"sentence":"La vernice rende il piano lucido.","explanation":"Il piano è oggetto di rende; lucido gli attribuisce la qualità prodotta dal trattamento."}]},{"title":"Attributo, apposizione e nome del predicato","text":"L’attributo modifica direttamente un nome: il piano lucido. Il predicativo collega invece la qualità al nome attraverso il verbo: il piano sembra lucido. L’apposizione è un nome che precisa un altro nome senza questo legame predicativo: Sara, la rappresentante, parla.\n\nCon essere copula, in Sara è rappresentante, rappresentante è nome del predicato nel predicato nominale. Le costruzioni possono avere significati vicini, ma richiedono analisi diverse. Alcune grammatiche usano una nozione più ampia di predicazione: negli esercizi segui la distinzione scolastica qui esplicitata.","examples":[{"sentence":"Gli allievi hanno eletto Sara rappresentante → Sara è stata eletta rappresentante.","explanation":"Nella frase attiva rappresentante è predicativo dell’oggetto; nella passiva è predicativo del soggetto."}]}],"diagram":{"title":"Una qualità attribuita attraverso il verbo","steps":[{"label":"Del soggetto","detail":"Marta sembra stanca: stanca riguarda Marta, soggetto."},{"label":"Dell’oggetto","detail":"Considero Marta affidabile: affidabile riguarda Marta, oggetto."},{"label":"Attivo / passivo","detail":"Eleggono Sara rappresentante → Sara è eletta rappresentante: cambia la funzione del predicativo."},{"label":"Attributo diverso","detail":"Il piano lucido: lucido modifica direttamente il nome."},{"label":"Predicato nominale","detail":"Marta è stanca: stanca è nome del predicato con la copula essere."}]},"pitfalls":[{"mistake":"Ogni aggettivo vicino a un nome è attributo.","correction":"Controllare se la qualità passa attraverso il verbo.","why":"In Marta sembra stanca, stanca completa sembra e predica una qualità di Marta."},{"mistake":"Rappresentante resta predicativo dell’oggetto anche al passivo.","correction":"Rianalizzare soggetto e oggetto dopo la trasformazione.","why":"Al passivo Sara è soggetto e rappresentante è il suo predicativo."}],"recap":["Il complemento predicativo è un nome o un aggettivo che attribuisce una qualità, uno stato o un ruolo attraverso il verbo.","Il predicativo del soggetto compare con verbi copulativi come sembrare, diventare, restare e risultare, che richiedono o favoriscono un completamento.","Il predicativo dell’oggetto è comune con verbi che esprimono nomina, denominazione, valutazione o trasformazione: eleggere, nominare, chiamare, considerare, ritenere, rendere.","L’attributo modifica direttamente un nome: il piano lucido."],"review":[{"question":"A chi si riferisce affidabile in Considero Luca affidabile?","answer":"Al complemento oggetto Luca: è predicativo dell’oggetto."},{"question":"Quale differenza c’è fra il piano lucido e il piano diventa lucido?","answer":"Nel primo gruppo lucido è attributo del nome; nella seconda frase è predicativo del soggetto attraverso diventa."},{"question":"Come si analizza stanca in Marta è stanca secondo la distinzione adottata?","answer":"È nome del predicato, insieme alla copula è nel predicato nominale."}],"levels":{"base":{"focus":"Riconoscere qualità riferite al soggetto o all’oggetto.","example":{"sentence":"Marta sembra stanca.","explanation":"Stanca si riferisce al soggetto Marta attraverso il verbo sembra: predicativo del soggetto."}},"consolidamento":{"focus":"Confrontare forme attive e passive dei verbi di nomina.","example":{"sentence":"Sara è stata eletta rappresentante.","explanation":"Rappresentante attribuisce un ruolo al soggetto Sara attraverso il verbo passivo è stata eletta."}},"avanzato":{"focus":"Distinguere predicativi, attributi, apposizioni e nome del predicato.","example":{"sentence":"Gli allievi hanno eletto Sara rappresentante → Sara è stata eletta rappresentante.","explanation":"Nella frase attiva rappresentante è predicativo dell’oggetto; nella passiva è predicativo del soggetto."}}},"simplified":{"lead":"Una qualità può essere collegata al soggetto o all’oggetto attraverso il verbo.","steps":["Trova il soggetto e l’eventuale oggetto.","Cerca la qualità collegata attraverso il verbo.","Chiedi a quale persona o cosa si riferisce."],"example":{"sentence":"Luca sembra stanco.","explanation":"Stanco si riferisce al soggetto Luca attraverso sembra: predicativo del soggetto."}},"pei":{"rule":"Chiedi a chi appartiene la qualità: al soggetto oppure all’oggetto?","example":{"sentence":"Luca sembra stanco.","explanation":"Stanco si riferisce al soggetto Luca attraverso sembra: predicativo del soggetto."}},"trackExamples":{"moda":{"sentence":"Considero il tessuto adatto.","explanation":"Adatto si riferisce all’oggetto il tessuto: predicativo dell’oggetto."},"arredo":{"sentence":"Considero il pannello adatto.","explanation":"Adatto si riferisce all’oggetto il pannello: predicativo dell’oggetto."},"liuteria":{"sentence":"Considero il legno adatto.","explanation":"Adatto si riferisce all’oggetto il legno: predicativo dell’oggetto."}},"anchor":{"sentence":"Consideriamo Amir indispensabile.","explanation":"Amir è complemento oggetto di consideriamo. Indispensabile gli attribuisce una qualità attraverso il verbo: è predicativo dell’oggetto.","memory":"Segui il filo: consideriamo → Amir → indispensabile."}},{"topic":"Altre subordinate","area":"periodo","lead":"Alcune subordinate indicano un luogo, aggiungono un fatto o mettono in contrasto due azioni. Un inciso può invece interrompere il filo del periodo.","objectives":["Riconoscere locative, aggiuntive e avversative nel contesto","Interpretare la sfumatura delle relative improprie","Distinguere una proposizione incidentale da una subordinata"],"sections":[{"title":"Dove avviene il fatto: la locativa","text":"La subordinata locativa indica il luogo, reale o figurato, in cui si svolge l’azione della reggente o verso cui essa si dirige. Può essere introdotta da «dove», «da dove», «fin dove» o espressioni simili e ha una forma esplicita con verbo finito.\n\nNon confonderla con una relativa: nella relativa l’avverbio dove riprende un nome espresso, come laboratorio; nella locativa il luogo è indicato dalla proposizione senza un antecedente nominale espresso. La frase può però ammettere analisi diverse se un antecedente è sottinteso: osserva sempre il contesto.","examples":[{"sentence":"Riponi il righello dove trovi spazio.","explanation":"Dove trovi spazio indica il luogo in cui riporre il righello."},{"sentence":"Questo è il cassetto dove ripongo il righello.","explanation":"Dove ripongo il righello precisa il nome cassetto: è relativa."}]},{"title":"Un fatto in più: l’aggiuntiva","text":"La subordinata aggiuntiva presenta un fatto che si aggiunge a quello espresso dalla reggente. La forma più comune è implicita: oltre a oppure oltre che precedono un infinito.\n\nPer riconoscerla prova a parafrasare aggiungendo anche un’azione, senza cambiare soggetto o rapporti temporali. Non basta incontrare oltre: se introduce soltanto un nome e non un predicato, non forma una subordinata.","examples":[{"sentence":"Oltre a disegnare la sedia, Nora costruisce un modellino.","explanation":"Oltre a disegnare aggiunge un’azione a costruisce."},{"sentence":"Oltre al modello, porto il righello.","explanation":"Al modello è un gruppo nominale: non contiene un predicato subordinato."}]},{"title":"Contrapporre due fatti: l’avversativa","text":"La subordinata avversativa contrappone un fatto a quello della reggente. Può essere implicita con invece di o anziché seguiti dall’infinito; una forma esplicita può essere introdotta da mentre o laddove con valore di contrasto.\n\nMentre può anche indicare contemporaneità: non classificarlo automaticamente. Chiediti se il periodo contrappone le informazioni oppure si limita a dire quando avvengono le azioni. Una coordinata con ma collega invece proposizioni sullo stesso piano.","examples":[{"sentence":"Invece di buttare il cartone, lo riutilizziamo.","explanation":"La subordinata oppone l’azione non scelta a quella realizzata."},{"sentence":"Mentre Sara taglia la stoffa, Luca prepara il cartamodello.","explanation":"Senza altri indizi, mentre indica la contemporaneità delle azioni."}]},{"title":"Relative con sfumatura e incidentali","text":"Una relativa impropria resta legata a un antecedente ma, nel contesto, può assumere anche un valore circostanziale: per esempio finale, causale o concessivo. La parafrasi aiuta a interpretare la sfumatura, senza cancellare il legame relativo.\n\nUna proposizione incidentale interrompe o accompagna il discorso come commento del parlante; spesso è isolata da virgole, trattini o parentesi. Per esempio «credo» in «La misura, credo, è giusta» esprime un inciso e non precisa un luogo o uno scopo. Le grammatiche possono descrivere le incidentali con etichette diverse.","examples":[{"sentence":"Cerco una persona che mi aiuti.","explanation":"Che mi aiuti precisa persona e ha anche una sfumatura di scopo."},{"sentence":"Il disegno, penso, è pronto.","explanation":"Penso è un commento incidentale inserito nel periodo."}]}],"diagram":{"title":"Tre domande e un inciso","steps":[{"label":"Dove?","detail":"La locativa indica il luogo dell’azione."},{"label":"Che cosa in più?","detail":"L’aggiuntiva affianca un’ulteriore azione."},{"label":"In contrasto?","detail":"L’avversativa contrappone due fatti."},{"label":"Relativa","detail":"Riprende un antecedente e può avere una sfumatura circostanziale."},{"label":"Inciso","detail":"L’incidentale inserisce un commento nel discorso."}]},"pitfalls":[{"mistake":"Chiamare sempre temporale una subordinata introdotta da mentre.","correction":"Leggere il rapporto tra le due azioni.","why":"Mentre può indicare contemporaneità oppure contrasto."},{"mistake":"Definire locativa ogni proposizione introdotta da dove.","correction":"Cercare un antecedente nominale espresso.","why":"Se dove riprende un nome, la costruzione è relativa."}],"recap":["La locativa indica il luogo dell’azione senza un antecedente nominale espresso.","L’aggiuntiva aggiunge un’azione; l’avversativa contrappone fatti.","Una relativa impropria può avere una sfumatura di scopo, causa o concessione.","Una incidentale inserisce un commento e può essere isolata dalla punteggiatura."],"review":[{"question":"Come distingui locativa e relativa con dove?","answer":"Cerco un antecedente nominale espresso: se dove lo riprende, la proposizione è relativa."},{"question":"Che cosa aggiunge oltre a disegnare in «Oltre a disegnare, costruisco»?","answer":"Un’azione ulteriore rispetto a costruire."},{"question":"Che cosa fa penso in «Il disegno, penso, è pronto»?","answer":"Inserisce un commento incidentale."}],"levels":{"base":{"focus":"Riconoscere il rapporto di luogo e di aggiunta.","example":{"sentence":"Lascia il filo dove trovi spazio.","explanation":"Dove trovi spazio indica il luogo."}},"consolidamento":{"focus":"Distinguere contrasto e contemporaneità.","example":{"sentence":"Invece di scartare il legno, lo recuperiamo.","explanation":"Invece di scartare contrappone due scelte."}},"avanzato":{"focus":"Distinguere relativa impropria e proposizione incidentale.","example":{"sentence":"Cerco una persona che mi consigli.","explanation":"Chi mi consigli ha una sfumatura di scopo: cerco una persona perché mi consigli."}}},"simplified":{"lead":"Alcune frasi indicano dove, aggiungono un’azione o mostrano un contrasto.","steps":["Cerca i verbi.","Chiediti se una parte indica luogo, aggiunta o contrasto.","Controlla se una parte è solo un commento inserito."],"example":{"sentence":"Appoggia il libro dove c’è spazio.","explanation":"Dove c’è spazio indica il luogo."}},"pei":{"rule":"Dove può indicare il luogo. Cerca il verbo nella parte che inizia con dove.","example":{"sentence":"Siediti dove c’è posto.","explanation":"Dove c’è posto indica il luogo."}},"trackExamples":{"moda":{"sentence":"Riponi il filo dove trovi spazio.","explanation":"La subordinata indica il luogo."},"arredo":{"sentence":"Oltre a disegnare il tavolo, costruisco un modello.","explanation":"La subordinata aggiunge un’azione."},"liuteria":{"sentence":"Invece di scartare il legno, lo recupero.","explanation":"La subordinata contrappone due scelte."}},"anchor":{"sentence":"Il righello, credo, si è nascosto dove nessuno guarda!","explanation":"Credo è un commento incidentale; dove nessuno guarda indica il luogo in cui si sarebbe nascosto.","memory":"Prima cerca il luogo, poi isola il piccolo commento tra virgole."}}];
